-- 020_seed_commercial_code_law.sql — بذر قانون التجارة رقم 17 لسنة 1999
-- (772 مادة) + ملحق الفصل الساري من قانون التجارة القديم 1883 (47 مادة:
-- 19-65، شركات الأشخاص) — EP-08، 2026-09-02
--
-- المصدر: النسخة الرسمية المطبوعة الصادرة عن الهيئة العامة لشئون المطابع
-- الأميرية (نفس ملف WIPO Lex الرسمي: wipo.int/wipolex/en/legislation/
-- details/13558). طبقة النص الداخلية فى ملف الـ PDF المصدر تالفة (ترميز خط
-- مكسور)، فتم النسخ الحرفى الكامل بالقراءة البصرية المباشرة لصور الصفحات
-- الـ 135 (200dpi)، وليس عبر استخراج آلى (راجع
-- /home/claude/cat2_laws/commercial_code/text_17_1999_full.txt للنص الخام
-- الكامل وتقرير الإتمام فى المشروع بتاريخ 2026-09-02). تحقّق آلي نهائي: 772
-- مادة متتالية بلا فجوة أو تكرار للمتن الأساسى، 47 مادة (19-65) بلا فجوة أو
-- تكرار للملحق.
--
-- قرار معمارى: فئة جديدة 'commercial' تُضاف صراحة لأن قانون التجارة مجال
-- تشريعى رئيسى مستقل (كالعمل والإيجارات والأحوال الشخصية)، وليس مناسباً
-- لتصنيفه تحت 'other' (النمط الاحتياطى المستخدم سابقاً لمحتوى صغير ينقصه
-- تصنيف مخصص فى 019). يتطلب هذا لمسة لاحقة على القائمة الجانبية بالواجهة
-- الأمامية لإظهار الفئة الجديدة (نفس الملاحظة المعلَّقة سابقاً فى 019 عن
-- 'other'/cyber_crime — هنا يُحسم القرار فوراً بدل التأجيل لأهمية المجال).
--
-- قرار معمارى ثانٍ: ملحق 1883 يُدرَج كسجل `laws` منفصل تماماً (law_no=0,
-- law_year=1883) وليس كجزء من مواد قانون 17/1999 — لأنه قانونياً أداة
-- تشريعية مستقلة (الأمر العالى الصادر 1883/11/13)، لم يُلغَ صراحة بنص
-- المادة الأولى من قانون 17/1999 (انظر النص الحرفى فى مقدمة قانون
-- 17/1999: "يلغى قانون التجارة الصادر بالأمر العالي في 13 من نوفمبر سنة
-- 1883 , عدا الفصل الأول من الباب الثاني منه والخاص بشركات الأشخاص")، أى
-- لا يزال هذا الفصل بعينه ساري المفعول فعلياً حتى صدور قانون شركات جديد
-- يحل محله. law_no=0 يعمل كقيمة حارسة (sentinel) صريحة تشير إلى "أداة
-- تشريعية سابقة على نظام الترقيم السنوى الحديث" وليست قيمة اعتباطية — موثّق
-- هنا صراحة بدل إخفائها. ترقيم مواده (19-65) مستقل تماماً عن ترقيم قانون
-- 17/1999 (1-772) ولا يوجد تعارض لأنهما صفان مختلفان فى جدول laws.
--
-- تاريخ نفاذ مجزّأ داخل نفس القانون (موثّق حرفياً فى نص إصدار القانون،
-- المادة الثالثة): يعمل بقانون 17/1999 اعتباراً من 1999/10/1، عدا الأحكام
-- الخاصة بالشيك (الفصل الثالث من الباب الرابع، المواد 472-539) فتعمل بها
-- اعتباراً من 2001/10/1 فقط — رُوعِى هذا التمايز صراحة فى effective_from
-- لكل مادة أدناه (وليس تاريخاً واحداً موحَّداً للقانون كله، تفادياً لخطأ
-- دقيق قد يضلل أى استعلام مستقبلى عن "هل كانت هذه المادة سارية بتاريخ
-- كذا"). ملحق 1883 يحمل effective_from = تاريخ نفاذه الأصلى (1883/11/13)
-- لأنه لم ينقطع سريانه قط بالنسبة لهذا الفصل بعينه.
--
-- قابل لإعادة التشغيل بأمان (idempotent) — نفس نمط بقية ملفات هذا المجلد
-- (ON CONFLICT DO NOTHING على كل من laws وarticles).

BEGIN;

ALTER TABLE laws DROP CONSTRAINT IF EXISTS laws_category_check;
ALTER TABLE laws ADD CONSTRAINT laws_category_check
  CHECK (category IN ('labor','rent','personal_status','traffic','consumer_protection','insurance','aml_cft','legal_profession','capital_markets','non_bank_finance','commercial','other'));


-- ===== law17_1999 =====
INSERT INTO laws (law_no, law_year, title, short_title, category, kind, status, official_url, enacted_at)
VALUES (17, 1999, $cc1$القانون رقم 17 لسنة 1999 بإصدار قانون التجارة$cc1$, $cc2$قانون التجارة$cc2$, 'commercial', 'law', 'in_force', $cc3$https://www.wipo.int/wipolex/en/legislation/details/13558$cc3$, '1999-05-17')
ON CONFLICT (country_code, law_no, law_year) DO NOTHING;

-- 772 مادة (1-772) — تاريخ نفاذ مجزّأ: 1999/10/1 عموماً، وأحكام
-- الشيك (المواد 472-539) من 2001/10/1
WITH ins_art_law17_1999_1 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 1, $cc4$الباب الأول: التجارة بوجه عام$cc4$, $cc5$تسري أحكام هذا القانون على الأعمال التجارية , وعلى كل شخص طبيعي أو إعتباري تثبت له صفة التاجر.$cc5$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc5$تسري أحكام هذا القانون على الأعمال التجارية , وعلى كل شخص طبيعي أو إعتباري تثبت له صفة التاجر.$cc5$, '1999-10-01', 'active' FROM ins_art_law17_1999_1;

WITH ins_art_law17_1999_2 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 2, $cc6$الباب الأول: التجارة بوجه عام$cc6$, $cc7$1- تسري على المواد التجارية أحكام الإتفاق بين المتعاقدين, فإذا لم يوجد هذا الإتفاق , سرت نصوص هذا القانون أو غيره من القوانين المتعلقة بالمواد التجارية, ثم قواعد العرف التجاري والعادات التجارية, فإذا لم يوجد عرف تجاري أو عادة تجارية وجب تطبيق أحكام القانون المدني.
2- لا يجوز تطبيق الإتفاقات بين المتعاقدين , أو قواعد العرف التجاري أو العادات التجارية متى تعارضت مع النظام العام في مصر.$cc7$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc7$1- تسري على المواد التجارية أحكام الإتفاق بين المتعاقدين, فإذا لم يوجد هذا الإتفاق , سرت نصوص هذا القانون أو غيره من القوانين المتعلقة بالمواد التجارية, ثم قواعد العرف التجاري والعادات التجارية, فإذا لم يوجد عرف تجاري أو عادة تجارية وجب تطبيق أحكام القانون المدني.
2- لا يجوز تطبيق الإتفاقات بين المتعاقدين , أو قواعد العرف التجاري أو العادات التجارية متى تعارضت مع النظام العام في مصر.$cc7$, '1999-10-01', 'active' FROM ins_art_law17_1999_2;

WITH ins_art_law17_1999_3 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 3, $cc8$الباب الأول: التجارة بوجه عام$cc8$, $cc9$إذا كان العقد تجاريا بالنسبة الى أحد طرفيه , فلا تسري أحكام القانون التجاري إلا على إلتزامات هذا الطرف وحده, وتسري على إلتزامات الطرف الآخر أحكام القانون المدني ما لم ينص القانون على غير ذلك.$cc9$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
