SELECT id, 1, $cc9$إذا كان العقد تجاريا بالنسبة الى أحد طرفيه , فلا تسري أحكام القانون التجاري إلا على إلتزامات هذا الطرف وحده, وتسري على إلتزامات الطرف الآخر أحكام القانون المدني ما لم ينص القانون على غير ذلك.$cc9$, '1999-10-01', 'active' FROM ins_art_law17_1999_3;

WITH ins_art_law17_1999_4 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 4, $cc10$الباب الأول: التجارة بوجه عام — الفصل الأول: الأعمال التجارية$cc10$, $cc11$يعد عملا تجاريا:
(أ) شراء المنقولات أيا كان نوعها بقصد بيعها أو تأجيرها بذاتها أو بعد تهيئتها في صورة أخرى, وكذلك بيع أو تأجير هذه المنقولات.
(ب) إستئجار المنقولات بقصد تأجيرها وكذلك تأجير هذه المنقولات.
(ج) تأسيس الشركات التجارية.$cc11$
