WITH ins_art_law17_1999_5 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 5, $cc12$الباب الأول: التجارة بوجه عام — الفصل الأول: الأعمال التجارية$cc12$, $cc13$تعد الأعمال التالية تجارية إذا كانت مزاولتها على وجه الإحتراف:
(أ) توريد البضائع والخدمات.
(ب) الصناعة.
(ج) النقل البري والنقل في المياه الداخلية.
(د) الوكالة التجارية والسمسرة أيا كانت طبيعة العمليات التي يمارسها السمسار.
(هـ) التأمين على إختلاف أنواعه.
(و) عمليات البنوك والصرافة.
(ز) استيداع البضائع ووسائط النقل والمحاصيل والتصدير وغيرها.
(ح) أعمال الدور والمكاتب التي تعمل في مجالات النشر, والطباعة, والتصوير, والكتابة على الآلات الكاتبة, وغيرها, والترجمة, والإذاعة , والتلفزيون , والصحافة , ونقل الأخبار , والبريد والإتصالات , والإعلان.
(ط) الإستغلال التجاري لبرامج الحاسب الآلي والبث الفضائي عبر الأقمار الصناعية.
(ي) العمليات الإستخراجية لمواد الثروات الطبيعية كالمناجم والمحاجر ومنابع النفط والغاز وغيرها.
(ك) مشروعات تربية الدواجن والمواشي وغيرها بقصد بيعها.
(ل) مقاولات تشييد العقارات أو ترميمها أو تعديلها أو هدمها أو طلائها أو مقاولات الأشغال العامة.
(م) تشييد العقارات أو شراؤها أو إستئجارها بقصد بيعها أو تأجيرها كاملة أو مجزأة الى شقق أو غرف أو وحدات إدارية أو تجارية سواء كانت مفروشة أو غير مفروشة.
(ن) أعمال مكاتب السياحة ومكاتب التصدير والإستيراد والإفراج الجمركي ومكاتب الإستخدام ومحال البيع بالمزاد العلني.
(س) أعمال الفنادق والمطاعم والمقاهي والتمثيل والسينما والسيرك وغير ذلك من الملاهي العامة.
(ع) توزيع المياه أو الغاز أو الكهرباء وغيرها من مصادر الطاقة.$cc13$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc13$تعد الأعمال التالية تجارية إذا كانت مزاولتها على وجه الإحتراف:
(أ) توريد البضائع والخدمات.
(ب) الصناعة.
(ج) النقل البري والنقل في المياه الداخلية.
(د) الوكالة التجارية والسمسرة أيا كانت طبيعة العمليات التي يمارسها السمسار.
(هـ) التأمين على إختلاف أنواعه.
(و) عمليات البنوك والصرافة.
(ز) استيداع البضائع ووسائط النقل والمحاصيل والتصدير وغيرها.
(ح) أعمال الدور والمكاتب التي تعمل في مجالات النشر, والطباعة, والتصوير, والكتابة على الآلات الكاتبة, وغيرها, والترجمة, والإذاعة , والتلفزيون , والصحافة , ونقل الأخبار , والبريد والإتصالات , والإعلان.
(ط) الإستغلال التجاري لبرامج الحاسب الآلي والبث الفضائي عبر الأقمار الصناعية.
(ي) العمليات الإستخراجية لمواد الثروات الطبيعية كالمناجم والمحاجر ومنابع النفط والغاز وغيرها.
(ك) مشروعات تربية الدواجن والمواشي وغيرها بقصد بيعها.
(ل) مقاولات تشييد العقارات أو ترميمها أو تعديلها أو هدمها أو طلائها أو مقاولات الأشغال العامة.
(م) تشييد العقارات أو شراؤها أو إستئجارها بقصد بيعها أو تأجيرها كاملة أو مجزأة الى شقق أو غرف أو وحدات إدارية أو تجارية سواء كانت مفروشة أو غير مفروشة.
(ن) أعمال مكاتب السياحة ومكاتب التصدير والإستيراد والإفراج الجمركي ومكاتب الإستخدام ومحال البيع بالمزاد العلني.
(س) أعمال الفنادق والمطاعم والمقاهي والتمثيل والسينما والسيرك وغير ذلك من الملاهي العامة.
(ع) توزيع المياه أو الغاز أو الكهرباء وغيرها من مصادر الطاقة.$cc13$, '1999-10-01', 'active' FROM ins_art_law17_1999_5;

WITH ins_art_law17_1999_6 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 6, $cc14$الباب الأول: التجارة بوجه عام — الفصل الأول: الأعمال التجارية$cc14$, $cc15$يعد أيضا عملا تجاريا كل عمل يتعلق بالملاحة التجارية بحرية كانت أو جوية, وعلى وجه الخصوص ما يأتي:
(أ) بناء السفن أو الطائرات وإصلاحها وصيانتها.
(ب) شراء أو بيع أو تأجير أو استئجار السفن أو الطائرات.
(ج) شراء أدوات أو مواد تموين السفن أو الطائرات.
(د) النقل البحري والنقل الجوي.
(هـ) عمليات الشحن أو التفريغ.
(و) استخدام الملاحين أو الطيارين أو غيرهم من العاملين في السفن أو الطائرات.$cc15$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc15$يعد أيضا عملا تجاريا كل عمل يتعلق بالملاحة التجارية بحرية كانت أو جوية, وعلى وجه الخصوص ما يأتي:
(أ) بناء السفن أو الطائرات وإصلاحها وصيانتها.
(ب) شراء أو بيع أو تأجير أو استئجار السفن أو الطائرات.
(ج) شراء أدوات أو مواد تموين السفن أو الطائرات.
(د) النقل البحري والنقل الجوي.
(هـ) عمليات الشحن أو التفريغ.
(و) استخدام الملاحين أو الطيارين أو غيرهم من العاملين في السفن أو الطائرات.$cc15$, '1999-10-01', 'active' FROM ins_art_law17_1999_6;

