WITH ins_art_law17_1999_10 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 10, $cc22$الباب الأول: التجارة بوجه عام — الفصل الثاني: التاجر$cc22$, $cc23$يكون تاجرا:
1- كل من يزاول على وجه الإحتراف باسمه ولحسابه عملا تجاريا.
2- كل شركة تتخذ أحد الأشكال المنصوص عليها في القوانين المتعلقة بالشركات أيا كان الغرض الذي أنشئت الشركة من أجله.$cc23$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc23$يكون تاجرا:
1- كل من يزاول على وجه الإحتراف باسمه ولحسابه عملا تجاريا.
2- كل شركة تتخذ أحد الأشكال المنصوص عليها في القوانين المتعلقة بالشركات أيا كان الغرض الذي أنشئت الشركة من أجله.$cc23$, '1999-10-01', 'active' FROM ins_art_law17_1999_10;

WITH ins_art_law17_1999_11 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 11, $cc24$الباب الأول: التجارة بوجه عام — الفصل الثاني: التاجر$cc24$, $cc25$1- يكون أهلا لمزاولة التجارة مصريا كان أو أجنبيا:
(أ) من بلغت سنه إحدى وعشرين سنة كاملة , ولو كان قانون الدولة التي ينتمي إليها بجنسيته يعتبر قاصرا في هذه السن.
(ب) من أكمل الثامنة عشرة بالشروط المقررة في قانون الدولة التي ينتمي إليها بجنسيته وذلك بعد الحصول على إذن من المحكمة المصرية المختصة.
2- لا يجوز لمن نقل سنه عن ثماني عشرة سنة أن يزاول التجارة في مصر ولو كان قانون الدولة التي ينتمي إليها بجنسيته يعتبر راشدا في هذه السن أو يجيز له الاتجار.
3- تكون للقاصر المأذون له في الإتجار الأهلية الكاملة للقيام بجميع التصرفات القانونية التي تقتضيها تجارته.$cc25$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc25$1- يكون أهلا لمزاولة التجارة مصريا كان أو أجنبيا:
(أ) من بلغت سنه إحدى وعشرين سنة كاملة , ولو كان قانون الدولة التي ينتمي إليها بجنسيته يعتبر قاصرا في هذه السن.
(ب) من أكمل الثامنة عشرة بالشروط المقررة في قانون الدولة التي ينتمي إليها بجنسيته وذلك بعد الحصول على إذن من المحكمة المصرية المختصة.
2- لا يجوز لمن نقل سنه عن ثماني عشرة سنة أن يزاول التجارة في مصر ولو كان قانون الدولة التي ينتمي إليها بجنسيته يعتبر راشدا في هذه السن أو يجيز له الاتجار.
3- تكون للقاصر المأذون له في الإتجار الأهلية الكاملة للقيام بجميع التصرفات القانونية التي تقتضيها تجارته.$cc25$, '1999-10-01', 'active' FROM ins_art_law17_1999_11;

WITH ins_art_law17_1999_12 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 12, $cc26$الباب الأول: التجارة بوجه عام — الفصل الثاني: التاجر$cc26$, $cc27$1- إذا كان للصغير أو للمحجور عليه مال في تجارة جاز للمحكمة أن تأمر بإخراج ماله منها, أو باستمراره فيها وفقا لما تقضي به مصلحته.
2- إذا أمرت المحكمة بالاستمرار في التجارة وجب أن تمنح النائب عن الصغير أو المحجور عليه إذنا مطلقا أو مقيدا للقيام بالتصرفات التي تقتضيها التجارة.
3- إذا طرأت أسباب جدية يخشى معها سوء إدارة النائب المأذون له في الإستمرار في تجارة الصغير أو المحجور عليه جاز للمحكمة أن تسحب الإذن أو أن تقيده وذلك دون إخلال بالحقوق التي اكتسبها الغير حسن النية.
4- كل أمر يصدر من المحكمة في شأن الاستمرار في تجارة الصغير أو المحجور عليه أو سحب الإذن أو تقييده أو تصفية التجارة, يجب قيده في السجل التجاري ونشره في صحيفة السجل.$cc27$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
