3- لا يؤثر الإعتراض أو سحب الإذن في الحقوق التي اكتسبها الغير حسن النية.$cc31$, '1999-10-01', 'active' FROM ins_art_law17_1999_14;

WITH ins_art_law17_1999_15 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 15, $cc32$الباب الأول: التجارة بوجه عام — الفصل الثاني: التاجر$cc32$, $cc33$1- يفترض في الزوجة الأجنبية التاجرة أنها تزوجت وفقا لنظام انفصال الأموال إلا إذا كانت المشارطة المالية بين الزوجين تنص على خلاف ذلك.
2- لا يحتج على الغير بالمشارطة المالية بين الزوجين إلا إذا أشهرت بقيدها في السجل التجاري ونشر ملخصها في صحيفة السجل.
3- يجوز للغير في حالة إهمال شهر المشارطة المالية بين الزوجين أن يثبت أن الزواج قد تم وفقا لنظام مالي أكثر ملائمة لمصلحته من نظام انفصال الأموال.
4- لا يحتج على الغير بالحكم الصادر خارج مصر القاضي بانفصال الأموال بين الزوجين إلا من تاريخ قيده في السجل التجاري ونشر ملخصه في صحيفة هذا السجل.$cc33$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
