WITH ins_art_law17_1999_23 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 23, $cc48$الباب الأول: التجارة بوجه عام — الفصل الثالث: الدفاتر التجارية$cc48$, $cc49$1- يقيد في دفتر الجرد تفصيل البضاعة الموجودة لدى التاجر في آخر سنته المالية أو بيان إجمالي عنها إذا كانت تفصيلاتها واردة بدفاتر أو قوائم مستقلة. وفي هذه الحالة تعتبر تلك الدفاتر أو القوائم جزءا متمما لدفتر الجرد الأصلي.
2- تقيد في دفتر الجرد صورة من الميزانية السنوية وحساب الأرباح والخسائر.$cc49$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc49$1- يقيد في دفتر الجرد تفصيل البضاعة الموجودة لدى التاجر في آخر سنته المالية أو بيان إجمالي عنها إذا كانت تفصيلاتها واردة بدفاتر أو قوائم مستقلة. وفي هذه الحالة تعتبر تلك الدفاتر أو القوائم جزءا متمما لدفتر الجرد الأصلي.
2- تقيد في دفتر الجرد صورة من الميزانية السنوية وحساب الأرباح والخسائر.$cc49$, '1999-10-01', 'active' FROM ins_art_law17_1999_23;

WITH ins_art_law17_1999_24 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 24, $cc50$الباب الأول: التجارة بوجه عام — الفصل الثالث: الدفاتر التجارية$cc50$, $cc51$على التاجر أن يحتفظ بصورة من المراسلات والبرقيات وغيرها من الوثائق التي يرسلها أو يتسلمها لشئون تتعلق بتجارته. ويكون الحفظ بطريقة منتظمة تسهل معها المراجعة.$cc51$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc51$على التاجر أن يحتفظ بصورة من المراسلات والبرقيات وغيرها من الوثائق التي يرسلها أو يتسلمها لشئون تتعلق بتجارته. ويكون الحفظ بطريقة منتظمة تسهل معها المراجعة.$cc51$, '1999-10-01', 'active' FROM ins_art_law17_1999_24;

WITH ins_art_law17_1999_25 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 25, $cc52$الباب الأول: التجارة بوجه عام — الفصل الثالث: الدفاتر التجارية$cc52$, $cc53$1- يجب أن تكون الدفاتر التجارية خالية من أي فراغ أو شطب أو محو أو كتابة في الهوامش أو بين السطور.
2- يجب قبل استعمال دفتري اليومية والجرد أن ترقم صفحاتهما وأن يوقع كل صفحة مكتب السجل التجاري وأن يضع على كل صفحة خاتم مكتب السجل مع بيان عدد صفحات الدفتر.
3- يجب تقديم دفتري اليومية والجرد في نهاية السنة المالية للتاجر الى مكتب السجل التجاري للتصديق على عدد الصفحات التي استعملت خلال السنة. وعند انتهاء صفحات الدفتر يجب على التاجر تقديمه الى مكتب السجل عليه بما يفيد انتهاء صفحاته.
4- على التاجر أو ورثته في حالة وقف نشاط المتجر تقديم دفتري اليومية والجرد الى مكتب السجل التجاري للتأشير عليهما بما يفيد قفلهما.
5- يجوز بقرار من الوزير المختص وضع أحكام خاصة بتنظيم الدفاتر التجارية التي تستعملها البنوك أو الشركات التي يعينها القرار.$cc53$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc53$1- يجب أن تكون الدفاتر التجارية خالية من أي فراغ أو شطب أو محو أو كتابة في الهوامش أو بين السطور.
2- يجب قبل استعمال دفتري اليومية والجرد أن ترقم صفحاتهما وأن يوقع كل صفحة مكتب السجل التجاري وأن يضع على كل صفحة خاتم مكتب السجل مع بيان عدد صفحات الدفتر.
3- يجب تقديم دفتري اليومية والجرد في نهاية السنة المالية للتاجر الى مكتب السجل التجاري للتصديق على عدد الصفحات التي استعملت خلال السنة. وعند انتهاء صفحات الدفتر يجب على التاجر تقديمه الى مكتب السجل عليه بما يفيد انتهاء صفحاته.
4- على التاجر أو ورثته في حالة وقف نشاط المتجر تقديم دفتري اليومية والجرد الى مكتب السجل التجاري للتأشير عليهما بما يفيد قفلهما.
5- يجوز بقرار من الوزير المختص وضع أحكام خاصة بتنظيم الدفاتر التجارية التي تستعملها البنوك أو الشركات التي يعينها القرار.$cc53$, '1999-10-01', 'active' FROM ins_art_law17_1999_25;

WITH ins_art_law17_1999_26 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 26, $cc54$الباب الأول: التجارة بوجه عام — الفصل الثالث: الدفاتر التجارية$cc54$, $cc55$1- يجب على التاجر أو ورثته الاحتفاظ بالدفاتر التجارية والوثائق المؤيدة للقيود الواردة بها مدة خمس سنوات تبدأ من تاريخ التأشير على الدفتر بانتهائه أو قفله.
2- وعليهم أيضا حفظ صور المراسلات والبرقيات وغيرها مدة خمس سنوات من تاريخ إرسالها أو تسلمها . ويجوز لهم الإحتفاظ للمدة المذكورة بالصور المصغرة (ميكروفيلم) بدلا من الأصل, ويكون لتلك الصور حجية الأصل في الإثبات إذا روعى في إعدادها وحفظها واسترجاعها القواعد والضوابط التي يصدر بها قرار من وزير العدل.$cc55$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc55$1- يجب على التاجر أو ورثته الاحتفاظ بالدفاتر التجارية والوثائق المؤيدة للقيود الواردة بها مدة خمس سنوات تبدأ من تاريخ التأشير على الدفتر بانتهائه أو قفله.
2- وعليهم أيضا حفظ صور المراسلات والبرقيات وغيرها مدة خمس سنوات من تاريخ إرسالها أو تسلمها . ويجوز لهم الإحتفاظ للمدة المذكورة بالصور المصغرة (ميكروفيلم) بدلا من الأصل, ويكون لتلك الصور حجية الأصل في الإثبات إذا روعى في إعدادها وحفظها واسترجاعها القواعد والضوابط التي يصدر بها قرار من وزير العدل.$cc55$, '1999-10-01', 'active' FROM ins_art_law17_1999_26;

WITH ins_art_law17_1999_27 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 27, $cc56$الباب الأول: التجارة بوجه عام — الفصل الثالث: الدفاتر التجارية$cc56$, $cc57$القيود التي تدون في الدفاتر التجارية من قبل مستخدمي التاجر المأذونين في ذلك, تعتبر في حكم القيود التي يدونها التاجر بنفسه , ويفترض فيها أنها دونت بعلمه إلا إذا أقام الدليل على خلاف ذلك.$cc57$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
