SELECT id, 1, $cc57$القيود التي تدون في الدفاتر التجارية من قبل مستخدمي التاجر المأذونين في ذلك, تعتبر في حكم القيود التي يدونها التاجر بنفسه , ويفترض فيها أنها دونت بعلمه إلا إذا أقام الدليل على خلاف ذلك.$cc57$, '1999-10-01', 'active' FROM ins_art_law17_1999_27;

WITH ins_art_law17_1999_28 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 28, $cc58$الباب الأول: التجارة بوجه عام — الفصل الثالث: الدفاتر التجارية$cc58$, $cc59$1- يجوز للمحكمة بناء على طلب الخصم أو من تلقاء ذاتها أن تأمر التاجر بتقديم دفاتره إليها لاستخلاص ما يتعلق بالنزاع المعروض عليها. وللمحكمة أن تطلع على الدفاتر بنفسها أو بواسطة خبير تعينه لذلك.
2- لا يجوز للمحكمة أن تأمر التاجر بإطلاع خصمه على دفاتره إلا في المنازعات المتعلقة بالتركات ومواد الأموال المشاعة والشركات.
3- تسلم الدفاتر في حالة الإفلاس أو الصلح الواقي منه للمحكمة أو لأمين التفليسة أو لمراقب الصلح.
4- إذا امتنع التاجر دون عذر مقبول عن تقديم دفاتره للإطلاع عليها جاز للمحكمة اعتبار ذلك قرينة على صحة الوقائع المطلوب إثباتها من الدفاتر.$cc59$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc59$1- يجوز للمحكمة بناء على طلب الخصم أو من تلقاء ذاتها أن تأمر التاجر بتقديم دفاتره إليها لاستخلاص ما يتعلق بالنزاع المعروض عليها. وللمحكمة أن تطلع على الدفاتر بنفسها أو بواسطة خبير تعينه لذلك.
2- لا يجوز للمحكمة أن تأمر التاجر بإطلاع خصمه على دفاتره إلا في المنازعات المتعلقة بالتركات ومواد الأموال المشاعة والشركات.
3- تسلم الدفاتر في حالة الإفلاس أو الصلح الواقي منه للمحكمة أو لأمين التفليسة أو لمراقب الصلح.
4- إذا امتنع التاجر دون عذر مقبول عن تقديم دفاتره للإطلاع عليها جاز للمحكمة اعتبار ذلك قرينة على صحة الوقائع المطلوب إثباتها من الدفاتر.$cc59$, '1999-10-01', 'active' FROM ins_art_law17_1999_28;

