WITH ins_art_law17_1999_32 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 32, $cc66$الباب الأول: التجارة بوجه عام — الفصل الرابع: السجل التجاري$cc66$, $cc67$1- لكل شخص أن يحصل من مكتب السجل التجاري على صورة مستخرجة من صفحة القيد. وفي حالة عدم القيد يعطى المكتب شهادة سلبية.
2- لا يجوز أن تشتمل الصورة المستخرجة من صفحة القيد على:
(أ) أحكام شهر الإفلاس إذا حكم برد الاعتبار.
(ب) أحكام الحجر إذا حكم برفعه.$cc67$
