SELECT id, 1, $cc67$1- لكل شخص أن يحصل من مكتب السجل التجاري على صورة مستخرجة من صفحة القيد. وفي حالة عدم القيد يعطى المكتب شهادة سلبية.
2- لا يجوز أن تشتمل الصورة المستخرجة من صفحة القيد على:
(أ) أحكام شهر الإفلاس إذا حكم برد الاعتبار.
(ب) أحكام الحجر إذا حكم برفعه.$cc67$, '1999-10-01', 'active' FROM ins_art_law17_1999_32;

WITH ins_art_law17_1999_33 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 33, $cc68$الباب الأول: التجارة بوجه عام — الفصل الرابع: السجل التجاري$cc68$, $cc69$1- تكون البيانات المقيدة في السجل التجاري حجة على الغير من تاريخ قيدها في السجل ما لم ينص القانون على غير ذلك.
2- لا يجوز الإحتجاج على الغير بأي بيان واجب القيد في السجل التجاري ولم يتم قيده إلا إذا ثبت علم الغير بمضمون البيان.
3- لا يجوز للتاجر أن يتمسك بعدم قيده في السجل التجاري للتحلل من الإلتزامات التي يفرضها عليه القانون أو التي تنشأ عن معاملاته مع الغير بصفته تاجرا.$cc69$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
