WITH ins_art_law17_1999_37 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 37, $cc76$الباب الأول: التجارة بوجه عام — الفصل الخامس: المتجر$cc76$, $cc77$1- كل تصرف يكون موضوعه نقل ملكية المتجر أو إنشاء حق عيني عليه أو تأجير استغلاله يجب أن يكون مكتوبا وإلا كان باطلا.
2- يقيد التصرف في المتجر وعقد تأجير استغلاله في سجل خاص يصدر بتنظيمه قرار من الوزير المختص ويحفظ بمكتب السجل التجاري .
3- يشهر تصرف المتجر وتأجير استغلاله بالقيد في السجل التجاري , ويجب أن يشتمل هذا الشهر على البيانات الآتية:
(أ) أسماء المتعاقدين وعناوينهم وجنسياتهم.
(ب)تاريخ العقد ونوعه.
(ج) نشاط المتجر وعنوانه والعناصر التي اتفق على أن يشملها العقد.
(د) الثمن وما دفع منه عند البيع أو قيمة الأجرة المتفق عليها وكيفية سداد باقي الثمن أو أجرة الاستغلال.
(هـ) الاتفاقات بشأن العقود والتعهدات المتصلة بالمتجر.
(و) الاتفاقات المتعلقة باحتفاظ البائع بحق الفسخ أو بحق الإمتياز.$cc77$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
