  SELECT id, 50, $cc102$الباب الثاني: الإلتزامات والعقود التجارية$cc102$, $cc103$1- تعتبر تجارية القروض التي يعقدها التاجر لشئون تتعلق بأعماله التجارية.
2- اذا اقتضت مهنة التاجر اداء مبالغ او مصاريف لحساب عملائه جاز له مطالبتهم بعائد عنها من يوم صرفها ما لم يتفق على غير ذلك.
3- يحسب العائد وفقا للسعر الذي يتعامل به البنك المركزي، ما لم يتفق على مقابل اقل.
4- يؤدي العائد في نهاية كل سنة إذا كان الدين مؤجلا لاكثر من سنة وفي يوم الاستحقاق إذا كان لاجل سنة أو اقل ما لم يتفق أو يجر العرف على غير ذلك.$cc103$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc103$1- تعتبر تجارية القروض التي يعقدها التاجر لشئون تتعلق بأعماله التجارية.
2- اذا اقتضت مهنة التاجر اداء مبالغ او مصاريف لحساب عملائه جاز له مطالبتهم بعائد عنها من يوم صرفها ما لم يتفق على غير ذلك.
