SELECT id, 1, $cc131$يستحق العائد عن التأخير في الوفاء بالديون التجارية بمجرد استحقاقها ما لم ينص القانون أو الاتفاق على غير ذلك. ولا يجوز في أية حال أن يكون مجموع العائد الذي يتقاضاه الدائن اكثر من مبلغ الدين الذي احتسب عليه العائد إلا إذا نص القانون أو جرى العرف على غير ذلك.$cc131$, '1999-10-01', 'active' FROM ins_art_law17_1999_64;

WITH ins_art_law17_1999_65 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 65, $cc132$الباب الثاني: الإلتزامات والعقود التجارية$cc132$, $cc133$1- كل صك يكون محله دفع مبلغ من النقود أو تسليم بضائع يجوز تداوله بالتظهير إذا كان لامر الدائن أو بالمناولة إن كان لحامله.
2- يترتب على التظهير الناقل للملكية أو المناولة انتقال جميع الحقوق الناشئة عن الصك إلى حامله الجديد.
3- وفي حالة التظهير الناقل للملكية يضمن المظهر الوفاء بالحق الثابت في الصك في ميعاد الاستحقاق ما لم يتفق على قصر الضمان على وجود الحق وقت التظهير.
4- إذا أنشئ الصك بمناسبة عملية تجارية التزم الموقعون عليه بالتضامن بينهم ما لم ينص القانون أو الاتفاق على غير ذلك.
5- لا يجوز للمدين أن يحتج على حامل الصك بالدفوع المبينة على علاقات شخصية خاصة بمنشئ الصك أو بحامليه السابقين ما لم يكن قصد حامله- وقت حصوله على الصك- الإضرار بالمدين أو كان الدفع يتعلق بنقص أهلية المدين.
6- يجوز للمدين أن يمتنع عن الوفاء بالصك إذا لم يرد إليه مؤشرا عليه بالتخالص.
7- تسري على ضياع الصكوك المشار إليها في هذه المادة الأحكام الخاصة بضياع الأوراق التجارية ما لم ينص القانون على غير ذلك.$cc133$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc133$1- كل صك يكون محله دفع مبلغ من النقود أو تسليم بضائع يجوز تداوله بالتظهير إذا كان لامر الدائن أو بالمناولة إن كان لحامله.
2- يترتب على التظهير الناقل للملكية أو المناولة انتقال جميع الحقوق الناشئة عن الصك إلى حامله الجديد.
3- وفي حالة التظهير الناقل للملكية يضمن المظهر الوفاء بالحق الثابت في الصك في ميعاد الاستحقاق ما لم يتفق على قصر الضمان على وجود الحق وقت التظهير.
4- إذا أنشئ الصك بمناسبة عملية تجارية التزم الموقعون عليه بالتضامن بينهم ما لم ينص القانون أو الاتفاق على غير ذلك.
5- لا يجوز للمدين أن يحتج على حامل الصك بالدفوع المبينة على علاقات شخصية خاصة بمنشئ الصك أو بحامليه السابقين ما لم يكن قصد حامله- وقت حصوله على الصك- الإضرار بالمدين أو كان الدفع يتعلق بنقص أهلية المدين.
6- يجوز للمدين أن يمتنع عن الوفاء بالصك إذا لم يرد إليه مؤشرا عليه بالتخالص.
7- تسري على ضياع الصكوك المشار إليها في هذه المادة الأحكام الخاصة بضياع الأوراق التجارية ما لم ينص القانون على غير ذلك.$cc133$, '1999-10-01', 'active' FROM ins_art_law17_1999_65;

WITH ins_art_law17_1999_66 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 66, $cc134$الباب الثاني: الإلتزامات والعقود التجارية$cc134$, $cc135$1- يعتبر منافسة غير مشروعة كل فعل يخالف العادات والأصول المرعية في المعاملات التجارية، ويدخل في ذلك على وجه الخصوص الاعتداء على علامات الغير أو على اسمه التجاري أو على براءات الاختراع أو على أسراره الصناعية التي يملك حق استثمارها، وتحريض العاملين في متجره على إذاعة أسراره أو ترك العمل عنده وكذلك كل فعل أو ادعاء يكون من شأنه إحداث اللبس في المتجر أو في منتجاته أو في إضعاف الثقة في مالكه أو في القائمين على إدارته أو في منتجاته.
2- كل منافسة غير مشروعة تلزم فاعلها بتعويض الضرر الناجم عنها.وللمحكمة أن تقضى- فضلا عن التعويض- بإزالة الضرر وبنشر ملخص الحكم على نفقة المحكوم عليه في إحدى الصحف اليومية.$cc135$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc135$1- يعتبر منافسة غير مشروعة كل فعل يخالف العادات والأصول المرعية في المعاملات التجارية، ويدخل في ذلك على وجه الخصوص الاعتداء على علامات الغير أو على اسمه التجاري أو على براءات الاختراع أو على أسراره الصناعية التي يملك حق استثمارها، وتحريض العاملين في متجره على إذاعة أسراره أو ترك العمل عنده وكذلك كل فعل أو ادعاء يكون من شأنه إحداث اللبس في المتجر أو في منتجاته أو في إضعاف الثقة في مالكه أو في القائمين على إدارته أو في منتجاته.
2- كل منافسة غير مشروعة تلزم فاعلها بتعويض الضرر الناجم عنها.وللمحكمة أن تقضى- فضلا عن التعويض- بإزالة الضرر وبنشر ملخص الحكم على نفقة المحكوم عليه في إحدى الصحف اليومية.$cc135$, '1999-10-01', 'active' FROM ins_art_law17_1999_66;

WITH ins_art_law17_1999_67 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 67, $cc136$الباب الثاني: الإلتزامات والعقود التجارية$cc136$, $cc137$1- يسأل منتج السلعة وموزعها قبل كل من يلحقه ضرر بدني أو مادي يحدثه المنتج إذا اثبت هذا الشخص أن الضرر نشأ بسبب عيب في المنتج.
2- يكون المنتج معيبا- وعلى وجه الخصوص- إذا لم تراع في تصميمه أو صنعه أو تركيبه أو إعداده للاستهلاك أو حفظه أو تعبئته أو طريقة عرضه أو طريقة استعماله الحيطة الكافية لمنع وقوع الضرر أو للتنبيه إلى احتمال وقوعه.
3- وفي حكم هذه المادة:
(أ) يقصد بلفظ "المنتج" صانع السلعة الذي أعدها في هيئتها النهائية التي عرضت بها في التداول سواء أكانت جميع الأجزاء التي تتركب منها السلعة من صنعه ام استعان بأجزاء من صنع الغير، ولا ينصرف اللفظ إلى تابعي المنتج.
(ب)يقصد بلفظ " الموزع" مستورد السلعة فيها للاتجار للسلعة وتاجر الجملة الذي يقوم بتوزيعها في السوق المحلية على تجار التجزئة ولو قام في الوقت نفسه بعمليات بيع بالتجزئة. كما يشمل اللفظ تاجر التجزئة إذا كان يعلم أو كان من واجبه ان يعلم وقت يعلم بيع السلعة بالعيب الموجود بها، والعبرة في ذلك بما كان يفعله تاجر عادي يمارس بيع سلعة من النوع نفسه لو وجد في الظروف ذاتها.
4- يجوز للمدعى توجيه دعوى المسئولية إلى المنتج أو إلى الموزع أو إليهما معا دون تضامن بينهما، وإذا كان مركز أعمال المنتج أو الموزع موجودا خارج مصر جازت مقاضاته أمام المحكمة المصرية التي يوجد لها بدائرتها فرع أو مصنع أو وكالة أو مكتب.
5- تتقادم دعوى المسئولية بمضي ثلاث سنوات من تاريخ علم المضرور بحدوث الضرر وبالشخص المسئول عنه وتسقط هذه الدعوى بانقضاء خمس عشرة سنة من يوم وقوع العمل غير المشروع.
6- يقع باطلا كل شرط او بيان يكون من شأنه إعفاء المنتج أو الموزع من المسئولية أو تحديدها أو تخفيض مدة تقادمها.$cc137$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
