WITH ins_art_law17_1999_68 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 68, $cc138$الباب الثاني: الإلتزامات والعقود التجارية$cc138$, $cc139$تتقادم الدعوى الناشئة عن التزامات التجار قبل بعضهم البعض والمتعلقة بمعاملاتهم التجارية بمضي سبع سنوات من تاريخ حلول ميعاد الوفاء بالالتزام ما لم ينص القانون على خلاف ذلك وكذلك تسقط بمضي عشر سنوات الأحكام النهائية الصادرة في تلك الدعاوى.$cc139$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc139$تتقادم الدعوى الناشئة عن التزامات التجار قبل بعضهم البعض والمتعلقة بمعاملاتهم التجارية بمضي سبع سنوات من تاريخ حلول ميعاد الوفاء بالالتزام ما لم ينص القانون على خلاف ذلك وكذلك تسقط بمضي عشر سنوات الأحكام النهائية الصادرة في تلك الدعاوى.$cc139$, '1999-10-01', 'active' FROM ins_art_law17_1999_68;

WITH ins_art_law17_1999_69 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 69, $cc140$الباب الثاني: الإلتزامات والعقود التجارية$cc140$, $cc141$1- يجوز إثبات الالتزامات التجارية أيا كانت قيمتها بكافة طرق الإثبات ما لم ينص القانون على غير ذلك.
2- فيما عدا الحالات التي يوجب فيها القانون الإثبات بالكتابة في المواد التجارية يجوز في هذه المواد إثبات عكس ما اشتمل عليه دليل كتابي أو إثبات ما يجاوز هذا الدليل بكافة الطرق.
3- تكون الأوراق العرفية في المواد التجارية حجة على الغير في تاريخها ولو لم يكن هذا التاريخ ثابتا، ما لم يشترط القانون ثبوت التاريخ، ويعتبر التاريخ صحيحا حتى يثبت العكس.$cc141$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc141$1- يجوز إثبات الالتزامات التجارية أيا كانت قيمتها بكافة طرق الإثبات ما لم ينص القانون على غير ذلك.
2- فيما عدا الحالات التي يوجب فيها القانون الإثبات بالكتابة في المواد التجارية يجوز في هذه المواد إثبات عكس ما اشتمل عليه دليل كتابي أو إثبات ما يجاوز هذا الدليل بكافة الطرق.
3- تكون الأوراق العرفية في المواد التجارية حجة على الغير في تاريخها ولو لم يكن هذا التاريخ ثابتا، ما لم يشترط القانون ثبوت التاريخ، ويعتبر التاريخ صحيحا حتى يثبت العكس.$cc141$, '1999-10-01', 'active' FROM ins_art_law17_1999_69;

WITH ins_art_law17_1999_70 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 70, $cc142$الباب الثاني: الإلتزامات والعقود التجارية$cc142$, $cc143$يجوز قبول الدفاتر التجارية للإثبات في الدعاوى المقامة منا لتجار او المقامة عليها متى كانت متعلقة بأعمالهم التجارية، وذلك وفقا للقواعد الآتية:
(أ) تكون البيانات الواردة بالدفاتر حجة على صاحبها، ومع ذلك لا يجوز لمن يريد أن يستخلص من هذه الدفاتر المطابقة لاحكام القانون دليلا لنفسه أن يجزئ ما ورد بها من بيانات.
(ب)تكون البيانات الواردة بالدفاتر المطابقة لاحكام القانون حجة لصاحب هذه الدفاتر على خصمه التاجر، إلا إذا انقضها الخصم ببيانات واردة بدفاتره المطابقة لاحكام القانون أو أقام الدليل بأي طريق آخر على عدم صحتها.
(ج) إذا كانت دفاتر كل من الخصمين مطابقة لأحكام القانون وأسفرت المطابقة بينها عن تناقض بياناتها، وجب على المحكمة أن تطلب دليلا اخر.
(د) إذا اختلفت البيانات الواردة بدفاتر الخصمين وكانت دفاتر أحدهما مطابقة لأحكام القانون ودفاتر الآخر غير مطابقة، فالعبرة بما ورد بالدفاتر المطابقة إلا إذا أقام الخصم الدليل على خلاف ما ورد بها. ويسرى هذا الحكم إذا قدم أحد الخصمين دفاتر مطابقة ولم يقدم الآخر أية دفاتر.$cc143$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc143$يجوز قبول الدفاتر التجارية للإثبات في الدعاوى المقامة منا لتجار او المقامة عليها متى كانت متعلقة بأعمالهم التجارية، وذلك وفقا للقواعد الآتية:
(أ) تكون البيانات الواردة بالدفاتر حجة على صاحبها، ومع ذلك لا يجوز لمن يريد أن يستخلص من هذه الدفاتر المطابقة لاحكام القانون دليلا لنفسه أن يجزئ ما ورد بها من بيانات.
(ب)تكون البيانات الواردة بالدفاتر المطابقة لاحكام القانون حجة لصاحب هذه الدفاتر على خصمه التاجر، إلا إذا انقضها الخصم ببيانات واردة بدفاتره المطابقة لاحكام القانون أو أقام الدليل بأي طريق آخر على عدم صحتها.
(ج) إذا كانت دفاتر كل من الخصمين مطابقة لأحكام القانون وأسفرت المطابقة بينها عن تناقض بياناتها، وجب على المحكمة أن تطلب دليلا اخر.
(د) إذا اختلفت البيانات الواردة بدفاتر الخصمين وكانت دفاتر أحدهما مطابقة لأحكام القانون ودفاتر الآخر غير مطابقة، فالعبرة بما ورد بالدفاتر المطابقة إلا إذا أقام الخصم الدليل على خلاف ما ورد بها. ويسرى هذا الحكم إذا قدم أحد الخصمين دفاتر مطابقة ولم يقدم الآخر أية دفاتر.$cc143$, '1999-10-01', 'active' FROM ins_art_law17_1999_70;

WITH ins_art_law17_1999_71 AS (
