WITH ins_art_law17_1999_72 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 72, $cc146$الباب الثاني: الإلتزامات والعقود التجارية — الفصل الأول: نقل التكنولوجيا$cc146$, $cc147$1- تسرى أحكام هذا الفصل على كل عقد لنقل تكنولوجيا لاستخدامها في جمهورية مصر العربية سواء أكان هذا النقل دوليا يقع عبر الحدود الإقليمية لمصر أم داخليا ولا عبرة في الحالتين لجنسية أطراف الاتفاق أو لمحال إقامتهم.
2- كما تسرى أحكام هذا الفصل على كل اتفاق لنقل التكنولوجيا يبرم بعقد مستقل أو ضمن عقد آخر.$cc147$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc147$1- تسرى أحكام هذا الفصل على كل عقد لنقل تكنولوجيا لاستخدامها في جمهورية مصر العربية سواء أكان هذا النقل دوليا يقع عبر الحدود الإقليمية لمصر أم داخليا ولا عبرة في الحالتين لجنسية أطراف الاتفاق أو لمحال إقامتهم.
2- كما تسرى أحكام هذا الفصل على كل اتفاق لنقل التكنولوجيا يبرم بعقد مستقل أو ضمن عقد آخر.$cc147$, '1999-10-01', 'active' FROM ins_art_law17_1999_72;

WITH ins_art_law17_1999_73 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 73, $cc148$الباب الثاني: الإلتزامات والعقود التجارية — الفصل الأول: نقل التكنولوجيا$cc148$, $cc149$عقد نقل التكنولوجيا اتفاق يتعهد بمقتضاه (مورد التكنولوجيا) بأن ينقل بمقابل معلومات فنية إلى (مستورد التكنولوجيا) لاستخدامها في طريقة فنية خاصة لانتاج سلعة معينة أو تطويرها أو لتركيب أو تشغيل آلات أو أجهزة لتقديم خدمات ولا يعتبر نقلا لتكنولوجيا مجرد بيع أو شراء أو تأجير أو استئجار السلع. ولا بيع العلامات التجارية أو الأسماء التجارية أو الترخيص باستعمالها إلا إذا ورد ذلك كجزء من عقد نقل تكنولوجيا، أو كان مرتبطا به.$cc149$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc149$عقد نقل التكنولوجيا اتفاق يتعهد بمقتضاه (مورد التكنولوجيا) بأن ينقل بمقابل معلومات فنية إلى (مستورد التكنولوجيا) لاستخدامها في طريقة فنية خاصة لانتاج سلعة معينة أو تطويرها أو لتركيب أو تشغيل آلات أو أجهزة لتقديم خدمات ولا يعتبر نقلا لتكنولوجيا مجرد بيع أو شراء أو تأجير أو استئجار السلع. ولا بيع العلامات التجارية أو الأسماء التجارية أو الترخيص باستعمالها إلا إذا ورد ذلك كجزء من عقد نقل تكنولوجيا، أو كان مرتبطا به.$cc149$, '1999-10-01', 'active' FROM ins_art_law17_1999_73;

WITH ins_art_law17_1999_74 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 74, $cc150$الباب الثاني: الإلتزامات والعقود التجارية — الفصل الأول: نقل التكنولوجيا$cc150$, $cc151$1- يجب أن يكون عقد نقل التكنولوجيا مكتوبا وإلا كان باطلا.
2- ويجب أن يشتمل العقد على بيان عناصر المعرفة وتوابعها التي تنتقل إلى مستورد التكنولوجيا.
ويجوز أن يرد هذا البيان مصحوبا بدراسات الجدوى والتعليمات والتصميمات والرسومات الهندسية والخرائط والصور وبرامج الحاسب الآلي وغيرها من الوثائق الموضحة للمعرفة ترفق بالعقد وتعتبر جزءا منه.$cc151$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc151$1- يجب أن يكون عقد نقل التكنولوجيا مكتوبا وإلا كان باطلا.
2- ويجب أن يشتمل العقد على بيان عناصر المعرفة وتوابعها التي تنتقل إلى مستورد التكنولوجيا.
ويجوز أن يرد هذا البيان مصحوبا بدراسات الجدوى والتعليمات والتصميمات والرسومات الهندسية والخرائط والصور وبرامج الحاسب الآلي وغيرها من الوثائق الموضحة للمعرفة ترفق بالعقد وتعتبر جزءا منه.$cc151$, '1999-10-01', 'active' FROM ins_art_law17_1999_74;

WITH ins_art_law17_1999_75 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 75, $cc152$الباب الثاني: الإلتزامات والعقود التجارية — الفصل الأول: نقل التكنولوجيا$cc152$, $cc153$يجوز إبطال كل شرط يرد في عقد نقل التكنولوجيا ويكون من شأنه تقييد حرية المستورد في استخدامها أو تطويرها أو تعريف الإنتاج أو الإعلان عنه. وينطبق ذلك بوجه الخصوص على الشروط التي يكون موضوعها إلزام المستورد بأمر مما يأتي:
(أ) قبول التحسينات التي يدخلها المورد على التكنولوجيا وأداء قيمتها.
(ب)حظر إدخال تحسينات أو تعديلات على التكنولوجيا لتلائم الظروف المحلية أو ظروف منشأة المستورد، وكذلك حظر الحصول على تكنولوجيا أخرى مماثلة أو منافسة للتكنولوجيا محل العقد.
(ج) استعمال علامات تجارية معينة لتمييز السلع التي استخدمت التكنولوجيا في إنتاجها.
(د) تقييد حجم الإنتاج أو ثمنه أو كيفية توزيعه أو تصديره.
(هـ) اشتراك المورد في إدارة منشأة المستورد أو تدخله في اختيار العاملين الدائمين بها.
(و) شراء المواد الخام أو الآلات والمعدات والأجهزة أو قطع الغيار لتشغيل لتكنولوجيا من المورد وحده أو من المنشآت التي يعينها دون غيرها.
(ز) قصر بيع الإنتاج أو التوكيل أو بيعه على المورد أو الأشخاص الذين يعينهم. وذلك كله ما لم يكن أي من هذه الشروط قد وردت في عقد نقل التكنولوجيا بقصد حماية مصلحة مستهلكي المنتج، أو رعاية مصلحة جدية ومشروعة لمورد التكنولوجيا.$cc153$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
