(ج) استعمال علامات تجارية معينة لتمييز السلع التي استخدمت التكنولوجيا في إنتاجها.
(د) تقييد حجم الإنتاج أو ثمنه أو كيفية توزيعه أو تصديره.
(هـ) اشتراك المورد في إدارة منشأة المستورد أو تدخله في اختيار العاملين الدائمين بها.
(و) شراء المواد الخام أو الآلات والمعدات والأجهزة أو قطع الغيار لتشغيل لتكنولوجيا من المورد وحده أو من المنشآت التي يعينها دون غيرها.
(ز) قصر بيع الإنتاج أو التوكيل أو بيعه على المورد أو الأشخاص الذين يعينهم. وذلك كله ما لم يكن أي من هذه الشروط قد وردت في عقد نقل التكنولوجيا بقصد حماية مصلحة مستهلكي المنتج، أو رعاية مصلحة جدية ومشروعة لمورد التكنولوجيا.$cc153$, '1999-10-01', 'active' FROM ins_art_law17_1999_75;

WITH ins_art_law17_1999_76 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 76, $cc154$الباب الثاني: الإلتزامات والعقود التجارية — الفصل الأول: نقل التكنولوجيا$cc154$, $cc155$يلتزم مورد التكنولوجيا بأن يكشف للمستورد في العقد أو خلال المفاوضات التي تسبق إبرامه عما يلي:
(أ) الإخطار التي قد تنشأ عن استخدام التكنولوجيا وعلى وجه الخصوص ما يتعلق منها بالبيئة أو الصحة العامة أو سلامة الأرواح أو الأموال، وعليه أن يطلعه على ما يعلمه من وسائل لاتقاء هذه الأخطار.
(ب) الدعاوى القضائية وغيرها من العقبات التي قد تعوق استخدام الحقوق المتصلة بالتكنولوجيا لا سيما ما يتعلق منها ببراءات الاختراع.
(ج) أحكام القانون المحلي بشأن التصريح بتصدير التكنولوجيا.$cc155$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc155$يلتزم مورد التكنولوجيا بأن يكشف للمستورد في العقد أو خلال المفاوضات التي تسبق إبرامه عما يلي:
(أ) الإخطار التي قد تنشأ عن استخدام التكنولوجيا وعلى وجه الخصوص ما يتعلق منها بالبيئة أو الصحة العامة أو سلامة الأرواح أو الأموال، وعليه أن يطلعه على ما يعلمه من وسائل لاتقاء هذه الأخطار.
(ب) الدعاوى القضائية وغيرها من العقبات التي قد تعوق استخدام الحقوق المتصلة بالتكنولوجيا لا سيما ما يتعلق منها ببراءات الاختراع.
(ج) أحكام القانون المحلي بشأن التصريح بتصدير التكنولوجيا.$cc155$, '1999-10-01', 'active' FROM ins_art_law17_1999_76;

WITH ins_art_law17_1999_77 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 77, $cc156$الباب الثاني: الإلتزامات والعقود التجارية — الفصل الأول: نقل التكنولوجيا$cc156$, $cc157$1- يلتزم المورد بأن يقدم للمستورد المعلومات والبيانات وغيرها من الوثائق الفنية اللازمة لاستيعاب التكنولوجيا، وكذلك ما يطلبه المستورد من الخدمات الفنية اللازمة لتشغيل التكنولوجيا وعلى وجه الخصوص الخبرة والتدريب.
2- كما يلتزم المورد بأن يعلم المستورد بالتحسينات التي قد يدخلها على التكنولوجيا خلال مدة سريان العقد وان ينقل هذه التحسينات إلى المستورد إذا طلب منه ذلك.$cc157$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc157$1- يلتزم المورد بأن يقدم للمستورد المعلومات والبيانات وغيرها من الوثائق الفنية اللازمة لاستيعاب التكنولوجيا، وكذلك ما يطلبه المستورد من الخدمات الفنية اللازمة لتشغيل التكنولوجيا وعلى وجه الخصوص الخبرة والتدريب.
