3- ويجوز أن يكون المقابل كمية معينة من السلعة التي تستخدم التكنولوجيا في إنتاجها أو مادة أولية ينتجها المستورد ويتعهد المستورد بتصديرها إلى المورد.$cc167$, '1999-10-01', 'active' FROM ins_art_law17_1999_82;

