SELECT id, 1, $cc189$1- إذا لم يحدد ميعاد للتسليم. وجب أن يتم التسليم بمجرد إبرام العقد ما لم تستلزم طبيعة المبيع أو يقضى العرف بتحديد ميعاد آخر.
2- فإذا اتفق على أن يكون للمشتري تحديد ميعاد التسليم التزم البائع بالتسليم في الميعاد الذي يحدده المشتري مع مراعاة المدة التي تستلزمها طبيعة المبيع لإعداده للتسليم.$cc189$, '1999-10-01', 'active' FROM ins_art_law17_1999_93;

WITH ins_art_law17_1999_94 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 94, $cc190$الباب الثاني: الإلتزامات والعقود التجارية — الفصل الثاني: البيع التجاري$cc190$, $cc191$1- إذا قام البائع بناء على طلب المشتري بإرسال المبيع إلى غير المكان المعين لتسليمه كانت تبعة الهلاك على المشتري من وقت تسليم المبيع إلى من يتولى نقله، إلا إذا اتفق أو نص القانون على غير ذلك.
2- المصاريف التي يقتضيها تسليم المبيع في غير المكان المعين لتنفيذ البيع تكون على المشترى إلا إذا اتفق أو نص القانون على غير ذلك.
3- إذا خالف البائع دون ضرورة ملجئة تعليمات المشتري بشأن النقل كان مسئولا عما يلحق المبيع من ضرر بسبب هذه المخالفة.$cc191$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc191$1- إذا قام البائع بناء على طلب المشتري بإرسال المبيع إلى غير المكان المعين لتسليمه كانت تبعة الهلاك على المشتري من وقت تسليم المبيع إلى من يتولى نقله، إلا إذا اتفق أو نص القانون على غير ذلك.
2- المصاريف التي يقتضيها تسليم المبيع في غير المكان المعين لتنفيذ البيع تكون على المشترى إلا إذا اتفق أو نص القانون على غير ذلك.
3- إذا خالف البائع دون ضرورة ملجئة تعليمات المشتري بشأن النقل كان مسئولا عما يلحق المبيع من ضرر بسبب هذه المخالفة.$cc191$, '1999-10-01', 'active' FROM ins_art_law17_1999_94;

WITH ins_art_law17_1999_95 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 95, $cc192$الباب الثاني: الإلتزامات والعقود التجارية — الفصل الثاني: البيع التجاري$cc192$, $cc193$لا يعتد عند تسليم المبيع بما يطرأ عليه من نقص أو تلف يقضى العرف بالتسامح فيه.$cc193$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
