WITH ins_art_law17_1999_96 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 96, $cc194$الباب الثاني: الإلتزامات والعقود التجارية — الفصل الثاني: البيع التجاري$cc194$, $cc195$إذا لم يقم البائع بتسليم المبيع في الميعاد المحدد في العقد. فللمشتري أن يخطره بالتنفيذ خلال مدة مناسبة يحددها، فإذا لم يسلم البائع المبيع خلال تلك المدة، جاز للمشتري أن يحصل على شئ مماثل للمبيع على حساب البائع وان يطالبه بالفرق بين الثمن المتفق عليه وما دفعه بحسن نية للحصول على ذلك الشيء.
وإذا كان للمبيع سعر معلوم في السوق جاز للمشتري- وان لم يشتر فعلا شيئا مماثلا له- أن يطالب البائع بالفرق بين الثمن المتفق عليه وسعر السوق في اليوم المحدد للتسليم، وللمشتري بدلا من ذلك أن يخطر البائع بأن عدم التسليم خلال المدة المعينة من الإخطار يترتب عليه اعتبار العقد مفسوخا، وله في هذه الحالة أن يطلب التعويض إن كان له مقتضى.$cc195$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc195$إذا لم يقم البائع بتسليم المبيع في الميعاد المحدد في العقد. فللمشتري أن يخطره بالتنفيذ خلال مدة مناسبة يحددها، فإذا لم يسلم البائع المبيع خلال تلك المدة، جاز للمشتري أن يحصل على شئ مماثل للمبيع على حساب البائع وان يطالبه بالفرق بين الثمن المتفق عليه وما دفعه بحسن نية للحصول على ذلك الشيء.
وإذا كان للمبيع سعر معلوم في السوق جاز للمشتري- وان لم يشتر فعلا شيئا مماثلا له- أن يطالب البائع بالفرق بين الثمن المتفق عليه وسعر السوق في اليوم المحدد للتسليم، وللمشتري بدلا من ذلك أن يخطر البائع بأن عدم التسليم خلال المدة المعينة من الإخطار يترتب عليه اعتبار العقد مفسوخا، وله في هذه الحالة أن يطلب التعويض إن كان له مقتضى.$cc195$, '1999-10-01', 'active' FROM ins_art_law17_1999_96;

WITH ins_art_law17_1999_97 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 97, $cc196$الباب الثاني: الإلتزامات والعقود التجارية — الفصل الثاني: البيع التجاري$cc196$, $cc197$إذا اتفق على تسليم المبيع على دفعات جاز للمشتري أن يطلب الفسخ إذا لم يقم البائع بتسليم إحدى الدفعات في الميعاد المتفق عليه، ولا يسرى الفسخ على الدفعات التي تم تسليمها إلا إذا ترتب على تبعيض المبيع ضرر جسيم للمشتري.$cc197$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc197$إذا اتفق على تسليم المبيع على دفعات جاز للمشتري أن يطلب الفسخ إذا لم يقم البائع بتسليم إحدى الدفعات في الميعاد المتفق عليه، ولا يسرى الفسخ على الدفعات التي تم تسليمها إلا إذا ترتب على تبعيض المبيع ضرر جسيم للمشتري.$cc197$, '1999-10-01', 'active' FROM ins_art_law17_1999_97;

WITH ins_art_law17_1999_98 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 98, $cc198$الباب الثاني: الإلتزامات والعقود التجارية — الفصل الثاني: البيع التجاري$cc198$, $cc199$إذا لم يدفع الثمن في الميعاد المتفق عليه جاز للبائع بعد اعذار المشتري أن يعيد بيع البضاعة للغير فإذا بيعت بحسن نية بثمن اقل من الثمن المتفق عليه كان من حق البائع مطالبة المشتري بالفرق. وإذا كان للبضاعة سعر معلوم في السوق فللبائع- وان لم يقم بإعادة البيع فعلا- أن يطالب المشتري بالفرق بين الثمن المتفق عليه وسعر البضاعة في السوق في اليوم المعين لدفع الثمن.$cc199$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc199$إذا لم يدفع الثمن في الميعاد المتفق عليه جاز للبائع بعد اعذار المشتري أن يعيد بيع البضاعة للغير فإذا بيعت بحسن نية بثمن اقل من الثمن المتفق عليه كان من حق البائع مطالبة المشتري بالفرق. وإذا كان للبضاعة سعر معلوم في السوق فللبائع- وان لم يقم بإعادة البيع فعلا- أن يطالب المشتري بالفرق بين الثمن المتفق عليه وسعر البضاعة في السوق في اليوم المعين لدفع الثمن.$cc199$, '1999-10-01', 'active' FROM ins_art_law17_1999_98;

WITH ins_art_law17_1999_99 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 99, $cc200$الباب الثاني: الإلتزامات والعقود التجارية — الفصل الثاني: البيع التجاري$cc200$, $cc201$1- يجوز للمشتري الذي دفع الثمن بكامله أن يطلب من البائع إعطاءه قائمة مذكورا فيها أن الثمن قد دفع.
2- إذا قبل المشتري صراحة أو ضمنا قائمة البضاعة التي تسلمها من البائع فليس له بعد ذلك الاعتراض على البيانات التي وردت بها. ويعتبر قبولا ضمنيا عدم اعتراض المشتري على القائمة خلال عشرة أيام من تاريخ تسلمها.$cc201$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc201$1- يجوز للمشتري الذي دفع الثمن بكامله أن يطلب من البائع إعطاءه قائمة مذكورا فيها أن الثمن قد دفع.
2- إذا قبل المشتري صراحة أو ضمنا قائمة البضاعة التي تسلمها من البائع فليس له بعد ذلك الاعتراض على البيانات التي وردت بها. ويعتبر قبولا ضمنيا عدم اعتراض المشتري على القائمة خلال عشرة أيام من تاريخ تسلمها.$cc201$, '1999-10-01', 'active' FROM ins_art_law17_1999_99;

WITH ins_art_law17_1999_100 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 100, $cc202$الباب الثاني: الإلتزامات والعقود التجارية — الفصل الثاني: البيع التجاري$cc202$, $cc203$1- إذا رفض المشتري تسلم المبيع جاز للبائع بعد إثبات حالة المبيع أن يطلب بأمر على عريضة من القاضي المختص الإذن في بيعه بعد انقضاء مدة يحددها ويخطر بها المشتري، كما يحدد القاضي كيفية إجراء البيع، ويجوز له أن يأمر ببيع الاشياء القابلة لتلف سريع دون تحديد مهلة أو إخطار.
2- على البائع إيداع حصيلة المبيع خزانة المحكمة حتى يسوى النزاع بينه وبين المشتري إذا كان المشتري قد دفع الثمن بكامله.$cc203$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc203$1- إذا رفض المشتري تسلم المبيع جاز للبائع بعد إثبات حالة المبيع أن يطلب بأمر على عريضة من القاضي المختص الإذن في بيعه بعد انقضاء مدة يحددها ويخطر بها المشتري، كما يحدد القاضي كيفية إجراء البيع، ويجوز له أن يأمر ببيع الاشياء القابلة لتلف سريع دون تحديد مهلة أو إخطار.
2- على البائع إيداع حصيلة المبيع خزانة المحكمة حتى يسوى النزاع بينه وبين المشتري إذا كان المشتري قد دفع الثمن بكامله.$cc203$, '1999-10-01', 'active' FROM ins_art_law17_1999_100;

WITH ins_art_law17_1999_101 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 101, $cc204$الباب الثاني: الإلتزامات والعقود التجارية — الفصل الثاني: البيع التجاري$cc204$, $cc205$1- إذا تبين بعد تسليم المبيع أن كميته أو صنفه اقل مما هو متفق عليه أو أن به عيبا أو انه غير مطابق للشروط أو العينة التي تم العقد بمقتضاها، فلا يقضى للمشتري بالفسخ إلا إذا نشأ عن النقص أو العيب أو عدم المطابقة، عدم صلاحية المبيع للغرض الذي أعده له المشتري أو صعوبة تصريفه، ما لم يوجد اتفاق أو عرف يقضى بوجوب الفسخ، ويكتفي عند رفض طلب الفسخ بإنقاص الثمن دون إخلال بحق المشتري في التعويض.
2- على المشتري أن يخطر البائع بوجود النقص أو العيب أو عدم المطابقة خلال خمسة عشر يوما من تاريخ تسليم المبيع إليه تسليما فعليا، وعليه أن يقيم دعوى الفسخ أو إنقاص الثمن خلال ستين يوما من تاريخ هذا التسليم.
3- إذا لم يقع الإخطار أو لم ترفع الدعوى خلال الميعاد المنصوص عليه في الفقرة السابقة سقط حق المشتري في إقامتها إلا إذا اثبت الغش من جانب البائع.
4- وفي جميع الأحوال تسقط الدعوى بانقضاء ستة اشهر من تاريخ التسليم الفعلي.
5- ويجوز الاتفاق على تعديل المواعيد المنصوص عليها في هذه المادة، كما يجوز اعفاء المشتري من مراعاتها.$cc205$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
