2- على المشتري أن يخطر البائع بوجود النقص أو العيب أو عدم المطابقة خلال خمسة عشر يوما من تاريخ تسليم المبيع إليه تسليما فعليا، وعليه أن يقيم دعوى الفسخ أو إنقاص الثمن خلال ستين يوما من تاريخ هذا التسليم.
3- إذا لم يقع الإخطار أو لم ترفع الدعوى خلال الميعاد المنصوص عليه في الفقرة السابقة سقط حق المشتري في إقامتها إلا إذا اثبت الغش من جانب البائع.
4- وفي جميع الأحوال تسقط الدعوى بانقضاء ستة اشهر من تاريخ التسليم الفعلي.
5- ويجوز الاتفاق على تعديل المواعيد المنصوص عليها في هذه المادة، كما يجوز اعفاء المشتري من مراعاتها.$cc205$, '1999-10-01', 'active' FROM ins_art_law17_1999_101;

WITH ins_art_law17_1999_102 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 102, $cc206$الباب الثاني: الإلتزامات والعقود التجارية — الفصل الثاني: البيع التجاري$cc206$, $cc207$1- إذا تبين بعد تسليم المبيع للمشتري ان كميته تزيد على المقدار المتفق عليه فلا يقضى للبائع باسترداد الزيادة إلا إذا رفض المشتري تكملة الثمن خلال خمسة عشر يوما من تاريخ إخطاره بوجود الزيادة.
2- لا تقبل دعوى البائع باسترداد الزيادة بعد انقضاء ستين يوما من تاريخ تسليم المبيع للمشتري تسليما فعليا.
3- يجوز الاتفاق على تعديل المواعيد المنصوص عليها في هذه المادة، كما يجوز إعفاء البائع من مراعاتها.$cc207$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc207$1- إذا تبين بعد تسليم المبيع للمشتري ان كميته تزيد على المقدار المتفق عليه فلا يقضى للبائع باسترداد الزيادة إلا إذا رفض المشتري تكملة الثمن خلال خمسة عشر يوما من تاريخ إخطاره بوجود الزيادة.
2- لا تقبل دعوى البائع باسترداد الزيادة بعد انقضاء ستين يوما من تاريخ تسليم المبيع للمشتري تسليما فعليا.
3- يجوز الاتفاق على تعديل المواعيد المنصوص عليها في هذه المادة، كما يجوز إعفاء البائع من مراعاتها.$cc207$, '1999-10-01', 'active' FROM ins_art_law17_1999_102;

WITH ins_art_law17_1999_103 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 103, $cc208$الباب الثاني: الإلتزامات والعقود التجارية — الفصل الثاني: البيع التجاري$cc208$, $cc209$1- يجوز الاتفاق على إلزام المشتري بعدم التخفيض عن ثمن معين عند إعادة البيع إذا كان المبيع سلعة تحميها علامة تجارية مسجلة تميزها، ويجوز للمحكمة أن تقضى ببطلان هذا الشرط إذا كان المبيع من السلع الضرورية للاستهلاك الشعبي.
2- لا يلتزم خلفاء المشتري بمراعاة الشرط المشار إليه في الفقرة السابقة إلا إذا علموا به أو كان في مقدورهم العلم به.
