  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc209$1- يجوز الاتفاق على إلزام المشتري بعدم التخفيض عن ثمن معين عند إعادة البيع إذا كان المبيع سلعة تحميها علامة تجارية مسجلة تميزها، ويجوز للمحكمة أن تقضى ببطلان هذا الشرط إذا كان المبيع من السلع الضرورية للاستهلاك الشعبي.
2- لا يلتزم خلفاء المشتري بمراعاة الشرط المشار إليه في الفقرة السابقة إلا إذا علموا به أو كان في مقدورهم العلم به.
الفرع الثاني أحكام خاصة ببعض أنواع البيوع التجارية$cc209$, '1999-10-01', 'active' FROM ins_art_law17_1999_103;

