WITH ins_art_law17_1999_105 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 105, $cc212$الباب الثاني: الإلتزامات والعقود التجارية — الفصل الثاني: البيع التجاري$cc212$, $cc213$1- إذا لم يدفع المشتري أحد أقساط الثمن المتفق عليه فلا يجوز الحكم بفسخ البيع إذا تبين انه قام بتنفيذ خمسة وسبعين في المائة من التزاماته.
2- وفي حالة الحكم بفسخ البيع يجب أن يرد البائع الأقساط التي قبضها بعد استنزال ما يعادل أجرة الانتفاع بالمبيع بالإضافة إلى تعويض عن التلف الذي لحقه بسبب الاستعمال غير العادي، ويقع باطلا كل اتفاق على تحميل المشترى التزامات التزامات اشد من ذلك.
3- الاتفاق على حلول الثمن بأكمله عند عدم دفع أحد الأقساط في ميعاد استحقاقه لا يكون نافذا إلا إذا تخلف المشتري عن دفع قسطين متتاليين على الأقل.$cc213$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc213$1- إذا لم يدفع المشتري أحد أقساط الثمن المتفق عليه فلا يجوز الحكم بفسخ البيع إذا تبين انه قام بتنفيذ خمسة وسبعين في المائة من التزاماته.
2- وفي حالة الحكم بفسخ البيع يجب أن يرد البائع الأقساط التي قبضها بعد استنزال ما يعادل أجرة الانتفاع بالمبيع بالإضافة إلى تعويض عن التلف الذي لحقه بسبب الاستعمال غير العادي، ويقع باطلا كل اتفاق على تحميل المشترى التزامات التزامات اشد من ذلك.
3- الاتفاق على حلول الثمن بأكمله عند عدم دفع أحد الأقساط في ميعاد استحقاقه لا يكون نافذا إلا إذا تخلف المشتري عن دفع قسطين متتاليين على الأقل.$cc213$, '1999-10-01', 'active' FROM ins_art_law17_1999_105;

WITH ins_art_law17_1999_106 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 106, $cc214$الباب الثاني: الإلتزامات والعقود التجارية — الفصل الثاني: البيع التجاري$cc214$, $cc215$1- إذا احتفظ البائع بملكية المبيع حتى أداء أقساط الثمن بأكملها اكتسب المشتري هذه الملكية بأداء القسط الأخير، ويتحمل المشتري تبعة هلاك المبيع من وقت تسليمه إليه.
2- مع عدم الإخلال بالأحكام المنصوص عليها في باب الإفلاس لا يكون شرط الاحتفاظ بالملكية نافذا على الغير إلا إذا كان الشرط مدونا في ورقة ذات تاريخ ثابت وسابق على حق الغير أو على إجراءات التنفيذ التي يتخذها الدائنون على المبيع.$cc215$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc215$1- إذا احتفظ البائع بملكية المبيع حتى أداء أقساط الثمن بأكملها اكتسب المشتري هذه الملكية بأداء القسط الأخير، ويتحمل المشتري تبعة هلاك المبيع من وقت تسليمه إليه.
2- مع عدم الإخلال بالأحكام المنصوص عليها في باب الإفلاس لا يكون شرط الاحتفاظ بالملكية نافذا على الغير إلا إذا كان الشرط مدونا في ورقة ذات تاريخ ثابت وسابق على حق الغير أو على إجراءات التنفيذ التي يتخذها الدائنون على المبيع.$cc215$, '1999-10-01', 'active' FROM ins_art_law17_1999_106;

WITH ins_art_law17_1999_107 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 107, $cc216$الباب الثاني: الإلتزامات والعقود التجارية — الفصل الثاني: البيع التجاري$cc216$, $cc217$1- لا يجوز للمشتري التصرف في المبيع قبل أداء الأقساط بأجمعها إلا بإذن مكتوب من البائع وكل تصرف يجريه المشتري بالمخالفة لهذا الحكم لا يكون نافذا في حق البائع إذا اثبت علم المتصرف إليه وقت إجراء التصرف بعدم أداء الثمن بأكمله.
2- للبائع عند تصرف المشتري في المبيع قبل أداء أقساط الثمن بأكملها وبغير إذن منه أن يطالب المشتري بأداء الأقساط الباقية فورا.
3- يعاقب المشتري عند مخالفة أحكام الفقرة الأولى بالحبس مدة لا تجاوز ستة اشهر وبغرامة لا تجاوز 500 جنيه أو بإحدى هاتين العقوبتين. ويسرى على هذه الجريمة حكم المادة 18 مكرر
(أ) من قانون الإجراءات الجنائية.
وتأمر النيابة العامة بوقف تنفيذ العقوبة إذا تم الصلح أثناء تنفيذها ولو بعد صيرورة الحكم باتا.
٣- البيع بطريق التصفية أو المزايدة العلنية$cc217$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
