2- يعتبر في حكم التصفية الموسمية كل إجراء من شأنه عن الإعلان عن بيع السلع بأسعار مخفضة.$cc219$, '1999-10-01', 'active' FROM ins_art_law17_1999_108;

WITH ins_art_law17_1999_109 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 109, $cc220$الباب الثاني: الإلتزامات والعقود التجارية — الفصل الثاني: البيع التجاري$cc220$, $cc221$لا يجوز للتاجر أن يبيع بطريق المزايدة العلنية السلع غير المستعملة التي يتاجر فيها إلا لاحد الأسباب الآتية بشرط الإعلان عن السبب قبل المزايدة:
(أ) تصفية المتجر نهائيا.
(ب) تصفية أحد فروع المتجر.
(ج) تصفية التجارة في أحد الأصناف التي يتعامل فيها المتجر.
(د) تصفية السلع التي يصيبها عيب بسبب حريق أو تسرب مياه أو غير ذلك من الأسباب.
(ه) حالة التصفية الموسمية، على أن تتم خلال أسبوعين على الأكثر.$cc221$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc221$لا يجوز للتاجر أن يبيع بطريق المزايدة العلنية السلع غير المستعملة التي يتاجر فيها إلا لاحد الأسباب الآتية بشرط الإعلان عن السبب قبل المزايدة:
(أ) تصفية المتجر نهائيا.
(ب) تصفية أحد فروع المتجر.
(ج) تصفية التجارة في أحد الأصناف التي يتعامل فيها المتجر.
(د) تصفية السلع التي يصيبها عيب بسبب حريق أو تسرب مياه أو غير ذلك من الأسباب.
(ه) حالة التصفية الموسمية، على أن تتم خلال أسبوعين على الأكثر.$cc221$, '1999-10-01', 'active' FROM ins_art_law17_1999_109;

WITH ins_art_law17_1999_110 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 110, $cc222$الباب الثاني: الإلتزامات والعقود التجارية — الفصل الثاني: البيع التجاري$cc222$, $cc223$1- لا يجوز بيع السلع المستعملة بالمزايدة العلنية إلا بواسطة خبير مثمن مقيد في السجل الخاص.
2- يقصد بالبيع بالمزايدة العلنة كل بيع اختياري يجوز لكل شخص حضوره ولو اشترط لحضور المزايدة دفع مقابل أو اقتصر الحضور على طائفة معينة من الأشخاص.$cc223$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc223$1- لا يجوز بيع السلع المستعملة بالمزايدة العلنية إلا بواسطة خبير مثمن مقيد في السجل الخاص.
2- يقصد بالبيع بالمزايدة العلنة كل بيع اختياري يجوز لكل شخص حضوره ولو اشترط لحضور المزايدة دفع مقابل أو اقتصر الحضور على طائفة معينة من الأشخاص.$cc223$, '1999-10-01', 'active' FROM ins_art_law17_1999_110;

WITH ins_art_law17_1999_111 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 111, $cc224$الباب الثاني: الإلتزامات والعقود التجارية — الفصل الثاني: البيع التجاري$cc224$, $cc225$1- على المشتري الذي ترسو عليه المزايدة أن يدفع نصف الثمن في جلسة المزايدة وان يدفع الباقي عند تسليم المبيع إليه، ويجب أن يتم التسليم خلال ثلاثة أيام من تاريخ انتهاء المزايدة، ما لم تتضمن شروط طالب البيع خلاف ذلك.
2- إذا لم يدفع المشتري الباقي من الثمن أو إذا لم يحضر لتسلم المبيع في الميعاد المشار إليه في الفقرة السابقة وجب إعادة البيع على مسئوليته بطريق المزايدة العلنية أيضا ولا تقبل المزايدة منه.
3- إذا رست المزايدة الثانية بثمن اقل من الثمن في المزايدة الأولى التزم المشتري المتخلف عن الدفع بالفرق، وإذا رست المزايدة الثانية بثمن اكبر، فالزيادة لطالب البيع.$cc225$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc225$1- على المشتري الذي ترسو عليه المزايدة أن يدفع نصف الثمن في جلسة المزايدة وان يدفع الباقي عند تسليم المبيع إليه، ويجب أن يتم التسليم خلال ثلاثة أيام من تاريخ انتهاء المزايدة، ما لم تتضمن شروط طالب البيع خلاف ذلك.
2- إذا لم يدفع المشتري الباقي من الثمن أو إذا لم يحضر لتسلم المبيع في الميعاد المشار إليه في الفقرة السابقة وجب إعادة البيع على مسئوليته بطريق المزايدة العلنية أيضا ولا تقبل المزايدة منه.
3- إذا رست المزايدة الثانية بثمن اقل من الثمن في المزايدة الأولى التزم المشتري المتخلف عن الدفع بالفرق، وإذا رست المزايدة الثانية بثمن اكبر، فالزيادة لطالب البيع.$cc225$, '1999-10-01', 'active' FROM ins_art_law17_1999_111;

