SELECT id, 1, $cc241$مع مراعاة الأحكام التي تنظم أنواعا خاصة من الرهن التجاري تسرى أحكام هذا الأصل على كل رهن يتقرر على مال منقول ضمانا لدين يعتبر تجاريا بالنسبة إلى المدين.$cc241$, '1999-10-01', 'active' FROM ins_art_law17_1999_119;

WITH ins_art_law17_1999_120 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 120, $cc242$الباب الثاني: الإلتزامات والعقود التجارية — الفصل الثالث: الرهن التجاري$cc242$, $cc243$1- يشترط لنفاذ الرهن في حق الغير أن تنتقل حيازة الشيء المرهون إلى الدائن المرتهن أو إلى عدل يعينه المتعاقدان وان يبقى الشيء المرهون في حيازة من تسلمه منهما حتى انقضاء الرهن.
2- يكون الدائن المرتهن أو العدل حائزا للشيء المرهون في الحالات الآتية:
(أ) إذا وضع تحت تصرفه بكيفية تحمل الغير على الاعتقاد إن الشيء صار في حراسته.
(ب) إذا تسلم صكا يمثل الشيء المرهون ويعطي حائزه دون غيره حق تسلمه.
3- تنتقل حيازة الحقوق الثابتة بتسليم الصكوك الثابتة فيها، وإذا كان الصك مودعا عند الغير اعتبر تسليم إيصال الإيداع بمثابة تسليم الصك ذاته بشرط أن يكون الصك معينا في الإيصال تعيينا نافيا للجهالة وان يرضى المودع عنده بحيازة الصك لحساب الدائن المرتهن، وفي هذه الحالة يعتبر المودع عنده قد تخلى عن كل حق له في حبس الصك لحسابه لسبب سابق على الرهن ما لم يكن قد احتفظ بهذا الحق عند قبوله حيازة الصك لحساب الدائن المرتهن.$cc243$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
