2- وإذا كان الشيء المرهون من الأموال غير المثلية جاز للمدين أن يستبدل به غيره بشرط أن يكون متفقا على ذلك في عقد الرهن وان يقبل الدائن المرتهن البدل.$cc251$, '1999-10-01', 'active' FROM ins_art_law17_1999_124;

WITH ins_art_law17_1999_125 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 125, $cc252$الباب الثاني: الإلتزامات والعقود التجارية — الفصل الثالث: الرهن التجاري$cc252$, $cc253$على الدائن المرتهن أن يقوم بجميع التدابير والإجراءات اللازمة للمحافظة على الشيء المرهون وصيانته، وعليه أن يستوفي لحساب المدين الحقوق المتصلة بالشيء كقبض قيمته وتوابعه على أن يخصم ما يقبضه من المبلغ المضمون بالرهن ولو لم يكن قد حل اجله، ويكون الخصم أولا من قيمة ما أنفقه في المحافظة على الشئ وصيانته من المصاريف ثم من العوائد ثم من اصل الدين ما لم يتفق على غير ذلك.$cc253$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc253$على الدائن المرتهن أن يقوم بجميع التدابير والإجراءات اللازمة للمحافظة على الشيء المرهون وصيانته، وعليه أن يستوفي لحساب المدين الحقوق المتصلة بالشيء كقبض قيمته وتوابعه على أن يخصم ما يقبضه من المبلغ المضمون بالرهن ولو لم يكن قد حل اجله، ويكون الخصم أولا من قيمة ما أنفقه في المحافظة على الشئ وصيانته من المصاريف ثم من العوائد ثم من اصل الدين ما لم يتفق على غير ذلك.$cc253$, '1999-10-01', 'active' FROM ins_art_law17_1999_125;

WITH ins_art_law17_1999_126 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 126, $cc254$الباب الثاني: الإلتزامات والعقود التجارية — الفصل الثالث: الرهن التجاري$cc254$, $cc255$1- إذا لم يدفع المدين الدين المضمون بالرهن في ميعاد استحقاقه كان للدائن المرتهن بعد انقضاء خمسة أيام من تاريخ تكليف المدين بالوفاء أن يطلب بعريضة تقدم إلى القاضي المختص بالمحكمة التي يقع في دائرتها موطنه الأمر ببيع الشيء المرهون كله أو بعضه.
2- لا يجوز تنفيذ الأمر الصادر من القاضي ببيع الشيء المرهون إلا بعد انقضاء خمسة أيام من تاريخ تبليغه إلى المدين والكفيل إن وجد مع بيان المكان الذي يجري فيه البيع وتاريخه وساعته.
3- يجري البيع في الزمان والمكان الذين عينهما القاضي وبالمزايدة العلنية إلا إذا أمر القاضي باتباع طريقة أخرى وإذا كان الشيء المرهون متداولا في سوق الأوراق المالية أمر القاضي ببيعه في هذه السوق بمعرفة أحد السماسرة المقبولين للعمل بها.
4- يستوفي الدائن المرتهن دينه بطريق الأولوية من اصل وعائد ومصاريف من الثمن الناتج من البيع.$cc255$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
