4- يستوفي الدائن المرتهن دينه بطريق الأولوية من اصل وعائد ومصاريف من الثمن الناتج من البيع.$cc255$, '1999-10-01', 'active' FROM ins_art_law17_1999_126;

WITH ins_art_law17_1999_127 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 127, $cc256$الباب الثاني: الإلتزامات والعقود التجارية — الفصل الثالث: الرهن التجاري$cc256$, $cc257$إذا تقرر الرهن على عدة أموال، كان من حق الدائن المرتهن تعيين المال الذي يجري عليه البيع ما لم يتفق على غير ذلك أو كان من شأنه إلحاق ضرر بالمدين. وفي جميع الأحوال لا يجوز أن يشمل البيع إلا ما يكفي للوفاء بحق الدائن المرتهن.$cc257$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc257$إذا تقرر الرهن على عدة أموال، كان من حق الدائن المرتهن تعيين المال الذي يجري عليه البيع ما لم يتفق على غير ذلك أو كان من شأنه إلحاق ضرر بالمدين. وفي جميع الأحوال لا يجوز أن يشمل البيع إلا ما يكفي للوفاء بحق الدائن المرتهن.$cc257$, '1999-10-01', 'active' FROM ins_art_law17_1999_127;

WITH ins_art_law17_1999_128 AS (
