SELECT id, 1, $cc261$يكون باطلا كل اتفاق يبرم وقت تقرير الرهن أو بعد تقريره يعطى الدائن المرتهن في حالة عدم استيفاء الدين عند حلول أجله الحق في تملك الشيء المرهون أو في بيعه دون مراعاة الإجراءات المنصوص عليها في المادة (126) من هذا القانون.$cc261$, '1999-10-01', 'active' FROM ins_art_law17_1999_129;

WITH ins_art_law17_1999_130 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 130, $cc262$الباب الثاني: الإلتزامات والعقود التجارية — الفصل الرابع: الإيداع في المستودعات العامة$cc262$, $cc263$1- الإيداع في المستودعات العامة عقد يتعهد بمقتضاه مستثمر المستودع بتسلم بضاعة لحفظها لحساب المودع أو لحساب من تؤول إليه ملكيتها أو حيازتها أو بمقتضى الصكوك التي تمثلها.
2- لا يجوز إنشاء أو استثمار مستودع عام له حق إصدار صكوك تمثل البضائع المودعة وتكون قابلة للتداول. إلا بترخيص من الجهة الإدارية المختصة وفقا للشروط والأوضاع التي يصدر بها قرار منها.
3- تراعى في تطبيق أحكام هذا الفصل على إيداع بضائع لم تدفع عنها الضرائب أو الرسوم الجمركية، الأحكام المنصوص عليها في القوانين الخاصة بذلك والقرارات الصادرة بتنفيذها.
4- لا يعتبر مستودعا عاما خاضعا للأحكام المنصوص عليها في هذا الفصل منشأة الاستيداع التي لا يكون من حقها إصدار صكوك تمثل البضاعة تكون قابلة للتداول.$cc263$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc263$1- الإيداع في المستودعات العامة عقد يتعهد بمقتضاه مستثمر المستودع بتسلم بضاعة لحفظها لحساب المودع أو لحساب من تؤول إليه ملكيتها أو حيازتها أو بمقتضى الصكوك التي تمثلها.
2- لا يجوز إنشاء أو استثمار مستودع عام له حق إصدار صكوك تمثل البضائع المودعة وتكون قابلة للتداول. إلا بترخيص من الجهة الإدارية المختصة وفقا للشروط والأوضاع التي يصدر بها قرار منها.
3- تراعى في تطبيق أحكام هذا الفصل على إيداع بضائع لم تدفع عنها الضرائب أو الرسوم الجمركية، الأحكام المنصوص عليها في القوانين الخاصة بذلك والقرارات الصادرة بتنفيذها.
4- لا يعتبر مستودعا عاما خاضعا للأحكام المنصوص عليها في هذا الفصل منشأة الاستيداع التي لا يكون من حقها إصدار صكوك تمثل البضاعة تكون قابلة للتداول.$cc263$, '1999-10-01', 'active' FROM ins_art_law17_1999_130;

WITH ins_art_law17_1999_131 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 131, $cc264$الباب الثاني: الإلتزامات والعقود التجارية — الفصل الرابع: الإيداع في المستودعات العامة$cc264$, $cc265$1- يجب على من يستثمر مستودعا عاما أن يؤمن عليه ضد أخطار الحريق لدى إحدى شركات التأمين ويشمل هذا التأمين البضائع الموجودة بالمستودع لحساب الغير.
2- ومع ذلك لا يشمل التأمين البضائع المودعة أحد المستودعات العامة الموجودة في ميناء بحري أو ميناء جوي إذا كانت البضاعة مشمولة أيضا بتأمين بحري أو جوي ضد أخطار الحريق فإذا وقع الحادث خلال سريان التأمين البحري أو الجوي كان هذا التأمين وحده هو الواجب تطبيقه لتسوية التعويضات، ولا تصير البضاعة مشمولة بالتأمين على المستودع إلا بعد انقضاء مدة سريان التأمين البحري أو الجوي أو عدم كفاية هذا التأمين لتغطية الضرر.$cc265$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc265$1- يجب على من يستثمر مستودعا عاما أن يؤمن عليه ضد أخطار الحريق لدى إحدى شركات التأمين ويشمل هذا التأمين البضائع الموجودة بالمستودع لحساب الغير.
2- ومع ذلك لا يشمل التأمين البضائع المودعة أحد المستودعات العامة الموجودة في ميناء بحري أو ميناء جوي إذا كانت البضاعة مشمولة أيضا بتأمين بحري أو جوي ضد أخطار الحريق فإذا وقع الحادث خلال سريان التأمين البحري أو الجوي كان هذا التأمين وحده هو الواجب تطبيقه لتسوية التعويضات، ولا تصير البضاعة مشمولة بالتأمين على المستودع إلا بعد انقضاء مدة سريان التأمين البحري أو الجوي أو عدم كفاية هذا التأمين لتغطية الضرر.$cc265$, '1999-10-01', 'active' FROM ins_art_law17_1999_131;

WITH ins_art_law17_1999_132 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 132, $cc266$الباب الثاني: الإلتزامات والعقود التجارية — الفصل الرابع: الإيداع في المستودعات العامة$cc266$, $cc267$1- يلتزم المودع بأن يقدم إلى المستودع العام بيانات صحيحة عن طبيعة البضاعة المودعة ونوعها ومقدارها وقيمتها.
2- وللمودع في كل وقت الحق في فحص البضاعة التي سلمت للمستودع لحسابه واخذ عينات منها وتمكين الغير من ذلك.$cc267$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
