INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc271$لمستثمر المستودع أن يطلب من القاضي المختص بالمحكمة التي يقع في دائرتها المستودع، إصدار أمر على عريضة ببيع البضاعة المودعة إذا كانت مهددة بتلف سريع ويعين القاضي كيفية إجراء البيع والتصرف في الثمن.$cc271$, '1999-10-01', 'active' FROM ins_art_law17_1999_134;

WITH ins_art_law17_1999_135 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 135, $cc272$الباب الثاني: الإلتزامات والعقود التجارية — الفصل الرابع: الإيداع في المستودعات العامة$cc272$, $cc273$1- يجوز للمودع التعامل على البضاعة المودعة بالبيع والرهن وغيرها من التصرفات بموجب الصكوك التي يصدرها المستودع العام.
2- ويجوز لمستثمر المستودع أن يقدم قروضا للمودع برهن البضاعة المودعة لديه وله ان يتعامل بصك الرهن الذي يمثلها.
3- لا يجوز رهن البضائع المودعة في المستودعات العامة او التنفيذ عليها وفاء للدين المرهون إلا باتباع الأحكام المنصوص عليها في شأن الرهن التجاري.$cc273$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc273$1- يجوز للمودع التعامل على البضاعة المودعة بالبيع والرهن وغيرها من التصرفات بموجب الصكوك التي يصدرها المستودع العام.
2- ويجوز لمستثمر المستودع أن يقدم قروضا للمودع برهن البضاعة المودعة لديه وله ان يتعامل بصك الرهن الذي يمثلها.
3- لا يجوز رهن البضائع المودعة في المستودعات العامة او التنفيذ عليها وفاء للدين المرهون إلا باتباع الأحكام المنصوص عليها في شأن الرهن التجاري.$cc273$, '1999-10-01', 'active' FROM ins_art_law17_1999_135;

WITH ins_art_law17_1999_136 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 136, $cc274$الباب الثاني: الإلتزامات والعقود التجارية — الفصل الرابع: الإيداع في المستودعات العامة$cc274$, $cc275$1- يتسلم المودع إيصال إيداع يبين فيه اسمه ومهنته وموطنه ونوع البضاعة وطبيعتها وكميتها وغير ذلك من البيانات اللازمة لتعيين ذاتيتها وقيمتها واسم المستودع المودعة فيه واسم الشركة المؤمنة على المستودع وما إذا كانت قد دفعت عنها الرسوم والضرائب المستحقة من عدمه.
2- يرفق بإيصال الإيداع صك رهن يشتمل على جميع البيانات المذكورة في إيصال الإيداع.
3- للمودع تجزئة البضاعة إلى مجموعات متعددة والحصول على إيصال إيداع وصك رهن عن كل مجموعة منها.
4- يحتفظ المستودع بصورة طبق الأصل من إيصال الإيداع وصك الرهن.$cc275$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc275$1- يتسلم المودع إيصال إيداع يبين فيه اسمه ومهنته وموطنه ونوع البضاعة وطبيعتها وكميتها وغير ذلك من البيانات اللازمة لتعيين ذاتيتها وقيمتها واسم المستودع المودعة فيه واسم الشركة المؤمنة على المستودع وما إذا كانت قد دفعت عنها الرسوم والضرائب المستحقة من عدمه.
2- يرفق بإيصال الإيداع صك رهن يشتمل على جميع البيانات المذكورة في إيصال الإيداع.
3- للمودع تجزئة البضاعة إلى مجموعات متعددة والحصول على إيصال إيداع وصك رهن عن كل مجموعة منها.
4- يحتفظ المستودع بصورة طبق الأصل من إيصال الإيداع وصك الرهن.$cc275$, '1999-10-01', 'active' FROM ins_art_law17_1999_136;

WITH ins_art_law17_1999_137 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 137, $cc276$الباب الثاني: الإلتزامات والعقود التجارية — الفصل الرابع: الإيداع في المستودعات العامة$cc276$, $cc277$1- إذا كانت البضاعة المودعة والمسلم عنها إيصال إيداع وصك رهن من الاشياء المثلية جاز للمودع أن يستبدل بها بضاعة أخرى من نوعها وصفتها إذا كان منصوصا على ذلك في إيصال الإيداع وصك الرهن، وفي هذه الحالة تنتقل جميع حقوق حامل الإيصال أو الصك وامتيازاته إلى البضاعة الجديدة.
2- يجوز أن يصدر إيصال الإيداع وصك الرهن عن كمية من البضاعة المثلية سائبة في كمية اكبر.$cc277$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc277$1- إذا كانت البضاعة المودعة والمسلم عنها إيصال إيداع وصك رهن من الاشياء المثلية جاز للمودع أن يستبدل بها بضاعة أخرى من نوعها وصفتها إذا كان منصوصا على ذلك في إيصال الإيداع وصك الرهن، وفي هذه الحالة تنتقل جميع حقوق حامل الإيصال أو الصك وامتيازاته إلى البضاعة الجديدة.
2- يجوز أن يصدر إيصال الإيداع وصك الرهن عن كمية من البضاعة المثلية سائبة في كمية اكبر.$cc277$, '1999-10-01', 'active' FROM ins_art_law17_1999_137;

WITH ins_art_law17_1999_138 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 138, $cc278$الباب الثاني: الإلتزامات والعقود التجارية — الفصل الرابع: الإيداع في المستودعات العامة$cc278$, $cc279$1- يجوز أن يصدر إيصال الإيداع أو صك الرهن باسم المودع أو لأمره.
2- إذا كان إيصال الإيداع أو صك الرهن لامر المودع جاز له أن يتنازل بالتظهير عنهما متصلين أو منفصلين.
3- يجوز لمن ظهر له إيصال إيداع أو صك رهن أن يطلب قيد التظهير الذي حصل له مع بيان موطنه في دفاتر المستودع.$cc279$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc279$1- يجوز أن يصدر إيصال الإيداع أو صك الرهن باسم المودع أو لأمره.
2- إذا كان إيصال الإيداع أو صك الرهن لامر المودع جاز له أن يتنازل بالتظهير عنهما متصلين أو منفصلين.
3- يجوز لمن ظهر له إيصال إيداع أو صك رهن أن يطلب قيد التظهير الذي حصل له مع بيان موطنه في دفاتر المستودع.$cc279$, '1999-10-01', 'active' FROM ins_art_law17_1999_138;

WITH ins_art_law17_1999_139 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 139, $cc280$الباب الثاني: الإلتزامات والعقود التجارية — الفصل الرابع: الإيداع في المستودعات العامة$cc280$, $cc281$1- يجب أن يكون تظهير إيصال الإيداع أو صك الرهن مؤرخا ومشتملا على توقيع المظهر.
2- وإذا ظهر صك الرهن منفصلا عن إيصال الإيداع وجب أن يشمل التظهير بالإضافة إلى البيانات المنصوص عليها في الفقرة السابقة على بيان بمبلغ الدين المضمون بالرهن من اصل وعائد وتاريخ استحقاقه واسم الدائن ومهنته وموطنه، وعلى المظهر إليه الأول أن يبادر إلى طلب قيد تظهير صك الرهن وبيانات هذا التظهير في دفاتر المستودع والتأشير بذلك على صك الرهن.
3- على المظهر إليه الأول عند تظهير صك الرهن أن يطلب قيد تظهير صك الرهن والبيانات المتعلقة بالتظهير في دفاتر المستودع والتأشير بذلك على صك الرهن.$cc281$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc281$1- يجب أن يكون تظهير إيصال الإيداع أو صك الرهن مؤرخا ومشتملا على توقيع المظهر.
2- وإذا ظهر صك الرهن منفصلا عن إيصال الإيداع وجب أن يشمل التظهير بالإضافة إلى البيانات المنصوص عليها في الفقرة السابقة على بيان بمبلغ الدين المضمون بالرهن من اصل وعائد وتاريخ استحقاقه واسم الدائن ومهنته وموطنه، وعلى المظهر إليه الأول أن يبادر إلى طلب قيد تظهير صك الرهن وبيانات هذا التظهير في دفاتر المستودع والتأشير بذلك على صك الرهن.
3- على المظهر إليه الأول عند تظهير صك الرهن أن يطلب قيد تظهير صك الرهن والبيانات المتعلقة بالتظهير في دفاتر المستودع والتأشير بذلك على صك الرهن.$cc281$, '1999-10-01', 'active' FROM ins_art_law17_1999_139;

WITH ins_art_law17_1999_140 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 140, $cc282$الباب الثاني: الإلتزامات والعقود التجارية — الفصل الرابع: الإيداع في المستودعات العامة$cc282$, $cc283$1- لحامل صك الرهن دون إيصال الإيداع حق رهن على البضاعة المودعة.
2- ولحامل إيصال الإيداع دون صك الرهن حق سحب البضاعة المودعة بشرط أن يدفع الدين المضمون بالرهن إذا كان مستحق الأداء فإذا لم يكن الدين مستحق الأداء، جاز له سحب البضاعة قبل حلول ميعاد استحقاق الدين إذا أودع المستودع مبلغا كافيا لتغطية الدين وعوائده حتى حلول الأجل. ويسرى هذا الحكم إذا استحق الدين ولم يتقدم حامل صك الرهن لقبضه.
3- ويجوز أن يقتصر السحب على جزء من البضاعة بعد إيداع مبلغ يتناسب مع هذا الجزء.$cc283$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc283$1- لحامل صك الرهن دون إيصال الإيداع حق رهن على البضاعة المودعة.
2- ولحامل إيصال الإيداع دون صك الرهن حق سحب البضاعة المودعة بشرط أن يدفع الدين المضمون بالرهن إذا كان مستحق الأداء فإذا لم يكن الدين مستحق الأداء، جاز له سحب البضاعة قبل حلول ميعاد استحقاق الدين إذا أودع المستودع مبلغا كافيا لتغطية الدين وعوائده حتى حلول الأجل. ويسرى هذا الحكم إذا استحق الدين ولم يتقدم حامل صك الرهن لقبضه.
3- ويجوز أن يقتصر السحب على جزء من البضاعة بعد إيداع مبلغ يتناسب مع هذا الجزء.$cc283$, '1999-10-01', 'active' FROM ins_art_law17_1999_140;

WITH ins_art_law17_1999_141 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 141, $cc284$الباب الثاني: الإلتزامات والعقود التجارية — الفصل الرابع: الإيداع في المستودعات العامة$cc284$, $cc285$إذا لم يدفع الدين المضمون بالرهن في ميعاد الاستحقاق جاز لحامل صك الرهن منفصلا عن إيصال الإيداع أن يطلب بيع البضاعة المرهونة باتباع الإجراءات المنصوص عليها في شأن الرهن التجاري.$cc285$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc285$إذا لم يدفع الدين المضمون بالرهن في ميعاد الاستحقاق جاز لحامل صك الرهن منفصلا عن إيصال الإيداع أن يطلب بيع البضاعة المرهونة باتباع الإجراءات المنصوص عليها في شأن الرهن التجاري.$cc285$, '1999-10-01', 'active' FROM ins_art_law17_1999_141;

WITH ins_art_law17_1999_142 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 142, $cc286$الباب الثاني: الإلتزامات والعقود التجارية — الفصل الرابع: الإيداع في المستودعات العامة$cc286$, $cc287$1- يستوفى الدائن المرتهن حقه من ثمن البضاعة بالأولوية على الدائنين العاديين بعد خصم المبالغ الآتية:
(أ) الضرائب والرسوم المستحقة على البضاعة.
(ب) مصاريف بيع البضاعة وإيداعها وغير ذلك من مصاريف الحفظ.
2- إذا لم يكن حامل إيصال الإيداع حاضرا وقت بيع البضاعة أودع المبلغ الزائد على ما يستحقه حامل صك الرهن خزانة المحكمة الجزئية التي يقع في دائرتها المستودع.$cc287$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc287$1- يستوفى الدائن المرتهن حقه من ثمن البضاعة بالأولوية على الدائنين العاديين بعد خصم المبالغ الآتية:
(أ) الضرائب والرسوم المستحقة على البضاعة.
(ب) مصاريف بيع البضاعة وإيداعها وغير ذلك من مصاريف الحفظ.
2- إذا لم يكن حامل إيصال الإيداع حاضرا وقت بيع البضاعة أودع المبلغ الزائد على ما يستحقه حامل صك الرهن خزانة المحكمة الجزئية التي يقع في دائرتها المستودع.$cc287$, '1999-10-01', 'active' FROM ins_art_law17_1999_142;

WITH ins_art_law17_1999_143 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 143, $cc288$الباب الثاني: الإلتزامات والعقود التجارية — الفصل الرابع: الإيداع في المستودعات العامة$cc288$, $cc289$1- لا يجوز لحامل صك الرهن الرجوع على المدين أو المظهرين إلا بعد التنفيذ على البضاعة المرهونة وثبوت عدم كفاية حصيلة البيع للوفاء بدينه.
2- يكون الرجوع على المظهرين خلال خمسة عشر يوما من تاريخ بيع البضاعة وإلا سقط حق الحامل في الرجوع.
3- وفي جميع الأحوال يسقط حق حامل صك الرهن في الرجوع على المظهرين إذا لم يباشر إجراءات التنفيذ على البضاعة المرهونة خلال ثلاثين يوما من تاريخ استحقاق الدين.$cc289$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc289$1- لا يجوز لحامل صك الرهن الرجوع على المدين أو المظهرين إلا بعد التنفيذ على البضاعة المرهونة وثبوت عدم كفاية حصيلة البيع للوفاء بدينه.
2- يكون الرجوع على المظهرين خلال خمسة عشر يوما من تاريخ بيع البضاعة وإلا سقط حق الحامل في الرجوع.
3- وفي جميع الأحوال يسقط حق حامل صك الرهن في الرجوع على المظهرين إذا لم يباشر إجراءات التنفيذ على البضاعة المرهونة خلال ثلاثين يوما من تاريخ استحقاق الدين.$cc289$, '1999-10-01', 'active' FROM ins_art_law17_1999_143;

WITH ins_art_law17_1999_144 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 144, $cc290$الباب الثاني: الإلتزامات والعقود التجارية — الفصل الرابع: الإيداع في المستودعات العامة$cc290$, $cc291$إذا وقع حادث للبضاعة كان لحامل إيصال الإيداع أو صك الرهن على مبلغ التأمين الذي يستحق عند وقوع هذا الحادث جميع الحقوق المقررة له على البضاعة.$cc291$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc291$إذا وقع حادث للبضاعة كان لحامل إيصال الإيداع أو صك الرهن على مبلغ التأمين الذي يستحق عند وقوع هذا الحادث جميع الحقوق المقررة له على البضاعة.$cc291$, '1999-10-01', 'active' FROM ins_art_law17_1999_144;

WITH ins_art_law17_1999_145 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 145, $cc292$الباب الثاني: الإلتزامات والعقود التجارية — الفصل الرابع: الإيداع في المستودعات العامة$cc292$, $cc293$1- لمن ضاع أو تلف منه إيصال الإيداع أن يطلب من القاضي المختص بالمحكمة التي يقع في دائرتها المستودع إصدار أمر على عريضة بتسليمه صورة من الإيصال الضائع أو التالف بشرط أن يثبت ملكيته له مع تقديم كفيل، وتبرأ ذمة هذا الكفيل بانقضاء ستة اشهر من تاريخ تقديم الكفالة دون أن يتقدم أحد بطلب استرداد البضاعة المبيعة.
2- لمن ضاع منه صك الرهن أن يطلب من القاضي المختص بالمحكمة التي يقع في دائرتها المستودع إصدار أمر على عريضة بوفاء الدين المضمون بالرهن عند حلول اجله بشرط أن يثبت ملكيته للصك الضائع، وان يقدم كفيلا. فإذا لم يقم المدين بتنفيذ الأمر الذي صدر لمن صدر هذا الأمر لصالحه أن ينفذ على البضاعة المرهونة باتباع الإجراءات المنصوص عليها بشأن الرهن التجاري، وذلك بشرط أن يكون التظهير الأول الذي حصل على الصك قد قيد في دفاتر المستودع وفقا لأحكام الفقرة الثانية من المادة (139) من هذا القانون وتبرأ ذمة الكفيل بانقضاء ستة اشهر من تاريخ استحقاق الدين دون أن يتخذ من صدر الأمر لصالحه إجراءات التنفيذ على البضاعة.$cc293$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc293$1- لمن ضاع أو تلف منه إيصال الإيداع أن يطلب من القاضي المختص بالمحكمة التي يقع في دائرتها المستودع إصدار أمر على عريضة بتسليمه صورة من الإيصال الضائع أو التالف بشرط أن يثبت ملكيته له مع تقديم كفيل، وتبرأ ذمة هذا الكفيل بانقضاء ستة اشهر من تاريخ تقديم الكفالة دون أن يتقدم أحد بطلب استرداد البضاعة المبيعة.
2- لمن ضاع منه صك الرهن أن يطلب من القاضي المختص بالمحكمة التي يقع في دائرتها المستودع إصدار أمر على عريضة بوفاء الدين المضمون بالرهن عند حلول اجله بشرط أن يثبت ملكيته للصك الضائع، وان يقدم كفيلا. فإذا لم يقم المدين بتنفيذ الأمر الذي صدر لمن صدر هذا الأمر لصالحه أن ينفذ على البضاعة المرهونة باتباع الإجراءات المنصوص عليها بشأن الرهن التجاري، وذلك بشرط أن يكون التظهير الأول الذي حصل على الصك قد قيد في دفاتر المستودع وفقا لأحكام الفقرة الثانية من المادة (139) من هذا القانون وتبرأ ذمة الكفيل بانقضاء ستة اشهر من تاريخ استحقاق الدين دون أن يتخذ من صدر الأمر لصالحه إجراءات التنفيذ على البضاعة.$cc293$, '1999-10-01', 'active' FROM ins_art_law17_1999_145;

WITH ins_art_law17_1999_146 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 146, $cc294$الباب الثاني: الإلتزامات والعقود التجارية — الفصل الرابع: الإيداع في المستودعات العامة$cc294$, $cc295$1- إذا لم يسترد المودع البضاعة عند انتهاء عقد الإيداع جاز لمستثمر المستودع طلب بيعها باتباع الإجراءات المنصوص عليها في شأن الرهن التجاري ويستوفى من حصيلة البيع المبالغ المستحقة له ويسلم الباقي إلى المودع أو يودعه خزانة المحكمة المختصة.
2- يسرى الحكم المنصوص عليه في الفقرة السابقة إذا كان عقد الإيداع غير محدد المدة وانقضت سنة دون أن يطلب المودع استرداد البضاعة أو يبدى رغبته في استمرار عقد الإيداع.$cc295$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc295$1- إذا لم يسترد المودع البضاعة عند انتهاء عقد الإيداع جاز لمستثمر المستودع طلب بيعها باتباع الإجراءات المنصوص عليها في شأن الرهن التجاري ويستوفى من حصيلة البيع المبالغ المستحقة له ويسلم الباقي إلى المودع أو يودعه خزانة المحكمة المختصة.
2- يسرى الحكم المنصوص عليه في الفقرة السابقة إذا كان عقد الإيداع غير محدد المدة وانقضت سنة دون أن يطلب المودع استرداد البضاعة أو يبدى رغبته في استمرار عقد الإيداع.$cc295$, '1999-10-01', 'active' FROM ins_art_law17_1999_146;

WITH ins_art_law17_1999_147 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 147, $cc296$الباب الثاني: الإلتزامات والعقود التجارية — الفصل الرابع: الإيداع في المستودعات العامة$cc296$, $cc297$1- يعاقب بالحبس وبغرامة لا تقل عن خمسة آلاف جنيه ولا تزيد على خمسين ألف جنيه أو بإحدى هاتين العقوبتين كل من انشأ أو استغل مستودعا عاما دون الحصول على الترخيص المشار إليه في الفقرة الثانية من المادة (130) من هذا القانون.
2- للمحكمة أن تأمر في حالة الحكم بالإدانة بإغلاق المستودع وإيداع البضائع الموجودة فيه بأحد المستودعات المرخص بها، وذلك على نفقة المحكوم عليه وعلى ذمة تسليمها لاصحابها أو التصرف فيها لحسابهم وفقا للأحكام الواردة في هذا الفصل.
وتأمر المحكمة بنشر الحكم شاملا ببيان موقع المستودع الجديد في صحيفة يومية على نفقة المحكوم عليه.$cc297$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc297$1- يعاقب بالحبس وبغرامة لا تقل عن خمسة آلاف جنيه ولا تزيد على خمسين ألف جنيه أو بإحدى هاتين العقوبتين كل من انشأ أو استغل مستودعا عاما دون الحصول على الترخيص المشار إليه في الفقرة الثانية من المادة (130) من هذا القانون.
2- للمحكمة أن تأمر في حالة الحكم بالإدانة بإغلاق المستودع وإيداع البضائع الموجودة فيه بأحد المستودعات المرخص بها، وذلك على نفقة المحكوم عليه وعلى ذمة تسليمها لاصحابها أو التصرف فيها لحسابهم وفقا للأحكام الواردة في هذا الفصل.
وتأمر المحكمة بنشر الحكم شاملا ببيان موقع المستودع الجديد في صحيفة يومية على نفقة المحكوم عليه.$cc297$, '1999-10-01', 'active' FROM ins_art_law17_1999_147;

WITH ins_art_law17_1999_148 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 148, $cc298$الباب الثاني: الإلتزامات والعقود التجارية — الفصل الخامس: الوكالة التجارية$cc298$, $cc299$تطبق أحكام الوكالة التجارية إذا كان الوكيل محترفا إجراء المعاملات التجارية لحساب الغير.$cc299$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
