WITH ins_art_law17_1999_149 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 149, $cc300$الباب الثاني: الإلتزامات والعقود التجارية — الفصل الخامس: الوكالة التجارية$cc300$, $cc301$1- إذا أعطيت الوكالة التجارية مطلقة فلا تنصرف إلا إلى المعاملات التجارية.
2- وإذا أعطيت الوكالة التجارية مخصصة بمعاملة تجارية معينة جاز للوكيل القيام بجميع الأعمال اللازمة لإجراء هذه المعاملة دون حاجة إلى إذن من الموكل.$cc301$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc301$1- إذا أعطيت الوكالة التجارية مطلقة فلا تنصرف إلا إلى المعاملات التجارية.
2- وإذا أعطيت الوكالة التجارية مخصصة بمعاملة تجارية معينة جاز للوكيل القيام بجميع الأعمال اللازمة لإجراء هذه المعاملة دون حاجة إلى إذن من الموكل.$cc301$, '1999-10-01', 'active' FROM ins_art_law17_1999_149;

WITH ins_art_law17_1999_150 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 150, $cc302$الباب الثاني: الإلتزامات والعقود التجارية — الفصل الخامس: الوكالة التجارية$cc302$, $cc303$1- تكون الوكالة التجارية بأجر.
2- يستحق الوكيل التجاري الأجر بمجرد إبرام الصفقة التي كلف بها، وكذلك يستحق الأجر إذا اثبت تعذر إبرام الصفقة لسبب يرجع إلى الموكل.
3- في غير الحالتين المشار إليهما في الفقرة السابقة لا يستحق الوكيل أجرا وانما يستحق تعويضا عن الجهد الذي بذله طبقا لما يقضى به العرف التجاري.
4- استثناء من أحكام الفقرة الثانية من المادة (709) من القانون المدني إذا اتفق على اجر الوكيل التجاري فلا يخضع هذا الأجر لتقدير القاضي.$cc303$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc303$1- تكون الوكالة التجارية بأجر.
2- يستحق الوكيل التجاري الأجر بمجرد إبرام الصفقة التي كلف بها، وكذلك يستحق الأجر إذا اثبت تعذر إبرام الصفقة لسبب يرجع إلى الموكل.
3- في غير الحالتين المشار إليهما في الفقرة السابقة لا يستحق الوكيل أجرا وانما يستحق تعويضا عن الجهد الذي بذله طبقا لما يقضى به العرف التجاري.
4- استثناء من أحكام الفقرة الثانية من المادة (709) من القانون المدني إذا اتفق على اجر الوكيل التجاري فلا يخضع هذا الأجر لتقدير القاضي.$cc303$, '1999-10-01', 'active' FROM ins_art_law17_1999_150;

WITH ins_art_law17_1999_151 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 151, $cc304$الباب الثاني: الإلتزامات والعقود التجارية — الفصل الخامس: الوكالة التجارية$cc304$, $cc305$1- على الوكيل اتباع تعليمات الموكل، فإذا خالفها دون مسوغ مقبول جاز للموكل رفض الصفقة.
2- وإذا لم توجد تعليمات من الموكل بشأن الصفقة فعلى الوكيل تأخير إبرامها وطلب التعليمات من الموكل إلا إذا كان تأخير الصفقة يلحق الضرر بالموكل او كان الوكيل مفوضا في العمل بغير تعليمات منه.$cc305$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc305$1- على الوكيل اتباع تعليمات الموكل، فإذا خالفها دون مسوغ مقبول جاز للموكل رفض الصفقة.
2- وإذا لم توجد تعليمات من الموكل بشأن الصفقة فعلى الوكيل تأخير إبرامها وطلب التعليمات من الموكل إلا إذا كان تأخير الصفقة يلحق الضرر بالموكل او كان الوكيل مفوضا في العمل بغير تعليمات منه.$cc305$, '1999-10-01', 'active' FROM ins_art_law17_1999_151;

WITH ins_art_law17_1999_152 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 152, $cc306$الباب الثاني: الإلتزامات والعقود التجارية — الفصل الخامس: الوكالة التجارية$cc306$, $cc307$إذا كانت البضائع أو الاشياء التي يحوزها الوكيل لحساب الموكل مهددة بتلف سريع أو بهبوط في القيمة ولم تصله تعليمات من الموكل بشأنها في ميعاد مناسب فللوكيل أن يطلب من القاضي المختص بالمحكمة التي يوجد في دائرتها مركز أعماله إصدار أمر على عريضة ببيعها بالكيفية التي يعينها القاضي.$cc307$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc307$إذا كانت البضائع أو الاشياء التي يحوزها الوكيل لحساب الموكل مهددة بتلف سريع أو بهبوط في القيمة ولم تصله تعليمات من الموكل بشأنها في ميعاد مناسب فللوكيل أن يطلب من القاضي المختص بالمحكمة التي يوجد في دائرتها مركز أعماله إصدار أمر على عريضة ببيعها بالكيفية التي يعينها القاضي.$cc307$, '1999-10-01', 'active' FROM ins_art_law17_1999_152;

WITH ins_art_law17_1999_153 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 153, $cc308$الباب الثاني: الإلتزامات والعقود التجارية — الفصل الخامس: الوكالة التجارية$cc308$, $cc309$للوكيل أن يمتنع عن إجراء العمل المعهود به إليه إذا كان إجراؤه يتطلب مصاريف غير عادية ولم يرسلها إليه الموكل، إلا إذا اتفق أو جرى التعامل السابق بين الطرفين على أن يؤدي الوكيل هذه المصاريف.$cc309$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc309$للوكيل أن يمتنع عن إجراء العمل المعهود به إليه إذا كان إجراؤه يتطلب مصاريف غير عادية ولم يرسلها إليه الموكل، إلا إذا اتفق أو جرى التعامل السابق بين الطرفين على أن يؤدي الوكيل هذه المصاريف.$cc309$, '1999-10-01', 'active' FROM ins_art_law17_1999_153;

WITH ins_art_law17_1999_154 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 154, $cc310$الباب الثاني: الإلتزامات والعقود التجارية — الفصل الخامس: الوكالة التجارية$cc310$, $cc311$إذا رفض الوكيل إجراء الصفقة المعهود بها إليه، وجب عليه إخطار الموكل بذلك فورا، وفي هذه الحالة يجب على الوكيل المحافظة على البضائع وغيرها من الاشياء التي يحوزها لحساب الموكل حتى تصله تعليماته بشأنها. فإذا لم تصل التعليمات في ميعاد مناسب جاز للوكيل أن يطلب من القاضي المختص بالمحكمة التي يوجد في دائرتها مركز أعماله إصدار أمر على عريضة بإيداع البضائع أو الاشياء عند أمين يعينه القاضي.$cc311$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc311$إذا رفض الوكيل إجراء الصفقة المعهود بها إليه، وجب عليه إخطار الموكل بذلك فورا، وفي هذه الحالة يجب على الوكيل المحافظة على البضائع وغيرها من الاشياء التي يحوزها لحساب الموكل حتى تصله تعليماته بشأنها. فإذا لم تصل التعليمات في ميعاد مناسب جاز للوكيل أن يطلب من القاضي المختص بالمحكمة التي يوجد في دائرتها مركز أعماله إصدار أمر على عريضة بإيداع البضائع أو الاشياء عند أمين يعينه القاضي.$cc311$, '1999-10-01', 'active' FROM ins_art_law17_1999_154;

WITH ins_art_law17_1999_155 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 155, $cc312$الباب الثاني: الإلتزامات والعقود التجارية — الفصل الخامس: الوكالة التجارية$cc312$, $cc313$1- الوكيل مسئول عن هلاك أو تلف البضائع والأشياء التي يحوزها لحساب الموكل إلا إذا نتج ذلك عن سبب لا يد للوكيل أو لتابعيه فيه أو عن عيب ذاتي في البضاعة أو الشيء.
2- لا يلتزم الوكيل بالتأمين على الاشياء التي يحوزها لحساب الموكل إلا إذا طلب الموكل منه ذلك أو كان إجراء التأمين مما يقضى به العرف أو تستلزمه طبيعة الشيء.$cc313$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc313$1- الوكيل مسئول عن هلاك أو تلف البضائع والأشياء التي يحوزها لحساب الموكل إلا إذا نتج ذلك عن سبب لا يد للوكيل أو لتابعيه فيه أو عن عيب ذاتي في البضاعة أو الشيء.
2- لا يلتزم الوكيل بالتأمين على الاشياء التي يحوزها لحساب الموكل إلا إذا طلب الموكل منه ذلك أو كان إجراء التأمين مما يقضى به العرف أو تستلزمه طبيعة الشيء.$cc313$, '1999-10-01', 'active' FROM ins_art_law17_1999_155;

WITH ins_art_law17_1999_156 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 156, $cc314$الباب الثاني: الإلتزامات والعقود التجارية — الفصل الخامس: الوكالة التجارية$cc314$, $cc315$1- لا يجوز للوكيل أن يقيم نفسه طرفا ثانيا في الصفقة المكلف بإبرامها إلا في الحالات الآتية:
(أ) إذا أذن له الموكل في ذلك.
(ب) إذا كانت تعليمات الموكل بشأن الصفقة صريحة ومحددة ونفذها الوكيل بدقة.
(ج) إذا كانت الصفقة تتعلق بسلعة لها سعر محدد في السوق واشتراها الوكيل أو باعها بهذا السعر.
2- لا يستحق الوكيل في الحالات المذكورة في الفقرة السابقة أجرا نظير الوكالة.$cc315$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc315$1- لا يجوز للوكيل أن يقيم نفسه طرفا ثانيا في الصفقة المكلف بإبرامها إلا في الحالات الآتية:
(أ) إذا أذن له الموكل في ذلك.
(ب) إذا كانت تعليمات الموكل بشأن الصفقة صريحة ومحددة ونفذها الوكيل بدقة.
(ج) إذا كانت الصفقة تتعلق بسلعة لها سعر محدد في السوق واشتراها الوكيل أو باعها بهذا السعر.
2- لا يستحق الوكيل في الحالات المذكورة في الفقرة السابقة أجرا نظير الوكالة.$cc315$, '1999-10-01', 'active' FROM ins_art_law17_1999_156;

WITH ins_art_law17_1999_157 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 157, $cc316$الباب الثاني: الإلتزامات والعقود التجارية — الفصل الخامس: الوكالة التجارية$cc316$, $cc317$يجوز للغير الذي يتعامل مع الوكيل أن يطلب الاطلاع على عقد الوكالة وعلى المراسلات وغيرها من الوثائق المثبتة أو المقيدة لسلطة الوكيل. ولا يجوز الاحتجاج على الغير بالقيود الواردة على سلطة الوكيل إلا إذا ثبت علم الغير بها وقت التعاقد.$cc317$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc317$يجوز للغير الذي يتعامل مع الوكيل أن يطلب الاطلاع على عقد الوكالة وعلى المراسلات وغيرها من الوثائق المثبتة أو المقيدة لسلطة الوكيل. ولا يجوز الاحتجاج على الغير بالقيود الواردة على سلطة الوكيل إلا إذا ثبت علم الغير بها وقت التعاقد.$cc317$, '1999-10-01', 'active' FROM ins_art_law17_1999_157;

WITH ins_art_law17_1999_158 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 158, $cc318$الباب الثاني: الإلتزامات والعقود التجارية — الفصل الخامس: الوكالة التجارية$cc318$, $cc319$1- على الوكيل أن يحيط الموكل علما بالصفقات التي يبرمها لحسابه.
2- وعلى الوكيل أن يقدم للموكل في الميعاد المتفق عليه أو الذي يجرى عليه العرف أو التعامل السابق حسابا بينهما عن الأعمال التي يجريها لذمته. ويجب أن يكون هذا الحساب مطابقا للحقيقة، فإذا تضمن عن عمد بيانات غير صحيحة، جاز للموكل رفض الصفقات التي تتعلق بها هذه البيانات فضلا عن حقه في المطالبة بالتعويض، ولا يستحق الوكيل أجرا عن الصفقات المذكورة.$cc319$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc319$1- على الوكيل أن يحيط الموكل علما بالصفقات التي يبرمها لحسابه.
2- وعلى الوكيل أن يقدم للموكل في الميعاد المتفق عليه أو الذي يجرى عليه العرف أو التعامل السابق حسابا بينهما عن الأعمال التي يجريها لذمته. ويجب أن يكون هذا الحساب مطابقا للحقيقة، فإذا تضمن عن عمد بيانات غير صحيحة، جاز للموكل رفض الصفقات التي تتعلق بها هذه البيانات فضلا عن حقه في المطالبة بالتعويض، ولا يستحق الوكيل أجرا عن الصفقات المذكورة.$cc319$, '1999-10-01', 'active' FROM ins_art_law17_1999_158;

WITH ins_art_law17_1999_159 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 159, $cc320$الباب الثاني: الإلتزامات والعقود التجارية — الفصل الخامس: الوكالة التجارية$cc320$, $cc321$1- للوكيل فضلا عن حقه في الحبس امتياز على البضائع وغيرها من الاشياء التي يرسلها إليه الموكل أو يودعها لديه أو يسلمها له.
2- يضمن الامتياز اجر الوكيل والمصاريف والمبالغ التي يدفعها عن الموكل أو يقرضها له وغير ذلك من المبالغ التي تستحق للوكيل بسبب الوكالة سواء أنفقت قبل تسليم البضائع أو الاشياء أو أثناء وجودها في حيازة الوكيل.
3- يتقرر الامتياز دون اعتبار لما إذا كان الدين قد نشأ عن أعمال تتعلق بالبضائع أو الاشياء التي لا تزال في حيازة الوكيل أو ببضائع أو أشياء أخرى سبق إرسالها إليه أو إيداعها عنده أو تسليمها له.$cc321$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc321$1- للوكيل فضلا عن حقه في الحبس امتياز على البضائع وغيرها من الاشياء التي يرسلها إليه الموكل أو يودعها لديه أو يسلمها له.
2- يضمن الامتياز اجر الوكيل والمصاريف والمبالغ التي يدفعها عن الموكل أو يقرضها له وغير ذلك من المبالغ التي تستحق للوكيل بسبب الوكالة سواء أنفقت قبل تسليم البضائع أو الاشياء أو أثناء وجودها في حيازة الوكيل.
3- يتقرر الامتياز دون اعتبار لما إذا كان الدين قد نشأ عن أعمال تتعلق بالبضائع أو الاشياء التي لا تزال في حيازة الوكيل أو ببضائع أو أشياء أخرى سبق إرسالها إليه أو إيداعها عنده أو تسليمها له.$cc321$, '1999-10-01', 'active' FROM ins_art_law17_1999_159;

WITH ins_art_law17_1999_160 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 160, $cc322$الباب الثاني: الإلتزامات والعقود التجارية — الفصل الخامس: الوكالة التجارية$cc322$, $cc323$1- لا يكون للوكيل الامتياز المشار إليه في المادة السابقة إلا إذا كان حائزا لبضائع أو لأشياء لحساب الموكل. وتتحقق هذه الحيازة في الحالات الآتية:
(أ) إذا تسلم الوكيل البضائع أو الاشياء فعلا.
(ب) إذا وضعت تحت تصرفه في الجمرك أو في مخزن عام أو خاص.
(ج) إذا يحوزها قبل وصولها بمقتضى سند شحن أو أية وثيقة نقل أخرى.
(د) إذا صدرها وظل حائزا لها بمقتضى سند شحن أو أية وثيقة نقل أخرى.
2- إذا بيعت البضائع أو الاشياء التي يقع عليها الامتياز وسلمت إلى المشترى انتقل امتياز الوكيل إلى الثمن.$cc323$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc323$1- لا يكون للوكيل الامتياز المشار إليه في المادة السابقة إلا إذا كان حائزا لبضائع أو لأشياء لحساب الموكل. وتتحقق هذه الحيازة في الحالات الآتية:
(أ) إذا تسلم الوكيل البضائع أو الاشياء فعلا.
(ب) إذا وضعت تحت تصرفه في الجمرك أو في مخزن عام أو خاص.
(ج) إذا يحوزها قبل وصولها بمقتضى سند شحن أو أية وثيقة نقل أخرى.
(د) إذا صدرها وظل حائزا لها بمقتضى سند شحن أو أية وثيقة نقل أخرى.
2- إذا بيعت البضائع أو الاشياء التي يقع عليها الامتياز وسلمت إلى المشترى انتقل امتياز الوكيل إلى الثمن.$cc323$, '1999-10-01', 'active' FROM ins_art_law17_1999_160;

