WITH ins_art_law17_1999_194 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 194, $cc390$الباب الثاني: الإلتزامات والعقود التجارية — الفصل السادس: السمسرة$cc390$, $cc391$1- لا يستحق السمسار اجره إلا إذا أدت وساطته إلى إبرام العقد، وإذا لم يتم إبرام العقد بسبب تعنت من فوضه جاز للمحكمة أن تعوض السمسار عما بذله من جهد.
2- ويستحق السمسار الأجر بمجرد إبرام العقد ولو لم ينفذ كله أو بعضه.
3- إذا كان العقد معلقا على شرط واقف فلا يستحق السمسار اجره إلا إذا تحقق الشرط.
4- إذا كان أحد آثار العقد يتوقف على إتمام إجراء قانوني معين كالتسجيل في بيع العقار أو القيد في الرهن الرسمي استحق السمسار اجره بمجرد إبرام العقد الابتدائي.$cc391$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc391$1- لا يستحق السمسار اجره إلا إذا أدت وساطته إلى إبرام العقد، وإذا لم يتم إبرام العقد بسبب تعنت من فوضه جاز للمحكمة أن تعوض السمسار عما بذله من جهد.
2- ويستحق السمسار الأجر بمجرد إبرام العقد ولو لم ينفذ كله أو بعضه.
3- إذا كان العقد معلقا على شرط واقف فلا يستحق السمسار اجره إلا إذا تحقق الشرط.
4- إذا كان أحد آثار العقد يتوقف على إتمام إجراء قانوني معين كالتسجيل في بيع العقار أو القيد في الرهن الرسمي استحق السمسار اجره بمجرد إبرام العقد الابتدائي.$cc391$, '1999-10-01', 'active' FROM ins_art_law17_1999_194;

