WITH ins_art_law17_1999_204 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 204, $cc410$الباب الثاني: الإلتزامات والعقود التجارية — الفصل السادس: السمسرة$cc410$, $cc411$1- إذا أناب السمسار غيره في تنفيذ العمل المكلف به دون أن يكون مرخصا له في ذلك كان في مسئولا عن عمل النائب كما لو كان هذا العمل قد صدر منه ويكون السمسار ونائبه متضامنين في المسئولية.
2- وإذا رخص للسمسار في إقامة نائب عنه دون أن يعين له شخص النائب، فلا يكون السمسار مسئولا إلا عن خطئه في اختيار نائبه أو عن خطئه فيما أصدره له من تعليمات.
3- وفي جميع الأحوال يجوز لمن فوض السمسار ولنائب السمسار أن يرجع كل منهما مباشرة على الآخر.$cc411$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc411$1- إذا أناب السمسار غيره في تنفيذ العمل المكلف به دون أن يكون مرخصا له في ذلك كان في مسئولا عن عمل النائب كما لو كان هذا العمل قد صدر منه ويكون السمسار ونائبه متضامنين في المسئولية.
2- وإذا رخص للسمسار في إقامة نائب عنه دون أن يعين له شخص النائب، فلا يكون السمسار مسئولا إلا عن خطئه في اختيار نائبه أو عن خطئه فيما أصدره له من تعليمات.
3- وفي جميع الأحوال يجوز لمن فوض السمسار ولنائب السمسار أن يرجع كل منهما مباشرة على الآخر.$cc411$, '1999-10-01', 'active' FROM ins_art_law17_1999_204;

WITH ins_art_law17_1999_205 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 205, $cc412$الباب الثاني: الإلتزامات والعقود التجارية — الفصل السادس: السمسرة$cc412$, $cc413$1- إذا فوض عدة سماسرة بعقد واحد كانوا مسئولين بالتضامن عن العمل المكلفين به إلا إذا رخص لهم في العمل منفردين.
2- وإذا فوض أشخاص متعددون سمسارا واحدا في عمل مشترك كانوا بينهم مسئولين بالتضامن قبله عما يستحقه تنفيذا لهذا التفويض ما لم يتفق على غير ذلك.
3- وإذا تم العقد بتدخل عدة سماسرة ولم يعين لكل منهم اجر مستقل استحق كل منهم نصيبا في الأجر المشترك بنسبة ما بذله من جهد في إبرام العقد.$cc413$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
