SELECT id, 1, $cc421$1- فيما عدا النقل البحري تسرى الأحكام المنصوص عليها في هذا الفصل على جميع أنواع النقل أيا كانت صفة الناقل ما لم ينص القانون على غير ذلك.
2- كما تسرى تلك الأحكام على النقل ولو اقترنت به عمليات من طبيعة أخرى ما لم تكن هذه العمليات هي الغرض الرئيسي من التعاقد.$cc421$, '1999-10-01', 'active' FROM ins_art_law17_1999_209;

WITH ins_art_law17_1999_210 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 210, $cc422$الباب الثاني: الإلتزامات والعقود التجارية — الفصل السابع: النقل$cc422$, $cc423$1- يتم عقد النقل وعقد الوكالة بالعمولة للنقل بمجرد الاتفاق، ويجوز إثبات العقد بكافة طرق الإثبات المقررة قانونا.
2- تسلم الناقل الشيء محل النقل يعد قبولا منه للإيجاب الصادر من المرسل.
3- كما يعتبر صعود الراكب إلى وسيلة النقل قبولا للإيجاب الصادر من الناقل إلا إذا ثبت أن نية الراكب لم تتجه إلى إبرام عقد النقل.$cc423$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc423$1- يتم عقد النقل وعقد الوكالة بالعمولة للنقل بمجرد الاتفاق، ويجوز إثبات العقد بكافة طرق الإثبات المقررة قانونا.
2- تسلم الناقل الشيء محل النقل يعد قبولا منه للإيجاب الصادر من المرسل.
3- كما يعتبر صعود الراكب إلى وسيلة النقل قبولا للإيجاب الصادر من الناقل إلا إذا ثبت أن نية الراكب لم تتجه إلى إبرام عقد النقل.$cc423$, '1999-10-01', 'active' FROM ins_art_law17_1999_210;

WITH ins_art_law17_1999_211 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 211, $cc424$الباب الثاني: الإلتزامات والعقود التجارية — الفصل السابع: النقل$cc424$, $cc425$1- إذا كان للناقل اكثر من أنموذج واحد للعقود التي يبرمها، انعقد النقل بمقتضى الأنموذج الذي يتضمن الشروط العامة، ما لم يتفق على اتباع أنموذج آخر يشتمل على شروط خاصة.
2- وإذا اتفق على اتباع أنموذج خاص فلا يجوز تجزئة الشروط التي يشتمل عليها.$cc425$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
