WITH ins_art_law17_1999_217 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 217, $cc436$الباب الثاني: الإلتزامات والعقود التجارية — الفصل السابع: النقل$cc436$, $cc437$1- على المرسل أن يقدم للناقل بيانات عن اسم المرسل إليه وعنوانه والمكان المطلوب الإرسال إليه ونوع الاشياء محل النقل ووزنها وحجمها وكيفية حزمها وعدد الطرود التي تشملها وغير ذلك من البيانات التي قد يطلبها الناقل أو يقررها القانون لتعيين ذاتية الشيء.
2- يسأل المرسل عن الضرر الذي ينجم عن عدم صحة البيانات التي يقدمها أو عدم كفايتها.$cc437$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc437$1- على المرسل أن يقدم للناقل بيانات عن اسم المرسل إليه وعنوانه والمكان المطلوب الإرسال إليه ونوع الاشياء محل النقل ووزنها وحجمها وكيفية حزمها وعدد الطرود التي تشملها وغير ذلك من البيانات التي قد يطلبها الناقل أو يقررها القانون لتعيين ذاتية الشيء.
2- يسأل المرسل عن الضرر الذي ينجم عن عدم صحة البيانات التي يقدمها أو عدم كفايتها.$cc437$, '1999-10-01', 'active' FROM ins_art_law17_1999_217;

WITH ins_art_law17_1999_218 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 218, $cc438$الباب الثاني: الإلتزامات والعقود التجارية — الفصل السابع: النقل$cc438$, $cc439$1- إذا حررت وثيقة نقل وجب أن تشتمل بوجه خاص على البيانات الآتية:
(أ) مكان وتاريخ الوثيقة.
(ب) أسماء المرسل إليه والوكيل بالعمولة للنقل- إن وجد- وعناوينهم.
(ج) مكان القيام ومكان الوصول.
(د) البيانات الخاصة بتعيين الشيء محل النقل كوزنه وحجمه وكيفية حزمه وعدد الطرود وكل بيان آخر يكون لازما لتعيين ذاتية الشيء وتقدير قيمته.
(ه) الميعاد المعين لمباشرة النقل.
(و) أجرة النقل وغيرها من المصاريف مع بيان ما إذا كانت مستحقة على المرسل أو المرسل إليه.
(ز) الشروط الخاصة بالشحن أو التفريغ أو نوع العربات التي تستخدم في النقل والطريق الذي يجب اتباعه وتحديد المسئولية وغير ذلك من الشروط الخاصة التي قد يتضمنها اتفاق النقل.
2- وللمرسل أن يطلب من الناقل تسليمه نسخة من وثيقة النقل موقعه منه.$cc439$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
