SELECT id, 1, $cc449$1- على المرسل أن يسلم الناقل الشيء والوثائق اللازمة لتنفيذ النقل. ويكون المرسل مسئولا عن عدم كفاية هذه الوثائق أو عدم مطابقتها للحقيقة. ويكون الناقل مسئولا عن ضياعها أو إساءة استعمالها.
2- وإذا اقتضى النقل استعدادا خاصا من جانب الناقل وجب على المرسل إخطاره بذلك قبل تسليم الشيء إليه بوقت كاف.
3- يكون تسليم الشيء محل النقل في محل الناقل المعين بعقد النقل ما لم يتفق على غير ذلك.$cc449$, '1999-10-01', 'active' FROM ins_art_law17_1999_223;

WITH ins_art_law17_1999_224 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 224, $cc450$الباب الثاني: الإلتزامات والعقود التجارية — الفصل السابع: النقل$cc450$, $cc451$1- إذا اقتضت طبيعة الشيء إعداده للنقل بتغليفه أو تعبئته أو حزمه، وجب على المرسل أن يقوم بذلك بكيفية تقيه الهلاك أو التلف ولا تعرض الأشخاص أو الأموال الأخرى التي تنقل معه للضرر، وإذا كانت شروط النقل تستلزم اتباع طريقة معينة في التغليف أو التعبئة أو الحزم وجب على المرسل مراعاتها.
2- ويكون المرسل مسئولا عن الأضرار التي تنشأ عن العيب في التغليف أو التعبئة أو الحزم.
ومع ذلك يكون الناقل مسئولا عن هذه الأضرار إذا قبل النقل مع علمه بالعيب، ويكون الناقل عالما بالعيب إذا كان ظاهرا أو كان مما لا يخفي على الناقل العادي.
3- ولا يجوز للناقل أن ينفي مسئوليته عن هلاك أو تلف أحد الاشياء التي قام بنقلها بإثبات أن الضرر نشأ عن عيب في تغليف شئ آخر أو في تعبئته أو حزمه، ويقع باطلا كل اتفاق على خلاف ذلك.$cc451$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc451$1- إذا اقتضت طبيعة الشيء إعداده للنقل بتغليفه أو تعبئته أو حزمه، وجب على المرسل أن يقوم بذلك بكيفية تقيه الهلاك أو التلف ولا تعرض الأشخاص أو الأموال الأخرى التي تنقل معه للضرر، وإذا كانت شروط النقل تستلزم اتباع طريقة معينة في التغليف أو التعبئة أو الحزم وجب على المرسل مراعاتها.
2- ويكون المرسل مسئولا عن الأضرار التي تنشأ عن العيب في التغليف أو التعبئة أو الحزم.
ومع ذلك يكون الناقل مسئولا عن هذه الأضرار إذا قبل النقل مع علمه بالعيب، ويكون الناقل عالما بالعيب إذا كان ظاهرا أو كان مما لا يخفي على الناقل العادي.
3- ولا يجوز للناقل أن ينفي مسئوليته عن هلاك أو تلف أحد الاشياء التي قام بنقلها بإثبات أن الضرر نشأ عن عيب في تغليف شئ آخر أو في تعبئته أو حزمه، ويقع باطلا كل اتفاق على خلاف ذلك.$cc451$, '1999-10-01', 'active' FROM ins_art_law17_1999_224;

WITH ins_art_law17_1999_225 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 225, $cc452$الباب الثاني: الإلتزامات والعقود التجارية — الفصل السابع: النقل$cc452$, $cc453$1- للناقل الحق في فحص الاشياء المطلوب نقلها نفلها للتحقق من حالتها ومن صحة البيانات التي أدلى بها المرسل بشأنها.
2- وإذا اقتضى الفحص فض الأغلفة أو الأوعية وجب إخطار المرسل لحضور الفحص فإذا لم يحضر في الميعاد المعين لذلك، جاز للناقل إجراء الفحص بغير حضوره وللناقل الرجوع على المرسل أو المرسل إليه بمصاريف الفحص.
3- وإذا تبين من الفحص أن حالة الشيء لا تسمح بنقله دون ضرر، جاز للناقل رفض النقل أو تنفيذه بعد اخذ إقرار من المرسل بعلمه بحالة الشيء ورضائه بالنقل، ويجب إثبات حالة الشيء واقرار المرسل في وثيقة النقل.$cc453$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc453$1- للناقل الحق في فحص الاشياء المطلوب نقلها نفلها للتحقق من حالتها ومن صحة البيانات التي أدلى بها المرسل بشأنها.
2- وإذا اقتضى الفحص فض الأغلفة أو الأوعية وجب إخطار المرسل لحضور الفحص فإذا لم يحضر في الميعاد المعين لذلك، جاز للناقل إجراء الفحص بغير حضوره وللناقل الرجوع على المرسل أو المرسل إليه بمصاريف الفحص.
3- وإذا تبين من الفحص أن حالة الشيء لا تسمح بنقله دون ضرر، جاز للناقل رفض النقل أو تنفيذه بعد اخذ إقرار من المرسل بعلمه بحالة الشيء ورضائه بالنقل، ويجب إثبات حالة الشيء واقرار المرسل في وثيقة النقل.$cc453$, '1999-10-01', 'active' FROM ins_art_law17_1999_225;

