WITH ins_art_law17_1999_227 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 227, $cc456$الباب الثاني: الإلتزامات والعقود التجارية — الفصل السابع: النقل$cc456$, $cc457$1- يلتزم الناقل بشحن الشيء في وسيلة النقل ما لم يتفق على غير ذلك.
2- وإذا اتفق على أن يقوم المرسل بالشحن فلا يسأل عنه الناقل، ومع ذلك إذا قبل الناقل تنفيذ النقل دون تحفظ فيفترض أن الشحن قد تم وفقا للأصول الصحيحة حتى يقيم الناقل الدليل على عكس ذلك.
3- إذا طلب المرسل أن يكون الشحن على وسيلة نقل بمواصفات معينة، فلا يكون الناقل مسئولا عما ينجم عن استعمالها من ضرر.$cc457$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc457$1- يلتزم الناقل بشحن الشيء في وسيلة النقل ما لم يتفق على غير ذلك.
2- وإذا اتفق على أن يقوم المرسل بالشحن فلا يسأل عنه الناقل، ومع ذلك إذا قبل الناقل تنفيذ النقل دون تحفظ فيفترض أن الشحن قد تم وفقا للأصول الصحيحة حتى يقيم الناقل الدليل على عكس ذلك.
3- إذا طلب المرسل أن يكون الشحن على وسيلة نقل بمواصفات معينة، فلا يكون الناقل مسئولا عما ينجم عن استعمالها من ضرر.$cc457$, '1999-10-01', 'active' FROM ins_art_law17_1999_227;

WITH ins_art_law17_1999_228 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 228, $cc458$الباب الثاني: الإلتزامات والعقود التجارية — الفصل السابع: النقل$cc458$, $cc459$1- على الناقل أن يتبع الطريق المتفق عليه فإذا لم يتفق على طريق معين وجب اتباع افضل الطرق.
2- ومع ذلك يجوز للناقل أن يغير الطريق المتفق عليه إذا وجدت ضرورة تلجئه إلى ذلك. وفي هذه الحالة لا يسأل الناقل عن التأخير أو غيره من الأضرار التي تنجم عن تغيير الطريق إلا إذا ثبت الغش أو الخطأ الجسيم في جانبه أو في جانب تابعيه وللناقل أيضا الحق في المطالبة بالمصروفات الإضافية الناشئة عن ذلك.$cc459$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc459$1- على الناقل أن يتبع الطريق المتفق عليه فإذا لم يتفق على طريق معين وجب اتباع افضل الطرق.
2- ومع ذلك يجوز للناقل أن يغير الطريق المتفق عليه إذا وجدت ضرورة تلجئه إلى ذلك. وفي هذه الحالة لا يسأل الناقل عن التأخير أو غيره من الأضرار التي تنجم عن تغيير الطريق إلا إذا ثبت الغش أو الخطأ الجسيم في جانبه أو في جانب تابعيه وللناقل أيضا الحق في المطالبة بالمصروفات الإضافية الناشئة عن ذلك.$cc459$, '1999-10-01', 'active' FROM ins_art_law17_1999_228;

WITH ins_art_law17_1999_229 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 229, $cc460$الباب الثاني: الإلتزامات والعقود التجارية — الفصل السابع: النقل$cc460$, $cc461$1- يضمن الناقل سلامة الشيء أثناء تنفيذ عقد النقل.
2- إذا اقتضت المحافظة على الشيء أثناء الطريق إعادة الحزم أو إصلاح الأغلفة أو زيادتها أو تخفيضها أو غير ذلك من التدابير الضرورية، وجب على الناقل القيام بها واداء ما تستلزمه من مصاريف على أن يرجع بها على المرسل أو المرسل إليه ما لم يكن ذلك راجعا إلى خطأ الناقل. ومع ذلك لا يلتزم الناقل بالقيام بالتدابير غير المعتادة في النقل كرش النبات بالماء أو إطعام الحيوان أو سقيه أو تقديم الخدمات الطبية له ما لم يتفق على غير ذلك.$cc461$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc461$1- يضمن الناقل سلامة الشيء أثناء تنفيذ عقد النقل.
2- إذا اقتضت المحافظة على الشيء أثناء الطريق إعادة الحزم أو إصلاح الأغلفة أو زيادتها أو تخفيضها أو غير ذلك من التدابير الضرورية، وجب على الناقل القيام بها واداء ما تستلزمه من مصاريف على أن يرجع بها على المرسل أو المرسل إليه ما لم يكن ذلك راجعا إلى خطأ الناقل. ومع ذلك لا يلتزم الناقل بالقيام بالتدابير غير المعتادة في النقل كرش النبات بالماء أو إطعام الحيوان أو سقيه أو تقديم الخدمات الطبية له ما لم يتفق على غير ذلك.$cc461$, '1999-10-01', 'active' FROM ins_art_law17_1999_229;

WITH ins_art_law17_1999_230 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 230, $cc462$الباب الثاني: الإلتزامات والعقود التجارية — الفصل السابع: النقل$cc462$, $cc463$1- يلتزم الناقل بتفريغ الشيء محل النقل عند وصوله ما لم ينص القانون أو يتفق على غير ذلك وفي هذه الحالة الأخيرة لا يسأل الناقل عن الضرر الذي يقع بسبب التفريغ.
2- وفي جميع الأحوال يتحمل الناقل مصاريف التفريغ ما لم يتفق أو يجرى العرف على غير ذلك.$cc463$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc463$1- يلتزم الناقل بتفريغ الشيء محل النقل عند وصوله ما لم ينص القانون أو يتفق على غير ذلك وفي هذه الحالة الأخيرة لا يسأل الناقل عن الضرر الذي يقع بسبب التفريغ.
2- وفي جميع الأحوال يتحمل الناقل مصاريف التفريغ ما لم يتفق أو يجرى العرف على غير ذلك.$cc463$, '1999-10-01', 'active' FROM ins_art_law17_1999_230;

WITH ins_art_law17_1999_231 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 231, $cc464$الباب الثاني: الإلتزامات والعقود التجارية — الفصل السابع: النقل$cc464$, $cc465$1- إذا لم يكن التسليم واجبا في محل المرسل إليه فعلى الناقل أن يخطره أن الناقل بوصول الشيء وبالميعاد الذي يستطيع خلاله الحضور لتسلمه.
2- على المرسل إليه تسلم الشيء في الميعاد الذي عينه الناقل والالتزام بمصاريف التخزين.
وللناقل بعد انقضاء هذا الميعاد أن ينقل الشيء إلى محل المرسل إليه مقابل أجرة إضافية.
3- وللمرسل إليه طلب فحص الشيء قبل تسلمه فإذا امتنع الناقل عن تمكينه من ذلك جاز له رفض تسلم الشيء.$cc465$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc465$1- إذا لم يكن التسليم واجبا في محل المرسل إليه فعلى الناقل أن يخطره أن الناقل بوصول الشيء وبالميعاد الذي يستطيع خلاله الحضور لتسلمه.
2- على المرسل إليه تسلم الشيء في الميعاد الذي عينه الناقل والالتزام بمصاريف التخزين.
وللناقل بعد انقضاء هذا الميعاد أن ينقل الشيء إلى محل المرسل إليه مقابل أجرة إضافية.
3- وللمرسل إليه طلب فحص الشيء قبل تسلمه فإذا امتنع الناقل عن تمكينه من ذلك جاز له رفض تسلم الشيء.$cc465$, '1999-10-01', 'active' FROM ins_art_law17_1999_231;

WITH ins_art_law17_1999_232 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 232, $cc466$الباب الثاني: الإلتزامات والعقود التجارية — الفصل السابع: النقل$cc466$, $cc467$1- يجوز للمرسل أثناء وجود الشيء في حيازة الناقل أن يأمره بالامتناع عن مباشرة النقل أو بوقفه واعادة الشيء إليه أو بتوجيهه إلى شخص آخر غير المرسل إليه الأصلي أو إلى مكان آخر أو غير ذلك من التعليمات بشرط أن يدفع المرسل للناقل أجرة ما تم من النقل والمصاريف وتعويضا عما يلحقه من ضرر بسبب التعليمات الجديدة. وإذا كان المرسل قد تسلم نسخة من وثيقة النقل وجب أن يقدمها إلى الناقل ليدون فيها التعليمات الجديدة موقعا عليها من المرسل وإلا كان للناقل الامتناع عن تنفيذ هذه التعليمات.
2- ينتقل الحق في إصدار التعليمات المتعلقة بالشيء محل النقل إلى المرسل إليه بمجرد تسليمه وثيقة النقل. ويجب في هذه الحالة أيضا تقديم الوثيقة إلى الناقل ليدون فيها التعليمات الجديدة موقعا عليها من المرسل إليه وإلا جاز للناقل الامتناع عن تنفيذها.
3- ولا يجوز إصدار تعليمات جديدة تتعلق بالشيء محل النقل بعد وصوله وطلب المرسل إليه تسلمه أو إخطاره بالحضور لتسلمه.$cc467$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc467$1- يجوز للمرسل أثناء وجود الشيء في حيازة الناقل أن يأمره بالامتناع عن مباشرة النقل أو بوقفه واعادة الشيء إليه أو بتوجيهه إلى شخص آخر غير المرسل إليه الأصلي أو إلى مكان آخر أو غير ذلك من التعليمات بشرط أن يدفع المرسل للناقل أجرة ما تم من النقل والمصاريف وتعويضا عما يلحقه من ضرر بسبب التعليمات الجديدة. وإذا كان المرسل قد تسلم نسخة من وثيقة النقل وجب أن يقدمها إلى الناقل ليدون فيها التعليمات الجديدة موقعا عليها من المرسل وإلا كان للناقل الامتناع عن تنفيذ هذه التعليمات.
2- ينتقل الحق في إصدار التعليمات المتعلقة بالشيء محل النقل إلى المرسل إليه بمجرد تسليمه وثيقة النقل. ويجب في هذه الحالة أيضا تقديم الوثيقة إلى الناقل ليدون فيها التعليمات الجديدة موقعا عليها من المرسل إليه وإلا جاز للناقل الامتناع عن تنفيذها.
3- ولا يجوز إصدار تعليمات جديدة تتعلق بالشيء محل النقل بعد وصوله وطلب المرسل إليه تسلمه أو إخطاره بالحضور لتسلمه.$cc467$, '1999-10-01', 'active' FROM ins_art_law17_1999_232;

WITH ins_art_law17_1999_233 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 233, $cc468$الباب الثاني: الإلتزامات والعقود التجارية — الفصل السابع: النقل$cc468$, $cc469$على الناقل تنفيذ التعليمات الصادرة إليه ممن له الحق في إصدارها طبقا لأحكام المادة (232) من هذا القانون إلا إذا كانت تخالف شروط النقل أو تعذر على الناقل تنفيذها أو كان من شأن تنفيذها اضطراب حركة النقل أو كانت قيمة الشيء محل النقل لا تكفي لتغطية المصاريف التي يتحملها الناقل بسبب تنفيذها، وفي هذه الأحوال يجب على الناقل أن يخطر من أصدر التعليمات الجديدة بامتناعه عن تنفيذها وسبب هذا الامتناع، ويكون الناقل مسئولا إذا امتنع عن التنفيذ دون مسوغ.$cc469$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc469$على الناقل تنفيذ التعليمات الصادرة إليه ممن له الحق في إصدارها طبقا لأحكام المادة (232) من هذا القانون إلا إذا كانت تخالف شروط النقل أو تعذر على الناقل تنفيذها أو كان من شأن تنفيذها اضطراب حركة النقل أو كانت قيمة الشيء محل النقل لا تكفي لتغطية المصاريف التي يتحملها الناقل بسبب تنفيذها، وفي هذه الأحوال يجب على الناقل أن يخطر من أصدر التعليمات الجديدة بامتناعه عن تنفيذها وسبب هذا الامتناع، ويكون الناقل مسئولا إذا امتنع عن التنفيذ دون مسوغ.$cc469$, '1999-10-01', 'active' FROM ins_art_law17_1999_233;

WITH ins_art_law17_1999_234 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 234, $cc470$الباب الثاني: الإلتزامات والعقود التجارية — الفصل السابع: النقل$cc470$, $cc471$1- إذا توقف النقل أثناء تنفيذه أو لم يحضر المرسل إليه لتسلم الشيء أو حضر وامتنع عن تسلمه أو عن دفع أجرة النقل والمصاريف المستحقة عليه وجب على الناقل أن يبادر إلى إخطار المرسل بذلك مع طلب تعليماته. واستثناء من أحكام المادة (232) من هذا القانون يلتزم الناقل بتنفيذ التعليمات التي تصله من المرسل ولو تعذر على المرسل تقديم نسخة وثيقة النقل التي تسلمها من الناقل.
2- وإذا لم تصل تعليمات المرسل خلال ميعاد مناسب جاز للناقل أن يطلب من القاضي المختص تعيين خبير أو اكثر لاثبات حالة الشيء والإذن له في إيداعه عند أمين لحساب المرسل وعلى مسئوليته أو بيعه بالكيفية التي يعينها إذا كان الشيء معرضا للهلاك أو التلف أو هبوط القيمة أو كانت صيانته تتطلب مصاريف باهظة، وإيداع الثمن خزانة المحكمة لحساب ذوي الشأن.$cc471$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc471$1- إذا توقف النقل أثناء تنفيذه أو لم يحضر المرسل إليه لتسلم الشيء أو حضر وامتنع عن تسلمه أو عن دفع أجرة النقل والمصاريف المستحقة عليه وجب على الناقل أن يبادر إلى إخطار المرسل بذلك مع طلب تعليماته. واستثناء من أحكام المادة (232) من هذا القانون يلتزم الناقل بتنفيذ التعليمات التي تصله من المرسل ولو تعذر على المرسل تقديم نسخة وثيقة النقل التي تسلمها من الناقل.
2- وإذا لم تصل تعليمات المرسل خلال ميعاد مناسب جاز للناقل أن يطلب من القاضي المختص تعيين خبير أو اكثر لاثبات حالة الشيء والإذن له في إيداعه عند أمين لحساب المرسل وعلى مسئوليته أو بيعه بالكيفية التي يعينها إذا كان الشيء معرضا للهلاك أو التلف أو هبوط القيمة أو كانت صيانته تتطلب مصاريف باهظة، وإيداع الثمن خزانة المحكمة لحساب ذوي الشأن.$cc471$, '1999-10-01', 'active' FROM ins_art_law17_1999_234;

WITH ins_art_law17_1999_235 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 235, $cc472$الباب الثاني: الإلتزامات والعقود التجارية — الفصل السابع: النقل$cc472$, $cc473$1- يلتزم المرسل بدفع أجرة النقل وغيرها من المصاريف المستحقة للناقل ما لم يتفق على أن يتحملها المرسل إليه.
2- وإذا اتفق على أن يتحمل المرسل إليه أجرة النقل أو غيرها من المصاريف كان كل من المرسل والمرسل إليه مسئولين عن دفعها بالتضامن قبل الناقل.$cc473$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
