SELECT id, 1, $cc473$1- يلتزم المرسل بدفع أجرة النقل وغيرها من المصاريف المستحقة للناقل ما لم يتفق على أن يتحملها المرسل إليه.
2- وإذا اتفق على أن يتحمل المرسل إليه أجرة النقل أو غيرها من المصاريف كان كل من المرسل والمرسل إليه مسئولين عن دفعها بالتضامن قبل الناقل.$cc473$, '1999-10-01', 'active' FROM ins_art_law17_1999_235;

