2- يكون الشيء محل النقل في حكم الهالك كليا إذا لم يسلمه الناقل أو لم يخطر المرسل إليه بالحضور لتسلمه خلال ثلاثين يوما من انقضاء الميعاد المعين للتسليم أو من انقضاء الميعاد الذي يستغرقه الناقل العادي لو النقل في الظروف نفسها إذا لم يعين ميعاد للتسليم.$cc483$, '1999-10-01', 'active' FROM ins_art_law17_1999_240;

