SELECT id, 1, $cc491$1- لا يجوز للناقل أن ينفي مسئوليته عن هلاك الشيء محل النقل أو تلفه أو التأخير في تسليمه إلا بإثبات القوة القاهرة أو العيب الذاتي في الشيء أو خطا المرسل أو المرسل إليه.
2- إذا اثبت الناقل أحد الأمور المذكورة في الفقرة السابقة جاز للمدعى نقض هذا الإثبات بإقامة الدليل على أن الضرر لم يحدث بسببه.$cc491$, '1999-10-01', 'active' FROM ins_art_law17_1999_244;

WITH ins_art_law17_1999_245 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 245, $cc492$الباب الثاني: الإلتزامات والعقود التجارية — الفصل السابع: النقل$cc492$, $cc493$1- يقع باطلا كل شرط يقضى بإعفاء الناقل من المسئولية عن هلاك الشيء كليا أو جزئيا أو تلفه.
2- ويعد في حكم الإعفاء من المسئولية كل شرط يكون من شأنه إلزام المرسل أو المرسل إليه بدفع كل أو بعض نفقات التأمين ضد مسئولية الناقل، وكذلك كل شرط يقضى بنزول المرسل أو المرسل إليه للناقل عن الحقوق الناشئة عن التأمين على الشيء ضد مخاطر النقل.$cc493$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc493$1- يقع باطلا كل شرط يقضى بإعفاء الناقل من المسئولية عن هلاك الشيء كليا أو جزئيا أو تلفه.
2- ويعد في حكم الإعفاء من المسئولية كل شرط يكون من شأنه إلزام المرسل أو المرسل إليه بدفع كل أو بعض نفقات التأمين ضد مسئولية الناقل، وكذلك كل شرط يقضى بنزول المرسل أو المرسل إليه للناقل عن الحقوق الناشئة عن التأمين على الشيء ضد مخاطر النقل.$cc493$, '1999-10-01', 'active' FROM ins_art_law17_1999_245;

WITH ins_art_law17_1999_246 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 246, $cc494$الباب الثاني: الإلتزامات والعقود التجارية — الفصل السابع: النقل$cc494$, $cc495$1- يجوز للناقل:
(أ) أن يشترط تحديد مسئولية عن هلاك الشيء كليا أو جزئيا أو تلفه بشرط ألا يقل التعويض المتفق عليه عن ثلث قيمة البضاعة المنقولة في مكان وزمان نقلها وكل اتفاق على تعويض يقل عن هذا الحد يزاد إليه.
(ب) أن يشترط إعفاءه كليا أو جزئيا من المسئولية عن التأخير.
2- ويجب أن يكون شرط الإعفاء من المسئولية أو تحديدها مكتوبا في وثيقة النقل وإلا اعتبر كأن لم يكن. وإذا كان عقد النقل محررا على نماذج مطبوعة، وجب أن يكون الشرط واضحا ومكتوبا بكيفية تسترعي الانتباه وإلا جاز للمحكمة أن تعتبر الشرط كأن لم يكن.
3- ولا يجوز أن يتمسك الناقل بشرط الإعفاء من المسئولية أو تحديدها إذا ثبت صدور غش أو خطأ جسيم منه أو من تابعيه.$cc495$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc495$1- يجوز للناقل:
(أ) أن يشترط تحديد مسئولية عن هلاك الشيء كليا أو جزئيا أو تلفه بشرط ألا يقل التعويض المتفق عليه عن ثلث قيمة البضاعة المنقولة في مكان وزمان نقلها وكل اتفاق على تعويض يقل عن هذا الحد يزاد إليه.
(ب) أن يشترط إعفاءه كليا أو جزئيا من المسئولية عن التأخير.
2- ويجب أن يكون شرط الإعفاء من المسئولية أو تحديدها مكتوبا في وثيقة النقل وإلا اعتبر كأن لم يكن. وإذا كان عقد النقل محررا على نماذج مطبوعة، وجب أن يكون الشرط واضحا ومكتوبا بكيفية تسترعي الانتباه وإلا جاز للمحكمة أن تعتبر الشرط كأن لم يكن.
3- ولا يجوز أن يتمسك الناقل بشرط الإعفاء من المسئولية أو تحديدها إذا ثبت صدور غش أو خطأ جسيم منه أو من تابعيه.$cc495$, '1999-10-01', 'active' FROM ins_art_law17_1999_246;

WITH ins_art_law17_1999_247 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 247, $cc496$الباب الثاني: الإلتزامات والعقود التجارية — الفصل السابع: النقل$cc496$, $cc497$1- إذا هلك الشيء أو تلف دون أن تكون قيمته مبينة في وثيقة النقل، قدر التعويض على أساس قيمته الحقيقية في مكان الوصول وزمانه، إلا إذا نص القانون أو اتفق على غير ذلك. وفيما عدا حالة الهلاك الكلي، يراعى عند تقرير التعويض قيمة النقص المتسامح فيه وفقا للمادة (242) من هذا القانون.
2- وإذا كانت قيمة الشيء مبينة في وثيقة النقل، جاز للناقل أن ينازع في هذه القيمة وان يثبت بكافة طرق الإثبات القيمة الحقيقية للشيء.
3- وفيما عدا حالتي الغش والخطأ الجسيم من الناقل أو من تابعيه، لا يسأل الناقل عن هلاك ما عهد إليه بنقله من نقود أو أوراق مالية أو مجوهرات أو تحف أو غير ذلك من الاشياء الثمينة إلا بقدر ما قدمه المرسل بشأنها وقت تسليمها من بيانات كتابية.$cc497$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc497$1- إذا هلك الشيء أو تلف دون أن تكون قيمته مبينة في وثيقة النقل، قدر التعويض على أساس قيمته الحقيقية في مكان الوصول وزمانه، إلا إذا نص القانون أو اتفق على غير ذلك. وفيما عدا حالة الهلاك الكلي، يراعى عند تقرير التعويض قيمة النقص المتسامح فيه وفقا للمادة (242) من هذا القانون.
2- وإذا كانت قيمة الشيء مبينة في وثيقة النقل، جاز للناقل أن ينازع في هذه القيمة وان يثبت بكافة طرق الإثبات القيمة الحقيقية للشيء.
3- وفيما عدا حالتي الغش والخطأ الجسيم من الناقل أو من تابعيه، لا يسأل الناقل عن هلاك ما عهد إليه بنقله من نقود أو أوراق مالية أو مجوهرات أو تحف أو غير ذلك من الاشياء الثمينة إلا بقدر ما قدمه المرسل بشأنها وقت تسليمها من بيانات كتابية.$cc497$, '1999-10-01', 'active' FROM ins_art_law17_1999_247;

WITH ins_art_law17_1999_248 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 248, $cc498$الباب الثاني: الإلتزامات والعقود التجارية — الفصل السابع: النقل$cc498$, $cc499$1- لا يجوز الجمع بين التعويض عن الهلاك الكلي والتعويض عن التأخير.
2- ولا يقضى بالتعويض عن التأخير في حالة الهلاك الجزئي إلا بالنسبة إلى الجزء الذي لم يهلك.
3- وفي جميع الأحوال لا يجوز أن يزيد التعويض الذي يقضى به على ما يستحق في حالة هلاك الشيء كليا.$cc499$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc499$1- لا يجوز الجمع بين التعويض عن الهلاك الكلي والتعويض عن التأخير.
2- ولا يقضى بالتعويض عن التأخير في حالة الهلاك الجزئي إلا بالنسبة إلى الجزء الذي لم يهلك.
3- وفي جميع الأحوال لا يجوز أن يزيد التعويض الذي يقضى به على ما يستحق في حالة هلاك الشيء كليا.$cc499$, '1999-10-01', 'active' FROM ins_art_law17_1999_248;

WITH ins_art_law17_1999_249 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 249, $cc500$الباب الثاني: الإلتزامات والعقود التجارية — الفصل السابع: النقل$cc500$, $cc501$إذا تلف الشيء أو تأخر وصوله بحيث لم يعد صالحا للغرض منه وثبتت مسئولية الناقل عن التلف أو التأخير، جاز لطالب التعويض أن يتخلى له عن الشيء مقابل الحصول على تعويض يقدر على أساس هلاك الشيء كليا.$cc501$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc501$إذا تلف الشيء أو تأخر وصوله بحيث لم يعد صالحا للغرض منه وثبتت مسئولية الناقل عن التلف أو التأخير، جاز لطالب التعويض أن يتخلى له عن الشيء مقابل الحصول على تعويض يقدر على أساس هلاك الشيء كليا.$cc501$, '1999-10-01', 'active' FROM ins_art_law17_1999_249;

WITH ins_art_law17_1999_250 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 250, $cc502$الباب الثاني: الإلتزامات والعقود التجارية — الفصل السابع: النقل$cc502$, $cc503$1- إذا دفع التعويض بسبب هلاك الشيء ثم وجد خلال سنة من تاريخ الوفاء، وجب على الناقل أن يخطر بذلك فورا من قبض التعويض مع إعلامه بحالة الشيء ودعوته للحضور لمعاينته في المكان الذي وجد فيه أو في مكان القيام أو في مكان الوصول حسب اختيار من قبض التعويض.
2- فإذا لم يرسل من قبض التعويض تعليماته خلال خمسة عشر يوما من تاريخ تسلمه الإخطار أو أرسل التعليمات ولم يحضر للمعاينة في الميعاد الذي حدده الناقل، أو حضر ورفض استرداد الشيء جاز للناقل التصرف فيه.
3- وإذا طلب من قبض التعويض استرداد الشيء، وجب أن يرد التعويض الذي قبضه بعد خصم المصاريف ومقابل الضرر الذي حدث بسبب التأخير في تسليم الشيء.$cc503$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc503$1- إذا دفع التعويض بسبب هلاك الشيء ثم وجد خلال سنة من تاريخ الوفاء، وجب على الناقل أن يخطر بذلك فورا من قبض التعويض مع إعلامه بحالة الشيء ودعوته للحضور لمعاينته في المكان الذي وجد فيه أو في مكان القيام أو في مكان الوصول حسب اختيار من قبض التعويض.
2- فإذا لم يرسل من قبض التعويض تعليماته خلال خمسة عشر يوما من تاريخ تسلمه الإخطار أو أرسل التعليمات ولم يحضر للمعاينة في الميعاد الذي حدده الناقل، أو حضر ورفض استرداد الشيء جاز للناقل التصرف فيه.
3- وإذا طلب من قبض التعويض استرداد الشيء، وجب أن يرد التعويض الذي قبضه بعد خصم المصاريف ومقابل الضرر الذي حدث بسبب التأخير في تسليم الشيء.$cc503$, '1999-10-01', 'active' FROM ins_art_law17_1999_250;

WITH ins_art_law17_1999_251 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 251, $cc504$الباب الثاني: الإلتزامات والعقود التجارية — الفصل السابع: النقل$cc504$, $cc505$1- تسلم الشيء محل النقل دون تحفظ يسقط الحق في الرجوع على الناقل بسبب التلف أو الهلاك الجزئي ما لم يثبت المرسل إليه حالة الشيء ويقيم الدعوى على الناقل خلال تسعين يوما من تاريخ التسليم.
2- ولا يجوز للناقل التمسك بعدم قبول الدعوى وفقا للفقرة السابقة:
(أ) إذا ثبت أن الهلاك أو التلف نشأ عن غش أو خطأ جسيم صدر من الناقل أو من تابعيه.
(ب) إذا ثبت أن الناقل أو تابعيه تعمدوا إخفاء الهلاك الجزئي أو التلف.
3- يكون إثبات حالة الشيء المشار إليه في الفقرة الأولى من هذه المادة بمعرفة أحد رجال الإدارة أو خبير يعينه القاضي المختص بأمر على عريضة.$cc505$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc505$1- تسلم الشيء محل النقل دون تحفظ يسقط الحق في الرجوع على الناقل بسبب التلف أو الهلاك الجزئي ما لم يثبت المرسل إليه حالة الشيء ويقيم الدعوى على الناقل خلال تسعين يوما من تاريخ التسليم.
2- ولا يجوز للناقل التمسك بعدم قبول الدعوى وفقا للفقرة السابقة:
(أ) إذا ثبت أن الهلاك أو التلف نشأ عن غش أو خطأ جسيم صدر من الناقل أو من تابعيه.
(ب) إذا ثبت أن الناقل أو تابعيه تعمدوا إخفاء الهلاك الجزئي أو التلف.
3- يكون إثبات حالة الشيء المشار إليه في الفقرة الأولى من هذه المادة بمعرفة أحد رجال الإدارة أو خبير يعينه القاضي المختص بأمر على عريضة.$cc505$, '1999-10-01', 'active' FROM ins_art_law17_1999_251;

WITH ins_art_law17_1999_252 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 252, $cc506$الباب الثاني: الإلتزامات والعقود التجارية — الفصل السابع: النقل$cc506$, $cc507$1- إذا قام عدة ناقلين على التعاقب بتنفيذ عقد نقل واحد كان كل واحد منهم مسئولا بالتضامن مع الآخرين قبل المرسل أو المرسل إليه كما لو كان قد قام بتنفيذه وحده ويقع باطلا كل شرط على خلاف ذلك.
2- (*) وإذا دفع أحد الناقلين المتعاقبين التعويض أو طولب به رسميا كان له الرجوع على الناقلين الآخرين بنسبة ما يستحقه كل منهم من أجرة النقل، وتوزع حصة المعسر منهم على الآخرين بالنسبة ذاتها. ويعفى من الاشتراك في تحمل المسئولية الناقل الذي يثبت أن الضرر لم يقع في الجزء الخاص به من النقل.
[ملاحظة توثيقية: صححت الفقرة 2 من المادة (252) بالاستدراك المنشور بالجريدة الرسمية- العدد 38 (مكرر) في 1999/9/27.]$cc507$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc507$1- إذا قام عدة ناقلين على التعاقب بتنفيذ عقد نقل واحد كان كل واحد منهم مسئولا بالتضامن مع الآخرين قبل المرسل أو المرسل إليه كما لو كان قد قام بتنفيذه وحده ويقع باطلا كل شرط على خلاف ذلك.
2- (*) وإذا دفع أحد الناقلين المتعاقبين التعويض أو طولب به رسميا كان له الرجوع على الناقلين الآخرين بنسبة ما يستحقه كل منهم من أجرة النقل، وتوزع حصة المعسر منهم على الآخرين بالنسبة ذاتها. ويعفى من الاشتراك في تحمل المسئولية الناقل الذي يثبت أن الضرر لم يقع في الجزء الخاص به من النقل.
[ملاحظة توثيقية: صححت الفقرة 2 من المادة (252) بالاستدراك المنشور بالجريدة الرسمية- العدد 38 (مكرر) في 1999/9/27.]$cc507$, '1999-10-01', 'active' FROM ins_art_law17_1999_252;

WITH ins_art_law17_1999_253 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 253, $cc508$الباب الثاني: الإلتزامات والعقود التجارية — الفصل السابع: النقل$cc508$, $cc509$يسأل الناقل الأخير قبل الناقلين السابقين عليه عن مطالبة المرسل إليه بالمبالغ المستحقة بسبب النقل، وله حق تحصيلها عنهم بالنيابة واتخاذ الإجراءات القانونية لاستيفائها بما في ذلك استعمال حق الامتياز على الشيء موضوع النقل.$cc509$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
