INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc509$يسأل الناقل الأخير قبل الناقلين السابقين عليه عن مطالبة المرسل إليه بالمبالغ المستحقة بسبب النقل، وله حق تحصيلها عنهم بالنيابة واتخاذ الإجراءات القانونية لاستيفائها بما في ذلك استعمال حق الامتياز على الشيء موضوع النقل.$cc509$, '1999-10-01', 'active' FROM ins_art_law17_1999_253;

WITH ins_art_law17_1999_254 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 254, $cc510$الباب الثاني: الإلتزامات والعقود التجارية — الفصل السابع: النقل$cc510$, $cc511$1- تتقادم كل دعوى ناشئة عن عقد نقل الاشياء بمضي سنة تبدأ من تاريخ تسليم الشيء إلى المرسل إليه أو إلى الجمرك أو إلى الأمين الذي يعينه القاضي لاستيداع الشيء وتسرى المدة في حالة الهلاك الكلي من تاريخ انقضاء الميعاد المنصوص عليه في الفقرة الثانية من المادة (240) من هذا القانون.
2- كما تتقادم دعوى الناقل في الرجوع على الناقلين المتعاقبين وفقا للفقرة الثانية من المادة (252) من هذا القانون بمضي تسعين يوما من تاريخ الوفاء بالتعويض أو من تاريخ مطالبته به رسميا.
3- لا يجوز أن يتمسك بالتقادم المنصوص عليه في هذه المادة من صدر منه أو من تابعيه غش أو خطأ جسيم.
