WITH ins_art_law17_1999_256 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 256, $cc514$الباب الثاني: الإلتزامات والعقود التجارية — الفصل السابع: النقل$cc514$, $cc515$1- إذا حالت القوة القاهرة دون مباشرة النقل أو قامت قبل مباشرته ظروف تجعله خطرا على الأرواح، فلا يلتزم الناقل بأداء تعويض بسبب عدم تنفيذ النقل ولا يستحق أجرة النقل.
2- وإذا قامت القوة القاهرة أو الخطر على الأرواح أثناء تنفيذ النقل فلا يستحق الناقل الأجرة إلا عن الجزء الذي تم من النقل.$cc515$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc515$1- إذا حالت القوة القاهرة دون مباشرة النقل أو قامت قبل مباشرته ظروف تجعله خطرا على الأرواح، فلا يلتزم الناقل بأداء تعويض بسبب عدم تنفيذ النقل ولا يستحق أجرة النقل.
2- وإذا قامت القوة القاهرة أو الخطر على الأرواح أثناء تنفيذ النقل فلا يستحق الناقل الأجرة إلا عن الجزء الذي تم من النقل.$cc515$, '1999-10-01', 'active' FROM ins_art_law17_1999_256;

WITH ins_art_law17_1999_257 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 257, $cc516$الباب الثاني: الإلتزامات والعقود التجارية — الفصل السابع: النقل$cc516$, $cc517$1- إذا عدل الراكب عن مباشرته قبل النقل وجب أن يخطر الناقل بعدوله قبل اليوم المعين لتنفيذ النقل، ويجوز في أحوال الضرورة عمل الإخطار في اليوم المذكور بشرط أن يصل قبل الساعة المعينة لتنفيذ النقل.
2- إذا حصل الإخطار وفقا للفقرة السابقة فلا يستحق الناقل أجرة النقل.
3- إذا عدل الراكب عن مواصلة مباشرته بعد استحقت عليه الأجرة كاملة إلا إذا كان عدوله لضرورة فلا تستحق عليه إلا أجرة الجزء الذي تم من النقل.$cc517$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc517$1- إذا عدل الراكب عن مباشرته قبل النقل وجب أن يخطر الناقل بعدوله قبل اليوم المعين لتنفيذ النقل، ويجوز في أحوال الضرورة عمل الإخطار في اليوم المذكور بشرط أن يصل قبل الساعة المعينة لتنفيذ النقل.
2- إذا حصل الإخطار وفقا للفقرة السابقة فلا يستحق الناقل أجرة النقل.
3- إذا عدل الراكب عن مواصلة مباشرته بعد استحقت عليه الأجرة كاملة إلا إذا كان عدوله لضرورة فلا تستحق عليه إلا أجرة الجزء الذي تم من النقل.$cc517$, '1999-10-01', 'active' FROM ins_art_law17_1999_257;

WITH ins_art_law17_1999_258 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 258, $cc518$الباب الثاني: الإلتزامات والعقود التجارية — الفصل السابع: النقل$cc518$, $cc519$مع عدم الإخلال بأحكام المادة (257) من هذا القانون، إذا لم يحضر الراكب في الميعاد المعين للنقل استحقت عليه الأجرة كاملة، وإذا كان قد دفعها جاز له تنفيذ النقل في ميعاد لاحق إلا إذا اتفق أو جرى العرف على غير ذلك.$cc519$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc519$مع عدم الإخلال بأحكام المادة (257) من هذا القانون، إذا لم يحضر الراكب في الميعاد المعين للنقل استحقت عليه الأجرة كاملة، وإذا كان قد دفعها جاز له تنفيذ النقل في ميعاد لاحق إلا إذا اتفق أو جرى العرف على غير ذلك.$cc519$, '1999-10-01', 'active' FROM ins_art_law17_1999_258;

WITH ins_art_law17_1999_259 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 259, $cc520$الباب الثاني: الإلتزامات والعقود التجارية — الفصل السابع: النقل$cc520$, $cc521$إذا تعطل النقل بسبب يرجع إلى الناقل أو تابعيه أو الوسائل التي يستعملها في النقل، جاز للراكب اختيار وسيلة نقل أخرى، وفي هذه الحالة يتحمل الناقل مصاريف إيصاله إلى المكان المتفق عليه، وله ان يختار الانتظار حتى تعود حركة النقل، وفي هذه الحالة لا يجوز إلزامه بأداء أية أجرة إضافية مع عدم الإخلال بحق الراكب في التعويض في الحالتين إذا كان مقتض.$cc521$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc521$إذا تعطل النقل بسبب يرجع إلى الناقل أو تابعيه أو الوسائل التي يستعملها في النقل، جاز للراكب اختيار وسيلة نقل أخرى، وفي هذه الحالة يتحمل الناقل مصاريف إيصاله إلى المكان المتفق عليه، وله ان يختار الانتظار حتى تعود حركة النقل، وفي هذه الحالة لا يجوز إلزامه بأداء أية أجرة إضافية مع عدم الإخلال بحق الراكب في التعويض في الحالتين إذا كان مقتض.$cc521$, '1999-10-01', 'active' FROM ins_art_law17_1999_259;

WITH ins_art_law17_1999_260 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 260, $cc522$الباب الثاني: الإلتزامات والعقود التجارية — الفصل السابع: النقل$cc522$, $cc523$يجوز النزول عن بطاقة النقل قبل مباشرته إلا إذا كانت البطاقة باسم الراكب وروعي في إعطائها له اعتبارات شخصية.$cc523$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
