(أ) التأخير في الوصول.
(ب) ما يلحق الراكب أثناء تنفيذ عقد النقل من أضرار بدنية أو غير بدنية.$cc533$, '1999-10-01', 'active' FROM ins_art_law17_1999_265;

WITH ins_art_law17_1999_266 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 266, $cc534$الباب الثاني: الإلتزامات والعقود التجارية — الفصل السابع: النقل$cc534$, $cc535$لا يجوز للناقل أن ينفي مسئوليته عن التأخير أو عن الأضرار البدنية أو غير البدنية التي تلحق الراكب أثناء تنفيذ عقد النقل إلا بإثبات القوة القاهرة أو خطا الراكب.$cc535$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc535$لا يجوز للناقل أن ينفي مسئوليته عن التأخير أو عن الأضرار البدنية أو غير البدنية التي تلحق الراكب أثناء تنفيذ عقد النقل إلا بإثبات القوة القاهرة أو خطا الراكب.$cc535$, '1999-10-01', 'active' FROM ins_art_law17_1999_266;

WITH ins_art_law17_1999_267 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 267, $cc536$الباب الثاني: الإلتزامات والعقود التجارية — الفصل السابع: النقل$cc536$, $cc537$1- يقع باطلا كل شرط يقضى بإعفاء الناقل كليا أو جزئيا من المسئولية عما يلحق الراكب من أضرار بدنية.
2- ويعتبر في حكم الإعفاء من المسئولية كل شرط يكون من شأنه إلزام الراكب بدفع أو بعض نفقات التأمين ضد مسئولية الناقل وكل شرط ينزل بموجبه الراكب للناقل عن حقوقه في التأمين ضد أخطاء الناقل.$cc537$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc537$1- يقع باطلا كل شرط يقضى بإعفاء الناقل كليا أو جزئيا من المسئولية عما يلحق الراكب من أضرار بدنية.
2- ويعتبر في حكم الإعفاء من المسئولية كل شرط يكون من شأنه إلزام الراكب بدفع أو بعض نفقات التأمين ضد مسئولية الناقل وكل شرط ينزل بموجبه الراكب للناقل عن حقوقه في التأمين ضد أخطاء الناقل.$cc537$, '1999-10-01', 'active' FROM ins_art_law17_1999_267;

WITH ins_art_law17_1999_268 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 268, $cc538$الباب الثاني: الإلتزامات والعقود التجارية — الفصل السابع: النقل$cc538$, $cc539$1- يجوز للناقل أن يشترط إعفاءه إعفاء كليا أو جزئيا من المسئولية الناشئة عن التأخير أو عن الأضرار غير البدنية التي تلحق الراكب.
2- ويجب أن يكون شرط الإعفاء من المسئولية أو تحديدها مكتوبا وإلا اعتبر كأن لم يكن، وإذا كان عقد النقل محررا على نماذج مطبوعة وجب أن يكون الشرط واضحا ومكتوبا بكيفية تسترعى الانتباه، وإلا جاز للمحكمة أن تعتبر الشرط كأن لم يكن.
3- ولا يجوز أن يتمسك الناقل بشرط الإعفاء من المسئولية أو تحديدها إذا ثبت صدور غش أو خطأ جسيم منه أو من تابعيه.$cc539$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc539$1- يجوز للناقل أن يشترط إعفاءه إعفاء كليا أو جزئيا من المسئولية الناشئة عن التأخير أو عن الأضرار غير البدنية التي تلحق الراكب.
2- ويجب أن يكون شرط الإعفاء من المسئولية أو تحديدها مكتوبا وإلا اعتبر كأن لم يكن، وإذا كان عقد النقل محررا على نماذج مطبوعة وجب أن يكون الشرط واضحا ومكتوبا بكيفية تسترعى الانتباه، وإلا جاز للمحكمة أن تعتبر الشرط كأن لم يكن.
3- ولا يجوز أن يتمسك الناقل بشرط الإعفاء من المسئولية أو تحديدها إذا ثبت صدور غش أو خطأ جسيم منه أو من تابعيه.$cc539$, '1999-10-01', 'active' FROM ins_art_law17_1999_268;

WITH ins_art_law17_1999_269 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 269, $cc540$الباب الثاني: الإلتزامات والعقود التجارية — الفصل السابع: النقل$cc540$, $cc541$1- على الراكب حراسة الأمتعة والحيوانات التي يرخص له في نقلها معه، ولا يسأل الناقل عن ضياعها أو عما يلحقها من أضرار إلا إذا اثبت الراكب صدور خطأ من الناقل أو من تابعيه.
