WITH ins_art_law17_1999_272 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 272, $cc546$الباب الثاني: الإلتزامات والعقود التجارية — الفصل السابع: النقل$cc546$, $cc547$1- تتقادم بمضي سنتين كل دعوى تنشأ عن عقد النقل، ويكون موضوعها مطالبة الناقل بالتعويض عن وفاة الراكب أو أصابته بأضرار بدنية، وتسرى هذه المدة في حالة الوفاة من تاريخ وقوعها، وفي حالة الإصابة البدنية من تاريخ وقوع الحادث.
2- وتتقادم بمضي سنة كل دعوى أخرى تنشأ عن عقد نقل الأشخاص. وتسرى هذه المدة في الميعاد المعين للوصول، وعند عدم التعيين من الميعاد الذي كان يستغرقه الناقل العادي في النقل لو وجد في الظروف نفسها.
3- لا يجوز أن يتمسك بالتقادم المنصوص عليه في هذه المادة من صدر منه أو من تابعيه غش أو خطأ جسيم.
