(ب) كل شرط يقضى بإعفائه من المسئولية عما يلحق الراكب من أضرار بدنية.
2- ويعد في حكم الإعفاء من المسئولية كل شرط يكون من شأنه إلزام المرسل أو المرسل إليه في نقل الاشياء أو الراكب في نقل الأشخاص بدفع كل أو بعض نفقات التأمين ضد مسئولية الوكيل بالعمولة للنقل وكل شرط ينزل بموجبه المرسل أو المرسل إليه أو الراكب للوكيل بالعمولة عن الحقوق الناشئة عن التأمين الذي أبرمه ضد مخاطر النقل.$cc561$, '1999-10-01', 'active' FROM ins_art_law17_1999_279;

WITH ins_art_law17_1999_280 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 280, $cc562$الباب الثاني: الإلتزامات والعقود التجارية — الفصل السابع: النقل$cc562$, $cc563$1- فيما عدا حالتي الغش والخطأ الجسيم من الوكيل بالعمولة للنقل أو من أحد تابعيه أو من الناقل أو من أحد تابعيه، يجوز للوكيل بالعمولة للنقل أن يشترط:
(أ) تحديد مسئوليته عن هلاك الشيء موضوع النقل كليا أو جزئيا أو تلفه بشرط ألا يقل التعويض المتفق عليه عن ثلث قيمة البضاعة المنقولة من مكان وزمان نقلها، وكل اتفاق على تعويض يقل عن هذا الحد يزاد إليه.
(ب) إعفاءه كليا أو جزئيا من المسئولية عما يلحق الراكب من أضرار غير بدنية.
(ج) إعفاءه كليا أو جزئيا من المسئولية عن التأخير.
2- يجب أن يكون شرط الإعفاء من المسئولية أو تحديدها مكتوبا وإلا اعتبر كأن لم يكن، وإذا كان عقد الوكالة بالعمولة للنقل محررا على نماذج مطبوعة وجب أن يكون الشرط واضحا ومكتوبا بكيفية تسترعى الانتباه وإلا جاز للمحكمة أن تعتبره كأن لم يكن.$cc563$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc563$1- فيما عدا حالتي الغش والخطأ الجسيم من الوكيل بالعمولة للنقل أو من أحد تابعيه أو من الناقل أو من أحد تابعيه، يجوز للوكيل بالعمولة للنقل أن يشترط:
