SELECT id, 1, $cc571$1- يقصد بالنقل الجوي في هذا الفرع نقل الأشخاص أو الأمتعة أو البضائع بالطائرات بهدف تحقيق الربح.
2- ويقصد بلفظ الأمتعة الاشياء التي يجوز للمسافر حملها معه في الطائرة وتسلم للناقل لتكون في حراسته أثناء السفر، ولا يشمل هذا اللفظ الاشياء الصغيرة والشخصية التي تبقى في حراسة الراكب أثناء السفر.$cc571$, '1999-10-01', 'active' FROM ins_art_law17_1999_284;

WITH ins_art_law17_1999_285 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 285, $cc572$الباب الثاني: الإلتزامات والعقود التجارية — الفصل السابع: النقل$cc572$, $cc573$1- تسرى على النقل الجوي الدولي أحكام الاتفاقيات الدولية النافذة في مصر.
2- وتسرى على النقل الجوي الداخلي أحكام هذا الفرع والأحكام الخاصة المنصوص عليها في المواد التالية.
3- يكون النقل الجوي داخليا إذا كانت النقطتان المعينتان باتفاق المتعاقدين للقيام والوصول واقعتين في مصر ولو كانت الطائرة تواصل رحلتها بعد مغادرة نقطة الوصول إلى ما وراء الحدود الإقليمية المصرية.$cc573$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
