SELECT id, 1, $cc577$يسأل الناقل الجوي عن الضرر الذي يحدث في حالة وفاة الراكب أو إصابته بجروح أو بأي ضرر بدني آخر إذا وقع الحادث الذي أدى إلى الضرر أثناء وجود الراكب في حراسة الناقل أو تابعيه داخل مطار القيام أو في الطائرة أو داخل مطار الوصول أو في أي مطار أو مكان آخر تهبط فيه الطائرة اختيارا أو اضطرارا.$cc577$, '1999-10-01', 'active' FROM ins_art_law17_1999_287;

WITH ins_art_law17_1999_288 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 288, $cc578$الباب الثاني: الإلتزامات والعقود التجارية — الفصل السابع: النقل$cc578$, $cc579$1- يسأل الناقل الجوي عن الضرر الذي يحدث في حالة هلاك الأمتعة أو البضائع أو تلفها إذا وقع الحادث الذي أدى الضرر إلى الضرر أثناء النقل الجوي.
2- يشمل النقل الجوي الفترة التي تكون فيها الأمتعة أو البضائع في حراسة الناقل أو تابعيه داخل مطار القيام أو أثناء الطيران أو داخل مطار الوصول أو في أي مطار أو مكان آخر تهبط فيه الطائرة اختيارا أو اضطرارا.
3- لا يشمل النقل الجوي الفترة التي تكون فيها الأمتعة أو البضائع محل نقل بري أو بحري أو نهري يقع خارج المطار إلا إذا كان هذا النقل لازما لشحن الأمتعة أو البضائع أو لتسليمها أو لنقلها من طائرة إلى أخرى تنفيذا لعقد النقل الجوي.$cc579$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc579$1- يسأل الناقل الجوي عن الضرر الذي يحدث في حالة هلاك الأمتعة أو البضائع أو تلفها إذا وقع الحادث الذي أدى الضرر إلى الضرر أثناء النقل الجوي.
2- يشمل النقل الجوي الفترة التي تكون فيها الأمتعة أو البضائع في حراسة الناقل أو تابعيه داخل مطار القيام أو أثناء الطيران أو داخل مطار الوصول أو في أي مطار أو مكان آخر تهبط فيه الطائرة اختيارا أو اضطرارا.
3- لا يشمل النقل الجوي الفترة التي تكون فيها الأمتعة أو البضائع محل نقل بري أو بحري أو نهري يقع خارج المطار إلا إذا كان هذا النقل لازما لشحن الأمتعة أو البضائع أو لتسليمها أو لنقلها من طائرة إلى أخرى تنفيذا لعقد النقل الجوي.$cc579$, '1999-10-01', 'active' FROM ins_art_law17_1999_288;

WITH ins_art_law17_1999_289 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 289, $cc580$الباب الثاني: الإلتزامات والعقود التجارية — الفصل السابع: النقل$cc580$, $cc581$1- يسأل الناقل الجوي عن الضرر الذي يترتب على التأخير في وصول الراكب أو الأمتعة أو البضائع.
2- تعتبر في حكم الهالكة الأمتعة أو البضائع التي لا يسلمها الناقل للمرسل أليه أو يخطره بالحضور لتسلمها خلال ثلاثين يوما من تاريخ انقضاء الميعاد للتسليم، وفي حالة عدم التعيين من تاريخ انقضاء الميعاد الذي يستغرقه الناقل الجوي العادي في النقل إذا وجد في نفس الظروف.$cc581$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc581$1- يسأل الناقل الجوي عن الضرر الذي يترتب على التأخير في وصول الراكب أو الأمتعة أو البضائع.
2- تعتبر في حكم الهالكة الأمتعة أو البضائع التي لا يسلمها الناقل للمرسل أليه أو يخطره بالحضور لتسلمها خلال ثلاثين يوما من تاريخ انقضاء الميعاد للتسليم، وفي حالة عدم التعيين من تاريخ انقضاء الميعاد الذي يستغرقه الناقل الجوي العادي في النقل إذا وجد في نفس الظروف.$cc581$, '1999-10-01', 'active' FROM ins_art_law17_1999_289;

WITH ins_art_law17_1999_290 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 290, $cc582$الباب الثاني: الإلتزامات والعقود التجارية — الفصل السابع: النقل$cc582$, $cc583$1- لا يجوز للناقل الجوي نفي مسئوليته إلا بإثبات القوة القاهرة أو العيب الذاتي في الشيء أو خطا المرسل أو المرسل إليه أو الراكب.
2- إذا اثبت الناقل أحد الأمور المذكورة في الفقرة السابقة جاز للمدعى نفي هذا الإثبات بإقامة الدليل على أن الضرر لم يحدث بسبب هذا الأمر أو انه لم يكن السبب الوحيد في إحداث الضرر، وفي هذه الحالة الأخيرة يخفض التعويض بنسبة الضرر الذي ينسب إلى الأمر الذي أثبته الناقل الجوي.$cc583$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc583$1- لا يجوز للناقل الجوي نفي مسئوليته إلا بإثبات القوة القاهرة أو العيب الذاتي في الشيء أو خطا المرسل أو المرسل إليه أو الراكب.
2- إذا اثبت الناقل أحد الأمور المذكورة في الفقرة السابقة جاز للمدعى نفي هذا الإثبات بإقامة الدليل على أن الضرر لم يحدث بسبب هذا الأمر أو انه لم يكن السبب الوحيد في إحداث الضرر، وفي هذه الحالة الأخيرة يخفض التعويض بنسبة الضرر الذي ينسب إلى الأمر الذي أثبته الناقل الجوي.$cc583$, '1999-10-01', 'active' FROM ins_art_law17_1999_290;

WITH ins_art_law17_1999_291 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 291, $cc584$الباب الثاني: الإلتزامات والعقود التجارية — الفصل السابع: النقل$cc584$, $cc585$لا يسأل الناقل الجوي عن الاشياء الصغيرة أو الشخصية التي تبقى في حراسة المسافر أثناء السفر إلا إذا اثبت المسافر صدور خطأ من الناقل أو من تابعيه.$cc585$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc585$لا يسأل الناقل الجوي عن الاشياء الصغيرة أو الشخصية التي تبقى في حراسة المسافر أثناء السفر إلا إذا اثبت المسافر صدور خطأ من الناقل أو من تابعيه.$cc585$, '1999-10-01', 'active' FROM ins_art_law17_1999_291;

WITH ins_art_law17_1999_292 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 292, $cc586$الباب الثاني: الإلتزامات والعقود التجارية — الفصل السابع: النقل$cc586$, $cc587$1- لا يجوز في حالة نقل الأشخاص أن يجاوز التعويض الذي يحكم به على الناقل الجوي مائة وخمسين ألف جنيه بالنسبة إلى كل مسافر إلا إذا اتفق صراحة على تجاوز هذا المبلغ.
2- وفي حالة نقل الأمتعة والبضائع لا يجوز أن يجاوز التعويض خمسين جنيها عن كل كيلوجرام. ومع ذلك إذا أعلن المرسل عند تسليم الأمتعة أو البضائع إلى الناقل انه يعلق أهمية خاصة على تسليمها نظرا لقيمتها ودفع ما يطلبه الناقل من أجرة إضافية نظير ذلك، التزم الناقل بأداء التعويض بمقدار القيمة التي أعلنها المرسل إلا إذا اثبت الناقل أنها تجاوز القيمة الحقيقة للشيء.
3- وبالنسبة إلى الاشياء الصغيرة أو الشخصية التي تبقى في حراسة المسافر أثناء السفر لا يجاوز التعويض الذي يحكم به لكل مسافر عن تلك الاشياء خمسمائة جنيه.
4- ولا يجوز للناقل الجوي التمسك بتحديد المسئولية المنصوص عليها في هذه المادة إذا ثبت أن الضرر نجم عن فعل أو امتناع من الناقل أو من تابعيه أو من وكلائه أثناء تأدية وظائفهم بقصد إحداث الضرر أو برعونة مقرونة بإدراك احتمال وقوع الضرر.$cc587$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc587$1- لا يجوز في حالة نقل الأشخاص أن يجاوز التعويض الذي يحكم به على الناقل الجوي مائة وخمسين ألف جنيه بالنسبة إلى كل مسافر إلا إذا اتفق صراحة على تجاوز هذا المبلغ.
2- وفي حالة نقل الأمتعة والبضائع لا يجوز أن يجاوز التعويض خمسين جنيها عن كل كيلوجرام. ومع ذلك إذا أعلن المرسل عند تسليم الأمتعة أو البضائع إلى الناقل انه يعلق أهمية خاصة على تسليمها نظرا لقيمتها ودفع ما يطلبه الناقل من أجرة إضافية نظير ذلك، التزم الناقل بأداء التعويض بمقدار القيمة التي أعلنها المرسل إلا إذا اثبت الناقل أنها تجاوز القيمة الحقيقة للشيء.
3- وبالنسبة إلى الاشياء الصغيرة أو الشخصية التي تبقى في حراسة المسافر أثناء السفر لا يجاوز التعويض الذي يحكم به لكل مسافر عن تلك الاشياء خمسمائة جنيه.
4- ولا يجوز للناقل الجوي التمسك بتحديد المسئولية المنصوص عليها في هذه المادة إذا ثبت أن الضرر نجم عن فعل أو امتناع من الناقل أو من تابعيه أو من وكلائه أثناء تأدية وظائفهم بقصد إحداث الضرر أو برعونة مقرونة بإدراك احتمال وقوع الضرر.$cc587$, '1999-10-01', 'active' FROM ins_art_law17_1999_292;

WITH ins_art_law17_1999_293 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 293, $cc588$الباب الثاني: الإلتزامات والعقود التجارية — الفصل السابع: النقل$cc588$, $cc589$1- إذا أقيمت دعوى التعويض على أحد تابعي الناقل أو أحد وكلائه جاز له التمسك بتحديد المسئولية المنصوص عليها في المادة (292) من هذا القانون إذا ثبت أن الفعل الذي أحدث الضرر وقع منه أثناء تأدية وظيفته.
2- ولا يجوز لتابع الناقل أو وكيله التمسك بتحديد مسئوليته إذا ثبت أن الضرر نجم عن فعل أو امتناع منه أثناء تأدية وظيفته بقصد إحداث الضرر أو برعونة مقرونة بإدراك احتمال وقوع الضرر.
3- ولا يجوز أن يريد مجموع ما يريد أن يحصل عليه طالب التعويض من الناقل وتابعيه ووكلائه عن الحدود المنصوص عليها في المادة (292) من هذا القانون.$cc589$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc589$1- إذا أقيمت دعوى التعويض على أحد تابعي الناقل أو أحد وكلائه جاز له التمسك بتحديد المسئولية المنصوص عليها في المادة (292) من هذا القانون إذا ثبت أن الفعل الذي أحدث الضرر وقع منه أثناء تأدية وظيفته.
2- ولا يجوز لتابع الناقل أو وكيله التمسك بتحديد مسئوليته إذا ثبت أن الضرر نجم عن فعل أو امتناع منه أثناء تأدية وظيفته بقصد إحداث الضرر أو برعونة مقرونة بإدراك احتمال وقوع الضرر.
3- ولا يجوز أن يريد مجموع ما يريد أن يحصل عليه طالب التعويض من الناقل وتابعيه ووكلائه عن الحدود المنصوص عليها في المادة (292) من هذا القانون.$cc589$, '1999-10-01', 'active' FROM ins_art_law17_1999_293;

WITH ins_art_law17_1999_294 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 294, $cc590$الباب الثاني: الإلتزامات والعقود التجارية — الفصل السابع: النقل$cc590$, $cc591$1- يقع باطلا كل شرط يقضى بإعفاء الناقل الجوي من المسئولية أو بتحديدها اقل من الحدود المنصوص عليها في المادة (292) من هذا القانون.
2- ويعتبر في حكم الإعفاء من المسئولية كل شرط يكون من شأنه إلزام المسافر أو المرسل إليه بدفع كل أو بعض نفقات التأمين ضد مسئولية الناقل الجوي وكل شرط ينزل بموجبه المسافر أو المرسل إليه للناقل عن حقوقه في التأمين ضد أخطار النقل.$cc591$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc591$1- يقع باطلا كل شرط يقضى بإعفاء الناقل الجوي من المسئولية أو بتحديدها اقل من الحدود المنصوص عليها في المادة (292) من هذا القانون.
2- ويعتبر في حكم الإعفاء من المسئولية كل شرط يكون من شأنه إلزام المسافر أو المرسل إليه بدفع كل أو بعض نفقات التأمين ضد مسئولية الناقل الجوي وكل شرط ينزل بموجبه المسافر أو المرسل إليه للناقل عن حقوقه في التأمين ضد أخطار النقل.$cc591$, '1999-10-01', 'active' FROM ins_art_law17_1999_294;

WITH ins_art_law17_1999_295 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 295, $cc592$الباب الثاني: الإلتزامات والعقود التجارية — الفصل السابع: النقل$cc592$, $cc593$تسلم الأمتعة أو البضائع دون تحفظ يسقط الحق في الرجوع على الناقل بسبب الهلاك الجزئي او التلف ما لم يثبت المسافر أو المرسل إليه حالة الأمتعة أو البضائع ويقيم الدعوى خلال تسعين يوما من تاريخ التسليم، وتسرى في هذا الشأن الأحكام المنصوص عليها في الفقرتين الثانية والثالثة من المادة (251) من هذا القانون.$cc593$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc593$تسلم الأمتعة أو البضائع دون تحفظ يسقط الحق في الرجوع على الناقل بسبب الهلاك الجزئي او التلف ما لم يثبت المسافر أو المرسل إليه حالة الأمتعة أو البضائع ويقيم الدعوى خلال تسعين يوما من تاريخ التسليم، وتسرى في هذا الشأن الأحكام المنصوص عليها في الفقرتين الثانية والثالثة من المادة (251) من هذا القانون.$cc593$, '1999-10-01', 'active' FROM ins_art_law17_1999_295;

WITH ins_art_law17_1999_296 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 296, $cc594$الباب الثاني: الإلتزامات والعقود التجارية — الفصل السابع: النقل$cc594$, $cc595$1- تتقادم بمضي سنة كل دعوى ناشئة عن عقد النقل الجوي يكون موضوعها مطالبة الناقل بالتعويض عن هلاك الأمتعة والبضائع أو تلفها. وتسرى هذه المدة في حالة الهلاك الجزئي او التلف من تاريخ تسليم الشيء موضوع النقل وفقا للفقرة الأولى من المادة (254) من هذا القانون، وفي حالة الهلاك الكلي من تاريخ انقضاء الميعاد المنصوص عليه في الفقرة الثانية من المادة (289) من هذا القانون.
2- تتقادم بمضي سنتين كل دعوى ناشئة عن عقد النقل الجوي يكون موضوعها مطالبة الناقل بالتعويض عن وفاة المسافر أو إصابته بأضرار بدنية. وتسرى هذه المدة في حالة الوفاة من تاريخ وقوعها، وفي حالة الإصابة البدنية من تاريخ وقوع الحادث.
3- تتقادم بمضي سنة كل دعوى أخرى تنشأ عن عقد النقل الجوي. وتسرى هذه المدة من الميعاد المعين لوصول الطائرة، وفي حالة عدم التعيين تسرى من الميعاد الذي يستغرقه الناقل الجوي العادي إذا وجد في نفس الظروف.
4- لا يجوز أن يتمسك بالتقادم المنصوص عليه في الفقرات الثلاث السابقة من هذه المادة من صدر منه أو من وكلائه أو من تابعيه غش أو خطأ جسيم.$cc595$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc595$1- تتقادم بمضي سنة كل دعوى ناشئة عن عقد النقل الجوي يكون موضوعها مطالبة الناقل بالتعويض عن هلاك الأمتعة والبضائع أو تلفها. وتسرى هذه المدة في حالة الهلاك الجزئي او التلف من تاريخ تسليم الشيء موضوع النقل وفقا للفقرة الأولى من المادة (254) من هذا القانون، وفي حالة الهلاك الكلي من تاريخ انقضاء الميعاد المنصوص عليه في الفقرة الثانية من المادة (289) من هذا القانون.
2- تتقادم بمضي سنتين كل دعوى ناشئة عن عقد النقل الجوي يكون موضوعها مطالبة الناقل بالتعويض عن وفاة المسافر أو إصابته بأضرار بدنية. وتسرى هذه المدة في حالة الوفاة من تاريخ وقوعها، وفي حالة الإصابة البدنية من تاريخ وقوع الحادث.
3- تتقادم بمضي سنة كل دعوى أخرى تنشأ عن عقد النقل الجوي. وتسرى هذه المدة من الميعاد المعين لوصول الطائرة، وفي حالة عدم التعيين تسرى من الميعاد الذي يستغرقه الناقل الجوي العادي إذا وجد في نفس الظروف.
4- لا يجوز أن يتمسك بالتقادم المنصوص عليه في الفقرات الثلاث السابقة من هذه المادة من صدر منه أو من وكلائه أو من تابعيه غش أو خطأ جسيم.$cc595$, '1999-10-01', 'active' FROM ins_art_law17_1999_296;

WITH ins_art_law17_1999_297 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 297, $cc596$الباب الثاني: الإلتزامات والعقود التجارية — الفصل السابع: النقل$cc596$, $cc597$1- إذا اتفق على أن يكون النقل بالمجان فلا يكون الناقل الجوي مسئولا إلا إذا اثبت طالب التعويض أن الضرر نشأ عن خطأ صدر من الناقل أو من أحد تابعيه أو من وكلائه وفي هذه الحالة أيضا يجوز للناقل الجوي أو لتابعيه أو لوكيله التمسك بتحديد المسئولية وفقا للمادة 292 من هذا القانون.
2- يكون النقل مجانيا إذا كان بدون أجرة ولم يكن الناقل محترفا النقل. فإذا كان الناقل محترفا اعتبر النقل غير مجاني ولو كان بغير أجرة.$cc597$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc597$1- إذا اتفق على أن يكون النقل بالمجان فلا يكون الناقل الجوي مسئولا إلا إذا اثبت طالب التعويض أن الضرر نشأ عن خطأ صدر من الناقل أو من أحد تابعيه أو من وكلائه وفي هذه الحالة أيضا يجوز للناقل الجوي أو لتابعيه أو لوكيله التمسك بتحديد المسئولية وفقا للمادة 292 من هذا القانون.
2- يكون النقل مجانيا إذا كان بدون أجرة ولم يكن الناقل محترفا النقل. فإذا كان الناقل محترفا اعتبر النقل غير مجاني ولو كان بغير أجرة.$cc597$, '1999-10-01', 'active' FROM ins_art_law17_1999_297;

