  SELECT id, 302, $cc606$الباب الثالث: عمليات البنوك$cc606$, $cc607$يفتح البنك للمودع حسابا تقيد فيه جميع العمليات التي تتم بين البنك والمودع او بين البنك والغير لحساب المودع.$cc607$
