WITH ins_art_law17_1999_309 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 309, $cc620$الباب الثالث: عمليات البنوك$cc620$, $cc621$1- إذا اصدر البنك دفتر توفير وجب أن يذكر في الدفتر اسم من صدر من صالحه وان يدون في الدفتر المدفوعات والمسحوبات، وتكون البيانات الواردة بالدفتر المرافقة عليها من موظف البنك حجة من إثبات تلك البيانات في العلاقة بين البنك ومن صدر الدفتر لصالحه.
2- يجوز إصدار دفتر توفير باسم القاصر، ويكون للقاصر ولكل شخص آخر حق الإيداع في هذا الدفتر، ولا يكون للقاصر حق السحب منه إلا وفقا للأحكام المنصوص عليها في القانون.
