SELECT id, 1, $cc637$1- يسلم مفتاح الخزانة إلى المستأجر ويحتفظ البنك بمفتاح آخر وفيما عدا المستأجر والبنك لا يجوز تسليم نسخة من المفتاح لأي شخص آخر.
2- يبقى المفتاح الذي يسلم للمستأجر ملكا للبنك ويجب رده إليه عند انتهاء الإجارة.
3- ولا يجوز للبنك أن يأذن لغير المستأجر أو وكيله الخاص في استعمال الخزانة.$cc637$, '1999-10-01', 'active' FROM ins_art_law17_1999_317;

WITH ins_art_law17_1999_318 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 318, $cc638$الباب الثالث: عمليات البنوك$cc638$, $cc639$1- على البنك اتخاذ التدابير اللازمة لضمان سلامة الخزانة والمحافظة على محتوياتها.
2- ولا يجوز للمستأجر أن يضع في الخزانة أشياء تهدد سلامتها أو سلامة المكان الذي توجد به.
3- إذا صارت الخزانة مهددة بخطر أو تبين أنها تحتوي على أشياء خطرة وجب على البنك أن يخطر المستأجر فورا بالحضور لافراغها أو لسحب الاشياء الخطرة منها، فإذا لم يحضر المستأجر في الميعاد المعين، جاز للبنك أن يطلب من القاضي المختص إصدار أمر على عريضة بالإذن له في فتح الخزانة وافراغها أو سحب الاشياء الخطرة منها وذلك بحضور من يعينه القاضي لذلك، ويحرر محضر بالواقعة يذكر فيه محتويات الخزانة، وإذا كان الخطر حالا، جاز للبنك وعلى مسئوليته فتح الخزانة وافراغها أو سحب الأشياء الخطرة منها دون إخطار أو أذن من القاضي.$cc639$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc639$1- على البنك اتخاذ التدابير اللازمة لضمان سلامة الخزانة والمحافظة على محتوياتها.
2- ولا يجوز للمستأجر أن يضع في الخزانة أشياء تهدد سلامتها أو سلامة المكان الذي توجد به.
3- إذا صارت الخزانة مهددة بخطر أو تبين أنها تحتوي على أشياء خطرة وجب على البنك أن يخطر المستأجر فورا بالحضور لافراغها أو لسحب الاشياء الخطرة منها، فإذا لم يحضر المستأجر في الميعاد المعين، جاز للبنك أن يطلب من القاضي المختص إصدار أمر على عريضة بالإذن له في فتح الخزانة وافراغها أو سحب الاشياء الخطرة منها وذلك بحضور من يعينه القاضي لذلك، ويحرر محضر بالواقعة يذكر فيه محتويات الخزانة، وإذا كان الخطر حالا، جاز للبنك وعلى مسئوليته فتح الخزانة وافراغها أو سحب الأشياء الخطرة منها دون إخطار أو أذن من القاضي.$cc639$, '1999-10-01', 'active' FROM ins_art_law17_1999_318;

WITH ins_art_law17_1999_319 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 319, $cc640$الباب الثالث: عمليات البنوك$cc640$, $cc641$1- إذا لم يدفع المستأجر أجرة الخزانة في مواعيد استحقاقها جاز للبنك بعد انقضاء ثلاثين يوما من إخطاره بالدفع أن يعتبر العقد منتهيا من تلقاء نفسه ويسترد البنك الخزانة بعد إخطار المستأجر بالحضور وإفراغ محتوياتها.
2- وإذا لم يحضر المستأجر في الميعاد المحدد، جاز للبنك أن يطلب من القاضي المختص إصدار أمر على عريضة بالإذن له في فتح الخزانة وافراغ محتوياتها بحضور من يعينه لذلك.
ويحرر محضر بالواقعة تذكر فيه محتويات الخزانة، وللقاضي أن يأمر بإيداع المحتويات عند البنك أو عند أمين يعينه لذلك.$cc641$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc641$1- إذا لم يدفع المستأجر أجرة الخزانة في مواعيد استحقاقها جاز للبنك بعد انقضاء ثلاثين يوما من إخطاره بالدفع أن يعتبر العقد منتهيا من تلقاء نفسه ويسترد البنك الخزانة بعد إخطار المستأجر بالحضور وإفراغ محتوياتها.
2- وإذا لم يحضر المستأجر في الميعاد المحدد، جاز للبنك أن يطلب من القاضي المختص إصدار أمر على عريضة بالإذن له في فتح الخزانة وافراغ محتوياتها بحضور من يعينه لذلك.
ويحرر محضر بالواقعة تذكر فيه محتويات الخزانة، وللقاضي أن يأمر بإيداع المحتويات عند البنك أو عند أمين يعينه لذلك.$cc641$, '1999-10-01', 'active' FROM ins_art_law17_1999_319;

WITH ins_art_law17_1999_320 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 320, $cc642$الباب الثالث: عمليات البنوك$cc642$, $cc643$للبنك حق حبس محتويات الخزانة، وله حق امتياز على الثمن الناتج عن بيعها لاستيفاء الأجرة و المصاريف المستحقة له.$cc643$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc643$للبنك حق حبس محتويات الخزانة، وله حق امتياز على الثمن الناتج عن بيعها لاستيفاء الأجرة و المصاريف المستحقة له.$cc643$, '1999-10-01', 'active' FROM ins_art_law17_1999_320;

WITH ins_art_law17_1999_321 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 321, $cc644$الباب الثالث: عمليات البنوك$cc644$, $cc645$1- يجوز توقيع الحجز التحفظي أو الحجز التنفيذي على الخزانة.
2- يوقع الحجز بتبليغ البنك مضمون السند الذي يتم الحجز بموجبه، مع تكليفه بالتقرير عما إذا كان يؤجر خزانة للمحجوز عليه، وعلى البنك بمجرد تسلمه هذا التبليغ أن يخطر المستأجر فورا بتوقيع الحجز وان يمنعه من استعمال الخزانة.
3- إذا كان الحجز تحفظيا، جاز للمستأجر أن يطلب من القاضي المختص إصدار أمر على عريضة بالترخيص له في سحب بعض محتويات الخزانة في حضور من يندبه القاضي لذلك.
4- وإذا كان الحجز تنفيذيا التزم البنك بفتح الخزانة وافراغ محتوياتها بحضور الحاجز أو من يندبه القاضي لذلك، ويخطر المستأجر بالميعاد الذي حدد لفتح الخزانة وتجرد محتوياتها وتسلم إلى البنك أو إلى أمين قاضي التنفيذ حتى يتم بيعها وفقا للأحكام المنصوص عليها في قانون المرافعات المدنية والتجارية.
5- وإذا كان بالخزانة أوراق أو وثائق لا يشملها البيع وجب تسليمها إلى المستأجر فإذا لم يكن حاضرا وقت فتح الخزانة وجب تسليمها إلى البنك لحفظها حتى يطلبها المستأجر أو ورثته وإذا لم يتقدم المستأجر أو ورثته لاستلام الأوراق أو الوثائق المشار إليها خلال خمس سنوات يكون للبنك الحق في عرض الأمر على قاضي الأمور الوقتية ليقرر بشأنها ما يراه.$cc645$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
