SELECT id, 1, $cc653$1- إذا كان الدائن المرتهن حائزا للأوراق المرهونة لسبب آخر سابق على الرهن فإنه يعتبر حائزا لها بوصفه دائنا مرتهنا بمجرد إنشاء الرهن.
2- يعتبر الغير الذي عينه المتعاقدان لحيازة الأوراق المرهونة انه تنازل عن كل حق له في حبسها لسبب سابق على الرهن ما لم يكن قد احتفظ بهذا الحق عند قبوله حيازة الأوراق المرهونة لحساب الدائن المرتهن.$cc653$, '1999-10-01', 'active' FROM ins_art_law17_1999_325;

