النقل المصرفي$cc659$, '1999-10-01', 'active' FROM ins_art_law17_1999_328;

WITH ins_art_law17_1999_329 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 329, $cc660$الباب الثالث: عمليات البنوك$cc660$, $cc661$1- النقل المصرفي عملية يقيد البنك بمقتضاها مبلغا معينا في الجانب المدين من حساب الآمر بالنقل بناء على أمر كتابي منه وفي الجانب الدائن من حساب آخر.
ويجوز بهذه العملية إجراء ما يأتي:
(أ)- نقل مبلغ معين من شخص إلى آخر لكل منهما حساب لدى البنك ذاته أو لدى بنكين مختلفين.
(ب)- نقل مبلغ معين من حساب إلى آخر كلاهما مفتوح باسم الآمر بالنقل لدى البنك ذاته أو لدى بنكين مختلفين.
2- ينظم الاتفاق بين البنك والآمر بالنقل شروط إصدار الأمر. ومع ذلك لا يجوز أن يكون أمر النقل لحامله.
3- يجوز الاتفاق على أن يتقدم المستفيد بنفسه بأمر النقل إلى البنك بدلا من تبليغه إليه من الآمر بالنقل.$cc661$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc661$1- النقل المصرفي عملية يقيد البنك بمقتضاها مبلغا معينا في الجانب المدين من حساب الآمر بالنقل بناء على أمر كتابي منه وفي الجانب الدائن من حساب آخر.
ويجوز بهذه العملية إجراء ما يأتي:
(أ)- نقل مبلغ معين من شخص إلى آخر لكل منهما حساب لدى البنك ذاته أو لدى بنكين مختلفين.
(ب)- نقل مبلغ معين من حساب إلى آخر كلاهما مفتوح باسم الآمر بالنقل لدى البنك ذاته أو لدى بنكين مختلفين.
2- ينظم الاتفاق بين البنك والآمر بالنقل شروط إصدار الأمر. ومع ذلك لا يجوز أن يكون أمر النقل لحامله.
3- يجوز الاتفاق على أن يتقدم المستفيد بنفسه بأمر النقل إلى البنك بدلا من تبليغه إليه من الآمر بالنقل.$cc661$, '1999-10-01', 'active' FROM ins_art_law17_1999_329;

