2- وإذا اتفق على أن يتقدم المستفيد بنفسه بأمر النقل إلى البنك، فلا يجوز للآمر الرجوع في الأمر، وذلك مع مراعاة ما تقضى به المادة 337 من هذا القانون.$cc667$, '1999-10-01', 'active' FROM ins_art_law17_1999_332;

