2- وإذا كان أمر النقل مقدما مباشرة من المستفيد قيد البنك لحسابه المقابل الناقص ما لم يرفض المستفيد ذلك. وعلى البنك أن يؤشر على أمر النقل بقيد المقابل الناقص أو بالرفض الصادر من المستفيد.
