WITH ins_art_law17_1999_379 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 379, $cc760$الباب الرابع: الأوراق التجارية — الفصل الأول: الكمبيالة$cc760$, $cc761$تشتمل الكمبيالة على البيانات الآتية:
(أ) كلمة "كمبيالة" في متن الصك وباللغة التي كتب بها.
(ب) أمر غير معلق على شرط بوفاء مبلغ معين من النقود.
(ج) اسم من يلزمه الوفاء (المسحوب عليه).
(د) ميعاد الاستحقاق.
(ه) مكان الوفاء.
(و) اسم من يجب الوفاء له أو لامره (المستفيد).
(ز) تاريخ ومكان إصدار الكمبيالة.
(ح) توقيع من اصدر الكمبيالة (الساحب) على نحو مقروء.$cc761$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
