SELECT id, 1, $cc785$1- كل كمبيالة ولو لم يصرح فيها إنها مسحوبة للأمر تتداول بالتظهير.
2- لا يجوز تداول الكمبيالة التي يضع فيها الساحب عبارة "ليست للأمر" أو أية عبارة أخرى تفيد هذا المعنى إلا باتباع إجراءات حوالة الحق المنصوص عليها في القانون المدني مع ما يترتب عليها من آثار.
3- يجوز التظهير إلى المسحوب عليه سواء قبل الكمبيالة او لم يقبلها، كما يجوز التظهير إلى الساحب أو أي ملتزم آخر، ويجوز لجميع هؤلاء تظهير الكمبيالة من جديد.$cc785$, '1999-10-01', 'active' FROM ins_art_law17_1999_391;

