WITH ins_art_law17_1999_407 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 407, $cc816$الباب الرابع: الأوراق التجارية — الفصل الأول: الكمبيالة$cc816$, $cc817$1- إذا أفلس المسحوب عليه وكان مقابل الوفاء دينا في ذمته للساحب دخل هذا الدين في موجودات التفليسة.
2- أما إذا كان للساحب لدى المسحوب عليه بضائع أو أوراق تجارية أو أوراق مالية أو غير ذلك من الأموال التي يجوز استردادها طبقا لاحكام الإفلاس وكانت هذه الأموال مخصصة صراحة أو ضمنا لوفاء الكمبيالة فللحامل الأولوية في استيفاء حقه في قيمتها.$cc817$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc817$1- إذا أفلس المسحوب عليه وكان مقابل الوفاء دينا في ذمته للساحب دخل هذا الدين في موجودات التفليسة.
2- أما إذا كان للساحب لدى المسحوب عليه بضائع أو أوراق تجارية أو أوراق مالية أو غير ذلك من الأموال التي يجوز استردادها طبقا لاحكام الإفلاس وكانت هذه الأموال مخصصة صراحة أو ضمنا لوفاء الكمبيالة فللحامل الأولوية في استيفاء حقه في قيمتها.$cc817$, '1999-10-01', 'active' FROM ins_art_law17_1999_407;

WITH ins_art_law17_1999_408 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 408, $cc818$الباب الرابع: الأوراق التجارية — الفصل الأول: الكمبيالة$cc818$, $cc819$1- إذا سحبت عدة كمبيالات على مقابل وفاء واحد لا يكفي لوفائها كلها فيراعى في ترتيب تواريخ سحبها فيما يتعلق بحقوق حامليها في استيفاء ديونهم من مقابل الوفاء المذكور، ويكون حامل الكمبيالة السابق تاريخها على تواريخ الكمبيالات الأخرى مقدما على غيره.
2- فإذا سحبت الكمبيالات في تاريخ واحد قدمت الكمبيالة التي تحمل قبول المسحوب عليه.
3- وإذا لم تحمل أية كمبيالة قبول المسحوب عليه قدمت الكمبيالة التي خصص لها مقابل الوفاء.
4- أما الكمبيالات التي تشتمل على شرط عدم القبول فتأتي في المرتبة الأخيرة.
٤- القبول$cc819$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
