WITH ins_art_law17_1999_410 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 410, $cc822$الباب الرابع: الأوراق التجارية — الفصل الأول: الكمبيالة$cc822$, $cc823$1- يجوز لساحب الكمبيالة أن يشترط تقديمها للقبول في ميعاد يحدده أو بغير تحديد ميعاد.
2- وللساحب أن يشترط عدم تقديم الكمبيالة للقبول، ومع ذلك لا يجوز وضع هذا الشرط إذا كانت الكمبيالة مستحقة الدفع عند شخص آخر غير المسحوب عليه أو كانت مستحقة الوفاء في محل آخر غير المحل الذي يوجد فيه موطن المسحوب عليه أو كانت مستحقة الدفع بعد مدة معينة من الاطلاع عليها.
3- وللساحب أن يشترط أيضا عدم تقديم الكمبيالة للقبول قبل ميعاد معين.
4- ولكل مظهر أن يشترط تقديم الكمبيالة للقبول في ميعاد يحدده أو بغير تحديد ميعاد، ما لم يكن الساحب قد اشترط عدم تقديمها للقبول.$cc823$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
