SELECT id, 1, $cc829$1- يكتب القبول على الكمبيالة نفسها، ويؤدى بلفظ "مقبول" أو بأية عبارة أخرى تفيد معناه ويوقعه المسحوب عليه.
2- ويعتبر قبولا مجرد وضع المسحوب عليه توقيعه على صدر الكمبيالة.
3- فإذا كانت الكمبيالة مستحقة الوفاء بعد مدة معينة من الاطلاع عليها أو كانت واجبة التقديم للقبول في مدة معينة بناء على شرط خاص، وجب بيان تاريخ القبول باليوم الذي وقع فيه إلا إذا أوجب الحامل بيان تاريخ القبول بيوم تقديم الكمبيالة، فإذا خلا القبول من التاريخ جاز للحامل- حفاظا على حقوقه في الرجوع على المظهرين وعلى الساحب- إثبات عدم وجود التاريخ باحتجاج يعمل في وقت يكون فيه مجديا.$cc829$, '1999-10-01', 'active' FROM ins_art_law17_1999_413;

WITH ins_art_law17_1999_414 AS (
