2- وكل تعديل آخر لبيانات الكمبيالة يقع في صيغة القبول يعتبر رفضا للقبول، ومع ذلك يبقى القابل ملزما بما تضمنته صيغة قبوله.$cc831$, '1999-10-01', 'active' FROM ins_art_law17_1999_414;

WITH ins_art_law17_1999_415 AS (
