WITH ins_art_law17_1999_424 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 424, $cc850$الباب الرابع: الأوراق التجارية — الفصل الأول: الكمبيالة$cc850$, $cc851$1- الكمبيالة المسحوبة لشهر او لعدة شهور من تاريخ اصدارها او من تاريخ الاطلاع عليها يكون استحقاقها في التاريخ المقابل من الشهر الذي يجب فيه الوفاء، فإذا لم يوجد للتاريخ مقابل في هذا الشهر كان الاستحقاق في اليوم الاخير منه.
2- وإذا سحبت الكمبيالة لشهر ونصف شهر أو لعدة شهور ونصف شهر من تاريخ إصدارها أو من تاريخ الاطلاع عليها، وجب البدء بحساب الشهور كاملة.
3- وإذا كان الاستحقاق في أول الشهر أو في منتصفه أو في آخره كان المقصود اليوم الأول أو الخامس عشر أو الأخير من الشهر.
4- وتعني عبارة "نصف شهر" خمسة عشر يوما.$cc851$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
