WITH ins_art_law17_1999_427 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 427, $cc856$الباب الرابع: الأوراق التجارية — الفصل الأول: الكمبيالة$cc856$, $cc857$1- إذا أوفى المسحوب عليه الكمبيالة جاز له استردادها من حاملها موقعا عليها بما يفيد الوفاء.
2- لا يجوز لحامل الكمبيالة أن يمتنع عن قبول الوفاء الجزئي.
3- وإذا كان الوفاء جزئيا جاز للمسحوب عليه أن يطلب إثباته على الكمبيالة وإعطاءه مخالصة به.
4- وتبرأ ذمة الساحب والمظهرين وغيرهم من الملتزمين في الكمبيالة بقدر ما يدفع من قيمتها، وعلى حاملها عمل الاحتجاج عن القدر غير المدفوع.$cc857$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc857$1- إذا أوفى المسحوب عليه الكمبيالة جاز له استردادها من حاملها موقعا عليها بما يفيد الوفاء.
2- لا يجوز لحامل الكمبيالة أن يمتنع عن قبول الوفاء الجزئي.
3- وإذا كان الوفاء جزئيا جاز للمسحوب عليه أن يطلب إثباته على الكمبيالة وإعطاءه مخالصة به.
4- وتبرأ ذمة الساحب والمظهرين وغيرهم من الملتزمين في الكمبيالة بقدر ما يدفع من قيمتها، وعلى حاملها عمل الاحتجاج عن القدر غير المدفوع.$cc857$, '1999-10-01', 'active' FROM ins_art_law17_1999_427;

WITH ins_art_law17_1999_428 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 428, $cc858$الباب الرابع: الأوراق التجارية — الفصل الأول: الكمبيالة$cc858$, $cc859$1- لا يجبر حامل الكمبيالة على قبض قيمتها قبل ميعاد الاستحقاق.
2- وإذا أوفى المسحوب عليه قبل ميعاد الاستحقاق تحمل تبعة ذلك.
3- وفاء الكمبيالة في ميعاد الاستحقاق دون معارضة صحيحة يبرئ ذمة الموفى إلا إذا وقع منه غش أو خطأ جسيم، وعليه أن يستوثق من انتظام تسلسل التظهيرات ولكنه غير ملزم بالتحقق من صحة توقيعات المظهرين.$cc859$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
