  SELECT id, 431, $cc864$الباب الرابع: الأوراق التجارية — الفصل الأول: الكمبيالة$cc864$, $cc865$لا يقبل الاعتراض على وفاء الكمبيالة إلا في حالة ضياعها أو إفلاس حاملها أو الحجر عليه.
