)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc873$لمن ضاعت منه الكمبيالة أن يحصل على نسخة منها من أحد المظهرين، ويلزم هذا المظهر بأن يظهر له النسخة التي حصل عليها من المظهر إليه مباشرة، وهكذا حتى يصل الأمر إلى الساحب، ولا يجوز لمن ضاعت منه الكمبيالة أن يطالب بوفائها بمقتضى هذه النسخة إلا بأمر من القضاء وبعد تقديم كفيل، وتكون نفقات الحصول على النسخة الجديدة وإجراءات إثبات الملكية على عاتق من ضاعت منه الكمبيالة.$cc873$, '1999-10-01', 'active' FROM ins_art_law17_1999_435;

