WITH ins_art_law17_1999_438 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 438, $cc878$الباب الرابع: الأوراق التجارية — الفصل الأول: الكمبيالة$cc878$, $cc879$لحامل الكمبيالة أن يرجع عند حلول الأجل، إذا لم يقع الوفاء، على المظهرين والساحب وغيرهم من الملتزمين بها.
ويجوز للحامل الرجوع قبل حلول الأجل في الأحوال الآتية:
أ- إذا رفض قبول الكمبيالة كليا أو جزئيا.
ب- إذا أفلس المسحوب عليه سواء أكان قابلا للكمبيالة أم غير قابل لها، أو توقف عن الدفع ولو لم يثبت توقفه هذا بحكم، أو وقع الحجز على أمواله حجزا غير مجد.
ج- إذا أفلس ساحب كمبيالة اشترط فيها عدم تقديمها للقبول.
ولكل ضامن بالكمبيالة، إذا رجع عليه الحامل قبل حلول الأجل في الحالتين المنصوص عليهما في البندين (ب) و(ج) من الفقرة السابقة، أن يتقدم إلى القاضي المختص الكائن موطنه بدائرته خلال ثلاثة أيام يطلب منحه أجلا للوفاء.$cc879$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc879$لحامل الكمبيالة أن يرجع عند حلول الأجل، إذا لم يقع الوفاء، على المظهرين والساحب وغيرهم من الملتزمين بها.
ويجوز للحامل الرجوع قبل حلول الأجل في الأحوال الآتية:
أ- إذا رفض قبول الكمبيالة كليا أو جزئيا.
ب- إذا أفلس المسحوب عليه سواء أكان قابلا للكمبيالة أم غير قابل لها، أو توقف عن الدفع ولو لم يثبت توقفه هذا بحكم، أو وقع الحجز على أمواله حجزا غير مجد.
ج- إذا أفلس ساحب كمبيالة اشترط فيها عدم تقديمها للقبول.
ولكل ضامن بالكمبيالة، إذا رجع عليه الحامل قبل حلول الأجل في الحالتين المنصوص عليهما في البندين (ب) و(ج) من الفقرة السابقة، أن يتقدم إلى القاضي المختص الكائن موطنه بدائرته خلال ثلاثة أيام يطلب منحه أجلا للوفاء.$cc879$, '1999-10-01', 'active' FROM ins_art_law17_1999_438;

WITH ins_art_law17_1999_439 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 439, $cc880$الباب الرابع: الأوراق التجارية — الفصل الأول: الكمبيالة$cc880$, $cc881$يجب إثبات رفض قبول الكمبيالة أو رفض وفائها بورقة رسمية تسمى الاحتجاج (بروتستو رفض القبول أو بروتستو رفض الوفاء).
ويجب أن يقع احتجاج رفض القبول في المواعيد المحددة لتقديم الكمبيالة للقبول، فإذا وقع تقديم الكمبيالة للقبول في اليوم الأخير من الميعاد المحدد لذلك طبقا للفقرة الأولى من المادة (408)، جاز أن يقع الاحتجاج في اليوم التالي.
ويجب أن يقع احتجاج رفض الوفاء بالنسبة إلى الكمبيالة المستحقة الوفاء في يوم معين أو بعد مدة من تاريخ إنشائها أو بعد مدة من الاطلاع عليها، خلال يومي العمل التاليين ليوم استحقاقها.
* أما إذا كانت الكمبيالة مستحقة الوفاء لدى الاطلاع، فيجب أن يقع الاحتجاج بالشروط المقررة في الفقرة السابقة لإثبات احتجاج رفض القبول.
ويقوم احتجاج رفض القبول مقام تقديم الكمبيالة للوفاء والاحتجاج على رفضه.
وإذا توقف المسحوب عليه، سواء أكان قابلا للكمبيالة أم لم يكن، عن الدفع، أو وقع الحجز على أمواله حجزا غير مجد، فليس على حامل الكمبيالة أن يقدمها للوفاء ولا أن يحرر احتجاجا ليتمكن من الرجوع بحقه.
وإذا أشهر إفلاس المسحوب عليه، سواء أكان قابلا للكمبيالة أم لم يكن، أو أشهر إفلاس الساحب في كمبيالة اشترط فيها عدم تقديمها للقبول، فإن حكم إشهار الإفلاس يكفي لأن يتمسك الحامل بحقه في الرجوع.
[ملاحظة توثيقية: صححت الفقرة المشار إليها بعلامة (*) من المادة (439) بالاستدراك المنشور بالجريدة الرسمية- العدد 38 (مكرر) في 1999/9/27.]$cc881$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc881$يجب إثبات رفض قبول الكمبيالة أو رفض وفائها بورقة رسمية تسمى الاحتجاج (بروتستو رفض القبول أو بروتستو رفض الوفاء).
ويجب أن يقع احتجاج رفض القبول في المواعيد المحددة لتقديم الكمبيالة للقبول، فإذا وقع تقديم الكمبيالة للقبول في اليوم الأخير من الميعاد المحدد لذلك طبقا للفقرة الأولى من المادة (408)، جاز أن يقع الاحتجاج في اليوم التالي.
ويجب أن يقع احتجاج رفض الوفاء بالنسبة إلى الكمبيالة المستحقة الوفاء في يوم معين أو بعد مدة من تاريخ إنشائها أو بعد مدة من الاطلاع عليها، خلال يومي العمل التاليين ليوم استحقاقها.
* أما إذا كانت الكمبيالة مستحقة الوفاء لدى الاطلاع، فيجب أن يقع الاحتجاج بالشروط المقررة في الفقرة السابقة لإثبات احتجاج رفض القبول.
ويقوم احتجاج رفض القبول مقام تقديم الكمبيالة للوفاء والاحتجاج على رفضه.
وإذا توقف المسحوب عليه، سواء أكان قابلا للكمبيالة أم لم يكن، عن الدفع، أو وقع الحجز على أمواله حجزا غير مجد، فليس على حامل الكمبيالة أن يقدمها للوفاء ولا أن يحرر احتجاجا ليتمكن من الرجوع بحقه.
وإذا أشهر إفلاس المسحوب عليه، سواء أكان قابلا للكمبيالة أم لم يكن، أو أشهر إفلاس الساحب في كمبيالة اشترط فيها عدم تقديمها للقبول، فإن حكم إشهار الإفلاس يكفي لأن يتمسك الحامل بحقه في الرجوع.
[ملاحظة توثيقية: صححت الفقرة المشار إليها بعلامة (*) من المادة (439) بالاستدراك المنشور بالجريدة الرسمية- العدد 38 (مكرر) في 1999/9/27.]$cc881$, '1999-10-01', 'active' FROM ins_art_law17_1999_439;

WITH ins_art_law17_1999_440 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 440, $cc882$الباب الرابع: الأوراق التجارية — الفصل الأول: الكمبيالة$cc882$, $cc883$1- يجب على حامل الكمبيالة أن يخطر بامتناع القبول أو الوفاء المظهر له والساحب في الأيام الأربعة أيام العمل التالية ليوم الاحتجاج، أو التالية ليوم تقديم الكمبيالة إذا كان فيها شرط الرجوع بلا مصاريف.
2- ويجب على كل مظهر أن يخطر خلال يومي العمل التاليين لتلقيه الإخطار من المظهر إليه بالإخطار الذي تلقاه، مبينا أسماء وعناوين من أخطروه في الإخطارات السابقة، وهكذا بالتتابع حتى يصل الأمر إلى الساحب، وتسري هذه المواعيد من وقت تلقي الإخطار السابق.
3- وإذا أخطر بمقتضى الفقرة السابقة أحد الموقعين على الكمبيالة، وجب في ذات الميعاد إخطار ضامنه الاحتياطي بذلك.
4- وإذا لم يبين أحد المظهرين عنوانه أو بينه بطريقة غير مقروءة، اكتفى بإخطار من يسبقه في التظهير.
5- يجوز أن يقع الإخطار بأية طريقة، ولو بمجرد إعادة الكمبيالة، ويقع عبء إثبات حصول الإخطار في الميعاد المحدد على من كان ملزما به، ويعتبر الميعاد محفوظا إذا سلمت الرسالة التي تتضمن الإخطار إلى مكتب البريد قبل انقضائه.
ولا يترتب على عدم مراعاة الميعاد المشار إليه سقوط الحق في الرجوع، وإنما يكون المقصر مسئولا، إذا اقتضى الحال، عن التعويض عن الضرر الناشئ عن إهماله على ألا تجاوز قيمة التعويض قيمة الكمبيالة.$cc883$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
