ولا يترتب على عدم مراعاة الميعاد المشار إليه سقوط الحق في الرجوع، وإنما يكون المقصر مسئولا، إذا اقتضى الحال، عن التعويض عن الضرر الناشئ عن إهماله على ألا تجاوز قيمة التعويض قيمة الكمبيالة.$cc883$, '1999-10-01', 'active' FROM ins_art_law17_1999_440;

WITH ins_art_law17_1999_441 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 441, $cc884$الباب الرابع: الأوراق التجارية — الفصل الأول: الكمبيالة$cc884$, $cc885$1- للساحب ولكل مظهر أو ضامن احتياطي أن يعفى الحامل من عمل احتجاج عدم القبول أو احتجاج عدم الوفاء عند استعمال حقه في الرجوع إذا كتب على الكمبيالة شرط "الرجوع بلا مصاريف" أو "بدون احتجاج" أو أي شرط آخر يفيد هذا المعنى ووقع الشرط.
2- ولا يعفى هذا الشرط الحامل من تقديم الكمبيالة في المواعيد المقررة ولا من عمل الاخطارات اللازمة، وعلى من يتمسك تجاه الحامل بعدم مراعاة هذه المواعيد إثبات ذلك.
3- إذا كتب الساحب شرط الرجوع بلا مصاريف، سرت آثاره على كل الموقعين، أما إذا كتبه أحد المظهرين أو الضامنين الاحتياطيين، سرت آثاره عليه وحده.
4- وإذا كان الساحب هو الذي وضع الشرط وعمل الحامل احتجاجا رغم ذلك تحمل وحده المصاريف، أما إذا كان الشرط صادرا من مظهر أو ضامن احتياطي جاز الرجوع على جميع الموقعين الآخرين بمصاريف الاحتجاج إن عمل.$cc885$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
