3- إذا كتب الساحب شرط الرجوع بلا مصاريف، سرت آثاره على كل الموقعين، أما إذا كتبه أحد المظهرين أو الضامنين الاحتياطيين، سرت آثاره عليه وحده.
4- وإذا كان الساحب هو الذي وضع الشرط وعمل الحامل احتجاجا رغم ذلك تحمل وحده المصاريف، أما إذا كان الشرط صادرا من مظهر أو ضامن احتياطي جاز الرجوع على جميع الموقعين الآخرين بمصاريف الاحتجاج إن عمل.$cc885$, '1999-10-01', 'active' FROM ins_art_law17_1999_441;

WITH ins_art_law17_1999_442 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 442, $cc886$الباب الرابع: الأوراق التجارية — الفصل الأول: الكمبيالة$cc886$, $cc887$1- الأشخاص الملتزمون بموجب كمبيالة مسئولون بالتضامن قبل حاملها.
2- ولحامل الكمبيالة الرجوع على هؤلاء الملتزمين منفردين أو مجتمعين دون أن يلزم بمراعاة ترتيب التزاماتهم.
3- ويثبت هذا الحق لكل موقع على الكمبيالة إذا دفع قيمتها.
4- الدعوى المقامة على أحد الملتزمين لا تحول دون الرجوع على الباقين ولو كانوا لاحقين للملتزم الذي وجهت إليه الدعوى ابتداء.$cc887$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc887$1- الأشخاص الملتزمون بموجب كمبيالة مسئولون بالتضامن قبل حاملها.
2- ولحامل الكمبيالة الرجوع على هؤلاء الملتزمين منفردين أو مجتمعين دون أن يلزم بمراعاة ترتيب التزاماتهم.
3- ويثبت هذا الحق لكل موقع على الكمبيالة إذا دفع قيمتها.
4- الدعوى المقامة على أحد الملتزمين لا تحول دون الرجوع على الباقين ولو كانوا لاحقين للملتزم الذي وجهت إليه الدعوى ابتداء.$cc887$, '1999-10-01', 'active' FROM ins_art_law17_1999_442;

WITH ins_art_law17_1999_443 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 443, $cc888$الباب الرابع: الأوراق التجارية — الفصل الأول: الكمبيالة$cc888$, $cc889$لحامل الكمبيالة مطالبة من له حق الرجوع عليه بما يأتي:-
(أ) اصل مبلغ الكمبيالة غير المقبولة أو غير المدفوعة مع العائد المتفق عليه.
(ب) العائد محسوبا وفقا للسعر الذي يتعامل به البنك المركزي وذلك ابتداء من يوم الاستحقاق.
(ج) مصاريف الاحتجاج والاخطارات والدمغة وغيرها.
(د) في أحوال الرجوع قبل ميعاد استحقاق الكمبيالة يجب أن يستنزل من قيمتها ما يساوي سعر الخصم الرسمي في تاريخ الرجوع بالمكان الذي يقع فيه موطن الحامل.$cc889$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc889$لحامل الكمبيالة مطالبة من له حق الرجوع عليه بما يأتي:-
(أ) اصل مبلغ الكمبيالة غير المقبولة أو غير المدفوعة مع العائد المتفق عليه.
(ب) العائد محسوبا وفقا للسعر الذي يتعامل به البنك المركزي وذلك ابتداء من يوم الاستحقاق.
(ج) مصاريف الاحتجاج والاخطارات والدمغة وغيرها.
(د) في أحوال الرجوع قبل ميعاد استحقاق الكمبيالة يجب أن يستنزل من قيمتها ما يساوي سعر الخصم الرسمي في تاريخ الرجوع بالمكان الذي يقع فيه موطن الحامل.$cc889$, '1999-10-01', 'active' FROM ins_art_law17_1999_443;

