WITH ins_art_law17_1999_447 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 447, $cc896$الباب الرابع: الأوراق التجارية — الفصل الأول: الكمبيالة$cc896$, $cc897$1- تسقط حقوق حامل الكمبيالة قبل المظهرين والساحب وغيرهم من الملتزمين ما عدا القابل بمضي المواعيد المعينة لإجراء ما يلي:-
(أ) تقديم الكمبيالات المستحقة الوفاء لدى الاطلاع أو بعد مدة معينة من الاطلاع.
(ب) عمل احتجاج عدم القبول أو احتجاج عدم الدفع.
(ج) تقديم الكمبيالة للوفاء في حالة اشتمالها على شرط الرجوع بلا مصاريف.
2- ومع ذلك لا يفيد الساحب من هذا السقوط إلا إذا اثبت انه أوجد مقابل الوفاء في ميعاد الاستحقاق، وفي هذه الحالة لا يبقى للحامل إلا الرجوع على المسحوب عليه.
3- وإذا لم تقدم الكمبيالة للقبول في الميعاد الذي اشترطه الساحب سقطت حقوق الحامل في الرجوع بسبب عدم القبول وعدم الوفاء على السواء الا اذا تبين من عبارة الشرط أن الساحب لم يقصد منه سوى إعفاء نفسه من ضمان القبول وحده.
4- إذا كان المظهر هو الذي اشترط في التظهير ميعادا لتقديم الكمبيالة للقبول، فله وحده الإفادة من هذا الشرط.$cc897$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc897$1- تسقط حقوق حامل الكمبيالة قبل المظهرين والساحب وغيرهم من الملتزمين ما عدا القابل بمضي المواعيد المعينة لإجراء ما يلي:-
(أ) تقديم الكمبيالات المستحقة الوفاء لدى الاطلاع أو بعد مدة معينة من الاطلاع.
(ب) عمل احتجاج عدم القبول أو احتجاج عدم الدفع.
(ج) تقديم الكمبيالة للوفاء في حالة اشتمالها على شرط الرجوع بلا مصاريف.
2- ومع ذلك لا يفيد الساحب من هذا السقوط إلا إذا اثبت انه أوجد مقابل الوفاء في ميعاد الاستحقاق، وفي هذه الحالة لا يبقى للحامل إلا الرجوع على المسحوب عليه.
3- وإذا لم تقدم الكمبيالة للقبول في الميعاد الذي اشترطه الساحب سقطت حقوق الحامل في الرجوع بسبب عدم القبول وعدم الوفاء على السواء الا اذا تبين من عبارة الشرط أن الساحب لم يقصد منه سوى إعفاء نفسه من ضمان القبول وحده.
4- إذا كان المظهر هو الذي اشترط في التظهير ميعادا لتقديم الكمبيالة للقبول، فله وحده الإفادة من هذا الشرط.$cc897$, '1999-10-01', 'active' FROM ins_art_law17_1999_447;

WITH ins_art_law17_1999_448 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 448, $cc898$الباب الرابع: الأوراق التجارية — الفصل الأول: الكمبيالة$cc898$, $cc899$1- إذا حالت قوة قاهرة دون تقديم الكمبيالة أو عمل الاحتجاج في المواعيد المقررة لذلك امتدت هذه المواعيد.
2- وعلى الحامل أن يخطر دون إبطاء من ظهر له الكمبيالة بالقوة القاهرة وان يثبت هذا الإخطار مؤرخا وموقعا منه في الكمبيالة أو في الوصلة وتتسلسل الاخطارات وفقا للمادة (440) من هذا القانون.
3- وعلى الحامل بعد زوال القوة القاهرة تقديم الكمبيالة للقبول أو للوفاء دون إبطاء ثم عمل الاحتجاج عند الاقتضاء.
4- إذا استمرت القوة القاهرة لاكثر من ثلاثين يوما محسوبة من يوم الاستحقاق جاز الرجوع على الملتزمين دون حاجة إلى تقديم الكمبيالة أو عمل الاحتجاج.
5- إذا كانت الكمبيالة مستحقة الوفاء لدى الاطلاع أو بعد مدة معينة من الاطلاع سرى ميعاد الثلاثين يوما من التاريخ الذي اخطر فيه الحامل من ظهر له الكمبيالة بالقوة القاهرة ولو وقع هذا التاريخ قبل انتهاء مواعيد تقديم الكمبيالة. وتزاد مدة الاطلاع على ميعاد الثلاثين يوما إذا كانت الكمبيالة مستحقة الوفاء بعد مدة معينة من الاطلاع عليها.
6- لا يعتبر من القوة القاهرة الأمور المتصلة بشخص حامل الكمبيالة أو بمن كلفه بتقديمها أو بعمل الاحتجاج.$cc899$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
