5- إذا كانت الكمبيالة مستحقة الوفاء لدى الاطلاع أو بعد مدة معينة من الاطلاع سرى ميعاد الثلاثين يوما من التاريخ الذي اخطر فيه الحامل من ظهر له الكمبيالة بالقوة القاهرة ولو وقع هذا التاريخ قبل انتهاء مواعيد تقديم الكمبيالة. وتزاد مدة الاطلاع على ميعاد الثلاثين يوما إذا كانت الكمبيالة مستحقة الوفاء بعد مدة معينة من الاطلاع عليها.
6- لا يعتبر من القوة القاهرة الأمور المتصلة بشخص حامل الكمبيالة أو بمن كلفه بتقديمها أو بعمل الاحتجاج.$cc899$, '1999-10-01', 'active' FROM ins_art_law17_1999_448;

WITH ins_art_law17_1999_449 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 449, $cc900$الباب الرابع: الأوراق التجارية — الفصل الأول: الكمبيالة$cc900$, $cc901$يجوز لحامل الكمبيالة المعمول عنها احتجاج عدم الوفاء أن يوقع حجزا تحفظيا بغير كفالة على أموال كل من الساحب أو القابل أو المظهر أو الضامن الاحتياطي أو غيرهم من الملتزمين بالكمبيالة مع مراعاة الأحكام المقررة في قانون المرافعات المدنية والتجارية.
9- التدخل أولا: أحكام عامة$cc901$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc901$يجوز لحامل الكمبيالة المعمول عنها احتجاج عدم الوفاء أن يوقع حجزا تحفظيا بغير كفالة على أموال كل من الساحب أو القابل أو المظهر أو الضامن الاحتياطي أو غيرهم من الملتزمين بالكمبيالة مع مراعاة الأحكام المقررة في قانون المرافعات المدنية والتجارية.
9- التدخل أولا: أحكام عامة$cc901$, '1999-10-01', 'active' FROM ins_art_law17_1999_449;

WITH ins_art_law17_1999_450 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 450, $cc902$الباب الرابع: الأوراق التجارية — الفصل الأول: الكمبيالة$cc902$, $cc903$1- لساحب الكمبيالة أو مظهرها أو ضامنها الاحتياطي أن يعين شخصا ليقبلها أو لوفاء قيمتها عند الاقتضاء.
2- ويجوز قبول الكمبيالة أو وفاؤها من شخص يتدخل لمصلحة أي مدين بها يكون مستهدفا للرجوع عليه، وذلك مع مراعاة الشروط المنصوص عليها في المواد التالية.
3- يجوز أن يكون المتدخل من الغير ولو كانت المسحوب عليه غير القابل، كما يجوز أن يكون المتدخل أي شخص ملتزم بالكمبيالة ما عدا المسحوب عليه بالقابل.
4- ويجب على المتدخل أن يخطر من وقع التدخل لمصلحته خلال يومي العمل التاليين وإلا كان مسئولا عند الاقتضاء عن تعويض ما يترتب على إهماله من ضرر بشرط ألا يجاوز التعويض مبلغ الكمبيالة.
ثانيا: القبول بالتدخل$cc903$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc903$1- لساحب الكمبيالة أو مظهرها أو ضامنها الاحتياطي أن يعين شخصا ليقبلها أو لوفاء قيمتها عند الاقتضاء.
2- ويجوز قبول الكمبيالة أو وفاؤها من شخص يتدخل لمصلحة أي مدين بها يكون مستهدفا للرجوع عليه، وذلك مع مراعاة الشروط المنصوص عليها في المواد التالية.
3- يجوز أن يكون المتدخل من الغير ولو كانت المسحوب عليه غير القابل، كما يجوز أن يكون المتدخل أي شخص ملتزم بالكمبيالة ما عدا المسحوب عليه بالقابل.
4- ويجب على المتدخل أن يخطر من وقع التدخل لمصلحته خلال يومي العمل التاليين وإلا كان مسئولا عند الاقتضاء عن تعويض ما يترتب على إهماله من ضرر بشرط ألا يجاوز التعويض مبلغ الكمبيالة.
ثانيا: القبول بالتدخل$cc903$, '1999-10-01', 'active' FROM ins_art_law17_1999_450;

WITH ins_art_law17_1999_451 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 451, $cc904$الباب الرابع: الأوراق التجارية — الفصل الأول: الكمبيالة$cc904$, $cc905$1- يجوز القبول بالتدخل في جميع الأحوال التي يكون فيها لحامل كمبيالة جائزة القبول، حق الرجوع قبل ميعاد استحقاقها.
2- إذا عين في الكمبيالة من يقبلها أو يوفى قيمتها عند الاقتضاء في مكان وفائها فليس للحامل أن يرجع قبل ميعاد استحقاقها على من صدر هذا التعيين على من صدر عنه من التعيين ولا على الموقعين اللاحقين له إلا إذا قدم الكمبيالة إلى من عين لقبولها أو لوفائها وامتنع هذا الشخص عن قبولها واثبت الحامل هذا الامتناع باحتجاج.
3- وللحامل في الأحوال الأخرى رفض القبول بالتدخل، فإذا قبله فقد حقوقه في الرجوع قبل ميعاد الاستحقاق من حصل التدخل لمصلحته وعلى الموقعين اللاحقين له.$cc905$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc905$1- يجوز القبول بالتدخل في جميع الأحوال التي يكون فيها لحامل كمبيالة جائزة القبول، حق الرجوع قبل ميعاد استحقاقها.
2- إذا عين في الكمبيالة من يقبلها أو يوفى قيمتها عند الاقتضاء في مكان وفائها فليس للحامل أن يرجع قبل ميعاد استحقاقها على من صدر هذا التعيين على من صدر عنه من التعيين ولا على الموقعين اللاحقين له إلا إذا قدم الكمبيالة إلى من عين لقبولها أو لوفائها وامتنع هذا الشخص عن قبولها واثبت الحامل هذا الامتناع باحتجاج.
3- وللحامل في الأحوال الأخرى رفض القبول بالتدخل، فإذا قبله فقد حقوقه في الرجوع قبل ميعاد الاستحقاق من حصل التدخل لمصلحته وعلى الموقعين اللاحقين له.$cc905$, '1999-10-01', 'active' FROM ins_art_law17_1999_451;

WITH ins_art_law17_1999_452 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 452, $cc906$الباب الرابع: الأوراق التجارية — الفصل الأول: الكمبيالة$cc906$, $cc907$يذكر القبول بالتدخل على الكمبيالة ويوقعه المتدخل ويبين فيه اسم من حصل التدخل لمصلحته، فإذا خلا القبول بالتدخل من هذا البيان الأخير اعتبر حاصلا لمصلحة الساحب.$cc907$
