SELECT id, 1, $cc907$يذكر القبول بالتدخل على الكمبيالة ويوقعه المتدخل ويبين فيه اسم من حصل التدخل لمصلحته، فإذا خلا القبول بالتدخل من هذا البيان الأخير اعتبر حاصلا لمصلحة الساحب.$cc907$, '1999-10-01', 'active' FROM ins_art_law17_1999_452;

WITH ins_art_law17_1999_453 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 453, $cc908$الباب الرابع: الأوراق التجارية — الفصل الأول: الكمبيالة$cc908$, $cc909$1- يلتزم القابل بالتدخل قبل حامل الكمبيالة والمظهرين اللاحقين لمن حصل التدخل لمصلحته بالأوجه التي يلتزم بها هذا الأخير.
2- يجوز لمن حصل التدخل لمصلحته ولضامنيه على الرغم من حصول القبول بالتدخل أن يلزموا الحامل في مقابل وفاء المبالغ المنصوص عليها في المادة 443 من هذا القانون بتسليم الكمبيالة والاحتجاج وتقديم مخالصة بقبض المبالغ المذكورة.
