WITH ins_art_law17_1999_458 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 458, $cc918$الباب الرابع: الأوراق التجارية — الفصل الأول: الكمبيالة$cc918$, $cc919$1- يكتسب من أوفى كمبيالة بطريق التدخل جميع الحقوق الناشئة عنها قبل من حصل الوفاء لمصلحته وقبل الملتزمين تجاه هذا الشخص بموجب الكمبيالة، ومع ذلك لا يجوز للموفى بالتدخل تظهير الكمبيالة من جديد.
2- وتبرأ ذمة المظهرين اللاحقين لمن حصل الوفاء لمصلحته.
3- إذا تزاحم عدة أشخاص على الوفاء بالتدخل فضل من يترتب على الوفاء منه إبراء اكبر عدد من الملتزمين. ومن يتدخل للوفاء بالمخالفة لهذه القاعدة مع علمه بذلك يفقد حقه في الرجوع على من كانت ذمته تبرأ ولو روعيت القاعدة.
