WITH ins_art_law17_1999_461 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 461, $cc924$الباب الرابع: الأوراق التجارية — الفصل الأول: الكمبيالة$cc924$, $cc925$على من أرسل إحدى نسخ الكمبيالة لقبول أن يبين على النسخ الأخرى اسم الشخص الذي تكون تلك النسخة في حيازته وعلى هذا الشخص أن يسلمها للحامل الشرعي لأية نسخة أخرى، فإذا رفض تسليمها فلا يكون للحامل حق الرجوع إلا إذا عمل احتجاجا يذكر فيه:
(أ) أن النسخة التي أرسلت للقبول لم تسلم له رغم طلبه لها.
(ب) وان القبول أو الوفاء لم يحصل بموجب نسخة أخرى.
