  SELECT id, 463, $cc928$الباب الرابع: الأوراق التجارية — الفصل الأول: الكمبيالة$cc928$, $cc929$1- يبين في صورة الكمبيالة اسم حائز الأصل، وعلى هذا الحائز أن يسلم الأصل للحامل الشرعي للصورة.
2- وإذا امتنع حائز الأصل عن تسليمه فلا يكون لحامل الصورة حق الرجوع على مظهريها أو ضامنيها الاحتياطيين إلا إذا عمل احتجاجا يذكر فيه أن الأصل لم يسلم إليه بناء على طلبه.
3- إذا كتب على الأصل عقب التظهير الأخير الحاصل قبل عمل الصورة عبارة "منذ الآن لا يصح التظهير إلا على الصورة" أو أية عبارة اخرى تفيد هذا المعنى، فكل تظهير يكتب على الاصل بعد ذلك يعتبر كأن لم يكن.
