WITH ins_art_law17_1999_468 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 468, $cc938$الباب الرابع: الأوراق التجارية — الفصل الثاني: السند لأمر$cc938$, $cc939$يشتمل السند لامر على البيانات الآتية:
(أ) شرط الأمر أو عبارة "سند لامر" أو أي عبارة أخرى تفيد هذا المعنى مكتوبة في متن السند باللغة التي كتب بها.
