WITH ins_art_law17_1999_469 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 469, $cc940$الباب الرابع: الأوراق التجارية — الفصل الثاني: السند لأمر$cc940$, $cc941$الصك الخالي من أحد البيانات المذكورة في المادة السابقة لا يعتبر سندا لامر إلا في الأحوال الآتية:
(أ) إذا خلا السند لأمر من بيان ميعاد الاستحقاق اعتبر واجب الوفاء لدى الاطلاع.
(ب) وإذا خلا السند لأمر من بيان مكان الوفاء أو موطن المحرر اعتبر المحرر محل إنشائه مكانا للوفاء به وموطنا لمحرره.
(ج) وإذا خلا السند لأمر من بيان مكان إنشائه اعتبر منشأ في المكان المبين بجانب اسم المحرر.$cc941$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc941$الصك الخالي من أحد البيانات المذكورة في المادة السابقة لا يعتبر سندا لامر إلا في الأحوال الآتية:
(أ) إذا خلا السند لأمر من بيان ميعاد الاستحقاق اعتبر واجب الوفاء لدى الاطلاع.
(ب) وإذا خلا السند لأمر من بيان مكان الوفاء أو موطن المحرر اعتبر المحرر محل إنشائه مكانا للوفاء به وموطنا لمحرره.
(ج) وإذا خلا السند لأمر من بيان مكان إنشائه اعتبر منشأ في المكان المبين بجانب اسم المحرر.$cc941$, '1999-10-01', 'active' FROM ins_art_law17_1999_469;

WITH ins_art_law17_1999_470 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 470, $cc942$الباب الرابع: الأوراق التجارية — الفصل الثاني: السند لأمر$cc942$, $cc943$تسرى على السند لأمر أحكام الكمبيالة بالقدر الذي لا تتعارض فيه مع ماهيته، وتسرى بوجه خاص الأحكام المتعلقة بالمسائل الآتية:
- الأهلية.
- التظهير.
