(أ) أن يملأ البياض بكتابة اسمه أو اسم شخص آخر.
(ب) أن يظهر الشيك من جديد على بياض أو إلى شخص آخر.
(ج) أن يسلم الشيك إلى شخص آخر دون أن يملا البياض ولو لم يظهره.$cc981$
