  SELECT id, 499, $cc1000$الباب الرابع: الأوراق التجارية — الفصل الثالث: الشيك$cc1000$, $cc1001$1- تنتقل ملكية مقابل الوفاء بحكم القانون إلى حملة الشيك المتعاقبين.
2- إذا كان مقابل الوفاء اقل من قيمة الشيك كان للحامل على المقابل الناقص جميع الحقوق المقررة له على المقابل الكامل.
3- للحامل رفض المقابل الناقص إذا عرضه عليه المسحوب عليه, وللحامل ان يقبضه، وفي هذه الحالة يؤشر المسحوب عليه على الشيك بالمبلغ المدفوع ويطلب من الحامل تسليمه مخالصة به ويقوم الحامل بعمل الاحتجاج أو ما يقوم مقامه عن الجزء الباقي.
4- وتبرأ ذمة الساحب أو المظهرين والضامنين الاحتياطيين بقدر المقابل الناقص في حالة الوفاء به والتأشير بذلك على الشيك.
3- الضمان الاحتياطي$cc1001$
