WITH ins_art_law17_1999_509 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 509, $cc1020$الباب الرابع: الأوراق التجارية — الفصل الثالث: الشيك$cc1020$, $cc1021$1- إذا قدمت عدة شيكات في وقت واحد وكان مقابل الوفاء غير كاف لوفائها, وجب مراعاة ترتيب تواريخ إصدارها.
2- وإذا كانت هذه الشيكات مفصولة من دفتر شيكات واحد وتحمل تاريخ إصدار واحد اعتبر الشيك الأسبق رقما صادرا قبل غيره. وإذا كانت الشيكات مفصولة من دفاتر مختلفة وجب الوفاء أولا بالشيك الأقل مبلغا.$cc1021$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1021$1- إذا قدمت عدة شيكات في وقت واحد وكان مقابل الوفاء غير كاف لوفائها, وجب مراعاة ترتيب تواريخ إصدارها.
2- وإذا كانت هذه الشيكات مفصولة من دفتر شيكات واحد وتحمل تاريخ إصدار واحد اعتبر الشيك الأسبق رقما صادرا قبل غيره. وإذا كانت الشيكات مفصولة من دفاتر مختلفة وجب الوفاء أولا بالشيك الأقل مبلغا.$cc1021$, '2001-10-01', 'active' FROM ins_art_law17_1999_509;

WITH ins_art_law17_1999_510 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 510, $cc1022$الباب الرابع: الأوراق التجارية — الفصل الثالث: الشيك$cc1022$, $cc1023$1- إذا اشترط الوفاء بمبلغ الشيك في مصر بنقد أجنبي معين, وجب الوفاء بهذا النقد إذا كان للساحب لدى المسحوب عليه مقابل وفاء به.
2- وإذا اشترط الوفاء بمبلغ الشيك في مصر بنقد أجنبي معين دون أن يكون للساحب لدى المسحوب عليه مقابل الوفاء بهذا النقد, جاز الوفاء بالعملة المصرية وفقا لسعر الصرف المعلن/ بيع تحويلات لدى المسحوب عليه وقت تقديم الشيك للوفاء إذا وجد عند المسحوب عليه مقابل وفاء بهذه العملة ما لم يرفض الحامل هذا الوفاء.
3- إذا لم يتم الوفاء وقت تقديم الشيك , كان للحامل الخيار بين سعر الصرف الساري يوم التقديم "إقفال" أو وقت الوفاء.
وفي مجال تطبيق حكمى البندين 2 , 3 فإنه إذا لم يوجد سعر معلن للتحويلات فيتم تطبيق سعر البنكنوت.
4- إذا قدم الشيك للمرة الأولى بعد إنقضاء ميعاد التقديم فيه انتهى ميعاد التقديم كانت العبرة بسعر الصرف الساري في اليوم الذي انتهى فيه ميعاد التقديم.
5- إذا عين مبلغ الشيك بنقد يحمل تسمية مشتركة وتختلف قيمته في بلد الإصدار عن قيمته في بلد الوفاء افترض أن المقصود نقد بلد الوفاء.
6- إذا عين مبلغ الشيك بنقد يحمل تسمية مشتركة من عملات أجنبية مختلفة ليس بينها نقد بلد الوفاء كانت العبرة بنوع العملة الموجودة بحساب الساحب لدى البنك المسحوب عليه أو على أساس عملة البلد الذي صدر فيه الشيك إذا لم يوجد بحسابات الساحب عملة تحمل الاسم المشترك. فإذا تعددت العملات الموجودة بحسابات الساحب الموجودة لدى المسحوب عليه وتعذر تحديد العملة المقصودة في الشيك يتم الوفاء بقيمة الشيك من العملة الأقل قيمة ويحصل كله ما لم يرفض الحامل سداد قيمة الشيك وفقا لتلك الأسس.$cc1023$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
