وفي مجال تطبيق حكمى البندين 2 , 3 فإنه إذا لم يوجد سعر معلن للتحويلات فيتم تطبيق سعر البنكنوت.
4- إذا قدم الشيك للمرة الأولى بعد إنقضاء ميعاد التقديم فيه انتهى ميعاد التقديم كانت العبرة بسعر الصرف الساري في اليوم الذي انتهى فيه ميعاد التقديم.
5- إذا عين مبلغ الشيك بنقد يحمل تسمية مشتركة وتختلف قيمته في بلد الإصدار عن قيمته في بلد الوفاء افترض أن المقصود نقد بلد الوفاء.
6- إذا عين مبلغ الشيك بنقد يحمل تسمية مشتركة من عملات أجنبية مختلفة ليس بينها نقد بلد الوفاء كانت العبرة بنوع العملة الموجودة بحساب الساحب لدى البنك المسحوب عليه أو على أساس عملة البلد الذي صدر فيه الشيك إذا لم يوجد بحسابات الساحب عملة تحمل الاسم المشترك. فإذا تعددت العملات الموجودة بحسابات الساحب الموجودة لدى المسحوب عليه وتعذر تحديد العملة المقصودة في الشيك يتم الوفاء بقيمة الشيك من العملة الأقل قيمة ويحصل كله ما لم يرفض الحامل سداد قيمة الشيك وفقا لتلك الأسس.$cc1023$, '2001-10-01', 'active' FROM ins_art_law17_1999_510;

WITH ins_art_law17_1999_511 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 511, $cc1024$الباب الرابع: الأوراق التجارية — الفصل الثالث: الشيك$cc1024$, $cc1025$1- تسرى في حالة ضياع الشيك لأمر الأحكام المنصوص عليها في المواد من 433 الى 436 من هذا القانون.
2- ينقضى التزام الكفيل الذي يقدم في حالة ضياع الشيك لأمر بمضى ستة أشهر من تاريخ الصرف إذا لم تحصل خلالها مطالبة أو دعوى.$cc1025$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1025$1- تسرى في حالة ضياع الشيك لأمر الأحكام المنصوص عليها في المواد من 433 الى 436 من هذا القانون.
2- ينقضى التزام الكفيل الذي يقدم في حالة ضياع الشيك لأمر بمضى ستة أشهر من تاريخ الصرف إذا لم تحصل خلالها مطالبة أو دعوى.$cc1025$, '2001-10-01', 'active' FROM ins_art_law17_1999_511;

WITH ins_art_law17_1999_512 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 512, $cc1026$الباب الرابع: الأوراق التجارية — الفصل الثالث: الشيك$cc1026$, $cc1027$1- إذا ضاع شيك لحامله أو هلك جاز لمالكه أن يعترض لدى المسحوب عليه على الوفاء بقيمته ويجب أن يشتمل الاعتراض على رقم الشيك ومبلغه واسم ساحبه وكل بيان آخر يساعد على التعرف عليه والظروف التي أحاطت بفقده أو هلاكه، وإذا تعذر تقديم بعض هذه البيانات وجب ذكر أسباب ذلك. وإذا لم يكن للمعترض موطن في مصر وجب أن يعين له موطنا مختارا بها.
2- ومتى تلقى المسحوب عليه الإعتراض وجب عليه الإمتناع عن الوفاء بقيمة الشيك لحائزه وتجنيب مقابل وفاء الشيك الى أن يفصل في أمره.
3- ويقوم المعترض بنشر رقم الشيك المفقود أو الهالك ومبلغه واسم الساحب واسم المسحوب عليه واسم المعترض وعنوانه في إحدى الصحف اليومية , ويكون باطلا كل تصرف يقع على الشيك بعد تاريخ هذا النشر.$cc1027$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1027$1- إذا ضاع شيك لحامله أو هلك جاز لمالكه أن يعترض لدى المسحوب عليه على الوفاء بقيمته ويجب أن يشتمل الاعتراض على رقم الشيك ومبلغه واسم ساحبه وكل بيان آخر يساعد على التعرف عليه والظروف التي أحاطت بفقده أو هلاكه، وإذا تعذر تقديم بعض هذه البيانات وجب ذكر أسباب ذلك. وإذا لم يكن للمعترض موطن في مصر وجب أن يعين له موطنا مختارا بها.
2- ومتى تلقى المسحوب عليه الإعتراض وجب عليه الإمتناع عن الوفاء بقيمة الشيك لحائزه وتجنيب مقابل وفاء الشيك الى أن يفصل في أمره.
3- ويقوم المعترض بنشر رقم الشيك المفقود أو الهالك ومبلغه واسم الساحب واسم المسحوب عليه واسم المعترض وعنوانه في إحدى الصحف اليومية , ويكون باطلا كل تصرف يقع على الشيك بعد تاريخ هذا النشر.$cc1027$, '2001-10-01', 'active' FROM ins_art_law17_1999_512;

WITH ins_art_law17_1999_513 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 513, $cc1028$الباب الرابع: الأوراق التجارية — الفصل الثالث: الشيك$cc1028$, $cc1029$1- يجوز لحائز الشيك لحامله في حالة ضياعه أن ينازع لدى المسحوب عليه في الإعتراض الذي قدم لمنع الوفاء به. وعلى المسحوب عليه أن يؤشر على الشيك بحصول الاعتراض والإحتفاظ بصورة منه ثم يخطر المعترض باسم حائز الشيك وعنوانه.
2- وعلى حائز الشيك إخطار المعترض بكتاب مسجل بعلم الوصول بوجوب رفع دعوى استحقاق الشيك خلال ثلاثين يوما من تاريخ تسلمه الإخطار. ويشتمل الإخطار على أسباب حيازة الشيك وتاريخها.
3- وإذا لم يرفع المعترض دعوى الإستحقاق خلال الميعاد المنصوص عليه في الفقرة السابقة تعين على قاضي الأمور المستعجلة بناء على طلب حائز الشيك أن يقضي بشطب الإعتراض. وفي هذه الحالة يعتبر حائز الشيك بالنسبة الى المسحوب عليه مالكه الشرعي.
4- وإذا رفع المعترض دعوى استحقاق الشيك فلا يجوز للمسحوب عليه أن يدفع قيمته إلا لمن يتقدم له من الخصمين بحكم نهائي بملكية الشيك أو بتسوية ودية مصدق عليها من الطرفين تقر له بالملكية.$cc1029$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1029$1- يجوز لحائز الشيك لحامله في حالة ضياعه أن ينازع لدى المسحوب عليه في الإعتراض الذي قدم لمنع الوفاء به. وعلى المسحوب عليه أن يؤشر على الشيك بحصول الاعتراض والإحتفاظ بصورة منه ثم يخطر المعترض باسم حائز الشيك وعنوانه.
2- وعلى حائز الشيك إخطار المعترض بكتاب مسجل بعلم الوصول بوجوب رفع دعوى استحقاق الشيك خلال ثلاثين يوما من تاريخ تسلمه الإخطار. ويشتمل الإخطار على أسباب حيازة الشيك وتاريخها.
3- وإذا لم يرفع المعترض دعوى الإستحقاق خلال الميعاد المنصوص عليه في الفقرة السابقة تعين على قاضي الأمور المستعجلة بناء على طلب حائز الشيك أن يقضي بشطب الإعتراض. وفي هذه الحالة يعتبر حائز الشيك بالنسبة الى المسحوب عليه مالكه الشرعي.
4- وإذا رفع المعترض دعوى استحقاق الشيك فلا يجوز للمسحوب عليه أن يدفع قيمته إلا لمن يتقدم له من الخصمين بحكم نهائي بملكية الشيك أو بتسوية ودية مصدق عليها من الطرفين تقر له بالملكية.$cc1029$, '2001-10-01', 'active' FROM ins_art_law17_1999_513;

WITH ins_art_law17_1999_514 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 514, $cc1030$الباب الرابع: الأوراق التجارية — الفصل الثالث: الشيك$cc1030$, $cc1031$1- إذا انقضت ستة أشهر من تاريخ الإعتراض المنصوص عليه في المادة 512 من هذا القانون دون أن يتقدم حائز الشيك للمطالبة بالوفاء, جاز للمعترض أن يطلب من المحكمة الإذن له بقبض مبلغ الشيك. ويصدر هذا الحكم في مواجهة المسحوب عليه وبعد أن تتحقق المحكمة من ملكية المعترض على الشيك.
2- وإذا لم يرفع المعترض الدعوى المشار إليها في الفقرة السابقة, أو رفعها ورفضتها المحكمة وجب على المسحوب عليه أن يعيد قيد مقابل الوفاء في جانب الأصول من حساب الساحب.$cc1031$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1031$1- إذا انقضت ستة أشهر من تاريخ الإعتراض المنصوص عليه في المادة 512 من هذا القانون دون أن يتقدم حائز الشيك للمطالبة بالوفاء, جاز للمعترض أن يطلب من المحكمة الإذن له بقبض مبلغ الشيك. ويصدر هذا الحكم في مواجهة المسحوب عليه وبعد أن تتحقق المحكمة من ملكية المعترض على الشيك.
2- وإذا لم يرفع المعترض الدعوى المشار إليها في الفقرة السابقة, أو رفعها ورفضتها المحكمة وجب على المسحوب عليه أن يعيد قيد مقابل الوفاء في جانب الأصول من حساب الساحب.$cc1031$, '2001-10-01', 'active' FROM ins_art_law17_1999_514;

WITH ins_art_law17_1999_515 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 515, $cc1032$الباب الرابع: الأوراق التجارية — الفصل الثالث: الشيك$cc1032$, $cc1033$1- لساحب الشيك أو حامله أن يسطره بوضع خطين متوازيين على صدر الشيك.
2- يكون التسطير عاما أو خاصا.
3- إذا خلا ما بين الخطين من أي بيان أو إذا كتب بينهما كلمة (بنك) أو أي عبارة أخرى بهذا المعنى كان التسطير عاما. أما إذا كتب اسم (بنك) معين يبين الخطين كان التسطير خاصا.
4- ويجوز تحويل التسطير العام الى تسطير خاص. أما التسطير الخاص فلا يجوز تحويله الى تسطير عام.
5- يعتبر شطب التسطير أو شطب اسم (البنك) المكتوب بين الخطين كأن لم يكن.$cc1033$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1033$1- لساحب الشيك أو حامله أن يسطره بوضع خطين متوازيين على صدر الشيك.
2- يكون التسطير عاما أو خاصا.
3- إذا خلا ما بين الخطين من أي بيان أو إذا كتب بينهما كلمة (بنك) أو أي عبارة أخرى بهذا المعنى كان التسطير عاما. أما إذا كتب اسم (بنك) معين يبين الخطين كان التسطير خاصا.
4- ويجوز تحويل التسطير العام الى تسطير خاص. أما التسطير الخاص فلا يجوز تحويله الى تسطير عام.
5- يعتبر شطب التسطير أو شطب اسم (البنك) المكتوب بين الخطين كأن لم يكن.$cc1033$, '2001-10-01', 'active' FROM ins_art_law17_1999_515;

WITH ins_art_law17_1999_516 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 516, $cc1034$الباب الرابع: الأوراق التجارية — الفصل الثالث: الشيك$cc1034$, $cc1035$1- لا يجوز للمسحوب عليه في حالة التسطير العام أن يدفع قيمة الشيك إلا الى بنك أو إلى أحد عملائه.
2- ولا يجوز للمسحوب عليه في حالة التسطير الخاص أن يدفع قيمة الشيك إلا إلى البنك المكتوب اسمه بين الخطين, وإذا كان هذا البنك هو نفسه البنك المسحوب عليه جاز الوفاء لعميل له بطريق قيد قيمة الشيك في حساب هذا العميل . ويجوز للبنك المكتوب اسمه بين الخطين أن يعهد إلى بنك آخر بقبض قيمة الشيك بموجب تظهير توكيلي.
3- ولا يجوز لبنك أن يتسلم شيكا مسطرا لوفاء قيمته إلا من أحد عملائه أو من بنك آخر, كما لا يجوز له أن يقبض قيمة هذا الشيك لحساب أشخاص آخرين غيرهما.
4- إذا حمل الشيك أكثر من تسطير خاص واحد فلا يجوز للمسحوب عليه وفاؤه إلا إذا كان يحمل تسطيرين وكان أحدهما لتحصيل قيمته في غرفة مقاصة.
5- إذا خالف المسحوب عليه الأحكام المنصوص عليها في هذه المادة كان مسئولا عن تعويض الضرر بما لا يجاوز مبلغ الشيك.
6- يقصد بكلمة (عميل) في حكم هذه المادة كل شخص له حساب لدى المسحوب عليه وحصل منه على دفتر شيكات أو كان من حقه الحصول على هذا الدفتر.$cc1035$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1035$1- لا يجوز للمسحوب عليه في حالة التسطير العام أن يدفع قيمة الشيك إلا الى بنك أو إلى أحد عملائه.
2- ولا يجوز للمسحوب عليه في حالة التسطير الخاص أن يدفع قيمة الشيك إلا إلى البنك المكتوب اسمه بين الخطين, وإذا كان هذا البنك هو نفسه البنك المسحوب عليه جاز الوفاء لعميل له بطريق قيد قيمة الشيك في حساب هذا العميل . ويجوز للبنك المكتوب اسمه بين الخطين أن يعهد إلى بنك آخر بقبض قيمة الشيك بموجب تظهير توكيلي.
3- ولا يجوز لبنك أن يتسلم شيكا مسطرا لوفاء قيمته إلا من أحد عملائه أو من بنك آخر, كما لا يجوز له أن يقبض قيمة هذا الشيك لحساب أشخاص آخرين غيرهما.
4- إذا حمل الشيك أكثر من تسطير خاص واحد فلا يجوز للمسحوب عليه وفاؤه إلا إذا كان يحمل تسطيرين وكان أحدهما لتحصيل قيمته في غرفة مقاصة.
5- إذا خالف المسحوب عليه الأحكام المنصوص عليها في هذه المادة كان مسئولا عن تعويض الضرر بما لا يجاوز مبلغ الشيك.
6- يقصد بكلمة (عميل) في حكم هذه المادة كل شخص له حساب لدى المسحوب عليه وحصل منه على دفتر شيكات أو كان من حقه الحصول على هذا الدفتر.$cc1035$, '2001-10-01', 'active' FROM ins_art_law17_1999_516;

WITH ins_art_law17_1999_517 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 517, $cc1036$الباب الرابع: الأوراق التجارية — الفصل الثالث: الشيك$cc1036$, $cc1037$1- يجوز لساحب الشيك أو حامله أن يشترط عدم وفائه نقدا بأن يضع على صدره عبارة (للقيد في الحساب) أو أية عبارة أخرى بهذا المعنى, وفي هذه الحالة لا يكون للمسحوب عليه إلا تسوية قيمة الشيك بطريق قيود كتابية كالقيد في الحساب أو النقل المصرفي أو المقاصة. وتقوم التسوية بطريق هذه القيود مقام الوفاء.
2- لا يعتد بشطب عبارة (للقيد في الحساب).
3- وإذا خالف المسحوب عليه الأحكام المنصوص عليها في هذه المادة كان مسئولا عن تعويض الضرر بما لا يجاوز مبلغ الشيك.
5- الرجوع$cc1037$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1037$1- يجوز لساحب الشيك أو حامله أن يشترط عدم وفائه نقدا بأن يضع على صدره عبارة (للقيد في الحساب) أو أية عبارة أخرى بهذا المعنى, وفي هذه الحالة لا يكون للمسحوب عليه إلا تسوية قيمة الشيك بطريق قيود كتابية كالقيد في الحساب أو النقل المصرفي أو المقاصة. وتقوم التسوية بطريق هذه القيود مقام الوفاء.
2- لا يعتد بشطب عبارة (للقيد في الحساب).
3- وإذا خالف المسحوب عليه الأحكام المنصوص عليها في هذه المادة كان مسئولا عن تعويض الضرر بما لا يجاوز مبلغ الشيك.
5- الرجوع$cc1037$, '2001-10-01', 'active' FROM ins_art_law17_1999_517;

WITH ins_art_law17_1999_518 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 518, $cc1038$الباب الرابع: الأوراق التجارية — الفصل الثالث: الشيك$cc1038$, $cc1039$1- لحامل الشيك الرجوع على الساحب والمظهرين وغيرهم من الملتزمين به إذا قدمه خلال ميعاد التقديم ولم تدفع قيمته وأثبت الإمتناع عن الدفع باحتجاج. ويجوز عوضا عن الإحتجاج إثبات الإمتناع عن الدفع وسببه ببيان يصدر من المسحوب عليه مع ذكر وقت تقديم الشيك. ويكون البيان مؤرخا ومكتوبا على الشيك نفسه ومذيلا بتوقيع من أصدره ويجوز أن يصدر هذا البيان على أنموذج خاص أو من غرفة مقاصة على أن يذكر فيه أن الشيك قدم في الميعاد ولم تدفع قيمته.
2- لا يجوز الإمتناع عن إصدار البيان المشار إليه في الفقرة السابقة إذا طلبه الحامل ولو كان الشيك يشتمل على شرط الرجوع بلا مصاريف. ومع ذلك يجوز للملتزم بإصدار البيان طلب مهلة لا تجاوز يوم العمل التالي لتقديم الشيك ولو قدم في اليوم الأخير من ميعاد التقديم.
3- ويجب إثبات الإمتناع عن الدفع بالكيفية المنصوص عليها في الفقرة الأولى من هذه المادة قبل إنقضاء ميعاد التقديم. فإذا قدم الشيك في آخر يوم من هذا الميعاد جاز إثبات الإمتناع عن الدفع في يوم العمل التالي له.$cc1039$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
