3- ويجب إثبات الإمتناع عن الدفع بالكيفية المنصوص عليها في الفقرة الأولى من هذه المادة قبل إنقضاء ميعاد التقديم. فإذا قدم الشيك في آخر يوم من هذا الميعاد جاز إثبات الإمتناع عن الدفع في يوم العمل التالي له.$cc1039$, '2001-10-01', 'active' FROM ins_art_law17_1999_518;

