  SELECT id, 521, $cc1044$الباب الرابع: الأوراق التجارية — الفصل الثالث: الشيك$cc1044$, $cc1045$1- الأشخاص الملتزمون بموجب شيك مسئولون بالتضامن قبل حامله.
2- وللحامل الرجوع على هؤلاء الملتزمين منفردين أو مجتمعين دون أن يلزم بمراعاة ترتيب إلتزاماتهم.
3- ويثبت هذا الحق لكل ملتزم في الشيك إذا دفع قيمته.
4- والدعوى المقامة على أحد الملتزمين لا تحول دون الرجوع على الباقين ولو كانوا لاحقين للملتزم الذي وجهت إليه الدعوى إبتداء.$cc1045$
