  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 522, $cc1046$الباب الرابع: الأوراق التجارية — الفصل الثالث: الشيك$cc1046$, $cc1047$لحامل الشيك مطالبة من له حق الرجوع عليه بما يأتي:
