WITH ins_art_law17_1999_526 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 526, $cc1054$الباب الرابع: الأوراق التجارية — الفصل الثالث: الشيك$cc1054$, $cc1055$1- إذا حالت قوة قاهرة دون تقديم الشيك للوفاء أو عمل الإحتجاج أو ما يقوم مقامه في المواعيد المقررة لذلك امتدت هذه المواعيد.
2- وعلى الحامل أن يخطر دون إبطاء من ظهر له الشيك بالقوة القاهرة وأن يثبت هذا الإخطار مؤرخا وموقعا منه في الشيك, وتتسلسل الإخطارات وفقا للمادة 440 من هذا القانون.
3- وعلى الحامل بعد زوال القوة القاهرة تقديم الشيك للوفاء دون إبطاء وعمل الإحتجاج أو ما يقوم مقامه عند الإقتضاء.
4- إذا استمرت القوة القاهرة أكثر من ثلاثين يوما محسوبة من التاريخ الذي قام فيه الحامل بإخطار من ظهر له الشيك بقيام القوة القاهرة ولو وقع هذا التاريخ قبل انقضاء ميعاد تقديم الشيك جاز الرجوع على الملتزمين دون الحاجة إلى تقديم الشيك أو عمل الإحتجاج أو ما يقوم مقامه إلا إذا كان حق الرجوع موقوفا بموجب القانون لمدة أطول.
5- ولا يعتبر من القوة القاهرة الأمور المتصلة بشخص حامل الشيك أو بمن كلفه بتقديمه أو بعمل الاحتجاج أو ما يقوم مقامه.$cc1055$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1055$1- إذا حالت قوة قاهرة دون تقديم الشيك للوفاء أو عمل الإحتجاج أو ما يقوم مقامه في المواعيد المقررة لذلك امتدت هذه المواعيد.
2- وعلى الحامل أن يخطر دون إبطاء من ظهر له الشيك بالقوة القاهرة وأن يثبت هذا الإخطار مؤرخا وموقعا منه في الشيك, وتتسلسل الإخطارات وفقا للمادة 440 من هذا القانون.
3- وعلى الحامل بعد زوال القوة القاهرة تقديم الشيك للوفاء دون إبطاء وعمل الإحتجاج أو ما يقوم مقامه عند الإقتضاء.
4- إذا استمرت القوة القاهرة أكثر من ثلاثين يوما محسوبة من التاريخ الذي قام فيه الحامل بإخطار من ظهر له الشيك بقيام القوة القاهرة ولو وقع هذا التاريخ قبل انقضاء ميعاد تقديم الشيك جاز الرجوع على الملتزمين دون الحاجة إلى تقديم الشيك أو عمل الإحتجاج أو ما يقوم مقامه إلا إذا كان حق الرجوع موقوفا بموجب القانون لمدة أطول.
5- ولا يعتبر من القوة القاهرة الأمور المتصلة بشخص حامل الشيك أو بمن كلفه بتقديمه أو بعمل الاحتجاج أو ما يقوم مقامه.$cc1055$, '2001-10-01', 'active' FROM ins_art_law17_1999_526;

WITH ins_art_law17_1999_527 AS (
