WITH ins_art_law17_1999_528 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 528, $cc1058$الباب الرابع: الأوراق التجارية — الفصل الثالث: الشيك$cc1058$, $cc1059$1- يتحمل المسحوب عليه وحدة الضرر الذي يترتب على وفاء شيك زور فيه توقيع الساحب أو حرفت فيه بياناته إذا لم يمكن نسبة أي خطا إلى الساحب. وكل شرط على خلاف ذلك يعتبر كأن لم يكن.
