WITH ins_art_law17_1999_530 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 530, $cc1062$الباب الرابع: الأوراق التجارية — الفصل الثالث: الشيك$cc1062$, $cc1063$1- على كل بنك يسلم عميله دفترا يشتمل على نماذج شيكات على بياض للدفع بموجبها من خزائنه أن يكتب على كل نموذج منها رقم الشيك واسم البنك أو أحد فروعه واسم العميل الذي تسلم الدفتر ورقم حسابه.
2- يعتبر القبول الصريح أو الضمني من العميل لكشف الحساب الدوري الذي يرسله إليه البنك إبراء لذمة البنك مما قيده في هذا الحساب بالخصم أو الإضافة من مبالغ الشيكات، ويكون قبولا ضمنيا على وجه الخصوص عدم اعتراض العميل على كشف الحساب خلال ثلاثين يوما من تاريخ تسلمه. ويجوز للبنك بعد قبول كشف الحساب أن يرد إلى العميل الشيكات التي دفعها خصما على الحساب وان يحتفظ بتسجيلات مصورة لهذه الشيكات تكون لها حجية كاملة لصالحه.
7- التقادم$cc1063$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1063$1- على كل بنك يسلم عميله دفترا يشتمل على نماذج شيكات على بياض للدفع بموجبها من خزائنه أن يكتب على كل نموذج منها رقم الشيك واسم البنك أو أحد فروعه واسم العميل الذي تسلم الدفتر ورقم حسابه.
2- يعتبر القبول الصريح أو الضمني من العميل لكشف الحساب الدوري الذي يرسله إليه البنك إبراء لذمة البنك مما قيده في هذا الحساب بالخصم أو الإضافة من مبالغ الشيكات، ويكون قبولا ضمنيا على وجه الخصوص عدم اعتراض العميل على كشف الحساب خلال ثلاثين يوما من تاريخ تسلمه. ويجوز للبنك بعد قبول كشف الحساب أن يرد إلى العميل الشيكات التي دفعها خصما على الحساب وان يحتفظ بتسجيلات مصورة لهذه الشيكات تكون لها حجية كاملة لصالحه.
7- التقادم$cc1063$, '2001-10-01', 'active' FROM ins_art_law17_1999_530;

WITH ins_art_law17_1999_531 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 531, $cc1064$الباب الرابع: الأوراق التجارية — الفصل الثالث: الشيك$cc1064$, $cc1065$1- تتقادم دعاوى رجوع حامل الشيك على الساحب والمظهرين وغيرهم من الملتزمين بدفع قيمة الشيك بمضي ستة أشهر من تاريخ تقديمه للوفاء أو من تاريخ انقضاء ميعاد تقديمه.
2- وتتقادم دعوى حامل الشيك على المسحوب عليه بمضي ثلاث سنوات من تاريخ تقديمه للوفاء أو من تاريخ انقضاء ميعاد تقديمه.
3- وتتقادم دعاوى رجوع الملتزمين بعضهم على بعض الآخر بمضي ستة أشهر من اليوم الذي أوفى فيه الملتزم قيمة الشيك أو من يوم مطالبته قضائيا بالوفاء.
4- إذا أقيمت الدعوى فلا تسرى مدة التقادم المنصوص عليها في هذه المادة إلا من تاريخ آخر إجراء في الدعوى.
5- ولا تسرى مدة هذا التقادم إذا صدر حكم بالدين أو اقر به المدين بسند منفرد يترتب عليه إقرارا تجديده.
6- تسرى على انقطاع هذا التقادم أو وقفه الأحكام المنصوص عليها في القانون المدني.$cc1065$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1065$1- تتقادم دعاوى رجوع حامل الشيك على الساحب والمظهرين وغيرهم من الملتزمين بدفع قيمة الشيك بمضي ستة أشهر من تاريخ تقديمه للوفاء أو من تاريخ انقضاء ميعاد تقديمه.
2- وتتقادم دعوى حامل الشيك على المسحوب عليه بمضي ثلاث سنوات من تاريخ تقديمه للوفاء أو من تاريخ انقضاء ميعاد تقديمه.
3- وتتقادم دعاوى رجوع الملتزمين بعضهم على بعض الآخر بمضي ستة أشهر من اليوم الذي أوفى فيه الملتزم قيمة الشيك أو من يوم مطالبته قضائيا بالوفاء.
4- إذا أقيمت الدعوى فلا تسرى مدة التقادم المنصوص عليها في هذه المادة إلا من تاريخ آخر إجراء في الدعوى.
5- ولا تسرى مدة هذا التقادم إذا صدر حكم بالدين أو اقر به المدين بسند منفرد يترتب عليه إقرارا تجديده.
6- تسرى على انقطاع هذا التقادم أو وقفه الأحكام المنصوص عليها في القانون المدني.$cc1065$, '2001-10-01', 'active' FROM ins_art_law17_1999_531;

WITH ins_art_law17_1999_532 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 532, $cc1066$الباب الرابع: الأوراق التجارية — الفصل الثالث: الشيك$cc1066$, $cc1067$يجوز لحامل الشيك رغم تقادم دعوى المطالبة بقيمته أن يطالب الساحب الذي لم يقدم مقابل الوفاء أو قدمه ثم استرده كله أو بعضه ما أثرى به بغير وجه حق وكذلك يجوز للحامل توجيه هذه المطالبة إلى كل مظهر يحقق إثراء بغير وجه حق.
8- العقوبات$cc1067$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
