INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1067$يجوز لحامل الشيك رغم تقادم دعوى المطالبة بقيمته أن يطالب الساحب الذي لم يقدم مقابل الوفاء أو قدمه ثم استرده كله أو بعضه ما أثرى به بغير وجه حق وكذلك يجوز للحامل توجيه هذه المطالبة إلى كل مظهر يحقق إثراء بغير وجه حق.
8- العقوبات$cc1067$, '2001-10-01', 'active' FROM ins_art_law17_1999_532;

WITH ins_art_law17_1999_533 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 533, $cc1068$الباب الرابع: الأوراق التجارية — الفصل الثالث: الشيك$cc1068$, $cc1069$1- يعاقب بالغرامة التي لا تقل عن ثلاثة آلاف جنيه ولا تجاوز عشرة آلاف جنيه كل موظف بالبنك ارتكب عمدا أحد الأفعال الآتية:
(أ)- التصريح على خلاف الحقيقة بعدم وجود مقابل وفاء للشيك أو بوجود مقابل وفاء اقل من قيمته.
(ب)- الرفض بسوء نية وفاء شيك له مقابل وفاء كامل أو جزئي ولم يقدم بشأنه اعتراض صحيح.
(ج)- الامتناع عن وضع أو تسليم البيان المشار إليه في الفقرة الأولى من المادة 518 من هذا القانون.
(د)- تسليم أحد العملاء دفتر شيكات لا يشتمل على البيانات المنصوص عليها في المادة 530 من هذا القانون.
2- ويكون البنك مسئولا بالتضامن مع موظفيه المحكوم عليهم عن سداد العقوبات المالية المحكوم بها.$cc1069$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1069$1- يعاقب بالغرامة التي لا تقل عن ثلاثة آلاف جنيه ولا تجاوز عشرة آلاف جنيه كل موظف بالبنك ارتكب عمدا أحد الأفعال الآتية:
(أ)- التصريح على خلاف الحقيقة بعدم وجود مقابل وفاء للشيك أو بوجود مقابل وفاء اقل من قيمته.
(ب)- الرفض بسوء نية وفاء شيك له مقابل وفاء كامل أو جزئي ولم يقدم بشأنه اعتراض صحيح.
(ج)- الامتناع عن وضع أو تسليم البيان المشار إليه في الفقرة الأولى من المادة 518 من هذا القانون.
(د)- تسليم أحد العملاء دفتر شيكات لا يشتمل على البيانات المنصوص عليها في المادة 530 من هذا القانون.
2- ويكون البنك مسئولا بالتضامن مع موظفيه المحكوم عليهم عن سداد العقوبات المالية المحكوم بها.$cc1069$, '2001-10-01', 'active' FROM ins_art_law17_1999_533;

WITH ins_art_law17_1999_534 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 534, $cc1070$الباب الرابع: الأوراق التجارية — الفصل الثالث: الشيك$cc1070$, $cc1071$1- يعاقب بالحبس وبغرامة لا تجاوز خمسين ألف جنيه أو بإحدى هاتين العقوبتين كل من ارتكب عمدا أحد الأفعال الآتية:
(أ) إصدار شيك ليس له مقابل وفاء قابل للصرف.
(ب)استرداد كل الرصيد أو بعضه أو التصرف فيه بعد إصدار الشيك بحيث يصبح الباقي لا يفي بقيمة الشيك.
(ج) إصدار أمر للمسحوب عليه بعدم صرف الشيك في غير الحالات المقررة قانونا.
(د) تحرير شيك أو التوقيع عليه بسوء نية على نحو يحول دون صرفه.
2- يعاقب بالعقوبة المنصوص عليها في الفقرة السابقة كل من ظهر لغيره شيكا تظهيرا ناقلا للملكية أو سلمه شيكا مستحق الدفع لحامله مع علمه بأنه ليس له مقابل وفاء يفي بكامل قيمته أو انه غير قابل للصرف.
3- وإذا عاد الجاني إلى ارتكاب إحدى هذه الجرائم خلال خمس سنوات من تاريخ الحكم عليه نهائيا في أي منها تكون عقوبة الحبس والغرامة التي لا تجاوز مائة ألف جنيه.
4- وللمجني عليه ولوكيله الخاص في الجرائم المنصوص عليها في هذه المادة أن يطلب من النيابة العامة أو المحكمة بحسب الأحوال وفي أية حالة كانت عليها الدعوى إثبات صلحه مع المتهم.
ويترتب على الصلح انقضاء الدعوى الجنائية ولو كانت مرفوعة بطريق الادعاء المباشر، وتأمر النيابة العامة بوقف العقوبة إذا تم الصلح أثناء تنفيذها ولو بعد صيرورة الحكم باتا.$cc1071$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1071$1- يعاقب بالحبس وبغرامة لا تجاوز خمسين ألف جنيه أو بإحدى هاتين العقوبتين كل من ارتكب عمدا أحد الأفعال الآتية:
(أ) إصدار شيك ليس له مقابل وفاء قابل للصرف.
(ب)استرداد كل الرصيد أو بعضه أو التصرف فيه بعد إصدار الشيك بحيث يصبح الباقي لا يفي بقيمة الشيك.
(ج) إصدار أمر للمسحوب عليه بعدم صرف الشيك في غير الحالات المقررة قانونا.
(د) تحرير شيك أو التوقيع عليه بسوء نية على نحو يحول دون صرفه.
2- يعاقب بالعقوبة المنصوص عليها في الفقرة السابقة كل من ظهر لغيره شيكا تظهيرا ناقلا للملكية أو سلمه شيكا مستحق الدفع لحامله مع علمه بأنه ليس له مقابل وفاء يفي بكامل قيمته أو انه غير قابل للصرف.
3- وإذا عاد الجاني إلى ارتكاب إحدى هذه الجرائم خلال خمس سنوات من تاريخ الحكم عليه نهائيا في أي منها تكون عقوبة الحبس والغرامة التي لا تجاوز مائة ألف جنيه.
4- وللمجني عليه ولوكيله الخاص في الجرائم المنصوص عليها في هذه المادة أن يطلب من النيابة العامة أو المحكمة بحسب الأحوال وفي أية حالة كانت عليها الدعوى إثبات صلحه مع المتهم.
ويترتب على الصلح انقضاء الدعوى الجنائية ولو كانت مرفوعة بطريق الادعاء المباشر، وتأمر النيابة العامة بوقف العقوبة إذا تم الصلح أثناء تنفيذها ولو بعد صيرورة الحكم باتا.$cc1071$, '2001-10-01', 'active' FROM ins_art_law17_1999_534;

