SELECT id, 1, $cc1077$1- إذا قضت المحكمة بالإدانة في إحدى جرائم الشيك المنصوص عليها في المادة 534 من هذا القانون جاز لها أن تأمر بنشر الحكم على نفقة المحكوم عليه في صحيفة يومية ويجب أن يتضمن هذا النشر اسم المحكوم عليه وموطنه ومهنته والعقوبة المحكوم عليه بها.
2- ويجوز للمحكمة في حالة العود أن تأمر بسحب دفتر الشيكات من المحكوم عليه ومنع إعطائه دفاتر شيكات جديدة لمدة تعينها، وتتولى النيابة العامة تبليغ هذا الأمر إلى جميع البنوك.$cc1077$, '2001-10-01', 'active' FROM ins_art_law17_1999_537;

WITH ins_art_law17_1999_538 AS (
