2- وعلى المحضرين قيد أوراق الاحتجاج بتمامها يوما فيوما مع مراعاة ترتيب تواريخها في سجل خاص يصدر بتنظيمه قرار من وزير العدل.$cc1089$, '1999-10-01', 'active' FROM ins_art_law17_1999_543;

WITH ins_art_law17_1999_544 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 544, $cc1090$الباب الرابع: الأوراق التجارية — الفصل الرابع: أحكام مشتركة$cc1090$, $cc1091$1- على قلم المحضرين خلال الأيام العشرة الأولى من كل شهر أن يرسل إلى مكتب السجل التجاري الكائن في دائرته مكان عمل الاحتجاج قائمة باحتجاجات عدم الوفاء التي حررها خلال الشهر السابق عن الكمبيالات المقبولة والسندات لامر.
2- ويجب ان تشتمل هذه القائمة على البيانات الآتية:
(أ) تاريخ الاحتجاج.
(ب)اسم صاحب الكمبيالة ومهنته وموطنه.
(ج) اسم محرر السند لأمر أو اسم قابل الكمبيالة ومهنته وموطنه.
(د) تاريخ الاستحقاق.
(هـ) مبلغ الكمبيالة أو السند لأمر.
(و) ملخص أسباب الامتناع عن الوفاء التي ذكرها المدين وقت تحرير الاحتجاج.
3- يمسك مكتب السجل التجاري دفترا لقيد البيانات المذكورة في الفقرة السابقة، ويجوز لكل شخص الاطلاع عليها مقابل الرسوم المقررة، ويقوم مكتب السجل التجاري بعمل نشرة تتضمن تلك البيانات.$cc1091$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
