2- ويجب ان تشتمل هذه القائمة على البيانات الآتية:
(أ) تاريخ الاحتجاج.
(ب)اسم صاحب الكمبيالة ومهنته وموطنه.
(ج) اسم محرر السند لأمر أو اسم قابل الكمبيالة ومهنته وموطنه.
(د) تاريخ الاستحقاق.
(هـ) مبلغ الكمبيالة أو السند لأمر.
(و) ملخص أسباب الامتناع عن الوفاء التي ذكرها المدين وقت تحرير الاحتجاج.
3- يمسك مكتب السجل التجاري دفترا لقيد البيانات المذكورة في الفقرة السابقة، ويجوز لكل شخص الاطلاع عليها مقابل الرسوم المقررة، ويقوم مكتب السجل التجاري بعمل نشرة تتضمن تلك البيانات.$cc1091$, '1999-10-01', 'active' FROM ins_art_law17_1999_544;

WITH ins_art_law17_1999_545 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 545, $cc1092$الباب الرابع: الأوراق التجارية — الفصل الرابع: أحكام مشتركة$cc1092$, $cc1093$1- إذا وافق استحقاق الورقة التجارية يوم عطلة رسمية أو يوم العطلة الأسبوعية في منشأة المدين فلا يجوز المطالبة بوفاء الورقة إلا في يوم العمل التالي.
2- ولا يجوز القيام بأي إجراء يتعلق بالورقة التجارية لتقديمها للقبول أو الوفاء أو عمل الاحتجاج إلا في يوم عمل.
3- وإذا حدد لعمل أي إجراء يتعلق بالورقة التجارية ميعاد معين ووافق يومه الأخير يوم عطلة رسمية أو يوم العطلة الأسبوعية في منشأة المدين امتد الميعاد إلى اليوم التالي.
4- تحسب في كل ميعاد أيام العطلة التي تتخلله.
5- على كل تاجر أن يعلن في مكان بارز في منشأته عن يوم العطلة الأسبوعية في المنشأة وإلا افترض انه يوم الجمعة من كل أسبوع.$cc1093$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1093$1- إذا وافق استحقاق الورقة التجارية يوم عطلة رسمية أو يوم العطلة الأسبوعية في منشأة المدين فلا يجوز المطالبة بوفاء الورقة إلا في يوم العمل التالي.
2- ولا يجوز القيام بأي إجراء يتعلق بالورقة التجارية لتقديمها للقبول أو الوفاء أو عمل الاحتجاج إلا في يوم عمل.
3- وإذا حدد لعمل أي إجراء يتعلق بالورقة التجارية ميعاد معين ووافق يومه الأخير يوم عطلة رسمية أو يوم العطلة الأسبوعية في منشأة المدين امتد الميعاد إلى اليوم التالي.
4- تحسب في كل ميعاد أيام العطلة التي تتخلله.
5- على كل تاجر أن يعلن في مكان بارز في منشأته عن يوم العطلة الأسبوعية في المنشأة وإلا افترض انه يوم الجمعة من كل أسبوع.$cc1093$, '1999-10-01', 'active' FROM ins_art_law17_1999_545;

