WITH ins_art_law17_1999_550 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 550, $cc1102$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الأول: شهر الإفلاس$cc1102$, $cc1103$1- يعد في حالة إفلاس كل تاجر ملزم بموجب أحكام هذا القانون بإمساك دفاتر تجارية إذا توقف عن دفع ديونه التجارية اثر اضطراب أعماله المالية.
2- ولا يترتب على التوقف عن الدفع اثر قبل صدور حكم شهر الإفلاس، ما لم ينص القانون على غير ذلك.$cc1103$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1103$1- يعد في حالة إفلاس كل تاجر ملزم بموجب أحكام هذا القانون بإمساك دفاتر تجارية إذا توقف عن دفع ديونه التجارية اثر اضطراب أعماله المالية.
2- ولا يترتب على التوقف عن الدفع اثر قبل صدور حكم شهر الإفلاس، ما لم ينص القانون على غير ذلك.$cc1103$, '1999-10-01', 'active' FROM ins_art_law17_1999_550;

WITH ins_art_law17_1999_551 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 551, $cc1104$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الأول: شهر الإفلاس$cc1104$, $cc1105$1- يجوز شهر إفلاس التاجر بعد وفاته أو اعتزاله التجارة إذا توفى أو اعتزل التجارة وهو في حالة توقف عن الدفع، ويجب تقديم طلب شهر الإفلاس خلال السنة التالية للوفاة أو اعتزال التجارة. ولا يسرى هذا الميعاد في حالة اعتزال التجارة إلا من تاريخ شطب اسم التاجر من السجل التجاري.
2- يجوز لورثة التاجر طلب شهر إفلاسه بعد وفاته مع مراعاة الميعاد المذكور في الفقرة السابقة، فإذا اعترض بعض الورثة على شهر الإفلاس وجب أن تسمع المحكمة أقوالهم ثم تفصل في الطلب وفقا لمصلحة ذوي الشأن.
3- تعلن صحيفة دعوى شهر الإفلاس في حالة وفاة التاجر إلى الورثة جملة في آخر موطن للمتوفى.$cc1105$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1105$1- يجوز شهر إفلاس التاجر بعد وفاته أو اعتزاله التجارة إذا توفى أو اعتزل التجارة وهو في حالة توقف عن الدفع، ويجب تقديم طلب شهر الإفلاس خلال السنة التالية للوفاة أو اعتزال التجارة. ولا يسرى هذا الميعاد في حالة اعتزال التجارة إلا من تاريخ شطب اسم التاجر من السجل التجاري.
2- يجوز لورثة التاجر طلب شهر إفلاسه بعد وفاته مع مراعاة الميعاد المذكور في الفقرة السابقة، فإذا اعترض بعض الورثة على شهر الإفلاس وجب أن تسمع المحكمة أقوالهم ثم تفصل في الطلب وفقا لمصلحة ذوي الشأن.
3- تعلن صحيفة دعوى شهر الإفلاس في حالة وفاة التاجر إلى الورثة جملة في آخر موطن للمتوفى.$cc1105$, '1999-10-01', 'active' FROM ins_art_law17_1999_551;

WITH ins_art_law17_1999_552 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 552, $cc1106$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الأول: شهر الإفلاس$cc1106$, $cc1107$يشهر إفلاس التاجر بناء على طلبه أو طلب أحد الدائنين أو النيابة العامة. ويجوز للمحكمة أن تقضى بشهر الإفلاس من تلقاء ذاتها.$cc1107$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1107$يشهر إفلاس التاجر بناء على طلبه أو طلب أحد الدائنين أو النيابة العامة. ويجوز للمحكمة أن تقضى بشهر الإفلاس من تلقاء ذاتها.$cc1107$, '1999-10-01', 'active' FROM ins_art_law17_1999_552;

WITH ins_art_law17_1999_553 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 553, $cc1108$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الأول: شهر الإفلاس$cc1108$, $cc1109$1- يجب على التاجر أن يطلب شهر إفلاسه خلال خمسة عشر يوما من تاريخ توقفه عن الدفع ويكون الطلب بصحيفة تودع قلم كتاب المحكمة تذكر فيه أسباب التوقف عن الدفع وترفق بها الوثائق الآتية:
(أ) الدفاتر التجارية الرئيسية.
(ب)صورة من آخر ميزانية وحساب الأرباح والخسائر.
(ج)بيان إجمالي بالمصروفات الشخصية عن السنتين السابقتين على تقديم طلب شهر الإفلاس أو عن مدة اشتغاله بالتجارة إذا كانت اقل من ذلك.
(د) بيان تفصيلي بما يملكه من عقارات ومنقولات وقيمتها التقريبية في تاريخ التوقف عن الدفع، وكذلك المبالغ النقدية المودعة باسمه لدى البنوك سواء في مصر أو خارجها.
(هـ) بيان بأسماء الدائنين والمدينين وعناوينهم ومقدار حقوقهم أو ديونهم أو التأمينات الضامنة لها.
(و) بيان بالاحتجاجات التي حررت ضد التاجر خلال السنتين السابقتين على تقديم طلب شهر الإفلاس.
2- يجب أن تكون الوثائق المشار إليها في الفقرة السابقة مؤرخة وموقعة من التاجر، وإذا تعذر تقديم بعض هذه الوثائق أو استيفاء بياناتها وجب عليه إيضاح أسباب ذلك.$cc1109$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1109$1- يجب على التاجر أن يطلب شهر إفلاسه خلال خمسة عشر يوما من تاريخ توقفه عن الدفع ويكون الطلب بصحيفة تودع قلم كتاب المحكمة تذكر فيه أسباب التوقف عن الدفع وترفق بها الوثائق الآتية:
(أ) الدفاتر التجارية الرئيسية.
(ب)صورة من آخر ميزانية وحساب الأرباح والخسائر.
(ج)بيان إجمالي بالمصروفات الشخصية عن السنتين السابقتين على تقديم طلب شهر الإفلاس أو عن مدة اشتغاله بالتجارة إذا كانت اقل من ذلك.
(د) بيان تفصيلي بما يملكه من عقارات ومنقولات وقيمتها التقريبية في تاريخ التوقف عن الدفع، وكذلك المبالغ النقدية المودعة باسمه لدى البنوك سواء في مصر أو خارجها.
(هـ) بيان بأسماء الدائنين والمدينين وعناوينهم ومقدار حقوقهم أو ديونهم أو التأمينات الضامنة لها.
(و) بيان بالاحتجاجات التي حررت ضد التاجر خلال السنتين السابقتين على تقديم طلب شهر الإفلاس.
2- يجب أن تكون الوثائق المشار إليها في الفقرة السابقة مؤرخة وموقعة من التاجر، وإذا تعذر تقديم بعض هذه الوثائق أو استيفاء بياناتها وجب عليه إيضاح أسباب ذلك.$cc1109$, '1999-10-01', 'active' FROM ins_art_law17_1999_553;

WITH ins_art_law17_1999_554 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 554, $cc1110$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الأول: شهر الإفلاس$cc1110$, $cc1111$1- لكل دائن بدين تجاري خال من النزاع حال الأداء أن يطلب الحكم بشهر إفلاس مدينه التاجر، ويكون للدائن بدين مدني حال هذا الحق إذا اثبت أن التاجر قد توقف عن دفع ديونه التجارية الحالة فضلا عن دينه المدني.
2- ويكون للدائن بدين آجل الحق في طلب شهر الإفلاس إذا لم يكن لمدينه التاجر موطن معروف في مصر أو إذا لجأ إلى الفرار أو اغلق متجره أو شرع في تصفيته أو جرى تصرفات ضارة بدائنيه بشرط أن يقدم الدائن ما يثبت أن المدين توقف عن دفع ديونه التجارية الحالة.
3- ويطلب الدائن شهر إفلاس مدينه بصحيفة تودع قلم كتاب المحكمة المختصة مصحوبة بما يفيد إيداع مبلغ ألف جنيه خزانة المحكمة على سبيل الأمانة لحساب مصروفات نشر الحكم الصادر بشهر الإفلاس، يطلب فيها اتخاذ الإجراءات التحفظية اللازمة ويبين فيها الظروف التي يستدل منها على توقف المدين عن دفع ديونه، ويحدد قلم كتاب المحكمة اقرب جلسة لنظر الدعوى ويعلن بها المدين.$cc1111$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1111$1- لكل دائن بدين تجاري خال من النزاع حال الأداء أن يطلب الحكم بشهر إفلاس مدينه التاجر، ويكون للدائن بدين مدني حال هذا الحق إذا اثبت أن التاجر قد توقف عن دفع ديونه التجارية الحالة فضلا عن دينه المدني.
