3- ويطلب الدائن شهر إفلاس مدينه بصحيفة تودع قلم كتاب المحكمة المختصة مصحوبة بما يفيد إيداع مبلغ ألف جنيه خزانة المحكمة على سبيل الأمانة لحساب مصروفات نشر الحكم الصادر بشهر الإفلاس، يطلب فيها اتخاذ الإجراءات التحفظية اللازمة ويبين فيها الظروف التي يستدل منها على توقف المدين عن دفع ديونه، ويحدد قلم كتاب المحكمة اقرب جلسة لنظر الدعوى ويعلن بها المدين.$cc1111$, '1999-10-01', 'active' FROM ins_art_law17_1999_554;

WITH ins_art_law17_1999_555 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 555, $cc1112$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الأول: شهر الإفلاس$cc1112$, $cc1113$لا يجوز شهر إفلاس التاجر بسبب توقفه عن دفع ما يستحق عليه من غرامات جنائية أو ضرائب أو رسوم أو تأمينات اجتماعية.$cc1113$
