INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1119$يجوز للمحكمة المختصة بنظر دعوى الإفلاس أن تأمر باتخاذ التدابير اللازمة للمحافظة على أموال المدين أو إدارتها إلى أن يتم الفصل في الدعوى، كما يجوز أن تتخذ من الإجراءات ما يمكنها من الإحاطة بحالة المدين المالية واسباب توقفه عن الدفع.$cc1119$, '1999-10-01', 'active' FROM ins_art_law17_1999_558;

WITH ins_art_law17_1999_559 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 559, $cc1120$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الأول: شهر الإفلاس$cc1120$, $cc1121$1- تختص بشهر الإفلاس المحكمة الابتدائية التي يقع في دائرتها موطن تجاري للمدين، فإذا لم يكن له موطن تجاري كانت المحكمة المختصة هي التي يقع في دائرتها محل إقامته المعتادة.
2- ومع عدم الإخلال بالاتفاقات الدولية الثنائية أو المتعددة الأطراف النافذة في مصر يجوز شهر إفلاس التاجر الذي له في مصر فرع أو وكالة ولو لم يصدر حكم بشهر إفلاسه في دولة أجنبية وفي هذه الحالة تكون المحكمة المختصة بشهر الإفلاس في مصر هي التي تقع في دائرتها الفرع أو الوكالة.$cc1121$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1121$1- تختص بشهر الإفلاس المحكمة الابتدائية التي يقع في دائرتها موطن تجاري للمدين، فإذا لم يكن له موطن تجاري كانت المحكمة المختصة هي التي يقع في دائرتها محل إقامته المعتادة.
2- ومع عدم الإخلال بالاتفاقات الدولية الثنائية أو المتعددة الأطراف النافذة في مصر يجوز شهر إفلاس التاجر الذي له في مصر فرع أو وكالة ولو لم يصدر حكم بشهر إفلاسه في دولة أجنبية وفي هذه الحالة تكون المحكمة المختصة بشهر الإفلاس في مصر هي التي تقع في دائرتها الفرع أو الوكالة.$cc1121$, '1999-10-01', 'active' FROM ins_art_law17_1999_559;

WITH ins_art_law17_1999_560 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 560, $cc1122$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الأول: شهر الإفلاس$cc1122$, $cc1123$1- تكون المحكمة التي شهرت الإفلاس مختصة بنظر جميع الدعاوى الناشئة عن التفليسة.
2- وتعتبر الدعوى ناشئة عن التفليسة على وجه الخصوص إذا كانت متعلقة بإدارتها أو كان الفصل فيها يقتضى تطبيق أحكام الإفلاس، ولا يشمل ذلك الدعاوى الناشئة عن الديون التي للتفليسة على الغير أو للغير عليها.$cc1123$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1123$1- تكون المحكمة التي شهرت الإفلاس مختصة بنظر جميع الدعاوى الناشئة عن التفليسة.
2- وتعتبر الدعوى ناشئة عن التفليسة على وجه الخصوص إذا كانت متعلقة بإدارتها أو كان الفصل فيها يقتضى تطبيق أحكام الإفلاس، ولا يشمل ذلك الدعاوى الناشئة عن الديون التي للتفليسة على الغير أو للغير عليها.$cc1123$, '1999-10-01', 'active' FROM ins_art_law17_1999_560;

WITH ins_art_law17_1999_561 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 561, $cc1124$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الأول: شهر الإفلاس$cc1124$, $cc1125$1- تحدد المحكمة في حكم شهر الإفلاس تاريخا مؤقتا للتوقف عن الدفع، وتعين أمينا للتفليسة، وتختار أحد قضاة المحكمة ليكون قاضيا للتفليسة. وتأمر بوضع الأختام على محل تجارة المدين.
2- وللمحكمة، عند الضرورة، أن تأمر باتخاذ الإجراءات اللازمة للتحفظ على شخص المدين، ولا يجوز للمحكمة أن تأمر بهذا الإجراء في حكم شهر الإفلاس إذا طلب المدين شهر إفلاسه خلال الميعاد المشار إليه في الفقرة الأولى من المادة 553 من هذا القانون.
3- ويرسل قلم كتاب المحكمة إلى النيابة العامة ملخصا من حكم شهر الإفلاس فور صدوره.$cc1125$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1125$1- تحدد المحكمة في حكم شهر الإفلاس تاريخا مؤقتا للتوقف عن الدفع، وتعين أمينا للتفليسة، وتختار أحد قضاة المحكمة ليكون قاضيا للتفليسة. وتأمر بوضع الأختام على محل تجارة المدين.
2- وللمحكمة، عند الضرورة، أن تأمر باتخاذ الإجراءات اللازمة للتحفظ على شخص المدين، ولا يجوز للمحكمة أن تأمر بهذا الإجراء في حكم شهر الإفلاس إذا طلب المدين شهر إفلاسه خلال الميعاد المشار إليه في الفقرة الأولى من المادة 553 من هذا القانون.
3- ويرسل قلم كتاب المحكمة إلى النيابة العامة ملخصا من حكم شهر الإفلاس فور صدوره.$cc1125$, '1999-10-01', 'active' FROM ins_art_law17_1999_561;

WITH ins_art_law17_1999_562 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 562, $cc1126$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الأول: شهر الإفلاس$cc1126$, $cc1127$1- إذا لم يعين في حكم شهر الإفلاس التاريخ الذي توقف فيه المدين عن الدفع اعتبر تاريخ صدور حكم شهر الإفلاس تاريخا مؤقتا للتوقف عن الدفع.
2- وإذا صدر حكم شهر الإفلاس بعد وفاة المدين أو بعد اعتزاله التجارة ولم يعين فيه تاريخ التوقف عن الدفع اعتبر تاريخ الوفاة أو اعتزال التجارة تاريخا مؤقتا للتوقف عن الدفع.
3- تستعين المحكمة في تعيين تاريخ التوقف عن الدفع بكل فعل أو قول أو تصرف يصدر من المدين ويكشف عن اضطراب أعماله أو سعيه إلى الاستمرار في نشاطه التجاري بوسائل غير مشروعة ضارة بدائنيه. ويدخل في ذلك على الخصوص شروع المدين في الهرب أو الانتحار، أو إخفاء أمواله أو بيعها بخسارة أو عقد قروض بشروط باهظة أو الدخول في مضاربات طائشة.$cc1127$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1127$1- إذا لم يعين في حكم شهر الإفلاس التاريخ الذي توقف فيه المدين عن الدفع اعتبر تاريخ صدور حكم شهر الإفلاس تاريخا مؤقتا للتوقف عن الدفع.
2- وإذا صدر حكم شهر الإفلاس بعد وفاة المدين أو بعد اعتزاله التجارة ولم يعين فيه تاريخ التوقف عن الدفع اعتبر تاريخ الوفاة أو اعتزال التجارة تاريخا مؤقتا للتوقف عن الدفع.
3- تستعين المحكمة في تعيين تاريخ التوقف عن الدفع بكل فعل أو قول أو تصرف يصدر من المدين ويكشف عن اضطراب أعماله أو سعيه إلى الاستمرار في نشاطه التجاري بوسائل غير مشروعة ضارة بدائنيه. ويدخل في ذلك على الخصوص شروع المدين في الهرب أو الانتحار، أو إخفاء أمواله أو بيعها بخسارة أو عقد قروض بشروط باهظة أو الدخول في مضاربات طائشة.$cc1127$, '1999-10-01', 'active' FROM ins_art_law17_1999_562;

WITH ins_art_law17_1999_563 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 563, $cc1128$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الأول: شهر الإفلاس$cc1128$, $cc1129$1- يجوز للمحكمة من تلقاء ذاتها، أو بناء على طلب النيابة العامة أو المدين أو أحد الدائنين أو أمين التفليسة أو غيرهم من ذوى المصلحة، تعديل التاريخ المؤقت للتوقف عن الدفع وذلك إلى انقضاء عشرة أيام من تاريخ إيداع قائمة الديون المحققة قلم كتاب المحكمة طبقا للفقرة الأولى من المادة 653 من هذا القانون وبعد انقضاء هذا الميعاد يصير التاريخ المعين للتوقف عن الدفع نهائيا.
2- وفي جميع الأحوال لا يجوز إرجاع تاريخ التوقف عن الدفع إلى اكثر من سنتين سابقتين على تاريخ صدور الحكم بشهر الإفلاس.$cc1129$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1129$1- يجوز للمحكمة من تلقاء ذاتها، أو بناء على طلب النيابة العامة أو المدين أو أحد الدائنين أو أمين التفليسة أو غيرهم من ذوى المصلحة، تعديل التاريخ المؤقت للتوقف عن الدفع وذلك إلى انقضاء عشرة أيام من تاريخ إيداع قائمة الديون المحققة قلم كتاب المحكمة طبقا للفقرة الأولى من المادة 653 من هذا القانون وبعد انقضاء هذا الميعاد يصير التاريخ المعين للتوقف عن الدفع نهائيا.
2- وفي جميع الأحوال لا يجوز إرجاع تاريخ التوقف عن الدفع إلى اكثر من سنتين سابقتين على تاريخ صدور الحكم بشهر الإفلاس.$cc1129$, '1999-10-01', 'active' FROM ins_art_law17_1999_563;

WITH ins_art_law17_1999_564 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 564, $cc1130$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الأول: شهر الإفلاس$cc1130$, $cc1131$1- يقوم قلم كتاب المحكمة التي أصدرت الحكم بشهر الإفلاس بإخطار أمين التفليسة فور صدور الحكم بكتاب مسجل بعلم الوصول بمباشرة أعمال التفليسة.
2- وعلى أمين التفليسة شهر الحكم وكذلك تعديل تاريخ التوقف عن الدفع بتعديل تاريخ التوقف عن الدفع في السجل التجاري.
3- ويتولى أمين التفليسة نشر ملخص الحكم في صحيفة يومية تعينها المحكمة في حكم شهر الإفلاس، ويجب أن يتم النشر خلال عشرة أيام من تاريخ إخطاره بالحكم ويشتمل الملخص المذكور فيما يتعلق بحكم شهر الإفلاس على اسم المفلس وموطنه ورقم قيده في السجل التجاري والمحكمة التي أصدرت الحكم وتاريخ صدوره والتاريخ المؤقت للتوقف عن الدفع واسم قاضي التفليسة. وفي حالة تعديل تاريخ التوقف عن الدفع فيشتمل النشر فضلا عن البيانات المذكورة على التاريخ الجديد الذي عينته المحكمة.
4- وعلى أمين التفليسة، خلال ثلاثين يوما من تاريخ إخطاره بحكم شهر الإفلاس، قيد ملخصه باسم جماعة الدائنين. في كل مكتب للشهر العقاري يوجد في دائرته عقار للمفلس، ولا يترتب على هذا القيد أي حق آخر لجماعة الدائنين.$cc1131$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1131$1- يقوم قلم كتاب المحكمة التي أصدرت الحكم بشهر الإفلاس بإخطار أمين التفليسة فور صدور الحكم بكتاب مسجل بعلم الوصول بمباشرة أعمال التفليسة.
2- وعلى أمين التفليسة شهر الحكم وكذلك تعديل تاريخ التوقف عن الدفع بتعديل تاريخ التوقف عن الدفع في السجل التجاري.
3- ويتولى أمين التفليسة نشر ملخص الحكم في صحيفة يومية تعينها المحكمة في حكم شهر الإفلاس، ويجب أن يتم النشر خلال عشرة أيام من تاريخ إخطاره بالحكم ويشتمل الملخص المذكور فيما يتعلق بحكم شهر الإفلاس على اسم المفلس وموطنه ورقم قيده في السجل التجاري والمحكمة التي أصدرت الحكم وتاريخ صدوره والتاريخ المؤقت للتوقف عن الدفع واسم قاضي التفليسة. وفي حالة تعديل تاريخ التوقف عن الدفع فيشتمل النشر فضلا عن البيانات المذكورة على التاريخ الجديد الذي عينته المحكمة.
4- وعلى أمين التفليسة، خلال ثلاثين يوما من تاريخ إخطاره بحكم شهر الإفلاس، قيد ملخصه باسم جماعة الدائنين. في كل مكتب للشهر العقاري يوجد في دائرته عقار للمفلس، ولا يترتب على هذا القيد أي حق آخر لجماعة الدائنين.$cc1131$, '1999-10-01', 'active' FROM ins_art_law17_1999_564;

WITH ins_art_law17_1999_565 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 565, $cc1132$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الأول: شهر الإفلاس$cc1132$, $cc1133$1- يجوز لكل ذي مصلحة من غير الخصوم أن يعترض على حكم شهر الإفلاس أمام المحكمة التي أصدرته خلال ثلاثين يوما من تاريخ نشره في الصحف، ما لم يكن قد طعن عليه بالاستئناف فيرفع الاعتراض إلى المحكمة التي تنظر الاستئناف.
2- ومع عدم الإخلال بأحكام الفقرة الأولى من المادة 563 من هذا القانون يكون ميعاد الاعتراض في جميع الأحكام الصادرة في الدعاوى الناشئة عن التفليسة ثلاثين يوما من تاريخ صدورها ما لم تكن واجبة الشهر فيسرى الميعاد من تاريخ شهرها.
3- ويسرى على ميعاد استئناف الحكم الصادر في دعوى شهر الإفلاس وغيره من الأحكام الصادرة في الدعاوى الناشئة عن التفليسة وطريقة رفعها أحكام قانون المرافعات المدنية والتجارية.$cc1133$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1133$1- يجوز لكل ذي مصلحة من غير الخصوم أن يعترض على حكم شهر الإفلاس أمام المحكمة التي أصدرته خلال ثلاثين يوما من تاريخ نشره في الصحف، ما لم يكن قد طعن عليه بالاستئناف فيرفع الاعتراض إلى المحكمة التي تنظر الاستئناف.
2- ومع عدم الإخلال بأحكام الفقرة الأولى من المادة 563 من هذا القانون يكون ميعاد الاعتراض في جميع الأحكام الصادرة في الدعاوى الناشئة عن التفليسة ثلاثين يوما من تاريخ صدورها ما لم تكن واجبة الشهر فيسرى الميعاد من تاريخ شهرها.
3- ويسرى على ميعاد استئناف الحكم الصادر في دعوى شهر الإفلاس وغيره من الأحكام الصادرة في الدعاوى الناشئة عن التفليسة وطريقة رفعها أحكام قانون المرافعات المدنية والتجارية.$cc1133$, '1999-10-01', 'active' FROM ins_art_law17_1999_565;

WITH ins_art_law17_1999_566 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 566, $cc1134$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الأول: شهر الإفلاس$cc1134$, $cc1135$تكون الأحكام الصادرة في دعاوى الإفلاس واجبة النفاذ المعجل بلا كفالة ما لم ينص على غير ذلك.$cc1135$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
