INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1135$تكون الأحكام الصادرة في دعاوى الإفلاس واجبة النفاذ المعجل بلا كفالة ما لم ينص على غير ذلك.$cc1135$, '1999-10-01', 'active' FROM ins_art_law17_1999_566;

WITH ins_art_law17_1999_567 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 567, $cc1136$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الأول: شهر الإفلاس$cc1136$, $cc1137$لا يجوز الطعن بأي طريق في:
(أ) الأحكام أو القرارات الخاصة بتعيين أو استبدال قاضي التفليسة أو امينها أو مراقبها.
(ب)الأحكام الصادرة في الطعن في قرارات قاضي التفليسة.
(ج) الأوامر الصادرة بإلغاء إجراءات المحافظة على شخص المفلس.
(د) الأحكام الصادرة بوقف إجراءات التفليسة إلى حين الفصل في الطعن في قرار قاضي التفليسة بشأن قبول الديون أو رفضها.
(ه) الأحكام الصادرة بشأن قبول الديون المتنازع فيها مؤقتا.$cc1137$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1137$لا يجوز الطعن بأي طريق في:
(أ) الأحكام أو القرارات الخاصة بتعيين أو استبدال قاضي التفليسة أو امينها أو مراقبها.
(ب)الأحكام الصادرة في الطعن في قرارات قاضي التفليسة.
(ج) الأوامر الصادرة بإلغاء إجراءات المحافظة على شخص المفلس.
(د) الأحكام الصادرة بوقف إجراءات التفليسة إلى حين الفصل في الطعن في قرار قاضي التفليسة بشأن قبول الديون أو رفضها.
(ه) الأحكام الصادرة بشأن قبول الديون المتنازع فيها مؤقتا.$cc1137$, '1999-10-01', 'active' FROM ins_art_law17_1999_567;

WITH ins_art_law17_1999_568 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 568, $cc1138$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الأول: شهر الإفلاس$cc1138$, $cc1139$إذا أوفى المدين جميع ما هو مستحق عليه من ديون تجارية قبل أن يحوز حكم شهر الإفلاس قوة الشيء المقضى به وجب أن تقضى بإلغاء حكم شهر الإفلاس على أن يتحمل المدين كافة مصاريف الدعوى.$cc1139$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1139$إذا أوفى المدين جميع ما هو مستحق عليه من ديون تجارية قبل أن يحوز حكم شهر الإفلاس قوة الشيء المقضى به وجب أن تقضى بإلغاء حكم شهر الإفلاس على أن يتحمل المدين كافة مصاريف الدعوى.$cc1139$, '1999-10-01', 'active' FROM ins_art_law17_1999_568;

WITH ins_art_law17_1999_569 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 569, $cc1140$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الأول: شهر الإفلاس$cc1140$, $cc1141$إذا لم توجد في التفليسة، وقت شهرها، نقود حاضرة لمواجهة شهر حكم الإفلاس ونشره أو وضع الأختام على أموال المفلس أو رفعها أو التحفظ على شخص المفلس وجب دفع هذه المصاريف من مبلغ الأمانة التي أودعها طالب شهر الإفلاس المبينة بالمادة 554/3 من هذا القانون ويسترد طالب شهر الإفلاس المبالغ التي دفعها على سبيل الامتياز على جميع الدائنين من أول نقود تدخل التفليسة، كما يجوز لقاضي التفليسة أن يأمر بالمبادرة ببيع بعض أموال التفليسة لمواجهة هذه المصاريف.$cc1141$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1141$إذا لم توجد في التفليسة، وقت شهرها، نقود حاضرة لمواجهة شهر حكم الإفلاس ونشره أو وضع الأختام على أموال المفلس أو رفعها أو التحفظ على شخص المفلس وجب دفع هذه المصاريف من مبلغ الأمانة التي أودعها طالب شهر الإفلاس المبينة بالمادة 554/3 من هذا القانون ويسترد طالب شهر الإفلاس المبالغ التي دفعها على سبيل الامتياز على جميع الدائنين من أول نقود تدخل التفليسة، كما يجوز لقاضي التفليسة أن يأمر بالمبادرة ببيع بعض أموال التفليسة لمواجهة هذه المصاريف.$cc1141$, '1999-10-01', 'active' FROM ins_art_law17_1999_569;

WITH ins_art_law17_1999_570 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 570, $cc1142$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الأول: شهر الإفلاس$cc1142$, $cc1143$1- إذا طلب المدين شهر إفلاسه وقضت المحكمة برفض الطلب جاز لها أن تحكم عليه بغرامة لا تقل عن ألف جنيه ولا تجاوز خمسة آلاف جنيه إذا تبين لها انه تعمد اصطناع الإفلاس.
2- وإذا طلب أحد الدائنين شهر الإفلاس وقضت المحكمة برفض الطلب جاز لها أن تحكم على الدائن بالغرامة المنصوص عليها في الفقرة السابقة وبنشر الحكم على نفقته في الصحف التي تعينها، إذا تبين لها انه تعمد الإساءة إلى سمعة المدين التجارية، وذلك مع عدم الإخلال بحق المدين في طلب التعويض.$cc1143$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1143$1- إذا طلب المدين شهر إفلاسه وقضت المحكمة برفض الطلب جاز لها أن تحكم عليه بغرامة لا تقل عن ألف جنيه ولا تجاوز خمسة آلاف جنيه إذا تبين لها انه تعمد اصطناع الإفلاس.
2- وإذا طلب أحد الدائنين شهر الإفلاس وقضت المحكمة برفض الطلب جاز لها أن تحكم على الدائن بالغرامة المنصوص عليها في الفقرة السابقة وبنشر الحكم على نفقته في الصحف التي تعينها، إذا تبين لها انه تعمد الإساءة إلى سمعة المدين التجارية، وذلك مع عدم الإخلال بحق المدين في طلب التعويض.$cc1143$, '1999-10-01', 'active' FROM ins_art_law17_1999_570;

WITH ins_art_law17_1999_571 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 571, $cc1144$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الثاني: الأشخاص الذين يديرون التفليسة$cc1144$, $cc1145$1- تعين المحكمة في حكم الإفلاس وكيلا لإدارة التفليسة يسمى "أمين التفليسة".
2- ويجوز في كل وقت لقاضي التفليسة من تلقاء نفسه أو بناء على طلب المفلس أو المراقب الأمر بإضافة أمين أو اكثر بشرط ألا يزيد عددهم على ثلاثة.
3- يصدر بتنظيم مهنة أمناء التفليسات قرار من الوزير المختص.$cc1145$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1145$1- تعين المحكمة في حكم الإفلاس وكيلا لإدارة التفليسة يسمى "أمين التفليسة".
2- ويجوز في كل وقت لقاضي التفليسة من تلقاء نفسه أو بناء على طلب المفلس أو المراقب الأمر بإضافة أمين أو اكثر بشرط ألا يزيد عددهم على ثلاثة.
3- يصدر بتنظيم مهنة أمناء التفليسات قرار من الوزير المختص.$cc1145$, '1999-10-01', 'active' FROM ins_art_law17_1999_571;

WITH ins_art_law17_1999_572 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 572, $cc1146$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الثاني: الأشخاص الذين يديرون التفليسة$cc1146$, $cc1147$1- لا يجوز أن يعين أمينا للتفليسة من كان زوجا للمفلس أو قريبا له إلى الدرجة الرابعة أو من كان خلال السنتين السابقتين على شهر الإفلاس شريكا له أو مستخدما عنده أو محاسبا له أو وكيلا عنه.
2- وكذلك لا يجوز أن يعين أمينا للتفليسة من سبق الحكم عليه بالإدانة في جناية أو في جنحة ماسة بالشرف والأمانة.$cc1147$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1147$1- لا يجوز أن يعين أمينا للتفليسة من كان زوجا للمفلس أو قريبا له إلى الدرجة الرابعة أو من كان خلال السنتين السابقتين على شهر الإفلاس شريكا له أو مستخدما عنده أو محاسبا له أو وكيلا عنه.
2- وكذلك لا يجوز أن يعين أمينا للتفليسة من سبق الحكم عليه بالإدانة في جناية أو في جنحة ماسة بالشرف والأمانة.$cc1147$, '1999-10-01', 'active' FROM ins_art_law17_1999_572;

WITH ins_art_law17_1999_573 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 573, $cc1148$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الثاني: الأشخاص الذين يديرون التفليسة$cc1148$, $cc1149$1- يقوم أمين التفليسة بإدارة أموال التفليسة والمحافظة عليها وينوب عن المفلس في جميع الدعاوى والأعمال التي تقتضيها هذه الإدارة.
2- يدون أمين التفليسة، يوما بيوم، جميع الأعمال المتعلقة بإدارة التفليسة في دفتر خاص ترقم صفحاته ويضع عليها قاضي التفليسة توقيعه أو ختمه ويؤشر في نهاية الدفتر بما يفيد انتهاءه.
3- ويجوز للمحكمة ولقاضي التفليسة وللمراقب الاطلاع على هذا الدفتر في كل وقت، وللمفلس أيضا الاطلاع عليه بإذن من قاضي التفليسة.$cc1149$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1149$1- يقوم أمين التفليسة بإدارة أموال التفليسة والمحافظة عليها وينوب عن المفلس في جميع الدعاوى والأعمال التي تقتضيها هذه الإدارة.
2- يدون أمين التفليسة، يوما بيوم، جميع الأعمال المتعلقة بإدارة التفليسة في دفتر خاص ترقم صفحاته ويضع عليها قاضي التفليسة توقيعه أو ختمه ويؤشر في نهاية الدفتر بما يفيد انتهاءه.
3- ويجوز للمحكمة ولقاضي التفليسة وللمراقب الاطلاع على هذا الدفتر في كل وقت، وللمفلس أيضا الاطلاع عليه بإذن من قاضي التفليسة.$cc1149$, '1999-10-01', 'active' FROM ins_art_law17_1999_573;

WITH ins_art_law17_1999_574 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 574, $cc1150$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الثاني: الأشخاص الذين يديرون التفليسة$cc1150$, $cc1151$1- إذا تعدد أمناء التفليسة وجب أن يعملوا مجتمعين ويسألون بالتضامن عن إدارتهم.
2- ويجوز لقاضي التفليسة أن يقسم العمل بينهم أو أن يعهد إلى أحدهم بعمل معين، وفي هذه الحالة لا يكون أمين التفليسة مسئولا إلا عن العمل الذي كلف به.
3- ويجوز لأمناء التفليسة أن ينيبوا بعضهم البعض في القيام بالأعمال المعهود بها إليهم، ولا يجوز لهم إنابة الغير إلا بإذن من قاضي التفليسة، وفي هذه الحالة يكون أمين التفليسة ونائبه مسئولين بالتضامن عن الأعمال المذكورة.$cc1151$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1151$1- إذا تعدد أمناء التفليسة وجب أن يعملوا مجتمعين ويسألون بالتضامن عن إدارتهم.
2- ويجوز لقاضي التفليسة أن يقسم العمل بينهم أو أن يعهد إلى أحدهم بعمل معين، وفي هذه الحالة لا يكون أمين التفليسة مسئولا إلا عن العمل الذي كلف به.
3- ويجوز لأمناء التفليسة أن ينيبوا بعضهم البعض في القيام بالأعمال المعهود بها إليهم، ولا يجوز لهم إنابة الغير إلا بإذن من قاضي التفليسة، وفي هذه الحالة يكون أمين التفليسة ونائبه مسئولين بالتضامن عن الأعمال المذكورة.$cc1151$, '1999-10-01', 'active' FROM ins_art_law17_1999_574;

WITH ins_art_law17_1999_575 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 575, $cc1152$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الثاني: الأشخاص الذين يديرون التفليسة$cc1152$, $cc1153$يجوز للمفلس وللمراقب الاعتراض لدى قاضي التفليسة على أعمال امينها قبل إتمامها، ويترتب على الاعتراض وقف إجراء العمل، ويجب أن يفصل قاضي التفليسة في الاعتراض خلال خمسة أيام من تاريخ تقديمه، ويكون قرار قاضي التفليسة واجب النفاذ فورا.$cc1153$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1153$يجوز للمفلس وللمراقب الاعتراض لدى قاضي التفليسة على أعمال امينها قبل إتمامها، ويترتب على الاعتراض وقف إجراء العمل، ويجب أن يفصل قاضي التفليسة في الاعتراض خلال خمسة أيام من تاريخ تقديمه، ويكون قرار قاضي التفليسة واجب النفاذ فورا.$cc1153$, '1999-10-01', 'active' FROM ins_art_law17_1999_575;

WITH ins_art_law17_1999_576 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 576, $cc1154$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الثاني: الأشخاص الذين يديرون التفليسة$cc1154$, $cc1155$يجوز للمحكمة، من تلقاء ذاتها أو بناء على طلب قاضي التفليسة أو المفلس أو المراقب، أن تأمر بعزل أمين التفليسة وتعيين غيره أو بإنقاص عدد الأمناء إذا تعددوا.$cc1155$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1155$يجوز للمحكمة، من تلقاء ذاتها أو بناء على طلب قاضي التفليسة أو المفلس أو المراقب، أن تأمر بعزل أمين التفليسة وتعيين غيره أو بإنقاص عدد الأمناء إذا تعددوا.$cc1155$, '1999-10-01', 'active' FROM ins_art_law17_1999_576;

WITH ins_art_law17_1999_577 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 577, $cc1156$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الثاني: الأشخاص الذين يديرون التفليسة$cc1156$, $cc1157$1- تقدر أتعاب ومصاريف أمين التفليسة بقرار من قاضي التفليسة بعد أن يقدم الأمين تقريرا عن إدارته.
2- ويجوز لقاضي التفليسة أن يأمر بصرف مبالغ لأمين التفليسة قبل تقديم التقرير المذكور في الفقرة السابقة خصما من أتعابه.
3- ويجوز لكل ذي شأن الطعن أمام المحكمة في قرار قاضي التفليسة الخاص بتقدير أتعاب أمين التفليسة ومصاريفه.$cc1157$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1157$1- تقدر أتعاب ومصاريف أمين التفليسة بقرار من قاضي التفليسة بعد أن يقدم الأمين تقريرا عن إدارته.
2- ويجوز لقاضي التفليسة أن يأمر بصرف مبالغ لأمين التفليسة قبل تقديم التقرير المذكور في الفقرة السابقة خصما من أتعابه.
3- ويجوز لكل ذي شأن الطعن أمام المحكمة في قرار قاضي التفليسة الخاص بتقدير أتعاب أمين التفليسة ومصاريفه.$cc1157$, '1999-10-01', 'active' FROM ins_art_law17_1999_577;

WITH ins_art_law17_1999_578 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 578, $cc1158$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الثاني: الأشخاص الذين يديرون التفليسة$cc1158$, $cc1159$1- يتولى قاضي التفليسة بالإضافة إلى السلطات المقررة بنصوص خاصة مراقبة إدارة التفليسة وملاحظة سير إجراءاتها والأمر باتخاذ التدابير اللازمة للمحافظة على أموالها.
2- ويدعو الدائنين إلى الاجتماع في الأحوال المبينة في القانون ويتولى رئاسة الاجتماعات.
3- ويقدم للمحكمة كل ثلاثة اشهر تقريرا عن حالة التفليسة، كما يقدم لها تقريرا عن كل نزاع يتعلق بالتفليسة ويكون من اختصاصها الفصل فيه.
4- وله في كل وقت استدعاء المفلس أو ورثته أو وكلائه أو مستخدميه أو أي شخص آخر لسماع أقوالهم في شئون التفليسة.$cc1159$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1159$1- يتولى قاضي التفليسة بالإضافة إلى السلطات المقررة بنصوص خاصة مراقبة إدارة التفليسة وملاحظة سير إجراءاتها والأمر باتخاذ التدابير اللازمة للمحافظة على أموالها.
2- ويدعو الدائنين إلى الاجتماع في الأحوال المبينة في القانون ويتولى رئاسة الاجتماعات.
3- ويقدم للمحكمة كل ثلاثة اشهر تقريرا عن حالة التفليسة، كما يقدم لها تقريرا عن كل نزاع يتعلق بالتفليسة ويكون من اختصاصها الفصل فيه.
4- وله في كل وقت استدعاء المفلس أو ورثته أو وكلائه أو مستخدميه أو أي شخص آخر لسماع أقوالهم في شئون التفليسة.$cc1159$, '1999-10-01', 'active' FROM ins_art_law17_1999_578;

WITH ins_art_law17_1999_579 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 579, $cc1160$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الثاني: الأشخاص الذين يديرون التفليسة$cc1160$, $cc1161$تودع القرارات التي يصدرها قاضي التفليسة قلم كتاب المحكمة في اليوم التالي لصدورها، وللقاضي أن يأمر قلم الكتاب بتبليغها إلى الأشخاص الذين تعينهم، ويكون التبليغ بكتاب مسجل بعلم الوصول، إلا إذا نص القانون أو أمر قاضي التفليسة بتبليغها بطريقة أخرى.$cc1161$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1161$تودع القرارات التي يصدرها قاضي التفليسة قلم كتاب المحكمة في اليوم التالي لصدورها، وللقاضي أن يأمر قلم الكتاب بتبليغها إلى الأشخاص الذين تعينهم، ويكون التبليغ بكتاب مسجل بعلم الوصول، إلا إذا نص القانون أو أمر قاضي التفليسة بتبليغها بطريقة أخرى.$cc1161$, '1999-10-01', 'active' FROM ins_art_law17_1999_579;

WITH ins_art_law17_1999_580 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 580, $cc1162$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الثاني: الأشخاص الذين يديرون التفليسة$cc1162$, $cc1163$1- لا يجوز الطعن في القرارات التي يصدرها قاضي التفليسة ما لم ينص القانون على غير ذلك أو كان القرار مما يجاوز اختصاصه.
2- يقدم الطعن بصحيفة تودع قلم كتاب المحكمة وتعلن لذوى الشأن خلال عشرة أيام من تاريخ الإيداع أو التبليغ على حسب الأحوال، وتنظره المحكمة في أول جلسة، على ألا يشترك قاضي التفليسة المطعون في قراره في نظر هذا الطعن، ويوقف الطعن تنفيذ القرار حتى تفصل المحكمة في أمره ما لم تأمر باستمرار تنفيذه.
3- إذا رفضت المحكمة الطعن جاز لها أن تحكم على الطاعن بغرامة لا تقل عن خمسمائة جنيه ولا تجاوز ألفى جنيه إذا تبين لها انه تعمد تعطيل تنفيذ قرار قاضي التفليسة.$cc1163$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1163$1- لا يجوز الطعن في القرارات التي يصدرها قاضي التفليسة ما لم ينص القانون على غير ذلك أو كان القرار مما يجاوز اختصاصه.
2- يقدم الطعن بصحيفة تودع قلم كتاب المحكمة وتعلن لذوى الشأن خلال عشرة أيام من تاريخ الإيداع أو التبليغ على حسب الأحوال، وتنظره المحكمة في أول جلسة، على ألا يشترك قاضي التفليسة المطعون في قراره في نظر هذا الطعن، ويوقف الطعن تنفيذ القرار حتى تفصل المحكمة في أمره ما لم تأمر باستمرار تنفيذه.
3- إذا رفضت المحكمة الطعن جاز لها أن تحكم على الطاعن بغرامة لا تقل عن خمسمائة جنيه ولا تجاوز ألفى جنيه إذا تبين لها انه تعمد تعطيل تنفيذ قرار قاضي التفليسة.$cc1163$, '1999-10-01', 'active' FROM ins_art_law17_1999_580;

WITH ins_art_law17_1999_581 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 581, $cc1164$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الثاني: الأشخاص الذين يديرون التفليسة$cc1164$, $cc1165$1- للمحكمة في كل وقت، أن تستبدل بقاضي التفليسة غيره من قضاة المحكمة.
2- وفي حالة الغياب المؤقت يعين رئيس المحكمة أحد قضاتها لينوب عن قاضي التفليسة.$cc1165$
