WITH ins_art_law17_1999_584 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 584, $cc1170$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الثاني: الأشخاص الذين يديرون التفليسة$cc1170$, $cc1171$1- يقوم المراقب، بالإضافة إلى السلطات المقررة له، بنصوص خاصة بفحص الميزانية والتقرير المقدمين من المدين وغير ذلك من المهام التي يكلفه بها قاضي التفليسة في شأن الرقابة على أعمال أمينها، ومعاونة قاضي التفليسة في ذلك.
2- وللمراقب أن يطلب من أمين التفليسة إيضاحات عن سير إجراءاتها وعن إيراداتها ومصروفاتها وحالة الدعاوى المتعلقة بها.$cc1171$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1171$1- يقوم المراقب، بالإضافة إلى السلطات المقررة له، بنصوص خاصة بفحص الميزانية والتقرير المقدمين من المدين وغير ذلك من المهام التي يكلفه بها قاضي التفليسة في شأن الرقابة على أعمال أمينها، ومعاونة قاضي التفليسة في ذلك.
2- وللمراقب أن يطلب من أمين التفليسة إيضاحات عن سير إجراءاتها وعن إيراداتها ومصروفاتها وحالة الدعاوى المتعلقة بها.$cc1171$, '1999-10-01', 'active' FROM ins_art_law17_1999_584;

WITH ins_art_law17_1999_585 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 585, $cc1172$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الثاني: الأشخاص الذين يديرون التفليسة$cc1172$, $cc1173$1- لا يتقاضى المراقب أجرا نظير عمله، ومع ذلك يجوز للمحكمة أن تقرر له مكافأة إجمالية على عمله إذا بذل جهدا غير عادي وكانت الحالة المالية للتفليسة تسمح بذلك.
2- ويجوز عزل المراقب بقرار من قاضي التفليسة.
3- ولا يسأل المراقب إلا عن خطئه الجسيم.$cc1173$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
