2- ومع ذلك إذا كان المفلس حاملا لورقة تجارية جاز الوفاء له بقيمتها عند حلول ميعاد استحقاقها إلا إذا عارض أمين التفليسة في هذا الوفاء طبقا للمادة 431 من هذا القانون.$cc1183$
