SELECT id, 1, $cc1189$إذا آلت إلى المفلس تركة فلا يكون لدائنيه حق على أموالها إلا بعد أن يستوفى دائنو المورث حقوقهم من هذه الأموال، ولا يكون لدائني المورث أي حق على أموال التفليسة.$cc1189$, '1999-10-01', 'active' FROM ins_art_law17_1999_593;

WITH ins_art_law17_1999_594 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 594, $cc1190$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الثالث: آثار الإفلاس$cc1190$, $cc1191$1- لا يجوز بعد صدور حكم شهر الإفلاس رفع دعوى من المفلس أو عليه أو السير أو السير فيها مع استثناء ما يأتي:
(أ) الدعاوى المتعلقة بالأموال والتصرفات التي لا يشملها غل اليد.
(ب)الدعاوى المتعلقة بأعمال التفليسة التي يجيز القانون للمفلس القيام بها.
(ت)الدعاوى الجنائية.
2- يجوز للمحكمة أن تأذن بإدخال المفلس في الدعاوى المتعلقة بالتفليسة، كما يجوز لها أن تأذن بإدخال الدائن في هذه الدعاوى إذا كانت له مصلحة خاصة فيها.
3- إذا رفع المفلس أو رفعت عليه دعوى جنائية أو دعوى متعلقة بشخصه أو بأحواله الشخصية وجب إدخال أمين التفليسة فيها إذا اشتملت على طلبات مالية.$cc1191$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
