WITH ins_art_law17_1999_596 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 596, $cc1194$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الثالث: آثار الإفلاس$cc1194$, $cc1195$1- يجوز لقاضي التفليسة بعد سماع أقوال أمينها أن يقرر إعانة للمفلس تصرف من أموال التفليسة بناء على طلبه أو طلب من يعولهم.
2- لمن طلب الإعانة ولامين التفليسة التظلم من تقديرها أمام قاضي التفليسة دون أن يترتب على ذلك وقف صرف الإعانة.
3- يجوز في كل وقت لقاضي التفليسة من تلقاء ذاته أو بناء على طلب من أمين التفليسة أن يعدل مقدار الإعانة أو أن يأمر بإلغائها، ويجوز التظلم من هذا القرار أمام قاضي التفليسة نفسه.
4- يوقف صرف الإعانة متى حاز حكم التصديق على الصلح قوة الشيء المقضى، وإذا لم يقع الصلح يوقف صرف الإعانة بمجرد قيام حالة الاتحاد.$cc1195$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1195$1- يجوز لقاضي التفليسة بعد سماع أقوال أمينها أن يقرر إعانة للمفلس تصرف من أموال التفليسة بناء على طلبه أو طلب من يعولهم.
2- لمن طلب الإعانة ولامين التفليسة التظلم من تقديرها أمام قاضي التفليسة دون أن يترتب على ذلك وقف صرف الإعانة.
3- يجوز في كل وقت لقاضي التفليسة من تلقاء ذاته أو بناء على طلب من أمين التفليسة أن يعدل مقدار الإعانة أو أن يأمر بإلغائها، ويجوز التظلم من هذا القرار أمام قاضي التفليسة نفسه.
4- يوقف صرف الإعانة متى حاز حكم التصديق على الصلح قوة الشيء المقضى، وإذا لم يقع الصلح يوقف صرف الإعانة بمجرد قيام حالة الاتحاد.$cc1195$, '1999-10-01', 'active' FROM ins_art_law17_1999_596;

WITH ins_art_law17_1999_597 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 597, $cc1196$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الثالث: آثار الإفلاس$cc1196$, $cc1197$مع مراعاة حكم المادة 588 من هذا القانون يجوز للمفلس بدون إذن، أن يمارس تجارة جديدة بغير أموال التفليسة ويكون للدائنين الذين تنشأ ديونهم بمناسبة هذه التجارة الأولوية في استيفاء حقوقهم من أموالها.$cc1197$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1197$مع مراعاة حكم المادة 588 من هذا القانون يجوز للمفلس بدون إذن، أن يمارس تجارة جديدة بغير أموال التفليسة ويكون للدائنين الذين تنشأ ديونهم بمناسبة هذه التجارة الأولوية في استيفاء حقوقهم من أموالها.$cc1197$, '1999-10-01', 'active' FROM ins_art_law17_1999_597;

WITH ins_art_law17_1999_598 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 598, $cc1198$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الثالث: آثار الإفلاس$cc1198$, $cc1199$لا يجوز التمسك في مواجهة جماعة الدائنين بالتصرفات التالية إذا قام بها المدين بعد تاريخ التوقف عن الدفع وقبل الحكم بشهر الإفلاس:-
(أ) منح التبرعات أيا كان نوعها ما عدا الهدايا الصغيرة التي يجرى عليها العرف.
(ب)وفاء الديون قبل حلول الأجل أيا كانت كيفية الوفاء، ويعتبر إنشاء مقابل وفاء ورقة تجارية لم يحل ميعاد استحقاقها في حكم الوفاء قبل حلول الأجل.
(ج)وفاء الديون الحالة بغير الشيء المتفق عليه، ويعتبر الوفاء بطريق الأوراق التجارية أو النقل المصرفي في حكم الوفاء بالنقود.
(د) كل رهن أو تأمين اتفاقي آخر وكذلك كل اختصاص يتقرر على أموال المدين ضمانا لدين سابق على التأمين.$cc1199$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
