SELECT id, 1, $cc1199$لا يجوز التمسك في مواجهة جماعة الدائنين بالتصرفات التالية إذا قام بها المدين بعد تاريخ التوقف عن الدفع وقبل الحكم بشهر الإفلاس:-
(أ) منح التبرعات أيا كان نوعها ما عدا الهدايا الصغيرة التي يجرى عليها العرف.
(ب)وفاء الديون قبل حلول الأجل أيا كانت كيفية الوفاء، ويعتبر إنشاء مقابل وفاء ورقة تجارية لم يحل ميعاد استحقاقها في حكم الوفاء قبل حلول الأجل.
(ج)وفاء الديون الحالة بغير الشيء المتفق عليه، ويعتبر الوفاء بطريق الأوراق التجارية أو النقل المصرفي في حكم الوفاء بالنقود.
(د) كل رهن أو تأمين اتفاقي آخر وكذلك كل اختصاص يتقرر على أموال المدين ضمانا لدين سابق على التأمين.$cc1199$, '1999-10-01', 'active' FROM ins_art_law17_1999_598;

WITH ins_art_law17_1999_599 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 599, $cc1200$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الثالث: آثار الإفلاس$cc1200$, $cc1201$كل ما أجراه المفلس من تصرفات غير ما ذكر في المادة 598 من هذا القانون وخلال الفترة المشار إليها يجوز الحكم بعدم نفاذه في مواجهة جماعة الدائنين اذا كان التصرف ضارا بها وكان المتصرف إليه يعلم وقت وقوع التصرف بتوقف المفلس عن الدفع.$cc1201$
