INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1211$تسقط الدعاوى الناشئة عن تطبيق الأحكام المنصوص عليها في المواد 598 إلى 601 والمادة 603 من هذا القانون بمضي سنتين من تاريخ صدور الحكم بشهر الإفلاس.
2- آثار الإفلاس بالنسبة إلى الدائنين$cc1211$, '1999-10-01', 'active' FROM ins_art_law17_1999_604;

WITH ins_art_law17_1999_605 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 605, $cc1212$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الثالث: آثار الإفلاس$cc1212$, $cc1213$1- لا يجوز للدائنين العاديين أو الدائنين أصحاب حقوق الامتياز العامة بعد صدور حكم شهر الإفلاس إقامة دعاوى فردية على التفليسة أو اتخاذ أية إجراءات قضائية أخرى ضدها.
2- وكذلك يترتب على صدور حكم شهر الإفلاس وقف الدعاوى الفردية المقامة من الدائنين المذكورين في الفقرة السابقة ووقف إجراءات التنفيذ التي بدأها هؤلاء الدائنون قبل صدور حكم شهر الإفلاس ومع ذلك إذا تحدد يوم لبيع عقار المفلس جاز الاستمرار في إجراءات التنفيذ بإذن من قاضي التفليسة.
3- أما الدائنون المرتهنون واصحاب حقوق الامتياز الخاصة والحاصلون على اختصاص على أموال المدين فيجوز لهم إقامة الدعاوى الفردية في مواجهة أمين التفليسة أو الاستمرار فيها كما يجوز لهم التنفيذ او الاستمرار على الأموال التي تقع عليها تأميناتهم.$cc1213$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1213$1- لا يجوز للدائنين العاديين أو الدائنين أصحاب حقوق الامتياز العامة بعد صدور حكم شهر الإفلاس إقامة دعاوى فردية على التفليسة أو اتخاذ أية إجراءات قضائية أخرى ضدها.
2- وكذلك يترتب على صدور حكم شهر الإفلاس وقف الدعاوى الفردية المقامة من الدائنين المذكورين في الفقرة السابقة ووقف إجراءات التنفيذ التي بدأها هؤلاء الدائنون قبل صدور حكم شهر الإفلاس ومع ذلك إذا تحدد يوم لبيع عقار المفلس جاز الاستمرار في إجراءات التنفيذ بإذن من قاضي التفليسة.
3- أما الدائنون المرتهنون واصحاب حقوق الامتياز الخاصة والحاصلون على اختصاص على أموال المدين فيجوز لهم إقامة الدعاوى الفردية في مواجهة أمين التفليسة أو الاستمرار فيها كما يجوز لهم التنفيذ او الاستمرار على الأموال التي تقع عليها تأميناتهم.$cc1213$, '1999-10-01', 'active' FROM ins_art_law17_1999_605;

