SELECT id, 1, $cc1225$إذا استوفى الدائن من أحد الملتزمين بدين واحد جزءا من الدين ثم أفلس باقي الملتزمين أو أفلس أحدهم فلا يجوز للدائن أن يشترك في التفليسات إلا بالباقي من دينه ويبقى محتفظا بحقه في مطالبة الملتزم غير المفلس بهذا الباقي، ويجوز لهذا الملتزم أن يشترك لهذا الملتزم أن يشترك في كل تفليسة بما وفاه عنها.$cc1225$, '1999-10-01', 'active' FROM ins_art_law17_1999_611;

WITH ins_art_law17_1999_612 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 612, $cc1226$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الثالث: آثار الإفلاس$cc1226$, $cc1227$1- إذا أفلس جميع الملتزمين بدين واحد دفعة واحدة، جاز للدائن أن يشترك في كل تفليسة بكل دينه إلى أن يستوفيه بتمامه، من اصل وعوائد ومصاريف.
2- ولا يجوز لتفليسة الرجوع على تفليسة أخرى بما أوفته عنها.
3- وإذا كان مجموع ما حصل عليه الدائن يزيد على دينه وتوابعه عادت الزيادة إلى تفليسة من يكون مكفولا من الآخرين بحسب ترتيب التزاماتهم بالدين فإذا لم يوجد هذا الترتيب عادت الزيادة إلى التفليسات التي دفعت اكثر من حصتها في الدين.
3- آثار الإفلاس بالنسبة إلى أصحاب الديون المضمونة برهن أو امتياز على منقول$cc1227$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
