WITH ins_art_law17_1999_620 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 620, $cc1242$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الثالث: آثار الإفلاس$cc1242$, $cc1243$إذا حصل توزيع ثمن العقارات قبل توزيع ثمن المنقولات أو حصل التوزيعان معا كان للدائنين المرتهنين أو الممتازين أو الحاصلين على اختصاص الذين لم يستوفوا حقوقهم كلها أو بعضها من ثمن العقارات المحملة بالتأمين أن يشتركوا بالباقي مع الدائنين العاديين في توزيع الأموال التي يتعلق بها حق جماعة الدائنين بشرط أن تكون ديونهم قد حققت طبقا لاحكام هذا القانون.$cc1243$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1243$إذا حصل توزيع ثمن العقارات قبل توزيع ثمن المنقولات أو حصل التوزيعان معا كان للدائنين المرتهنين أو الممتازين أو الحاصلين على اختصاص الذين لم يستوفوا حقوقهم كلها أو بعضها من ثمن العقارات المحملة بالتأمين أن يشتركوا بالباقي مع الدائنين العاديين في توزيع الأموال التي يتعلق بها حق جماعة الدائنين بشرط أن تكون ديونهم قد حققت طبقا لاحكام هذا القانون.$cc1243$, '1999-10-01', 'active' FROM ins_art_law17_1999_620;

WITH ins_art_law17_1999_621 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 621, $cc1244$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الثالث: آثار الإفلاس$cc1244$, $cc1245$1- إذا أجرى توزيع واحد أو اكثر لثمن المنقولات قبل توزيع ثمن العقارات كان للدائنين المرتهنين أو الممتازين أو الحاصلين على اختصاص أن يشتركوا في التوزيعات بكل ديونهم بشرط أن تكون قد حققت طبقا لاحكام هذا القانون، ويجنب نصيبهم في هذه التوزيعات إلى حين إجراء التسوية النهائية.
2- وبعد بيع العقارات وإجراء التسوية النهائية بحسب مراتب الدائنين المرتهنين والممتازين واصحاب حقوق الاختصاص لا يجوز لمن تؤهله مرتبته للحصول على كل دينه من ثمن العقارات المذكورة، قبض الدين إلا بعد استنزال المقدار الذي جنب له، ويرد هذا المقدار إلى جماعة الدائنين العاديين.
3- وإذا كانت مرتبة الدائن المرتهن أو الممتاز أو صاحب حق الاختصاص لا تؤهله إلا للحصول على جزء من دينه كان من حقه الاشتراك في قسمة الغرماء بالباقي له من الدين، وإذا تبين عند التسوية النهائية أن ما حصل عليه وما جنب لحسابه يزيد على مقدار دينه وجب استنزال الجزء الزائد ورده إلى جماعة الدائنين العاديين.$cc1245$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1245$1- إذا أجرى توزيع واحد أو اكثر لثمن المنقولات قبل توزيع ثمن العقارات كان للدائنين المرتهنين أو الممتازين أو الحاصلين على اختصاص أن يشتركوا في التوزيعات بكل ديونهم بشرط أن تكون قد حققت طبقا لاحكام هذا القانون، ويجنب نصيبهم في هذه التوزيعات إلى حين إجراء التسوية النهائية.
2- وبعد بيع العقارات وإجراء التسوية النهائية بحسب مراتب الدائنين المرتهنين والممتازين واصحاب حقوق الاختصاص لا يجوز لمن تؤهله مرتبته للحصول على كل دينه من ثمن العقارات المذكورة، قبض الدين إلا بعد استنزال المقدار الذي جنب له، ويرد هذا المقدار إلى جماعة الدائنين العاديين.
3- وإذا كانت مرتبة الدائن المرتهن أو الممتاز أو صاحب حق الاختصاص لا تؤهله إلا للحصول على جزء من دينه كان من حقه الاشتراك في قسمة الغرماء بالباقي له من الدين، وإذا تبين عند التسوية النهائية أن ما حصل عليه وما جنب لحسابه يزيد على مقدار دينه وجب استنزال الجزء الزائد ورده إلى جماعة الدائنين العاديين.$cc1245$, '1999-10-01', 'active' FROM ins_art_law17_1999_621;

WITH ins_art_law17_1999_622 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 622, $cc1246$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الثالث: آثار الإفلاس$cc1246$, $cc1247$الدائنون المرتهنون أو الممتازون أو أصحاب حقوق الاختصاص الذين لا يحصلون على شئ من ثمن العقارات التي تقع عليها تأميناتهم يعتبرون دائنين عاديين وتسرى عليهم بهذه الصفة جميع الآثار الناشئة عن أعمال جماعة الدائنين وعن الصلح القضائي إن وقع.
5- أثر الإفلاس في العقود الصحيحة المبرمة قبل شهره$cc1247$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1247$الدائنون المرتهنون أو الممتازون أو أصحاب حقوق الاختصاص الذين لا يحصلون على شئ من ثمن العقارات التي تقع عليها تأميناتهم يعتبرون دائنين عاديين وتسرى عليهم بهذه الصفة جميع الآثار الناشئة عن أعمال جماعة الدائنين وعن الصلح القضائي إن وقع.
5- أثر الإفلاس في العقود الصحيحة المبرمة قبل شهره$cc1247$, '1999-10-01', 'active' FROM ins_art_law17_1999_622;

WITH ins_art_law17_1999_623 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 623, $cc1248$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الثالث: آثار الإفلاس$cc1248$, $cc1249$1- لا يترتب على الحكم بشهر الإفلاس فسخ العقود الملزمة للجانبين التي يكون المفلس طرفا فيها إلا إذا كانت قائمة على اعتبارات شخصية.
2- وإذا لم ينفذ أمين التفليسة العقد أو لم يستمر في تنفيذه جاز للطرف الآخر أن يطلب الفسخ، وكل قرار يتخذه أمين التفليسة بشأن العقد يجب أن يعرض على قاضي التفليسة ليأذن به، ويجوز للطرف الآخر أن يعين لأمين التفليسة مهلة مناسبة لإيضاح موقفه من العقد.
3- وللمتعاقد الاشتراك في التفليسة كدائن عادي بالتعويض المترتب على الفسخ الا اذا نص على احتفاظ التعويض بالامتياز المقرر له قانونا.$cc1249$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1249$1- لا يترتب على الحكم بشهر الإفلاس فسخ العقود الملزمة للجانبين التي يكون المفلس طرفا فيها إلا إذا كانت قائمة على اعتبارات شخصية.
2- وإذا لم ينفذ أمين التفليسة العقد أو لم يستمر في تنفيذه جاز للطرف الآخر أن يطلب الفسخ، وكل قرار يتخذه أمين التفليسة بشأن العقد يجب أن يعرض على قاضي التفليسة ليأذن به، ويجوز للطرف الآخر أن يعين لأمين التفليسة مهلة مناسبة لإيضاح موقفه من العقد.
3- وللمتعاقد الاشتراك في التفليسة كدائن عادي بالتعويض المترتب على الفسخ الا اذا نص على احتفاظ التعويض بالامتياز المقرر له قانونا.$cc1249$, '1999-10-01', 'active' FROM ins_art_law17_1999_623;

WITH ins_art_law17_1999_624 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 624, $cc1250$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الثالث: آثار الإفلاس$cc1250$, $cc1251$1- إذا كان المفلس مستأجرا للعقار الذي يمارس فيه التجارة فلا يترتب على صدور الحكم بشهر الإفلاس إنهاء الإجارة أو حلول الأجرة عن المدة المتبقية لانقضائها، وكل شرط على خلاف ذلك يعتبر كأن لم يكن.
2- وإذا كان المؤجر قد بدأ في التنفيذ على المنقولات الموجودة في العقار ولم يكن التنفيذ قد تم عند صدور الحكم بشهر الإفلاس وجب وقف التنفيذ لمدة ستين يوما من تاريخ هذا الحكم مع عدم الإخلال بحق المؤجر في اتخاذ الإجراءات التحفظية وفي طلب إخلاء العقار وفقا للقواعد العامة، ويجوز لقاضي التفليسة أن يأمر باستمرار وقف التنفيذ برغبته في إنهاء الإجارة أو الاستمرار فيها.
3- وإذا قرر أمين التفليسة الاستمرار في الإجارة وجب أن يدفع الأجرة المتأخرة وان يقدم ضمانا كافيا للوفاء بالأجرة المستقبلة، ويجوز للمؤجر أن يطلب من قاضي التفليسة إنهاء الإجارة إذا كان الضمان غير كاف وذلك خلال خمسة عشر يوما من تاريخ إخطاره برغبة أمين التفليسة في الاستمرار في الإجارة.
4- ولأمين التفليسة بعد الحصول على إذن من قاضي التفليسة تأجير العقار من الباطن او التنازل عن الإيجار وفقا للأحكام المنظمة للعلاقة بين المالك والمستأجر ولو كان المفلس ممنوعا من ذلك بمقتضى عقد الإيجار بشرط ألا يترتب على ذلك ضرر للمؤجر.$cc1251$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1251$1- إذا كان المفلس مستأجرا للعقار الذي يمارس فيه التجارة فلا يترتب على صدور الحكم بشهر الإفلاس إنهاء الإجارة أو حلول الأجرة عن المدة المتبقية لانقضائها، وكل شرط على خلاف ذلك يعتبر كأن لم يكن.
2- وإذا كان المؤجر قد بدأ في التنفيذ على المنقولات الموجودة في العقار ولم يكن التنفيذ قد تم عند صدور الحكم بشهر الإفلاس وجب وقف التنفيذ لمدة ستين يوما من تاريخ هذا الحكم مع عدم الإخلال بحق المؤجر في اتخاذ الإجراءات التحفظية وفي طلب إخلاء العقار وفقا للقواعد العامة، ويجوز لقاضي التفليسة أن يأمر باستمرار وقف التنفيذ برغبته في إنهاء الإجارة أو الاستمرار فيها.
3- وإذا قرر أمين التفليسة الاستمرار في الإجارة وجب أن يدفع الأجرة المتأخرة وان يقدم ضمانا كافيا للوفاء بالأجرة المستقبلة، ويجوز للمؤجر أن يطلب من قاضي التفليسة إنهاء الإجارة إذا كان الضمان غير كاف وذلك خلال خمسة عشر يوما من تاريخ إخطاره برغبة أمين التفليسة في الاستمرار في الإجارة.
4- ولأمين التفليسة بعد الحصول على إذن من قاضي التفليسة تأجير العقار من الباطن او التنازل عن الإيجار وفقا للأحكام المنظمة للعلاقة بين المالك والمستأجر ولو كان المفلس ممنوعا من ذلك بمقتضى عقد الإيجار بشرط ألا يترتب على ذلك ضرر للمؤجر.$cc1251$, '1999-10-01', 'active' FROM ins_art_law17_1999_624;

WITH ins_art_law17_1999_625 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 625, $cc1252$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الثالث: آثار الإفلاس$cc1252$, $cc1253$1- إذا أفلس رب العمل وكان عقد العمل غير محدد المدة جاز للعامل ولامين التفليسة إنهاء العقد مع مراعاة الأحكام المنصوص عليها في قوانين العمل.
ولا يجوز للعامل في هذه الحالة مطالبة التفليسة بالتعويض إلا إذا كان الإنهاء تعسفيا أو بغير مراعاة مواعيد الإخطار.
2- وإذا كان عقد العمل محدد المدة فلا يجوز إنهاؤه إلا إذا تقرر عدم الاستمرار في التجارة، ويجوز للعامل في هذه الحالة مطالبة التفليسة بالتعويض.
3- يكون للتعويض المستحق للعامل وفقا للفقرتين السابقتين الامتياز المقرر له قانونا.
6- الاسترداد$cc1253$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1253$1- إذا أفلس رب العمل وكان عقد العمل غير محدد المدة جاز للعامل ولامين التفليسة إنهاء العقد مع مراعاة الأحكام المنصوص عليها في قوانين العمل.
ولا يجوز للعامل في هذه الحالة مطالبة التفليسة بالتعويض إلا إذا كان الإنهاء تعسفيا أو بغير مراعاة مواعيد الإخطار.
2- وإذا كان عقد العمل محدد المدة فلا يجوز إنهاؤه إلا إذا تقرر عدم الاستمرار في التجارة، ويجوز للعامل في هذه الحالة مطالبة التفليسة بالتعويض.
3- يكون للتعويض المستحق للعامل وفقا للفقرتين السابقتين الامتياز المقرر له قانونا.
6- الاسترداد$cc1253$, '1999-10-01', 'active' FROM ins_art_law17_1999_625;

WITH ins_art_law17_1999_626 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 626, $cc1254$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الثالث: آثار الإفلاس$cc1254$, $cc1255$1- لكل شخص أن يسترد من التفليسة الأشياء التي تثبت له ملكيتها أو حق استردادها وقت شهر الإفلاس.
2- ويكون لأمين التفليسة، بعد اخذ رأى المراقب والحصول على إذن من قاضي التفليسة رد الشيء إلى مالكه أو صاحب الحق في استرداده، وإذا رفض طلب الاسترداد جاز لطالبه عرض النزاع على المحكمة.$cc1255$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1255$1- لكل شخص أن يسترد من التفليسة الأشياء التي تثبت له ملكيتها أو حق استردادها وقت شهر الإفلاس.
2- ويكون لأمين التفليسة، بعد اخذ رأى المراقب والحصول على إذن من قاضي التفليسة رد الشيء إلى مالكه أو صاحب الحق في استرداده، وإذا رفض طلب الاسترداد جاز لطالبه عرض النزاع على المحكمة.$cc1255$, '1999-10-01', 'active' FROM ins_art_law17_1999_626;

WITH ins_art_law17_1999_627 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 627, $cc1256$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الثالث: آثار الإفلاس$cc1256$, $cc1257$1- يجوز استرداد الأشياء الموجودة في حيازة المفلس، على سبيل الوديعة أو لأجل بيعها لحساب مالكها أو لأجل تسليمها إليه، بشرط أن توجد في التفليسة عينا.
كما يجوز استرداد ثمن البضائع إذا لم يكن قد تم الوفاء به نقدا أو بورقة تجارية أو بطريق قيده في حساب جار بين المفلس والمشتري.
2- وعلى المسترد ان يدفع لامين التفليسة الحقوق المستحقة للمفلس.
3- وإذا كان المفلس قد أودع البضائع لدى الغير جاز استردادها منه.
4- وإذا افترض المفلس برهن البضائع وكان الدائن المرتهن لا يعلم وقت إنشاء الرهن بعدم ملكية المفلس لها فلا يجوز استردادها إلا بعد وفاء الدين المضمون بالرهن.$cc1257$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1257$1- يجوز استرداد الأشياء الموجودة في حيازة المفلس، على سبيل الوديعة أو لأجل بيعها لحساب مالكها أو لأجل تسليمها إليه، بشرط أن توجد في التفليسة عينا.
كما يجوز استرداد ثمن البضائع إذا لم يكن قد تم الوفاء به نقدا أو بورقة تجارية أو بطريق قيده في حساب جار بين المفلس والمشتري.
2- وعلى المسترد ان يدفع لامين التفليسة الحقوق المستحقة للمفلس.
3- وإذا كان المفلس قد أودع البضائع لدى الغير جاز استردادها منه.
4- وإذا افترض المفلس برهن البضائع وكان الدائن المرتهن لا يعلم وقت إنشاء الرهن بعدم ملكية المفلس لها فلا يجوز استردادها إلا بعد وفاء الدين المضمون بالرهن.$cc1257$, '1999-10-01', 'active' FROM ins_art_law17_1999_627;

WITH ins_art_law17_1999_628 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 628, $cc1258$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الثالث: آثار الإفلاس$cc1258$, $cc1259$1- يجوز استرداد الأوراق التجارية وغيرها من الأوراق ذات القيمة، المسلمة إلى المفلس لتحصيلها أو لتخصيصها لوفاء معين إذا وجدت عينا في التفليسة ولم تكن قيمتها قد دفعت.
2- ولا يجوز استرداد أوراق النقد المودعة لدى المفلس إلا إذا اثبت طالب الاسترداد ذاتيتها.$cc1259$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1259$1- يجوز استرداد الأوراق التجارية وغيرها من الأوراق ذات القيمة، المسلمة إلى المفلس لتحصيلها أو لتخصيصها لوفاء معين إذا وجدت عينا في التفليسة ولم تكن قيمتها قد دفعت.
2- ولا يجوز استرداد أوراق النقد المودعة لدى المفلس إلا إذا اثبت طالب الاسترداد ذاتيتها.$cc1259$, '1999-10-01', 'active' FROM ins_art_law17_1999_628;

WITH ins_art_law17_1999_629 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 629, $cc1260$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الثالث: آثار الإفلاس$cc1260$, $cc1261$1- إذا فسخ عقد البيع بحكم أو بمقتضى شرط في العقد قبل صدور الحكم بشهر إفلاس المشتري، جاز للبائع استرداد البضائع كلها أو بعضها في التفليسة بشرط أن توجد عينا.
2- ويجوز الاسترداد ولو وقع الفسخ بعد صدور حكم شهر الإفلاس بشرط أن تكون دعوى الاسترداد أو دعوى الفسخ قد رفعت قبل صدور هذا الحكم.$cc1261$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1261$1- إذا فسخ عقد البيع بحكم أو بمقتضى شرط في العقد قبل صدور الحكم بشهر إفلاس المشتري، جاز للبائع استرداد البضائع كلها أو بعضها في التفليسة بشرط أن توجد عينا.
