2- ويقوم قاضي التفليسة بوضع الأختام فور صدور الحكم بشهر الإفلاس، وله أن يندب أحد موظفي المحكمة لذلك، كما يقوم بإبلاغ رئيس كل محكمة يوجد في دائرتها مال للمفلس ليأمر بندب من يقوم بوضع الأختام على هذا المال.
3- وإذا تبين لقاضي التفليسة إمكان جرد أموال المفلس في يوم واحد جاز له أو لمن يندبه، البدء في الجرد فورا دون حاجة إلى وضع الأختام.
4- ويحرر محضر بوضع الأختام أو بالجرد يوقعه من قام بهذا الإجراء، ويسلم المحضر لقاضي التفليسة.$cc1269$, '1999-10-01', 'active' FROM ins_art_law17_1999_633;

WITH ins_art_law17_1999_634 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 634, $cc1270$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الرابع: إدارة التفليسة$cc1270$, $cc1271$لا يجوز وضع الأختام على الملابس والمنقولات الضرورية للمفلس ولمن يعولهم، ويعين قاضي التفليسة هذه الأشياء وتسلم إلى المفلس بقائمة يوقعها كل من قاضي التفليسة والمفلس.$cc1271$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1271$لا يجوز وضع الأختام على الملابس والمنقولات الضرورية للمفلس ولمن يعولهم، ويعين قاضي التفليسة هذه الأشياء وتسلم إلى المفلس بقائمة يوقعها كل من قاضي التفليسة والمفلس.$cc1271$, '1999-10-01', 'active' FROM ins_art_law17_1999_634;

WITH ins_art_law17_1999_635 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 635, $cc1272$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الرابع: إدارة التفليسة$cc1272$, $cc1273$1- يجوز لقاضي التفليسة أن يأمر، من تلقاء نفسه، أو بناء على طلب أمين التفليسة، بعدم وضع الأختام أو برفعها عن الأشياء الآتية:
(أ) الدفاتر التجارية.
(ب)الأوراق التجارية وغيرها من الأوراق التي تستحق الوفاء في ميعاد قريب أو التي تحتاج إلى إجراءات للمحافظة على الحقوق الثابتة فيها.
(ج) النقود اللازمة للصرف على الشئون العاجلة للتفليسة.
(د) الأشياء القابلة لتلف سريع أو لنقص عاجل في القيمة أو التي تقتضى صيانتها مصاريف باهظة.
(هـ) الأشياء اللازمة لتشغيل المتجر إذا تقرر الاستمرار في تشغيله.
2- وتجرد الأشياء المذكورة في الفقرة السابقة بحضور قاضي التفليسة أو من يندبه لذلك، وتسلم لأمين التفليسة بقائمة يوقعها.$cc1273$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1273$1- يجوز لقاضي التفليسة أن يأمر، من تلقاء نفسه، أو بناء على طلب أمين التفليسة، بعدم وضع الأختام أو برفعها عن الأشياء الآتية:
(أ) الدفاتر التجارية.
(ب)الأوراق التجارية وغيرها من الأوراق التي تستحق الوفاء في ميعاد قريب أو التي تحتاج إلى إجراءات للمحافظة على الحقوق الثابتة فيها.
(ج) النقود اللازمة للصرف على الشئون العاجلة للتفليسة.
(د) الأشياء القابلة لتلف سريع أو لنقص عاجل في القيمة أو التي تقتضى صيانتها مصاريف باهظة.
(هـ) الأشياء اللازمة لتشغيل المتجر إذا تقرر الاستمرار في تشغيله.
2- وتجرد الأشياء المذكورة في الفقرة السابقة بحضور قاضي التفليسة أو من يندبه لذلك، وتسلم لأمين التفليسة بقائمة يوقعها.$cc1273$, '1999-10-01', 'active' FROM ins_art_law17_1999_635;

WITH ins_art_law17_1999_636 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 636, $cc1274$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الرابع: إدارة التفليسة$cc1274$, $cc1275$1- يأمر قاضي التفليسة، بناء على طلب أمينها، برفع الأختام للبدء في جرد أموال المفلس.
2- ويجب أن يبدأ رفع الأختام والجرد خلال ثلاثين يوما من تاريخ صدور حكم شهر الإفلاس.$cc1275$
