SELECT id, 1, $cc1275$1- يأمر قاضي التفليسة، بناء على طلب أمينها، برفع الأختام للبدء في جرد أموال المفلس.
2- ويجب أن يبدأ رفع الأختام والجرد خلال ثلاثين يوما من تاريخ صدور حكم شهر الإفلاس.$cc1275$, '1999-10-01', 'active' FROM ins_art_law17_1999_636;

WITH ins_art_law17_1999_637 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 637, $cc1276$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الرابع: إدارة التفليسة$cc1276$, $cc1277$1- يحصل الجرد بحضور قاضي التفليسة أو من يندبه لذلك وأمين التفليسة وكاتب المحكمة، ويجب أن يخطر به المفلس ويجوز له الحضور.
2- وتحرر قائمة جرد من نسختين يوقعهما قاضي التفليسة أو من ندبه لذلك وأمين التفليسة، وكاتب المحكمة وتودع إحداهما قلم كتاب المحكمة، وتبقى الأخرى لدى أمين التفليسة.
3- وتذكر في القائمة الأموال التي لم توضع عليها الأختام أو التي رفعت عنها.
4- وتجوز الاستعانة بخبير في إجراء الجرد وتقويم الأموال.$cc1277$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
