INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1279$إذا شهر الإفلاس بعد وفاة التاجر ولم تحرر قائمة جرد بمناسبة الوفاة، أو إذا توفى التاجر بعد شهر إفلاسه وقبل البدء في تحرير قائمة الجرد أو قبل إتمامها، وجب تحرير القائمة فورا او الاستمرار في تحريرها بالكيفية المبينة في المادة السابقة وذلك بحضور ورثة المفلس أو بعد إخطارهم بالحضور.$cc1279$, '1999-10-01', 'active' FROM ins_art_law17_1999_638;

