WITH ins_art_law17_1999_640 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 640, $cc1282$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الرابع: إدارة التفليسة$cc1282$, $cc1283$1- لا يجوز تسليم الدفاتر التجارية إلى أمين التفليسة إلا بعد إن يقوم قاضي التفليسة بإقفالها.
