)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1283$1- لا يجوز تسليم الدفاتر التجارية إلى أمين التفليسة إلا بعد إن يقوم قاضي التفليسة بإقفالها.
2- ويدعى المفلس إلى حضور جلسة إقفال الدفاتر التجارية، فإذا لم يحضر وجب دعوته مرة أخرى إلى الحضور خلال ثلاثة أيام من تاريخ الإخطار وإلا أقفلت الدفاتر بغير حضوره.
3- ولا يجوز للمفلس أن ينيب عنه غيره لحضور جلسة إقفال الدفاتر إلا لاسباب يقبلها قاضي التفليسة.$cc1283$, '1999-10-01', 'active' FROM ins_art_law17_1999_640;

WITH ins_art_law17_1999_641 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 641, $cc1284$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الرابع: إدارة التفليسة$cc1284$, $cc1285$1- اذا لم يكن المفلس قد قدم الميزانية، وجب على أمين التفليسة أن يقوم بعملها، وإيداعها قلم كتاب المحكمة.
2- ويتسلم أمين التفليسة الرسائل الواردة باسم المفلس والمتعلقة بأشغاله، ولأمين التفليسة فضها والاحتفاظ بها، وللمفلس الاطلاع عليها.$cc1285$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1285$1- اذا لم يكن المفلس قد قدم الميزانية، وجب على أمين التفليسة أن يقوم بعملها، وإيداعها قلم كتاب المحكمة.
2- ويتسلم أمين التفليسة الرسائل الواردة باسم المفلس والمتعلقة بأشغاله، ولأمين التفليسة فضها والاحتفاظ بها، وللمفلس الاطلاع عليها.$cc1285$, '1999-10-01', 'active' FROM ins_art_law17_1999_641;

WITH ins_art_law17_1999_642 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 642, $cc1286$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الرابع: إدارة التفليسة$cc1286$, $cc1287$1- يقوم أمين التفليسة بجميع الأعمال اللازمة للمحافظة على حقوق المفلس لدى الغير، ويطالب بهذه الحقوق ويستوفيها.
2- وعليه أن يفيد ما للمفلس من حقوق عينية على عقارات مدينيه، إذا لم يكن المفلس قد أجرى القيد.$cc1287$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1287$1- يقوم أمين التفليسة بجميع الأعمال اللازمة للمحافظة على حقوق المفلس لدى الغير، ويطالب بهذه الحقوق ويستوفيها.
2- وعليه أن يفيد ما للمفلس من حقوق عينية على عقارات مدينيه، إذا لم يكن المفلس قد أجرى القيد.$cc1287$, '1999-10-01', 'active' FROM ins_art_law17_1999_642;

WITH ins_art_law17_1999_643 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 643, $cc1288$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الرابع: إدارة التفليسة$cc1288$, $cc1289$1- لا يجوز بيع أموال التفليسة خلال فترة الإجراءات التمهيدية، ومع ذلك يجوز لقاضي التفليسة بناء على طلب أمينها أن يأذن ببيع الأشياء القابلة لتلف سريع، أو لنقص عاجل في القيمة، أو التي تقتضى صيانتها مصاريف باهظة، كما يجوز الإذن ببيع أموال التفليسة إذا كان البيع لازما للحصول على نقود للصرف على شئونها، أو كان البيع يحقق نفعا مؤكدا للدائنين أو للمفلس، ولا يجوز الإذن بالبيع في الحالة الأخيرة إلا بعد إخطار المفلس بالبيع وسماع أقواله.
2- ويتم بيع المنقول بالكيفية التي يعينها قاضي التفليسة،ا ما بيع العقار فيجب أن يتم طبقا للأحكام المنصوص عليها في قانون المرافعات المدنية والتجارية بشأن بيع عقارات المفلس.
3- يجوز الطعن أمام المحكمة في القرار الصادر من قاضي التفليسة ببيع أموال المفلس خلال فترة الإجراءات التمهيدية.$cc1289$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1289$1- لا يجوز بيع أموال التفليسة خلال فترة الإجراءات التمهيدية، ومع ذلك يجوز لقاضي التفليسة بناء على طلب أمينها أن يأذن ببيع الأشياء القابلة لتلف سريع، أو لنقص عاجل في القيمة، أو التي تقتضى صيانتها مصاريف باهظة، كما يجوز الإذن ببيع أموال التفليسة إذا كان البيع لازما للحصول على نقود للصرف على شئونها، أو كان البيع يحقق نفعا مؤكدا للدائنين أو للمفلس، ولا يجوز الإذن بالبيع في الحالة الأخيرة إلا بعد إخطار المفلس بالبيع وسماع أقواله.
2- ويتم بيع المنقول بالكيفية التي يعينها قاضي التفليسة،ا ما بيع العقار فيجب أن يتم طبقا للأحكام المنصوص عليها في قانون المرافعات المدنية والتجارية بشأن بيع عقارات المفلس.
3- يجوز الطعن أمام المحكمة في القرار الصادر من قاضي التفليسة ببيع أموال المفلس خلال فترة الإجراءات التمهيدية.$cc1289$, '1999-10-01', 'active' FROM ins_art_law17_1999_643;

WITH ins_art_law17_1999_644 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 644, $cc1290$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الرابع: إدارة التفليسة$cc1290$, $cc1291$1- يجوز لقاضي التفليسة بعد اخذ رأي المراقب وسماع أقوال المفلس أو إخطاره، أن يأذن لأمين التفليسة بالصلح أو بقبول التحكيم في كل نزاع يتعلق بالتفليسة، ولو كان خاصا بحقوق أو دعاوى عقارية.
2- فإذا كان النزاع غير معين القيمة، أو كانت قيمته تزيد على خمسة آلاف جنيه، فلا يكون الصلح أو قبول التحكيم نافذا إلا بعد تصديق قاضي التفليسة على شروطه، ويدعى المفلس إلى الحضور عند التصديق ويسمع قاضي التفليسة أقواله إذا حضر، ولا يكون لاعتراضه أي اثر. ويجوز الطعن أمام المحكمة في قرار قاضي التفليسة إذا صدر برفض التصديق على شروط الصلح أو التحكيم.
3- ولا يجوز لأمين التفليسة النزول عن حق للمفلس، أو الإقرار بحق للغير عليه إلا بالشروط المبينة في هذه المادة.$cc1291$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1291$1- يجوز لقاضي التفليسة بعد اخذ رأي المراقب وسماع أقوال المفلس أو إخطاره، أن يأذن لأمين التفليسة بالصلح أو بقبول التحكيم في كل نزاع يتعلق بالتفليسة، ولو كان خاصا بحقوق أو دعاوى عقارية.
2- فإذا كان النزاع غير معين القيمة، أو كانت قيمته تزيد على خمسة آلاف جنيه، فلا يكون الصلح أو قبول التحكيم نافذا إلا بعد تصديق قاضي التفليسة على شروطه، ويدعى المفلس إلى الحضور عند التصديق ويسمع قاضي التفليسة أقواله إذا حضر، ولا يكون لاعتراضه أي اثر. ويجوز الطعن أمام المحكمة في قرار قاضي التفليسة إذا صدر برفض التصديق على شروط الصلح أو التحكيم.
3- ولا يجوز لأمين التفليسة النزول عن حق للمفلس، أو الإقرار بحق للغير عليه إلا بالشروط المبينة في هذه المادة.$cc1291$, '1999-10-01', 'active' FROM ins_art_law17_1999_644;

WITH ins_art_law17_1999_645 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 645, $cc1292$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الرابع: إدارة التفليسة$cc1292$, $cc1293$1- لقاضي التفليسة بناء على طلب أمينها أو طلب المفلس وبعد اخذ رأي المراقب، أن يأذن بالاستمرار في تشغيل المتجر، إذا اقتضت ذلك المصلحة العامة أو مصلحة المفلس أو الدائنين.
2- ويعين قاضي التفليسة بناء على اقتراح أمينها من يتولى إدارة المتجر وأجره، ويجوز تعيين المفلس للإدارة، ويعتبر الأجر الذي يحصل عليه بديلا عن الإعانة.
3- ويشرف أمين التفليسة على من يعين للإدارة، وعليه أن يقدم تقريرا شهريا إلى قاضي التفليسة عن سير التجارة.
4- ويجوز للمفلس ولأمين التفليسة الطعن أمام المحكمة في قرار قاضي التفليسة برفض الإذن بالاستمرار في تشغيل المتجر.$cc1293$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1293$1- لقاضي التفليسة بناء على طلب أمينها أو طلب المفلس وبعد اخذ رأي المراقب، أن يأذن بالاستمرار في تشغيل المتجر، إذا اقتضت ذلك المصلحة العامة أو مصلحة المفلس أو الدائنين.
2- ويعين قاضي التفليسة بناء على اقتراح أمينها من يتولى إدارة المتجر وأجره، ويجوز تعيين المفلس للإدارة، ويعتبر الأجر الذي يحصل عليه بديلا عن الإعانة.
3- ويشرف أمين التفليسة على من يعين للإدارة، وعليه أن يقدم تقريرا شهريا إلى قاضي التفليسة عن سير التجارة.
4- ويجوز للمفلس ولأمين التفليسة الطعن أمام المحكمة في قرار قاضي التفليسة برفض الإذن بالاستمرار في تشغيل المتجر.$cc1293$, '1999-10-01', 'active' FROM ins_art_law17_1999_645;

WITH ins_art_law17_1999_646 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 646, $cc1294$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الرابع: إدارة التفليسة$cc1294$, $cc1295$في حالة وفاة المفلس يقوم مقامه ورثته في إجراءات الإفلاس، ولهم أن ينيبوا أحدهم ليمثلهم في ذلك، فإذا لم يتفقوا جاز لقاضي التفليسة بناء على طلب اميها إنابة من يمثلهم، وللقاضي في كل وقت عزل من أنيب وتعيين غيره.$cc1295$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1295$في حالة وفاة المفلس يقوم مقامه ورثته في إجراءات الإفلاس، ولهم أن ينيبوا أحدهم ليمثلهم في ذلك، فإذا لم يتفقوا جاز لقاضي التفليسة بناء على طلب اميها إنابة من يمثلهم، وللقاضي في كل وقت عزل من أنيب وتعيين غيره.$cc1295$, '1999-10-01', 'active' FROM ins_art_law17_1999_646;

WITH ins_art_law17_1999_647 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 647, $cc1296$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الرابع: إدارة التفليسة$cc1296$, $cc1297$1- تودع المبالغ التي يحصلها أمين التفليسة لحسابها خزانة المحكمة أو بنك يعينه قاضي التفليسة، وذلك في يوم التحصيل أو في يوم العمل التالي على الأكثر.
ويلزم أمين التفليسة بتعويض يقدره قاضي التفليسة إذا تأخر في الإيداع.
وعليه أن يقدم إلى قاضي التفليسة بيانا بالمبالغ المذكورة خلال خمسة أيام من تاريخ الإيداع.
2- ولا يجوز سحب تلك المبالغ أو غيرها مما يودعه الغير لحساب التفليسة إلا بأمر من قاضي التفليسة.$cc1297$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1297$1- تودع المبالغ التي يحصلها أمين التفليسة لحسابها خزانة المحكمة أو بنك يعينه قاضي التفليسة، وذلك في يوم التحصيل أو في يوم العمل التالي على الأكثر.
ويلزم أمين التفليسة بتعويض يقدره قاضي التفليسة إذا تأخر في الإيداع.
وعليه أن يقدم إلى قاضي التفليسة بيانا بالمبالغ المذكورة خلال خمسة أيام من تاريخ الإيداع.
