INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1299$1- يجوز عند الضرورة لقاضي التفليسة بعد اخذ رأي المراقب أن يأمر بإجراء توزيعات على الدائنين الذين حققت ديونهم، ويكون التوزيع بمقتضى قائمة يعدها أمين التفليسة ويؤشر عليها قاضي التفليسة بإجراء التوزيع.
2- ويجوز للمفلس ولكل ذي مصلحة الطعن أمام المحكمة في قرار قاضي التفليسة الخاص بإجراء توزيعات على الدائنين.$cc1299$, '1999-10-01', 'active' FROM ins_art_law17_1999_648;

WITH ins_art_law17_1999_649 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 649, $cc1300$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الرابع: إدارة التفليسة$cc1300$, $cc1301$1- على أمين التفليسة أن يقدم إلى قاضي التفليسة خلال ثلاثين يوما من تاريخ إخطاره بالتعيين تقريرا عن أسباب الإفلاس وحالة التفليسة الظاهرة وظروفها، ويجوز لقاضي التفليسة تعيين ميعاد آخر لتقديم هذا التقرير، وعلى القاضي إحالة التقرير مع ملاحظاته إلى النيابة العامة.
2- كما يجب على أمين التفليسة أن يقدم إلى قاضي التفليسة تقارير عن حالة التفليسة في مواعيد دورية يحددها القاضي.
2- تحقيق الديون$cc1301$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
