SELECT id, 1, $cc1301$1- على أمين التفليسة أن يقدم إلى قاضي التفليسة خلال ثلاثين يوما من تاريخ إخطاره بالتعيين تقريرا عن أسباب الإفلاس وحالة التفليسة الظاهرة وظروفها، ويجوز لقاضي التفليسة تعيين ميعاد آخر لتقديم هذا التقرير، وعلى القاضي إحالة التقرير مع ملاحظاته إلى النيابة العامة.
2- كما يجب على أمين التفليسة أن يقدم إلى قاضي التفليسة تقارير عن حالة التفليسة في مواعيد دورية يحددها القاضي.
