WITH ins_art_law17_1999_650 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 650, $cc1302$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الرابع: إدارة التفليسة$cc1302$, $cc1303$1- على جميع الدائنين ولو كانت ديونهم مصحوبة بتأمينات خاصة أو كانت ثابتة بأحكام نهائية أن يسلموا أمين التفليسة عقب صدور الحكم بشهر الإفلاس مستندات ديونهم مصحوبة ببيان بهذه الديون وتأميناتها ومقدارها إن وجدت ومقومة بالعملة الوطنية على أساس سعر الصرف المعلن لدى البنك المركزي بيعا أو إقفالا أو تحويلات أو بنكنوت إذا لم يوجد سعر تحويلات يوم صدور الحكم بشهر الإفلاس.
ويحرر أمين التفليسة إيصالا بتسلمه البيان ومستندات الدين.
2- ويجوز إرسال البيان والمستندات بالبريد المسجل مع علم الوصول.
3- ويجب ان يتضمن البيان تعيين محل مختار لأمين التفليسة في دائرة المحكمة.
4- ويعيد أمين التفليسة المستندات إلى الدائنين بعد قفل التفليسة، ويكون مسئولا عنها لمدة سنة من تاريخ التفليسة.
[ملاحظة توثيقية: صححت الفقرة 1 من المادة (650) بالاستدراك المنشور بالجريدة الرسمية- العدد 38 (مكرر) في 2000/9/27.]$cc1303$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1303$1- على جميع الدائنين ولو كانت ديونهم مصحوبة بتأمينات خاصة أو كانت ثابتة بأحكام نهائية أن يسلموا أمين التفليسة عقب صدور الحكم بشهر الإفلاس مستندات ديونهم مصحوبة ببيان بهذه الديون وتأميناتها ومقدارها إن وجدت ومقومة بالعملة الوطنية على أساس سعر الصرف المعلن لدى البنك المركزي بيعا أو إقفالا أو تحويلات أو بنكنوت إذا لم يوجد سعر تحويلات يوم صدور الحكم بشهر الإفلاس.
ويحرر أمين التفليسة إيصالا بتسلمه البيان ومستندات الدين.
2- ويجوز إرسال البيان والمستندات بالبريد المسجل مع علم الوصول.
3- ويجب ان يتضمن البيان تعيين محل مختار لأمين التفليسة في دائرة المحكمة.
4- ويعيد أمين التفليسة المستندات إلى الدائنين بعد قفل التفليسة، ويكون مسئولا عنها لمدة سنة من تاريخ التفليسة.
[ملاحظة توثيقية: صححت الفقرة 1 من المادة (650) بالاستدراك المنشور بالجريدة الرسمية- العدد 38 (مكرر) في 2000/9/27.]$cc1303$, '1999-10-01', 'active' FROM ins_art_law17_1999_650;

WITH ins_art_law17_1999_651 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 651, $cc1304$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الرابع: إدارة التفليسة$cc1304$, $cc1305$1- إذا لم يقدم جميع الدائنين المقيدة أسماؤهم في الميزانية مستندات ديونهم خلال الأيام العشرة التالية لنشر الحكم بشهر الإفلاس في الصحف، وجب على أمين التفليسة النشر فورا في الصحيفة اليومية التي نشر فيها حكم الإفلاس لدعوة الدائنين إلى تقديم مستنداتهم مصحوبة بالبيان المشار إليه في المادة السابقة.
2- وعلى الدائنين تقديم مستندات ديونهم مصحوبة بالبيان خلال عشرة أيام من تاريخ النشر في الصحف، ويكون هذا الميعاد أربعين يوما بالنسبة إلى الدائنين المقيمين خارج مصر، ولا يضاف إلى أي من هذه المواعيد ميعاد للمسافة.$cc1305$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1305$1- إذا لم يقدم جميع الدائنين المقيدة أسماؤهم في الميزانية مستندات ديونهم خلال الأيام العشرة التالية لنشر الحكم بشهر الإفلاس في الصحف، وجب على أمين التفليسة النشر فورا في الصحيفة اليومية التي نشر فيها حكم الإفلاس لدعوة الدائنين إلى تقديم مستنداتهم مصحوبة بالبيان المشار إليه في المادة السابقة.
2- وعلى الدائنين تقديم مستندات ديونهم مصحوبة بالبيان خلال عشرة أيام من تاريخ النشر في الصحف، ويكون هذا الميعاد أربعين يوما بالنسبة إلى الدائنين المقيمين خارج مصر، ولا يضاف إلى أي من هذه المواعيد ميعاد للمسافة.$cc1305$, '1999-10-01', 'active' FROM ins_art_law17_1999_651;

WITH ins_art_law17_1999_652 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 652, $cc1306$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الرابع: إدارة التفليسة$cc1306$, $cc1307$1- يحقق أمين التفليسة الديون بمعاونة المراقب وبحضور المفلس أو بعد إخطاره بالحضور.
2- وإذا نازع أمين التفليسة أو المراقب أو المفلس في صحة أحد الديون أو في مقداره أو في ضماناته وجب على أمين التفليسة إخطار الدائن بذلك فورا وللدائن تقديم إيضاحات كتابية أو شفوية خلال عشرة أيام من تاريخ تسلم الإخطار.
3- ولا تخضع الديون واجبة السداد المستحقة للحكومة بسبب الرسوم والضرائب على اختلاف انواعها لإجراءات التحقيق.$cc1307$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1307$1- يحقق أمين التفليسة الديون بمعاونة المراقب وبحضور المفلس أو بعد إخطاره بالحضور.
2- وإذا نازع أمين التفليسة أو المراقب أو المفلس في صحة أحد الديون أو في مقداره أو في ضماناته وجب على أمين التفليسة إخطار الدائن بذلك فورا وللدائن تقديم إيضاحات كتابية أو شفوية خلال عشرة أيام من تاريخ تسلم الإخطار.
3- ولا تخضع الديون واجبة السداد المستحقة للحكومة بسبب الرسوم والضرائب على اختلاف انواعها لإجراءات التحقيق.$cc1307$, '1999-10-01', 'active' FROM ins_art_law17_1999_652;

WITH ins_art_law17_1999_653 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 653, $cc1308$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الرابع: إدارة التفليسة$cc1308$, $cc1309$1- يودع أمين التفليسة قلم كتاب المحكمة بعد الانتهاء من تحقيق الديون قائمة بها تشتمل على بيان بمستنداتها، واسباب المنازعة فيها إن وجدت، وما يراه بشأن قبولها أو رفضها، كما يودع كشفا بأسماء الدائنين الذين يدعون أن لهم تأمينات خاصة على أموال المفلس مبينا مقدار ديونهم ونوع تأميناتهم والأموال المقررة عليها.
2- ويجب أن يتم هذا الإيداع خلال ستين يوما على الأكثر من تاريخ نشر الحكم بشهر الإفلاس، ويجوز عند الاقتضاء إطالة الميعاد بقرار من قاضي التفليسة.
3- وعلى أمين التفليسة خلال ستة أيام من تاريخ الإيداع أن ينشر في صحيفة يومية بيانا بحصوله، وعليه أن يرسل إلى المفلس والى كل دائن خلال هذا الميعاد نسخة من هذه القائمة والكشف المذكورين، مع بيان المبالغ التي يرى قبولها من كل دين.
4- ولكل ذي مصلحة الاطلاع على القائمة والكشف المودعين بقلم كتاب المحكمة.$cc1309$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
