2- ويجب أن يتم هذا الإيداع خلال ستين يوما على الأكثر من تاريخ نشر الحكم بشهر الإفلاس، ويجوز عند الاقتضاء إطالة الميعاد بقرار من قاضي التفليسة.
3- وعلى أمين التفليسة خلال ستة أيام من تاريخ الإيداع أن ينشر في صحيفة يومية بيانا بحصوله، وعليه أن يرسل إلى المفلس والى كل دائن خلال هذا الميعاد نسخة من هذه القائمة والكشف المذكورين، مع بيان المبالغ التي يرى قبولها من كل دين.
4- ولكل ذي مصلحة الاطلاع على القائمة والكشف المودعين بقلم كتاب المحكمة.$cc1309$, '1999-10-01', 'active' FROM ins_art_law17_1999_653;

WITH ins_art_law17_1999_654 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 654, $cc1310$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الرابع: إدارة التفليسة$cc1310$, $cc1311$للمفلس ولكل دائن ورد اسمه بقائمة الديون المدرجة بها أن ينازع في الديون المدرجة بها خلال عشرة أيام من تاريخ النشر في الصحف عن حصول الإيداع، وتسلم المنازعة إلى قلم كتاب المحكمة أو ترسل إليه بكتاب مسجل مصحوبا بعلم الوصول أو ببرقية أو فاكس أو تلكس وعلى قلم الكتاب عرضها فورا على قاضي التفليسة ولا يضاف إلى هذا الميعاد ميعاد للمسافة.$cc1311$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1311$للمفلس ولكل دائن ورد اسمه بقائمة الديون المدرجة بها أن ينازع في الديون المدرجة بها خلال عشرة أيام من تاريخ النشر في الصحف عن حصول الإيداع، وتسلم المنازعة إلى قلم كتاب المحكمة أو ترسل إليه بكتاب مسجل مصحوبا بعلم الوصول أو ببرقية أو فاكس أو تلكس وعلى قلم الكتاب عرضها فورا على قاضي التفليسة ولا يضاف إلى هذا الميعاد ميعاد للمسافة.$cc1311$, '1999-10-01', 'active' FROM ins_art_law17_1999_654;

WITH ins_art_law17_1999_655 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 655, $cc1312$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الرابع: إدارة التفليسة$cc1312$, $cc1313$1- يضع قاضي التفليسة بعد انقضاء الميعاد المنصوص عليه في المادة السابقة قائمة نهائية بالديون غير المتنازع فيها، ويؤشر أمين التفليسة على البيان الذي يصحب مستندات هذه الديون بما يفيد قبولها ومقدار ما قبل من كل دين منها.
2- ويجوز لقاضي التفليسة اعتبار الدين متنازعا فيه ولو لم تقدم بشأنه أية منازعة.
3- ويفصل قاضي التفليسة في الديون المتنازع فيها خلال ثلاثين يوما من تاريخ انقضاء ميعاد المنازعة، ويخطر قلم كتاب المحكمة ذوى الشأن بميعاد الجلسة قبل ميعاد انعقادها بثلاثة أيام على الأقل.$cc1313$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1313$1- يضع قاضي التفليسة بعد انقضاء الميعاد المنصوص عليه في المادة السابقة قائمة نهائية بالديون غير المتنازع فيها، ويؤشر أمين التفليسة على البيان الذي يصحب مستندات هذه الديون بما يفيد قبولها ومقدار ما قبل من كل دين منها.
2- ويجوز لقاضي التفليسة اعتبار الدين متنازعا فيه ولو لم تقدم بشأنه أية منازعة.
3- ويفصل قاضي التفليسة في الديون المتنازع فيها خلال ثلاثين يوما من تاريخ انقضاء ميعاد المنازعة، ويخطر قلم كتاب المحكمة ذوى الشأن بميعاد الجلسة قبل ميعاد انعقادها بثلاثة أيام على الأقل.$cc1313$, '1999-10-01', 'active' FROM ins_art_law17_1999_655;

WITH ins_art_law17_1999_656 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 656, $cc1314$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الرابع: إدارة التفليسة$cc1314$, $cc1315$1- يجوز الطعن أمام المحكمة في القرار الصادر من قاضي التفليسة بقبول الدين أو رفضه، وذلك خلال عشرة أيام من تاريخ صدور القرار، إذا كانت قيمة الدين تزيد على النصاب الانتهائي للمحكمة الجزئية، ولا يترتب على الطعن وقف إجراءات التفليسة إلا إذا أمرت المحكمة بوقفها.
2- ويجوز للمحكمة قبل الفصل في الطعن أن تقضى بقبول الدين مؤقتا بمبلغ تقدره.
3- ولا يجوز الطعن في حكم المحكمة برفض الدين نهائيا أو بقبوله.
4- وإذا كان الطعن في الدين متعلقا بتأميناته وجب قبوله مؤقتا بوصفه دينا عاديا.
5- ولا يشترك الدائن الذي لم يقبل دينه نهائيا أو مؤقتا في إجراءات التفليسة.$cc1315$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1315$1- يجوز الطعن أمام المحكمة في القرار الصادر من قاضي التفليسة بقبول الدين أو رفضه، وذلك خلال عشرة أيام من تاريخ صدور القرار، إذا كانت قيمة الدين تزيد على النصاب الانتهائي للمحكمة الجزئية، ولا يترتب على الطعن وقف إجراءات التفليسة إلا إذا أمرت المحكمة بوقفها.
2- ويجوز للمحكمة قبل الفصل في الطعن أن تقضى بقبول الدين مؤقتا بمبلغ تقدره.
3- ولا يجوز الطعن في حكم المحكمة برفض الدين نهائيا أو بقبوله.
4- وإذا كان الطعن في الدين متعلقا بتأميناته وجب قبوله مؤقتا بوصفه دينا عاديا.
5- ولا يشترك الدائن الذي لم يقبل دينه نهائيا أو مؤقتا في إجراءات التفليسة.$cc1315$, '1999-10-01', 'active' FROM ins_art_law17_1999_656;

WITH ins_art_law17_1999_657 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 657, $cc1316$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الرابع: إدارة التفليسة$cc1316$, $cc1317$1- لا يشترك الدائنون الذين لم يقدموا طلباتهم في المواعيد المقررة في التوزيعات الجارية، وانما يجوز لهما المنازعة أمام قاضي التفليسة إلى أن ينتهي توزيع النقود ويتحملون مصاريف المنازعة.
2- ولا يترتب على المنازعة وقف تنفيذ التوزيعات التي أمر بها قاضي التفليسة، ومع ذلك يجوز للدائنين المذكورين الاشتراك في التوزيعات الجديدة بالمبالغ التي يقدرها قاضي التفليسة تقديرا مؤقتا، وتحفظ لهم حصصهم إلى حين الفصل في المنازعة.
3- وإذا ثبتت ديونهم بعد ذلك فلا يجوز لهم المطالبة بحصص في التوزيعات التي تمت، وانما يجوز لهم ن يأخذوا من المبالغ الباقية دون توزيع أنصبة ديونهم التي كانت تؤول إليهم لو أنهم اشتركوا في التوزيعات السابقة.
3- قفل التفليسة لعدم كفاية الأموال$cc1317$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1317$1- لا يشترك الدائنون الذين لم يقدموا طلباتهم في المواعيد المقررة في التوزيعات الجارية، وانما يجوز لهما المنازعة أمام قاضي التفليسة إلى أن ينتهي توزيع النقود ويتحملون مصاريف المنازعة.
2- ولا يترتب على المنازعة وقف تنفيذ التوزيعات التي أمر بها قاضي التفليسة، ومع ذلك يجوز للدائنين المذكورين الاشتراك في التوزيعات الجديدة بالمبالغ التي يقدرها قاضي التفليسة تقديرا مؤقتا، وتحفظ لهم حصصهم إلى حين الفصل في المنازعة.
3- وإذا ثبتت ديونهم بعد ذلك فلا يجوز لهم المطالبة بحصص في التوزيعات التي تمت، وانما يجوز لهم ن يأخذوا من المبالغ الباقية دون توزيع أنصبة ديونهم التي كانت تؤول إليهم لو أنهم اشتركوا في التوزيعات السابقة.
3- قفل التفليسة لعدم كفاية الأموال$cc1317$, '1999-10-01', 'active' FROM ins_art_law17_1999_657;

WITH ins_art_law17_1999_658 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 658, $cc1318$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الرابع: إدارة التفليسة$cc1318$, $cc1319$1- إذا وقفت أعمال التفليسة لعدم كفاية الأموال قبل التصديق على الصلح أو قيام حالة الاتحاد، جاز لقاضي التفليسة من تلقاء نفسه أو بناء على تقرير من أمين التفليسة أن يأمر بقفلها.
2- ويترتب على قرار قفل التفليسة لعدم كفاية أموالها أن يعود إلى كل دائن الحق في اتخاذ الإجراءات ومباشرة الدعاوى الفردية ضد المفلس.
3- وإذا كان دين الدائن قد حقق نهائيا في التفليسة جاز له التنفيذ على أموال المفلس بناء على شهادة من قاضي التفليسة بمقدار دينه، تعتبر بمثابة حكم نهائي فيما يتعلق بهذا التنفيذ.$cc1319$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
