SELECT id, 1, $cc1319$1- إذا وقفت أعمال التفليسة لعدم كفاية الأموال قبل التصديق على الصلح أو قيام حالة الاتحاد، جاز لقاضي التفليسة من تلقاء نفسه أو بناء على تقرير من أمين التفليسة أن يأمر بقفلها.
2- ويترتب على قرار قفل التفليسة لعدم كفاية أموالها أن يعود إلى كل دائن الحق في اتخاذ الإجراءات ومباشرة الدعاوى الفردية ضد المفلس.
3- وإذا كان دين الدائن قد حقق نهائيا في التفليسة جاز له التنفيذ على أموال المفلس بناء على شهادة من قاضي التفليسة بمقدار دينه، تعتبر بمثابة حكم نهائي فيما يتعلق بهذا التنفيذ.$cc1319$, '1999-10-01', 'active' FROM ins_art_law17_1999_658;

WITH ins_art_law17_1999_659 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 659, $cc1320$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الرابع: إدارة التفليسة$cc1320$, $cc1321$1- يجوز للمفلس ولكل ذي مصلحة أن يطلب في كل وقت من قاضي التفليسة إلغاء قرار قفل التفليسة لعدم كفاية أموالها إذا أثبت وجود مال كاف لموجهة مصاريف أعمال التفليسة أو إذا سلم لأمين التفليسة مبلغا كافيا لذلك.
2- كما يجوز لقاضي التفليسة أن يأمر من تلقاء نفسه أو بناء على طلب أمين التفليسة بإعادة فتح التفليسة والاستمرار في إجراءاتها.
3- وفي جميع الأحوال يجب أن تدفع بالأولوية مصاريف الإجراءات التي تمت طبقا للفقرتين السابقتين.$cc1321$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1321$1- يجوز للمفلس ولكل ذي مصلحة أن يطلب في كل وقت من قاضي التفليسة إلغاء قرار قفل التفليسة لعدم كفاية أموالها إذا أثبت وجود مال كاف لموجهة مصاريف أعمال التفليسة أو إذا سلم لأمين التفليسة مبلغا كافيا لذلك.
2- كما يجوز لقاضي التفليسة أن يأمر من تلقاء نفسه أو بناء على طلب أمين التفليسة بإعادة فتح التفليسة والاستمرار في إجراءاتها.
3- وفي جميع الأحوال يجب أن تدفع بالأولوية مصاريف الإجراءات التي تمت طبقا للفقرتين السابقتين.$cc1321$, '1999-10-01', 'active' FROM ins_art_law17_1999_659;

WITH ins_art_law17_1999_660 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 660, $cc1322$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الخامس: انتهاء التفليسة$cc1322$, $cc1323$لقاضي التفليسة بعد وضع القائمة النهائية للديون المشار إليها في المادة 655 من هذا القانون أن يأمر في كل وقت بناء على طلب المفلس بإنهاء التفليسة إذا اثبت انه أوفى كل ديون الدائنين الذين تحققت ديونهم في التفليسة أو انه أودع قلم كتاب المحكمة أو لدى أمين التفليسة المبالغ اللازمة لوفاء تلك الديون من أصل وعوائد ومصاريف.$cc1323$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1323$لقاضي التفليسة بعد وضع القائمة النهائية للديون المشار إليها في المادة 655 من هذا القانون أن يأمر في كل وقت بناء على طلب المفلس بإنهاء التفليسة إذا اثبت انه أوفى كل ديون الدائنين الذين تحققت ديونهم في التفليسة أو انه أودع قلم كتاب المحكمة أو لدى أمين التفليسة المبالغ اللازمة لوفاء تلك الديون من أصل وعوائد ومصاريف.$cc1323$, '1999-10-01', 'active' FROM ins_art_law17_1999_660;

WITH ins_art_law17_1999_661 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 661, $cc1324$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الخامس: انتهاء التفليسة$cc1324$, $cc1325$1- لا يجوز لقاضي التفليسة أن يأمر بإنهائها لزوال مصلحة جماعة الدائنين إلا بعد الاطلاع على تقرير من أمين التفليسة يبين فيه تحقق أحد الشرطين المشار إليهما في المادة السابقة.
2- وتنتهي التفليسة بمجرد صدور قرار قاضي التفليسة بإنهائها لزوال مصلحة جماعة الدائنين ويستعيد المفلس جميع حقوقه.
2- الصلح القضائي$cc1325$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1325$1- لا يجوز لقاضي التفليسة أن يأمر بإنهائها لزوال مصلحة جماعة الدائنين إلا بعد الاطلاع على تقرير من أمين التفليسة يبين فيه تحقق أحد الشرطين المشار إليهما في المادة السابقة.
2- وتنتهي التفليسة بمجرد صدور قرار قاضي التفليسة بإنهائها لزوال مصلحة جماعة الدائنين ويستعيد المفلس جميع حقوقه.
2- الصلح القضائي$cc1325$, '1999-10-01', 'active' FROM ins_art_law17_1999_661;

WITH ins_art_law17_1999_662 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 662, $cc1326$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الخامس: انتهاء التفليسة$cc1326$, $cc1327$1- على قاضي التفليسة إذا طلب المدين الصلح أن يأمر قبل كتاب المحكمة بدعوة الدائنين الذين قبلت ديونهم نهائيا أو مؤقتا لحضور المداولة في الصلح.
2- وتوجه هذه الدعوة، في حالة عدم حصول أية منازعة في الديون، خلال الأيام الخمسة التالية لوضع القائمة النهائية بالديون المنصوص عليها في المادة 655 من هذا القانون وفي حالة حصول المنازعة توجه الدعوة خلال الخمسة عشر يوما التالية لانتهاء ميعاد الطعن في آخر قرار لقاضي التفليسة بشأن قبول الديون أو رفضها.
3- وعلى أمين التفليسة، خلال الميعاد المنصوص عليه في الفقرة السابقة، أن يقوم بنشر الدعوة لحضور المداولة في الصلح في الصحيفة اليومية التي نشر فيها حكم شهر الإفلاس.$cc1327$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1327$1- على قاضي التفليسة إذا طلب المدين الصلح أن يأمر قبل كتاب المحكمة بدعوة الدائنين الذين قبلت ديونهم نهائيا أو مؤقتا لحضور المداولة في الصلح.
2- وتوجه هذه الدعوة، في حالة عدم حصول أية منازعة في الديون، خلال الأيام الخمسة التالية لوضع القائمة النهائية بالديون المنصوص عليها في المادة 655 من هذا القانون وفي حالة حصول المنازعة توجه الدعوة خلال الخمسة عشر يوما التالية لانتهاء ميعاد الطعن في آخر قرار لقاضي التفليسة بشأن قبول الديون أو رفضها.
3- وعلى أمين التفليسة، خلال الميعاد المنصوص عليه في الفقرة السابقة، أن يقوم بنشر الدعوة لحضور المداولة في الصلح في الصحيفة اليومية التي نشر فيها حكم شهر الإفلاس.$cc1327$, '1999-10-01', 'active' FROM ins_art_law17_1999_662;

WITH ins_art_law17_1999_663 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 663, $cc1328$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الخامس: انتهاء التفليسة$cc1328$, $cc1329$1- تنعقد جمعية الصلح برئاسة قاضي التفليسة في المكان والزمان اللذين يعينهما.
2- ويحضر الدائنون الجمعية بأنفسهم أو بوكلاء مفوضين في كتابة الصلح.
3- ويدعى المفلس إلى حضور الجمعية، ولا يجوز له أن ينيب عنه غيره إلا لاسباب جدية يقبلها قاضي التفليسة.$cc1329$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1329$1- تنعقد جمعية الصلح برئاسة قاضي التفليسة في المكان والزمان اللذين يعينهما.
2- ويحضر الدائنون الجمعية بأنفسهم أو بوكلاء مفوضين في كتابة الصلح.
3- ويدعى المفلس إلى حضور الجمعية، ولا يجوز له أن ينيب عنه غيره إلا لاسباب جدية يقبلها قاضي التفليسة.$cc1329$, '1999-10-01', 'active' FROM ins_art_law17_1999_663;

WITH ins_art_law17_1999_664 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 664, $cc1330$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الخامس: انتهاء التفليسة$cc1330$, $cc1331$1- يقدم أمين التفليسة تقريرا إلى جمعية الصلح مشتملا على حالة التفليسة وما تم بشأنها من إجراءات، ومقترحات المفلس في الصلح ورأى أمين التفليسة في هذه المقترحات.
2- ويتلى تقرير أمين التفليسة في جمعية الصلح ويسلم موقعا منه الى قاضي التفليسة وتسمع أقوال المفلس إن حضر ويحرر قاضي التفليسة محضرا بما تم في الجمعية.$cc1331$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1331$1- يقدم أمين التفليسة تقريرا إلى جمعية الصلح مشتملا على حالة التفليسة وما تم بشأنها من إجراءات، ومقترحات المفلس في الصلح ورأى أمين التفليسة في هذه المقترحات.
2- ويتلى تقرير أمين التفليسة في جمعية الصلح ويسلم موقعا منه الى قاضي التفليسة وتسمع أقوال المفلس إن حضر ويحرر قاضي التفليسة محضرا بما تم في الجمعية.$cc1331$, '1999-10-01', 'active' FROM ins_art_law17_1999_664;

WITH ins_art_law17_1999_665 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 665, $cc1332$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الخامس: انتهاء التفليسة$cc1332$, $cc1333$1- لا يقع الصلح إلا بموافقة أغلبية الدائنين الذين قبلت ديونهم نهائيا أو مؤقتا بشرط أن يكونوا حائزين لثلثي قيمة هذه الديون، ولا يحسب في هاتين الاغلبيتين الدائنون الذين لم يشتركوا في التصويت كما لا تحسب ديونهم.
2- ولا يجوز التصويت على الصلح بالمراسلة.$cc1333$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1333$1- لا يقع الصلح إلا بموافقة أغلبية الدائنين الذين قبلت ديونهم نهائيا أو مؤقتا بشرط أن يكونوا حائزين لثلثي قيمة هذه الديون، ولا يحسب في هاتين الاغلبيتين الدائنون الذين لم يشتركوا في التصويت كما لا تحسب ديونهم.
2- ولا يجوز التصويت على الصلح بالمراسلة.$cc1333$, '1999-10-01', 'active' FROM ins_art_law17_1999_665;

WITH ins_art_law17_1999_666 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 666, $cc1334$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الخامس: انتهاء التفليسة$cc1334$, $cc1335$1- لا يجوز لزوج المفلس ولأقاربه إلى الدرجة الثانية الاشتراك في مداولات الصلح أو التصويت على شروطه.
2- وإذا نزل أحد هؤلاء الدائنين المشار إليهم في المادة السابقة عن دينه إلى الغير بعد صدور الحكم بشهر الإفلاس فلا يجوز للمتنازل إليه الاشتراك في مداولات الصلح أو التصويت عليه.$cc1335$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1335$1- لا يجوز لزوج المفلس ولأقاربه إلى الدرجة الثانية الاشتراك في مداولات الصلح أو التصويت على شروطه.
2- وإذا نزل أحد هؤلاء الدائنين المشار إليهم في المادة السابقة عن دينه إلى الغير بعد صدور الحكم بشهر الإفلاس فلا يجوز للمتنازل إليه الاشتراك في مداولات الصلح أو التصويت عليه.$cc1335$, '1999-10-01', 'active' FROM ins_art_law17_1999_666;

WITH ins_art_law17_1999_667 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 667, $cc1336$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الخامس: انتهاء التفليسة$cc1336$, $cc1337$1- لا يجوز للدائنين أصحاب التأمينات العينية المقررة على أموال المفلس الاشتراك في التصويت على الصلح بديونهم المضمونة بالتأمينات المذكورة إلا إذا نزلوا عن هذه التأمينات مقدما، ويجوز أن يكون التنازل مقصورا على جزء من التأمين بشرط ألا يقل عما يقابل ثلث الدين، ويذكر التنازل في محضر الجلسة.
2- إذا اشترك أحد الدائنين المذكورين في الفقرة السابقة في التصويت على الصلح دون أن يصرح بالتنازل عن تأمينه كله أو بعضه اعتبر ذلك تنازلا عن التأمين بأجمعه.
3- وفي جميع الأحوال لا يكون التنازل عن التأمين نهائيا إلا إذا تم الصلح وصدقت عليه المحكمة.
4- وإذا ابطل الصلح عاد التأمين الذي شمله التنازل.$cc1337$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1337$1- لا يجوز للدائنين أصحاب التأمينات العينية المقررة على أموال المفلس الاشتراك في التصويت على الصلح بديونهم المضمونة بالتأمينات المذكورة إلا إذا نزلوا عن هذه التأمينات مقدما، ويجوز أن يكون التنازل مقصورا على جزء من التأمين بشرط ألا يقل عما يقابل ثلث الدين، ويذكر التنازل في محضر الجلسة.
2- إذا اشترك أحد الدائنين المذكورين في الفقرة السابقة في التصويت على الصلح دون أن يصرح بالتنازل عن تأمينه كله أو بعضه اعتبر ذلك تنازلا عن التأمين بأجمعه.
3- وفي جميع الأحوال لا يكون التنازل عن التأمين نهائيا إلا إذا تم الصلح وصدقت عليه المحكمة.
4- وإذا ابطل الصلح عاد التأمين الذي شمله التنازل.$cc1337$, '1999-10-01', 'active' FROM ins_art_law17_1999_667;

WITH ins_art_law17_1999_668 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 668, $cc1338$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الخامس: انتهاء التفليسة$cc1338$, $cc1339$1- يوقع محضر الصلح في الجلسة التي تم فيها التصويت عليه وإلا كان لاغيا.
2- وإذا لم تتوافر إحدى الاغلبيتين المنصوص عليهما في المادة 665 من هذا القانون تأجلت المداولة مرة واحدة لمدة عشرة أيام.
3- ويجوز للدائنين الذين حضروا الاجتماع الأول أو كانوا ممثلين فيه ووقعوا محضر الصلح إلا يحضروا الاجتماع الثاني، وفي هذه الحالة تبقى موافقتهم على الصلح في الاجتماع الأول قائمة ونافذة في الاجتماع الثاني إلا إذا حضروا هذا الاجتماع وابدوا فيه مقترحاته بشأن الصلح في الفترة بين الاجتماعين.$cc1339$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1339$1- يوقع محضر الصلح في الجلسة التي تم فيها التصويت عليه وإلا كان لاغيا.
2- وإذا لم تتوافر إحدى الاغلبيتين المنصوص عليهما في المادة 665 من هذا القانون تأجلت المداولة مرة واحدة لمدة عشرة أيام.
3- ويجوز للدائنين الذين حضروا الاجتماع الأول أو كانوا ممثلين فيه ووقعوا محضر الصلح إلا يحضروا الاجتماع الثاني، وفي هذه الحالة تبقى موافقتهم على الصلح في الاجتماع الأول قائمة ونافذة في الاجتماع الثاني إلا إذا حضروا هذا الاجتماع وابدوا فيه مقترحاته بشأن الصلح في الفترة بين الاجتماعين.$cc1339$, '1999-10-01', 'active' FROM ins_art_law17_1999_668;

WITH ins_art_law17_1999_669 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 669, $cc1340$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الخامس: انتهاء التفليسة$cc1340$, $cc1341$لا يجوز عقد الصلح مع مفلس حكم عليه بعقوبة الإفلاس بالتدليس، وإذا بدأ التحقيق مع المفلس في جريمة الإفلاس بالتدليس وجب تأجيل النظر في الصلح.$cc1341$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
