)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1343$لا يحول الحكم على المفلس بعقوبة الإفلاس بالتقصير دون الصلح معه، وإذا بدأ التحقيق مع المفلس في جريمة الإفلاس بالتقصير جاز للدائنين النظر في الصلح أو تأجيل النظر فيه.$cc1343$, '1999-10-01', 'active' FROM ins_art_law17_1999_670;

WITH ins_art_law17_1999_671 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 671, $cc1344$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الخامس: انتهاء التفليسة$cc1344$, $cc1345$1- يجوز أن يتضمن الصلح منح المدين آجلا لوفاء الديون. كما يجوز أن يتضمن إبراءه من جزء من الدين.
2- ويجوز أن يعقد الصلح بشرط الوفاء إذا أيسر المدين خلال مدة تعين في عقد الصلح، على ألا تجاوز خمس سنوات من تاريخ التصديق على الصلح، ولا يعتبر المدين قد ايسر إلا إذا زادت قيمة موجوداته على ديونه بما يعادل عشرة في المائة على الأقل.
3- وللدائنين أن يشترطوا تقديم كفيل أو اكثر لضمان تنفيذ شروط الصلح.$cc1345$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1345$1- يجوز أن يتضمن الصلح منح المدين آجلا لوفاء الديون. كما يجوز أن يتضمن إبراءه من جزء من الدين.
2- ويجوز أن يعقد الصلح بشرط الوفاء إذا أيسر المدين خلال مدة تعين في عقد الصلح، على ألا تجاوز خمس سنوات من تاريخ التصديق على الصلح، ولا يعتبر المدين قد ايسر إلا إذا زادت قيمة موجوداته على ديونه بما يعادل عشرة في المائة على الأقل.
3- وللدائنين أن يشترطوا تقديم كفيل أو اكثر لضمان تنفيذ شروط الصلح.$cc1345$, '1999-10-01', 'active' FROM ins_art_law17_1999_671;

WITH ins_art_law17_1999_672 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 672, $cc1346$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الخامس: انتهاء التفليسة$cc1346$, $cc1347$1- يجوز لكل دائن له حق الاشتراك في عمل الصلح أن يبلغ قاضي التفليسة كتابة بما لديه من اعتراض على الصلح واسبابه وذلك خلال عشرة أيام من تاريخ التوقيع على محضر الصلح.
2- وعلى قاضي التفليسة خلال ثلاثة أيام من تاريخ انقضاء الميعاد المنصوص عليه في الفقرة السابقة أن يرسل محضر الصلح إلى المحكمة التي شهر الإفلاس للتصديق على الصلح، وذلك مع تقرير من القاضي عن حالة التفليسة ورأيه في شروط الصلح وبيان بالاعتراضات التي قدمت على الصلح وأسبابها.$cc1347$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1347$1- يجوز لكل دائن له حق الاشتراك في عمل الصلح أن يبلغ قاضي التفليسة كتابة بما لديه من اعتراض على الصلح واسبابه وذلك خلال عشرة أيام من تاريخ التوقيع على محضر الصلح.
2- وعلى قاضي التفليسة خلال ثلاثة أيام من تاريخ انقضاء الميعاد المنصوص عليه في الفقرة السابقة أن يرسل محضر الصلح إلى المحكمة التي شهر الإفلاس للتصديق على الصلح، وذلك مع تقرير من القاضي عن حالة التفليسة ورأيه في شروط الصلح وبيان بالاعتراضات التي قدمت على الصلح وأسبابها.$cc1347$, '1999-10-01', 'active' FROM ins_art_law17_1999_672;

WITH ins_art_law17_1999_673 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 673, $cc1348$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الخامس: انتهاء التفليسة$cc1348$, $cc1349$1- يقوم قلم كتاب المحكمة بإخطار المفلس والدائنين الذين قدموا اعتراضات على الصلح بتاريخ الجلسة التي حددت للنظر في هذه الاعتراضات وفي طلب التصديق على الصلح.
2- وتفصل المحكمة في الاعتراضات وفي طلب التصديق على الصلح بحكم واحد يكون نهائيا سواء أكان بقبول التصديق على الصلح أم برفض التصديق عليه.
3- ويجوز للمحكمة أن ترفض التصديق على الصلح ولو لم يقدم بشأنه أي اعتراض وذلك إذا وجدت أسباب تتصل بالمصلحة العامة أو كانت مصلحة الدائنين تبرر ذلك.
4- وتعين المحكمة في حكم التصديق على الصلح مراقبا أو اكثر للإشراف على تنفيذ شروط الصلح.
5- وإذا رفضت المحكمة الاعتراض على الصلح جاز لها الحكم على المعترض بغرامة لا تقل عن ألف جنيه ولا تجاوز خمسة آلاف جنيه إذا تبين انه تعمد تأخير وقوع الصلح.$cc1349$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1349$1- يقوم قلم كتاب المحكمة بإخطار المفلس والدائنين الذين قدموا اعتراضات على الصلح بتاريخ الجلسة التي حددت للنظر في هذه الاعتراضات وفي طلب التصديق على الصلح.
2- وتفصل المحكمة في الاعتراضات وفي طلب التصديق على الصلح بحكم واحد يكون نهائيا سواء أكان بقبول التصديق على الصلح أم برفض التصديق عليه.
3- ويجوز للمحكمة أن ترفض التصديق على الصلح ولو لم يقدم بشأنه أي اعتراض وذلك إذا وجدت أسباب تتصل بالمصلحة العامة أو كانت مصلحة الدائنين تبرر ذلك.
4- وتعين المحكمة في حكم التصديق على الصلح مراقبا أو اكثر للإشراف على تنفيذ شروط الصلح.
5- وإذا رفضت المحكمة الاعتراض على الصلح جاز لها الحكم على المعترض بغرامة لا تقل عن ألف جنيه ولا تجاوز خمسة آلاف جنيه إذا تبين انه تعمد تأخير وقوع الصلح.$cc1349$, '1999-10-01', 'active' FROM ins_art_law17_1999_673;

WITH ins_art_law17_1999_674 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 674, $cc1350$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الخامس: انتهاء التفليسة$cc1350$, $cc1351$تسرى شروط الصلح على الدائنين الذين تتألف منهم جماعة الدائنين ولو لم يشتركوا في إجراءات الصلح أو اشتركوا فيها ولم يوافقوا عليه.$cc1351$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1351$تسرى شروط الصلح على الدائنين الذين تتألف منهم جماعة الدائنين ولو لم يشتركوا في إجراءات الصلح أو اشتركوا فيها ولم يوافقوا عليه.$cc1351$, '1999-10-01', 'active' FROM ins_art_law17_1999_674;

WITH ins_art_law17_1999_675 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 675, $cc1352$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الخامس: انتهاء التفليسة$cc1352$, $cc1353$1- يشهر الحكم الصادر بالتصديق على الصلح بالكيفية التي يشهر بها حكم الإفلاس، ويشتمل الملخص الذي ينشر في الصحف على اسم المدين وموطنه ورقم قيده في السجل التجاري وتاريخ حكم التصديق على الصلح وملخص بأهم شروط الصلح.
2- وعلى أمين التفليسة خلال عشرة أيام من تاريخ صدور الحكم بالتصديق على الصلح قيد ملخصه باسم مراقب الصلح بوصفه نائبا عن الدائنين في كل مكتب للشهر العقاري يقع في دائرته عقار للمفلس، ويترتب على هذا القيد إنشاء رهن على العقارات المذكورة لضمان حقوق الدائنين الذي يسرى عليهم الصلح ما لم يتفق في الصلح على غير ذلك، ويقوم المراقب بشطب الرهن بعد تنفيذ شروط الصلح.
3- وكذلك يجب على أمين التفليسة خلال الميعاد المذكور في الفقرة السابقة قيد ملخص حكم التصديق على الصلح باسم المراقب بوصفه نائبا عن الدائنين في مكتب السجل التجاري الذي يقع في دائرته متجر المفلس وفي كل مكتب للسجل المذكور يكون للمفلس في دائرته فرع أو مكتب أو وكالة، ويترتب على هذا القيد إنشاء رهن على المتجر لضمان حقوق الدائنين الذين يسرى عليهم الصلح ما لم يتفق في الصلح على غير ذلك، ويقوم المراقب بشطب الرهن بعد تنفيذ شروط الصلح، وتسرى في شأن هذا الرهن الأحكام الخاصة برهن المتجر.$cc1353$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1353$1- يشهر الحكم الصادر بالتصديق على الصلح بالكيفية التي يشهر بها حكم الإفلاس، ويشتمل الملخص الذي ينشر في الصحف على اسم المدين وموطنه ورقم قيده في السجل التجاري وتاريخ حكم التصديق على الصلح وملخص بأهم شروط الصلح.
