3- وكذلك يجب على أمين التفليسة خلال الميعاد المذكور في الفقرة السابقة قيد ملخص حكم التصديق على الصلح باسم المراقب بوصفه نائبا عن الدائنين في مكتب السجل التجاري الذي يقع في دائرته متجر المفلس وفي كل مكتب للسجل المذكور يكون للمفلس في دائرته فرع أو مكتب أو وكالة، ويترتب على هذا القيد إنشاء رهن على المتجر لضمان حقوق الدائنين الذين يسرى عليهم الصلح ما لم يتفق في الصلح على غير ذلك، ويقوم المراقب بشطب الرهن بعد تنفيذ شروط الصلح، وتسرى في شأن هذا الرهن الأحكام الخاصة برهن المتجر.$cc1353$, '1999-10-01', 'active' FROM ins_art_law17_1999_675;

WITH ins_art_law17_1999_676 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 676, $cc1354$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الخامس: انتهاء التفليسة$cc1354$, $cc1355$1- فيما عدا سقوط الحقوق المشار إليها في المادة 588 من هذا القانون تزول جميع آثار الإفلاس بصدور حكم التصديق على الصلح.
2- وعلى أمين التفليسة أن يقدم حسابا ختاميا، وتحصل مناقشة هذا الحساب بحضور قاضي التفليسة.
3- تنتهي مهمة أمين التفليسة ويستلم المفلس أمواله ودفاتره وأوراقه منه بموجب إيصال، ولا يكون أمين التفليسة مسئولا عن هذه الأشياء إذا لم يستلمها المفلس خلال سنة من تاريخ إقرار الحساب الختامي.
4- ويحرر قاضي التفليسة محضرا بجميع ما تقدم، وإذا قام نزاع فصل فيه.$cc1355$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1355$1- فيما عدا سقوط الحقوق المشار إليها في المادة 588 من هذا القانون تزول جميع آثار الإفلاس بصدور حكم التصديق على الصلح.
2- وعلى أمين التفليسة أن يقدم حسابا ختاميا، وتحصل مناقشة هذا الحساب بحضور قاضي التفليسة.
3- تنتهي مهمة أمين التفليسة ويستلم المفلس أمواله ودفاتره وأوراقه منه بموجب إيصال، ولا يكون أمين التفليسة مسئولا عن هذه الأشياء إذا لم يستلمها المفلس خلال سنة من تاريخ إقرار الحساب الختامي.
4- ويحرر قاضي التفليسة محضرا بجميع ما تقدم، وإذا قام نزاع فصل فيه.$cc1355$, '1999-10-01', 'active' FROM ins_art_law17_1999_676;

WITH ins_art_law17_1999_677 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 677, $cc1356$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الخامس: انتهاء التفليسة$cc1356$, $cc1357$1- يبطل الصلح إذا صدر بعد التصديق عليه حكم بإدانة المفلس في إحدى جرائم الإفلاس بالتدليس.
2- وكذلك يبطل الصلح إذا ظهر بعد التصديق عليه تدليس ناشئ عن إخفاء موجودات المفلس أو المبالغة في ديونه، وفي هذه الحالة يجب أن يكون طلب إبطال الصلح خلال ستة اشهر من اليوم الذي يظهر فيه التدليس وإلا كان الطلب غير مقبول، وفي جميع الأحوال لا يكون طلب إبطال الصلح مقبولا إذا قدم بعد انقضاء سنتين من تاريخ التصديق على الصلح.
3- يترتب على إبطال الصلح براءة ذمة الكفيل الذي يضمن تنفيذ شروطه.
4- تختص المحكمة التي أصدرت حكم شهر الإفلاس بنظر دعوى إبطال الصلح.$cc1357$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1357$1- يبطل الصلح إذا صدر بعد التصديق عليه حكم بإدانة المفلس في إحدى جرائم الإفلاس بالتدليس.
2- وكذلك يبطل الصلح إذا ظهر بعد التصديق عليه تدليس ناشئ عن إخفاء موجودات المفلس أو المبالغة في ديونه، وفي هذه الحالة يجب أن يكون طلب إبطال الصلح خلال ستة اشهر من اليوم الذي يظهر فيه التدليس وإلا كان الطلب غير مقبول، وفي جميع الأحوال لا يكون طلب إبطال الصلح مقبولا إذا قدم بعد انقضاء سنتين من تاريخ التصديق على الصلح.
3- يترتب على إبطال الصلح براءة ذمة الكفيل الذي يضمن تنفيذ شروطه.
4- تختص المحكمة التي أصدرت حكم شهر الإفلاس بنظر دعوى إبطال الصلح.$cc1357$, '1999-10-01', 'active' FROM ins_art_law17_1999_677;

WITH ins_art_law17_1999_678 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 678, $cc1358$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الخامس: انتهاء التفليسة$cc1358$, $cc1359$إذا بدأ التحقيق مع المفلس في جريمة الإفلاس بالتدليس بعد التصديق على الصلح أو إذا أقيمت عليه الدعوى الجنائية في هذه الجريمة بعد التصديق على الصلح، جاز للمحكمة التي أصدرت حكم شهر الإفلاس، بناء على طلب النيابة العامة أو كل ذي مصلحة، أن تأمر باتخاذ ما تراه من تدابير للمحافظة على أموال المدين، وتلغى هذه التدابير، بحكم القانون، إذا تقرر حفظ التحقيق أو تقرر بأن لا وجه لاقامة الدعوى أو حكم ببراءة المفلس.$cc1359$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1359$إذا بدأ التحقيق مع المفلس في جريمة الإفلاس بالتدليس بعد التصديق على الصلح أو إذا أقيمت عليه الدعوى الجنائية في هذه الجريمة بعد التصديق على الصلح، جاز للمحكمة التي أصدرت حكم شهر الإفلاس، بناء على طلب النيابة العامة أو كل ذي مصلحة، أن تأمر باتخاذ ما تراه من تدابير للمحافظة على أموال المدين، وتلغى هذه التدابير، بحكم القانون، إذا تقرر حفظ التحقيق أو تقرر بأن لا وجه لاقامة الدعوى أو حكم ببراءة المفلس.$cc1359$, '1999-10-01', 'active' FROM ins_art_law17_1999_678;

WITH ins_art_law17_1999_679 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 679, $cc1360$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الخامس: انتهاء التفليسة$cc1360$, $cc1361$1- إذا لم يقم المفلس بتنفيذ شروط الصلح جاز طلب فسخه من المحكمة التي أصدرت حكم شهر الإفلاس.
2- ولا يترتب على فسخ الصلح براءة ذمة الكفيل الذي يضمن تنفيذ شروطه، ويجب تكليف هذا الكفيل بحضور الجلسة التي ينظر فيها طلب فسخ الصلح.$cc1361$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1361$1- إذا لم يقم المفلس بتنفيذ شروط الصلح جاز طلب فسخه من المحكمة التي أصدرت حكم شهر الإفلاس.
2- ولا يترتب على فسخ الصلح براءة ذمة الكفيل الذي يضمن تنفيذ شروطه، ويجب تكليف هذا الكفيل بحضور الجلسة التي ينظر فيها طلب فسخ الصلح.$cc1361$, '1999-10-01', 'active' FROM ins_art_law17_1999_679;

WITH ins_art_law17_1999_680 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 680, $cc1362$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الخامس: انتهاء التفليسة$cc1362$, $cc1363$1- تعين المحكمة في الحكم الصادر ببطلان الصلح أو فسخه قاضيا للتفليسة وأمينا لها، وللمحكمة أن تأمر بوضع الأختام على أموال المفلس.
2- وعلى أمين التفليسة خلال خمسة أيام من تاريخ صدور الحكم ببطلان الصلح أو بفسخه أن ينشر ملخص هذا الحكم في صحيفة يومية يعينها قاضي التفليسة.
3- ويقوم أمين التفليسة، بحضور القاضي أو من يندبه لذلك، بعمل جرد تكميلي لأموال المفلس ويضع ميزانية إضافية.
4- ويدعو أمين التفليسة الدائنين الجدد لتقديم مستندات ديونهم لتحقيقها وفقا لإجراءات تحقيق الديون.
5- وتحقق فورا الديون الجديدة دون ان يعاد تحقيق الديون التي سبق قبولها، ومع ذلك يجب استبعاد الديون التي دفعت بكاملها وتخفيض الديون التي دفع جزء منها.$cc1363$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1363$1- تعين المحكمة في الحكم الصادر ببطلان الصلح أو فسخه قاضيا للتفليسة وأمينا لها، وللمحكمة أن تأمر بوضع الأختام على أموال المفلس.
2- وعلى أمين التفليسة خلال خمسة أيام من تاريخ صدور الحكم ببطلان الصلح أو بفسخه أن ينشر ملخص هذا الحكم في صحيفة يومية يعينها قاضي التفليسة.
3- ويقوم أمين التفليسة، بحضور القاضي أو من يندبه لذلك، بعمل جرد تكميلي لأموال المفلس ويضع ميزانية إضافية.
4- ويدعو أمين التفليسة الدائنين الجدد لتقديم مستندات ديونهم لتحقيقها وفقا لإجراءات تحقيق الديون.
5- وتحقق فورا الديون الجديدة دون ان يعاد تحقيق الديون التي سبق قبولها، ومع ذلك يجب استبعاد الديون التي دفعت بكاملها وتخفيض الديون التي دفع جزء منها.$cc1363$, '1999-10-01', 'active' FROM ins_art_law17_1999_680;

WITH ins_art_law17_1999_681 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 681, $cc1364$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الخامس: انتهاء التفليسة$cc1364$, $cc1365$1- التصرفات الحاصلة من المدين بعد التصديق على الصلح وقبل إبطاله أو فسخه تكون نافذة في حق الدائنين، ولا يجوز لهم طلب عدم نفاذها في حقهم إلا طبقا للأحكام المنصوص عليها في المادة 237 من القانون المدني.
2- تسقط دعوى عدم نفاذ التصرف المنصوص عليها في الفقرة السابقة بمضي سنتين من تاريخ إبطال الصلح او فسخه.$cc1365$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1365$1- التصرفات الحاصلة من المدين بعد التصديق على الصلح وقبل إبطاله أو فسخه تكون نافذة في حق الدائنين، ولا يجوز لهم طلب عدم نفاذها في حقهم إلا طبقا للأحكام المنصوص عليها في المادة 237 من القانون المدني.
2- تسقط دعوى عدم نفاذ التصرف المنصوص عليها في الفقرة السابقة بمضي سنتين من تاريخ إبطال الصلح او فسخه.$cc1365$, '1999-10-01', 'active' FROM ins_art_law17_1999_681;

WITH ins_art_law17_1999_682 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 682, $cc1366$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الخامس: انتهاء التفليسة$cc1366$, $cc1367$1- تعود إلى الدائنين بعد إبطال الصلح أو فسخه ديونهم كاملة وذلك بالنسبة إلى المفلس فقط.
2- ويشترك هؤلاء الدائنون في جماعة الدائنين بديونهم الأصلية كاملة إذا لم يكونوا قد قبضوا شيئا من القدر الذي تقرر لهم في الصلح وإلا وجب تخفيض ديونهم الأصلية بنسبة ما حصلوا عليه من القدر المذكور.
3- تسرى الأحكام المذكورة في الفقرتين السابقتين في حالة شهر إفلاس المدين مرة أخرى قبل أن يصدر حكم بإبطال الصلح أو بفسخه.
3- الصلح مع التخلي عن الأموال$cc1367$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1367$1- تعود إلى الدائنين بعد إبطال الصلح أو فسخه ديونهم كاملة وذلك بالنسبة إلى المفلس فقط.
2- ويشترك هؤلاء الدائنون في جماعة الدائنين بديونهم الأصلية كاملة إذا لم يكونوا قد قبضوا شيئا من القدر الذي تقرر لهم في الصلح وإلا وجب تخفيض ديونهم الأصلية بنسبة ما حصلوا عليه من القدر المذكور.
3- تسرى الأحكام المذكورة في الفقرتين السابقتين في حالة شهر إفلاس المدين مرة أخرى قبل أن يصدر حكم بإبطال الصلح أو بفسخه.
3- الصلح مع التخلي عن الأموال$cc1367$, '1999-10-01', 'active' FROM ins_art_law17_1999_682;

WITH ins_art_law17_1999_683 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 683, $cc1368$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الخامس: انتهاء التفليسة$cc1368$, $cc1369$1- يجوز أن يعقد الصلح على أن يتخلى المدين عن أمواله كلها أو بعضها لبيعها وتوزيع ثمنها على الدائنين.
2- يتبع فيما يتعلق بشروط هذا الصلح وآثاره وإبطاله وفسخه الأحكام الخاصة بالصلح القضائي ومع ذلك يظل المدين ممنوعا من التصرف في الأموال التي تخلى عنها وادارتها.
3- تباع الأموال التي يتخلى عنها المدين ويوزع ثمنها طبقا للقواعد المقررة لبيع وتوزيع أموال المفلس في حالة الاتحاد.
4- إذا كان الثمن عن بيع الأموال التي تخلى عنها المدين يجاوز الديون المطلوبة منه وجب رد المقدار الزائد إليه.
4- اتحاد الدائنين$cc1369$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1369$1- يجوز أن يعقد الصلح على أن يتخلى المدين عن أمواله كلها أو بعضها لبيعها وتوزيع ثمنها على الدائنين.
2- يتبع فيما يتعلق بشروط هذا الصلح وآثاره وإبطاله وفسخه الأحكام الخاصة بالصلح القضائي ومع ذلك يظل المدين ممنوعا من التصرف في الأموال التي تخلى عنها وادارتها.
3- تباع الأموال التي يتخلى عنها المدين ويوزع ثمنها طبقا للقواعد المقررة لبيع وتوزيع أموال المفلس في حالة الاتحاد.
4- إذا كان الثمن عن بيع الأموال التي تخلى عنها المدين يجاوز الديون المطلوبة منه وجب رد المقدار الزائد إليه.
4- اتحاد الدائنين$cc1369$, '1999-10-01', 'active' FROM ins_art_law17_1999_683;

WITH ins_art_law17_1999_684 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 684, $cc1370$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الخامس: انتهاء التفليسة$cc1370$, $cc1371$يصير الدائنون في حالة اتحاد بحكم القانون في الحالات الآتية:
(أ) إذا لم يطلب المدين الصلح.
(ب) إذا طلب المدين الصلح ورفضه الدائنون أو رفضت المحكمة التصديق عليه.
(ج) إذا حصل المدين على الصلح ثم ابطل.$cc1371$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1371$يصير الدائنون في حالة اتحاد بحكم القانون في الحالات الآتية:
(أ) إذا لم يطلب المدين الصلح.
(ب) إذا طلب المدين الصلح ورفضه الدائنون أو رفضت المحكمة التصديق عليه.
(ج) إذا حصل المدين على الصلح ثم ابطل.$cc1371$, '1999-10-01', 'active' FROM ins_art_law17_1999_684;

WITH ins_art_law17_1999_685 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 685, $cc1372$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الخامس: انتهاء التفليسة$cc1372$, $cc1373$1- يدعو قاضي التفليسة الدائنين إثر قيام حالة الاتحاد للمداولة في شئون التفليسة والنظر في إبقاء أمين التفليسة أو تغييره، ويسمى في هذه المرحلة أمين الاتحاد، وللدائنين أصحاب التأمينات العينية المقررة على أموال المفلس الاشتراك في هذه المداولات والتصويت دون أن يترتب على ذلك سقوط تأميناتهم.
2- إذا قررت أغلبية الدائنين الحاضرين تغيير أمين التفليسة وجب على قاضي التفليسة تعيين غيره فورا.
3- على أمين التفليسة السابق أن يقدم إلى أمين الاتحاد في الميعاد الذي يعينه قاضي التفليسة وبحضوره حسابا عن إدارته ويخطر المدين بميعاد تقديم الحساب.$cc1373$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1373$1- يدعو قاضي التفليسة الدائنين إثر قيام حالة الاتحاد للمداولة في شئون التفليسة والنظر في إبقاء أمين التفليسة أو تغييره، ويسمى في هذه المرحلة أمين الاتحاد، وللدائنين أصحاب التأمينات العينية المقررة على أموال المفلس الاشتراك في هذه المداولات والتصويت دون أن يترتب على ذلك سقوط تأميناتهم.
2- إذا قررت أغلبية الدائنين الحاضرين تغيير أمين التفليسة وجب على قاضي التفليسة تعيين غيره فورا.
3- على أمين التفليسة السابق أن يقدم إلى أمين الاتحاد في الميعاد الذي يعينه قاضي التفليسة وبحضوره حسابا عن إدارته ويخطر المدين بميعاد تقديم الحساب.$cc1373$, '1999-10-01', 'active' FROM ins_art_law17_1999_685;

WITH ins_art_law17_1999_686 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 686, $cc1374$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الخامس: انتهاء التفليسة$cc1374$, $cc1375$1- يؤخذ رأي الدائنين خلال الاجتماع المنصوص عليه في المادة السابقة في أمر تقرير إعانة من أموال التفليسة للمفلس أو لمن يعولهم.
2- إذا وافقت أغلبية الدائنين الحاضرين على تقرير الإعانة للمفلس أو لمن يعولهم وجب على قاضي التفليسة، بعد اخذ رأي أمين الاتحاد ورأي المراقب، تعيين مقدار الإعانة.
3- ويجوز لأمين الاتحاد، دون غيره، الطعن أمام المحكمة في قرار قاضي التفليسة بتعيين مقدار الإعانة، وفي هذه الحالة يصرف نصف الإعانة لمن تقررت له إلى حين الفصل في الطعن.$cc1375$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1375$1- يؤخذ رأي الدائنين خلال الاجتماع المنصوص عليه في المادة السابقة في أمر تقرير إعانة من أموال التفليسة للمفلس أو لمن يعولهم.
2- إذا وافقت أغلبية الدائنين الحاضرين على تقرير الإعانة للمفلس أو لمن يعولهم وجب على قاضي التفليسة، بعد اخذ رأي أمين الاتحاد ورأي المراقب، تعيين مقدار الإعانة.
3- ويجوز لأمين الاتحاد، دون غيره، الطعن أمام المحكمة في قرار قاضي التفليسة بتعيين مقدار الإعانة، وفي هذه الحالة يصرف نصف الإعانة لمن تقررت له إلى حين الفصل في الطعن.$cc1375$, '1999-10-01', 'active' FROM ins_art_law17_1999_686;

WITH ins_art_law17_1999_687 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 687, $cc1376$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الخامس: انتهاء التفليسة$cc1376$, $cc1377$1- لا يجوز لأمين الإتحاد الإستمرار في تجارة المدين ولو كان مأذونا في ذلك من قبل إلا بعد الحصول على تفويض يصدر بأغلبية تمثل ثلاثة أرباع الدائنين عددا ومبلغا، ويجب أن يعين في التفويض مدته وسلطة أمين الاتحاد والمبالغ التي يجوز له استبقاؤها تحت يده لتشغيل التجارة.
2- ولا يجوز تنفيذ التفويض بالاستمرار في التجارة إلا بعد تصديق قاضي التفليسة عليه.
3- وإذا نشأت عن الاستمرار في التجارة التزامات تزيد على أموال الاتحاد وكان الدائنون الذين وافقوا على الاستمرار في التجارة مسئولين في أموالهم الخاصة دون تضامن بينهم عن الزيادة بشرط أن تكون ناشئة عن أعمال تدخل في حدود التفويض الصادر منهم، وتكون مسئولية كل دائن بنسبة دينه.$cc1377$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1377$1- لا يجوز لأمين الإتحاد الإستمرار في تجارة المدين ولو كان مأذونا في ذلك من قبل إلا بعد الحصول على تفويض يصدر بأغلبية تمثل ثلاثة أرباع الدائنين عددا ومبلغا، ويجب أن يعين في التفويض مدته وسلطة أمين الاتحاد والمبالغ التي يجوز له استبقاؤها تحت يده لتشغيل التجارة.
2- ولا يجوز تنفيذ التفويض بالاستمرار في التجارة إلا بعد تصديق قاضي التفليسة عليه.
3- وإذا نشأت عن الاستمرار في التجارة التزامات تزيد على أموال الاتحاد وكان الدائنون الذين وافقوا على الاستمرار في التجارة مسئولين في أموالهم الخاصة دون تضامن بينهم عن الزيادة بشرط أن تكون ناشئة عن أعمال تدخل في حدود التفويض الصادر منهم، وتكون مسئولية كل دائن بنسبة دينه.$cc1377$, '1999-10-01', 'active' FROM ins_art_law17_1999_687;

WITH ins_art_law17_1999_688 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 688, $cc1378$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الخامس: انتهاء التفليسة$cc1378$, $cc1379$1- لأمين الإتحاد بيع منقولات المفلس ومتجره واستيفاء ما له من حقوق أما بيع عقارات المفلس فيجب أن يتم بإذن من قاضي التفليسة.
2- إذا لم يكن قد بدئ في التنفيذ على عقارات المفلس قبل قيام حالة الاتحاد كان لأمين الاتحاد دون غيره حق التنفيذ عليها، ويجب عليه البدء في ذلك خلال الأيام العشرة التالية لقيام حالة الاتحاد ما لم يأمر قاضي التفليسة بتأجيل التنفيذ.
3- ويجوز لأمين الإتحاد الصلح أو قبول التحكيم في جميع حقوق المفلس بشرط مراعاة الأحكام المنصوص عليها في المادة 644 من هذا القانون.
[ملاحظة توثيقية: صححت الفقرة 3 من المادة (688) بالاستدراك المنشور بالجريدة الرسمية- العدد 38 (مكرر) في 2000/9/27.]$cc1379$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1379$1- لأمين الإتحاد بيع منقولات المفلس ومتجره واستيفاء ما له من حقوق أما بيع عقارات المفلس فيجب أن يتم بإذن من قاضي التفليسة.
2- إذا لم يكن قد بدئ في التنفيذ على عقارات المفلس قبل قيام حالة الاتحاد كان لأمين الاتحاد دون غيره حق التنفيذ عليها، ويجب عليه البدء في ذلك خلال الأيام العشرة التالية لقيام حالة الاتحاد ما لم يأمر قاضي التفليسة بتأجيل التنفيذ.
3- ويجوز لأمين الإتحاد الصلح أو قبول التحكيم في جميع حقوق المفلس بشرط مراعاة الأحكام المنصوص عليها في المادة 644 من هذا القانون.
[ملاحظة توثيقية: صححت الفقرة 3 من المادة (688) بالاستدراك المنشور بالجريدة الرسمية- العدد 38 (مكرر) في 2000/9/27.]$cc1379$, '1999-10-01', 'active' FROM ins_art_law17_1999_688;

WITH ins_art_law17_1999_689 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 689, $cc1380$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الخامس: انتهاء التفليسة$cc1380$, $cc1381$1- يجرى بيع منقولات المفلس بالكيفية التي يعينها قاضي التفليسة.
2- ويجرى بيع العقارات وفقا للأحكام المنصوص عليها في قانون المرافعات المدنية والتجارية بشأن بيع عقار المفلس.
3- ولا يجوز لأمين الاتحاد بيع موجودات التفليسة دفعة واحدة مقابل مبلغ إجمالي إلا بعد إستئذان قاضي التفليسة.
4- يجوز لكل ذي مصلحة الطعن في قرار قاضي التفليسة بشأن تعيين كيفية بيع منقولات المفلس أو الإذن ببيع أمواله دفعة واحدة مقابل مبلغ إجمالي، ويترتب على الطعن وقف تنفيذ القرار إلا إذا أمرت المحكمة بغير ذلك.$cc1381$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
