2- ويقدم أمين الاتحاد إلى قاضي التفليسة بيانا شهريا عن حالة التصفية ومقدار المبالغ المودعة ولا يجوز سحب هذه المبالغ إلا بأمر من قاضي التفليسة او بشيك يوقعه القاضي وأمين الاتحاد.$cc1383$
