WITH ins_art_law17_1999_694 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 694, $cc1390$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الخامس: انتهاء التفليسة$cc1390$, $cc1391$إذا انقضت ستة اشهر من تاريخ قيام حالة الاتحاد دون إنجاز التصفية وجب على أمين الاتحاد أن يقدم إلى قاضي التفليسة تقريرا عن حالة التصفية وأسباب التأخير في إنجازها، ويرسل لقاضي التفليسة هذا التقرير إلى الدائنين مع دعوتهم للاجتماع لمناقشته، ويكون الإجراء كذلك كلما انقضت ستة اشهر دون أن ينجز أمين الاتحاد أعمال التصفية.$cc1391$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1391$إذا انقضت ستة اشهر من تاريخ قيام حالة الاتحاد دون إنجاز التصفية وجب على أمين الاتحاد أن يقدم إلى قاضي التفليسة تقريرا عن حالة التصفية وأسباب التأخير في إنجازها، ويرسل لقاضي التفليسة هذا التقرير إلى الدائنين مع دعوتهم للاجتماع لمناقشته، ويكون الإجراء كذلك كلما انقضت ستة اشهر دون أن ينجز أمين الاتحاد أعمال التصفية.$cc1391$, '1999-10-01', 'active' FROM ins_art_law17_1999_694;

WITH ins_art_law17_1999_695 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 695, $cc1392$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الخامس: انتهاء التفليسة$cc1392$, $cc1393$1- يقدم أمين الإتحاد بعد الانتهاء من أعمال التصفية حسابا ختاميا إلى قاضي التفليسة، ويرسل القاضي هذا الحساب إلى الدائنين مع دعوتهم للاجتماع لمناقشته، ويخطر المفلس بهذا الاجتماع وله حضوره.
2- وينحل الاتحاد وتعتبر التفليسة منتهية بحكم القانون بعد المصادقة على الحساب المشار إليه في الفقرة السابقة.
3- ويكون أمين الاتحاد مسئولا لمدة سنة من تاريخ انتهاء التفليسة عن الدفاتر والمستندات والأوراق المسلمة إليه.$cc1393$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1393$1- يقدم أمين الإتحاد بعد الانتهاء من أعمال التصفية حسابا ختاميا إلى قاضي التفليسة، ويرسل القاضي هذا الحساب إلى الدائنين مع دعوتهم للاجتماع لمناقشته، ويخطر المفلس بهذا الاجتماع وله حضوره.
2- وينحل الاتحاد وتعتبر التفليسة منتهية بحكم القانون بعد المصادقة على الحساب المشار إليه في الفقرة السابقة.
3- ويكون أمين الاتحاد مسئولا لمدة سنة من تاريخ انتهاء التفليسة عن الدفاتر والمستندات والأوراق المسلمة إليه.$cc1393$, '1999-10-01', 'active' FROM ins_art_law17_1999_695;

WITH ins_art_law17_1999_696 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 696, $cc1394$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الخامس: انتهاء التفليسة$cc1394$, $cc1395$يعود الى كل دائن بعد انتهاء حالة الاتحاد الحق في التنفيذ على المدين للحصول على الباقي من دينه، ويعتبر قبول الدين في التفليسة بمثابة حكم نهائي فيما يتعلق بهذا التنفيذ.$cc1395$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
