INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1395$يعود الى كل دائن بعد انتهاء حالة الاتحاد الحق في التنفيذ على المدين للحصول على الباقي من دينه، ويعتبر قبول الدين في التفليسة بمثابة حكم نهائي فيما يتعلق بهذا التنفيذ.$cc1395$, '1999-10-01', 'active' FROM ins_art_law17_1999_696;

WITH ins_art_law17_1999_697 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 697, $cc1396$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل السادس: الإجراءات المختصرة$cc1396$, $cc1397$إذا تبين بعد جرد أموال المفلس أن قيمتها لا تزيد على خمسين ألف جنيه جاز لقاضي التفليسة من تلقاء نفسه او بناء على طلب من أمين التفليسة أو أحد الدائنين أن يأمر بالسير في إجراءات التفليسة وفقا لاحكام الإفلاس المنصوص عليها في هذا الباب معدلة كما يلي:
(أ) تخفض إلى النصف المواعيد المنصوص عليها في الفقرة الأولى من المادة 649 والمادة 651 والفقرة الثانية من المادة 653 والمادة 654 والفقرة الثالثة من المادة 655 من هذا القانون.
(ب) تكون جميع قرارات قاضي التفليسة غير قابلة للطعن فيها.
(ج) لا يعين مراقب للتفليسة.
(د) في حالة المنازعة في الديون عند تحقيقها يدعى الدائنون للمداولة في الصلح خلال خمسة أيام من تاريخ الانتهاء من الفصل في المنازعة.
(هـ) يكون الصلح نافذا بمجرد الموافقة عليه في اجتماع الدائنين في هذا الاجتماع ولا يقبل أي اعتراض عليه.
(و) لا يغير أمين التفليسة عند قيام حالة الاتحاد.
(ز) لا يجرى إلا توزيع واحد على الدائنين بعد الانتهاء من بيع أموال التفليسة.$cc1397$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1397$إذا تبين بعد جرد أموال المفلس أن قيمتها لا تزيد على خمسين ألف جنيه جاز لقاضي التفليسة من تلقاء نفسه او بناء على طلب من أمين التفليسة أو أحد الدائنين أن يأمر بالسير في إجراءات التفليسة وفقا لاحكام الإفلاس المنصوص عليها في هذا الباب معدلة كما يلي:
(أ) تخفض إلى النصف المواعيد المنصوص عليها في الفقرة الأولى من المادة 649 والمادة 651 والفقرة الثانية من المادة 653 والمادة 654 والفقرة الثالثة من المادة 655 من هذا القانون.
(ب) تكون جميع قرارات قاضي التفليسة غير قابلة للطعن فيها.
(ج) لا يعين مراقب للتفليسة.
(د) في حالة المنازعة في الديون عند تحقيقها يدعى الدائنون للمداولة في الصلح خلال خمسة أيام من تاريخ الانتهاء من الفصل في المنازعة.
(هـ) يكون الصلح نافذا بمجرد الموافقة عليه في اجتماع الدائنين في هذا الاجتماع ولا يقبل أي اعتراض عليه.
(و) لا يغير أمين التفليسة عند قيام حالة الاتحاد.
(ز) لا يجرى إلا توزيع واحد على الدائنين بعد الانتهاء من بيع أموال التفليسة.$cc1397$, '1999-10-01', 'active' FROM ins_art_law17_1999_697;

WITH ins_art_law17_1999_698 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 698, $cc1398$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل السابع: إفلاس الشركات$cc1398$, $cc1399$تسرى على إفلاس الشركات الأحكام المذكورة في هذا الباب والقواعد التالية.$cc1399$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
