WITH ins_art_law17_1999_699 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 699, $cc1400$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل السابع: إفلاس الشركات$cc1400$, $cc1401$1- فيما عدا شركات المحاصة، تعد في حالة إفلاس، كل شركة اتخذت أحد الأشكال المنصوص عليها في قانون الشركات إذا توقفت عن دفع ديونها إثر اضطراب أعمالها المالية، ويلزم شهر إفلاسها بحكم يصدر بذلك.
2- ويجوز شهر إفلاس الشركة ولو كانت في دور التصفية.$cc1401$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1401$1- فيما عدا شركات المحاصة، تعد في حالة إفلاس، كل شركة اتخذت أحد الأشكال المنصوص عليها في قانون الشركات إذا توقفت عن دفع ديونها إثر اضطراب أعمالها المالية، ويلزم شهر إفلاسها بحكم يصدر بذلك.
2- ويجوز شهر إفلاس الشركة ولو كانت في دور التصفية.$cc1401$, '1999-10-01', 'active' FROM ins_art_law17_1999_699;

WITH ins_art_law17_1999_700 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 700, $cc1402$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل السابع: إفلاس الشركات$cc1402$, $cc1403$1- لا يجوز للممثل القانوني للشركة أن يطلب شهر إفلاسها إلا بعد الحصول على إذن بذلك من أغلبية الشركاء أو من الجمعية العامة حسب الأحوال.
2- تقدم الصحيفة المشار إليها في المادة 553 من هذا القانون إلى قلم كتاب المحكمة التي يقع في دائرتها المركز الرئيسي للشركة، فإذا كان هذا المركز موجودا خارج مصر وجب تقديم الصحيفة الى قلم كتاب المحكمة التي يقع في دائرتها مركز الإدارة المحلي.
[ملاحظة توثيقية: مصححة بالاستدراك المنشور بالجريدة الرسمية- العدد 38 (مكرر) في 1999/9/27.]
3- ويجب أن تشتمل الصحيفة على أسماء الشركاء المتضامنين الحاليين والذين خرجوا من الشركة بعد توقفها عن الدفع مع بيان موطن كل شريك متضامن وجنسيته وتاريخ خروجه من الشركة في السجل التجاري.$cc1403$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1403$1- لا يجوز للممثل القانوني للشركة أن يطلب شهر إفلاسها إلا بعد الحصول على إذن بذلك من أغلبية الشركاء أو من الجمعية العامة حسب الأحوال.
2- تقدم الصحيفة المشار إليها في المادة 553 من هذا القانون إلى قلم كتاب المحكمة التي يقع في دائرتها المركز الرئيسي للشركة، فإذا كان هذا المركز موجودا خارج مصر وجب تقديم الصحيفة الى قلم كتاب المحكمة التي يقع في دائرتها مركز الإدارة المحلي.
[ملاحظة توثيقية: مصححة بالاستدراك المنشور بالجريدة الرسمية- العدد 38 (مكرر) في 1999/9/27.]
3- ويجب أن تشتمل الصحيفة على أسماء الشركاء المتضامنين الحاليين والذين خرجوا من الشركة بعد توقفها عن الدفع مع بيان موطن كل شريك متضامن وجنسيته وتاريخ خروجه من الشركة في السجل التجاري.$cc1403$, '1999-10-01', 'active' FROM ins_art_law17_1999_700;

WITH ins_art_law17_1999_701 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 701, $cc1404$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل السابع: إفلاس الشركات$cc1404$, $cc1405$1- يجوز لدائني الشركة طلب شهر إفلاسها ولو كان شريكا فيها، أما الشركاء غير الدائنين فلا يجوز لهم بصفتهم الفردية طلب شهر إفلاس الشركة.
2- إذا طلب الدائن شهر إفلاس الشركة، وجب اختصام كافة الشركاء المتضامنين.$cc1405$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1405$1- يجوز لدائني الشركة طلب شهر إفلاسها ولو كان شريكا فيها، أما الشركاء غير الدائنين فلا يجوز لهم بصفتهم الفردية طلب شهر إفلاس الشركة.
2- إذا طلب الدائن شهر إفلاس الشركة، وجب اختصام كافة الشركاء المتضامنين.$cc1405$, '1999-10-01', 'active' FROM ins_art_law17_1999_701;

WITH ins_art_law17_1999_702 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 702, $cc1406$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل السابع: إفلاس الشركات$cc1406$, $cc1407$يجوز للمحكمة من تلقاء ذاتها أو بناء على طلب الشركة أن تؤجل النظر في طلب شهر إفلاسها لمدة لا تجاوز ثلاثة اشهر إذا كان من المحتمل دعم مركزها المالي أو إذا اقتضت مصلحة الاقتصاد القومي ذلك، وللمحكمة أن تأمر باتخاذ ما تراه من تدابير المحافظة على موجودات الشركة.$cc1407$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1407$يجوز للمحكمة من تلقاء ذاتها أو بناء على طلب الشركة أن تؤجل النظر في طلب شهر إفلاسها لمدة لا تجاوز ثلاثة اشهر إذا كان من المحتمل دعم مركزها المالي أو إذا اقتضت مصلحة الاقتصاد القومي ذلك، وللمحكمة أن تأمر باتخاذ ما تراه من تدابير المحافظة على موجودات الشركة.$cc1407$, '1999-10-01', 'active' FROM ins_art_law17_1999_702;

WITH ins_art_law17_1999_703 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 703, $cc1408$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل السابع: إفلاس الشركات$cc1408$, $cc1409$1- إذا شهر إفلاس الشركة وجب شهر إفلاس جميع الشركاء المتضامنين فيها، ويشمل شهر الإفلاس الشريك المتضامن الذي خرج من الشركة بعد توقفها عن الدفع إذا طلب شهر إفلاس الشركة قبل انقضاء سنة من تاريخ شهر خروج الشريك في السجل التجاري.
2- وتقضى المحكمة بحكم واحد بشهر إفلاس الشركة والشركاء المتضامنين ولو لم تكن مختصة بشهر إفلاس هؤلاء الشركاء.
3- وتعين المحكمة لتفليسة الشركة وتفليسات الشركاء المتضامنين قاضيا واحدا وأمينا واحدا أو اكثر، ومع ذلك تكون كل تفليسة مستقلة عن غيرها من التفليسات من حيث موجوداتها وخصومها وإدارتها وتحقيق ديونها وكيفية انتهائها.$cc1409$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1409$1- إذا شهر إفلاس الشركة وجب شهر إفلاس جميع الشركاء المتضامنين فيها، ويشمل شهر الإفلاس الشريك المتضامن الذي خرج من الشركة بعد توقفها عن الدفع إذا طلب شهر إفلاس الشركة قبل انقضاء سنة من تاريخ شهر خروج الشريك في السجل التجاري.
2- وتقضى المحكمة بحكم واحد بشهر إفلاس الشركة والشركاء المتضامنين ولو لم تكن مختصة بشهر إفلاس هؤلاء الشركاء.
3- وتعين المحكمة لتفليسة الشركة وتفليسات الشركاء المتضامنين قاضيا واحدا وأمينا واحدا أو اكثر، ومع ذلك تكون كل تفليسة مستقلة عن غيرها من التفليسات من حيث موجوداتها وخصومها وإدارتها وتحقيق ديونها وكيفية انتهائها.$cc1409$, '1999-10-01', 'active' FROM ins_art_law17_1999_703;

WITH ins_art_law17_1999_704 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 704, $cc1410$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل السابع: إفلاس الشركات$cc1410$, $cc1411$1- إذا طلب شهر إفلاس الشركة جاز للمحكمة أن تقضى أيضا بشهر إفلاس كل شخص قام تحت ستار هذه الشركة بأعمال تجارية لحسابه الخاص وتصرف في أموال الشركة كما لو كانت أمواله الخاصة.
2- وإذا تبين أن موجودات الشركة لا تكفى لوفاء 20% على الأقل من ديونها، جاز للمحكمة بناء على طلب قاضي التفليسة أن تقضى بإلزام أعضاء مجلس الإدارة أو المديرين كلهم أو بعضهم بالتضامن بينهم أو بغير تضامن بدفع ديون الشركة كلها أو بعضها إلا إذا اثبتوا انهم بذلوا في تدبير شئون الشركة عناية الرجل الحريص.
3- ويجوز للمحكمة من تلقاء ذاتها أو بناء على طلب قاضي التفليسة أن تقضى بإسقاط الحقوق المنصوص عليها في المادة 588 من هذا القانون عن أعضاء مجلس إدارة الشركة أو مديريها الذين ارتكبوا أخطاء جسيمة أدت إلى اضطراب أعمال الشركة وتوقفها عن الدفع.$cc1411$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1411$1- إذا طلب شهر إفلاس الشركة جاز للمحكمة أن تقضى أيضا بشهر إفلاس كل شخص قام تحت ستار هذه الشركة بأعمال تجارية لحسابه الخاص وتصرف في أموال الشركة كما لو كانت أمواله الخاصة.
2- وإذا تبين أن موجودات الشركة لا تكفى لوفاء 20% على الأقل من ديونها، جاز للمحكمة بناء على طلب قاضي التفليسة أن تقضى بإلزام أعضاء مجلس الإدارة أو المديرين كلهم أو بعضهم بالتضامن بينهم أو بغير تضامن بدفع ديون الشركة كلها أو بعضها إلا إذا اثبتوا انهم بذلوا في تدبير شئون الشركة عناية الرجل الحريص.
3- ويجوز للمحكمة من تلقاء ذاتها أو بناء على طلب قاضي التفليسة أن تقضى بإسقاط الحقوق المنصوص عليها في المادة 588 من هذا القانون عن أعضاء مجلس إدارة الشركة أو مديريها الذين ارتكبوا أخطاء جسيمة أدت إلى اضطراب أعمال الشركة وتوقفها عن الدفع.$cc1411$, '1999-10-01', 'active' FROM ins_art_law17_1999_704;

WITH ins_art_law17_1999_705 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 705, $cc1412$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل السابع: إفلاس الشركات$cc1412$, $cc1413$1- يقوم الممثل القانوني عن الشركة التي شهر إفلاسها مقامها في كل أمر يستلزم فيه القانون اخذ رأي المفلس أو حضوره، وعليه الحضور أمام قاضي التفليسة أو أمينها متى طلب منه ذلك والإدلاء بما يطلب منه من معلومات أو إيضاحات.$cc1413$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1413$1- يقوم الممثل القانوني عن الشركة التي شهر إفلاسها مقامها في كل أمر يستلزم فيه القانون اخذ رأي المفلس أو حضوره، وعليه الحضور أمام قاضي التفليسة أو أمينها متى طلب منه ذلك والإدلاء بما يطلب منه من معلومات أو إيضاحات.$cc1413$, '1999-10-01', 'active' FROM ins_art_law17_1999_705;

WITH ins_art_law17_1999_706 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 706, $cc1414$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل السابع: إفلاس الشركات$cc1414$, $cc1415$يجوز لأمين التفليسة بعد استئذان قاضي التفليسة أن يطالب الشركاء بدفع الباقي من حصصهم في رأس المال ولو لم يحل ميعاد استحقاقه، ولقاضي التفليسة أن يأمر بقصر هذه المطالبة على القدر اللازم لوفاء ديون الشركة.$cc1415$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
