)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1415$يجوز لأمين التفليسة بعد استئذان قاضي التفليسة أن يطالب الشركاء بدفع الباقي من حصصهم في رأس المال ولو لم يحل ميعاد استحقاقه، ولقاضي التفليسة أن يأمر بقصر هذه المطالبة على القدر اللازم لوفاء ديون الشركة.$cc1415$, '1999-10-01', 'active' FROM ins_art_law17_1999_706;

WITH ins_art_law17_1999_707 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 707, $cc1416$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل السابع: إفلاس الشركات$cc1416$, $cc1417$لا تخضع سندات القرض التي أصدرتها الشركة لإجراءات تحقيق الديون، وتقبل هذه السندات بقيمتها الإسمية بعد إستنزال ما تكون الشركة قد دفعته منها، وإذا اشترط أداء مكافأة عند الوفاء بسند القرض وجب قبول السند بقيمته الإسمية مضافا إليها الجزء الذي استحق من المكافأة حتى صدور الحكم بشهر الإفلاس.$cc1417$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1417$لا تخضع سندات القرض التي أصدرتها الشركة لإجراءات تحقيق الديون، وتقبل هذه السندات بقيمتها الإسمية بعد إستنزال ما تكون الشركة قد دفعته منها، وإذا اشترط أداء مكافأة عند الوفاء بسند القرض وجب قبول السند بقيمته الإسمية مضافا إليها الجزء الذي استحق من المكافأة حتى صدور الحكم بشهر الإفلاس.$cc1417$, '1999-10-01', 'active' FROM ins_art_law17_1999_707;

