SELECT id, 1, $cc1419$1- توضع مقترحات الصلح بموافقة أغلبية الشركاء أو الجمعية العامة على حسب الأحوال.
2- ويتولى الممثل القانوني عن الشركة تقديم مقترحات الصلح في جمعية الدائنين.$cc1419$, '1999-10-01', 'active' FROM ins_art_law17_1999_708;

WITH ins_art_law17_1999_709 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 709, $cc1420$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل السابع: إفلاس الشركات$cc1420$, $cc1421$إذا كان الصلح خاصا بشركة أصدرت سندات قرض تجاوز قيمتها ثلث مجموع ديونها فلا يجوز منحها الصلح إلا إذا وافقت على شروطه الجمعية العامة لجماعة مالكي هذه السندات، وتؤجل دعوة الدائنين إلى الاجتماع للمداولة في الصلح إلى ان تصدر تلك الموافقة.$cc1421$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1421$إذا كان الصلح خاصا بشركة أصدرت سندات قرض تجاوز قيمتها ثلث مجموع ديونها فلا يجوز منحها الصلح إلا إذا وافقت على شروطه الجمعية العامة لجماعة مالكي هذه السندات، وتؤجل دعوة الدائنين إلى الاجتماع للمداولة في الصلح إلى ان تصدر تلك الموافقة.$cc1421$, '1999-10-01', 'active' FROM ins_art_law17_1999_709;

WITH ins_art_law17_1999_710 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 710, $cc1422$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل السابع: إفلاس الشركات$cc1422$, $cc1423$1- إذا انتهت تفليسة الشركة بالاتحاد وتم الصلح مع واحد أو اكثر من الشركاء المتضامنين فلا يجوز تخصيص أموال الشركة للوفاء بشروط هذا الصلح أو لضمان تنفيذها، ويبرأ الشريك الذي حصل على الصلح من التضامن.
2- وإذا تم الصلح مع الشركة وانتهت تفليسات الشركاء المتضامنين بالاتحاد استمرت الشركة قائمة إلا إذا كان موضوع الصلح هو التخلي عن جميع أموالها.
3- وإذا انتهت تفليسة الشركة وتفليسات الشركاء بالصلح اعتبر كل صلح مستقلا عن غيره ولا تسرى شروطه إلا على دائني التفليسة الخاصة به.$cc1423$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1423$1- إذا انتهت تفليسة الشركة بالاتحاد وتم الصلح مع واحد أو اكثر من الشركاء المتضامنين فلا يجوز تخصيص أموال الشركة للوفاء بشروط هذا الصلح أو لضمان تنفيذها، ويبرأ الشريك الذي حصل على الصلح من التضامن.
2- وإذا تم الصلح مع الشركة وانتهت تفليسات الشركاء المتضامنين بالاتحاد استمرت الشركة قائمة إلا إذا كان موضوع الصلح هو التخلي عن جميع أموالها.
3- وإذا انتهت تفليسة الشركة وتفليسات الشركاء بالصلح اعتبر كل صلح مستقلا عن غيره ولا تسرى شروطه إلا على دائني التفليسة الخاصة به.$cc1423$, '1999-10-01', 'active' FROM ins_art_law17_1999_710;

