INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1427$فيما عدا حالة الإفلاس بالتدليس تعود بحكم القانون جميع الحقوق التي سقطت عن المفلس طبقا للمادة 588 من هذا القانون بعد انقضاء ثلاث سنوات من تاريخ انتهاء التفليسة.$cc1427$, '1999-10-01', 'active' FROM ins_art_law17_1999_712;

WITH ins_art_law17_1999_713 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 713, $cc1428$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الثامن: رد الاعتبار التجاري$cc1428$, $cc1429$يجب الحكم برد الاعتبار إلى المفلس ولو لم ينقض الميعاد المنصوص عليه في المادة السابقة إذا أوفى جميع ديونه من اصل ومصاريف وعوائد مدة لا تزيد على سنتين.
وإذا كان المفلس شريكا متضامنا في شركة حكم بشهر إفلاسها فلا يرد إليه اعتباره وجوبا إلا إذا أوفى جميع ديون الشركة من اصل ومصاريف وعوائد مدة لا تزيد على سنتين.$cc1429$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1429$يجب الحكم برد الاعتبار إلى المفلس ولو لم ينقض الميعاد المنصوص عليه في المادة السابقة إذا أوفى جميع ديونه من اصل ومصاريف وعوائد مدة لا تزيد على سنتين.
وإذا كان المفلس شريكا متضامنا في شركة حكم بشهر إفلاسها فلا يرد إليه اعتباره وجوبا إلا إذا أوفى جميع ديون الشركة من اصل ومصاريف وعوائد مدة لا تزيد على سنتين.$cc1429$, '1999-10-01', 'active' FROM ins_art_law17_1999_713;

WITH ins_art_law17_1999_714 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 714, $cc1430$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل الثامن: رد الاعتبار التجاري$cc1430$, $cc1431$يجوز الحكم برد الاعتبار إلى المفلس ولو لم ينقض الميعاد المنصوص عليه في المادة 712 من هذا القانون في الحالتين الآتيتين:-
(أ) إذا حصل المفلس على صلح من دائنيه ونفذ شروطه، ويسرى هذا الحكم على الشريك المتضامن في شركة حكم بشهر إفلاسها إذا حصل هذا الشريك على صلح خاص به ونفذ شروطه.
(ب) إذا اثبت المفلس أن الدائنين قد أبرءوا ذمته من جميع الديون أو انهم اجمعوا على الموافقة على رد اعتباره.$cc1431$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
