(أ) إذا حصل المفلس على صلح من دائنيه ونفذ شروطه، ويسرى هذا الحكم على الشريك المتضامن في شركة حكم بشهر إفلاسها إذا حصل هذا الشريك على صلح خاص به ونفذ شروطه.
(ب) إذا اثبت المفلس أن الدائنين قد أبرءوا ذمته من جميع الديون أو انهم اجمعوا على الموافقة على رد اعتباره.$cc1431$, '1999-10-01', 'active' FROM ins_art_law17_1999_714;

