SELECT id, 1, $cc1457$1- لمن آل إليهم المتجر بطريق الإرث أو الوصية أن يطلبوا الصلح الواقي إذا قرروا الاستمرار في التجارة وكان التاجر قد فاته قبل ممن يجوز لهم الحصول على هذا الصلح.
2- ويجب أن يطلب الورثة أو الموصى إليهم الصلح الواقي خلال ثلاثة اشهر من تاريخ الوفاة وإذا لم يتفق الورثة أو الموصى إليهم جميعا على طلب الصلح، وجب على المحكمة أن تسمع أقوال من عارض منهم في طلب الصلح ثم تفصل فيه وفقا لمصلحة ذوى الشأن.$cc1457$, '1999-10-01', 'active' FROM ins_art_law17_1999_727;

