WITH ins_art_law17_1999_730 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 730, $cc1462$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل التاسع: الصلح الواقي من الإفلاس$cc1462$, $cc1463$يقدم طلب الصلح الواقي إلى قلم كتاب المحكمة الابتدائية المختصة بشهر الإفلاس يبين فيه أسباب اضطراب الأعمال ومقترحات الصلح وضمانات تنفيذها، وإذا لم يتمكن الطالب من تقديم كل هذه البيانات وجب بيان أسباب ذلك.$cc1463$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1463$يقدم طلب الصلح الواقي إلى قلم كتاب المحكمة الابتدائية المختصة بشهر الإفلاس يبين فيه أسباب اضطراب الأعمال ومقترحات الصلح وضمانات تنفيذها، وإذا لم يتمكن الطالب من تقديم كل هذه البيانات وجب بيان أسباب ذلك.$cc1463$, '1999-10-01', 'active' FROM ins_art_law17_1999_730;

WITH ins_art_law17_1999_731 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 731, $cc1464$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل التاسع: الصلح الواقي من الإفلاس$cc1464$, $cc1465$يرفق بطلب الصلح الواقي ما يأتي:-
الوثائق المؤيدة للبيانات المذكورة فيه.
شهادة من مكتب السجل التجاري تثبت قيام التاجر بما تفرضه الأحكام الخاصة بالسجل التجاري خلال السنتين السابقتين على طلب الصلح.
شهادة من الغرفة التجارية تفيد مزاولة التجارة بصفة مستمرة خلال السنتين السابقتين على طلب الصلح.
صورة من الميزانية وحساب الأرباح والخسائر عن السنتين السابقتين على طلب الصلح.
بيان إجمالي بالمصروفات الشخصية في السنتين السابقتين على طلب الصلح.
بيان تفصيلي بالأموال المنقولة وغير المنقولة وقيمتها التقريبية عند طلب الصلح.
بيان بأسماء الدائنين والمدينين وعناوينهم ومقدار حقوقهم وديونهم أو ضمانات التأمينات الضامنة لها.
ما يفيد إيداع مبلغ ألف جنيه خزينة المحكمة على ذمة مصروفات نشر ما يصدر من أحكام.
وإذا كان الطلب خاصا بشركة وجب أن يرفق به فضلا عن الوثائق المذكورة في الفقرة السابقة صورة من عقد الشركة ونظامها مصدقا عليها من مكتب السجل التجاري والوثائق المثبتة لصفة مقدم الطلب وصورة من قرار الشركاء أو الجمعية العامة بطلب الصلح وبيان بأسماء الشركاء المتضامنين وعناوينهم وجنسياتهم.
ويجب أن تكون تلك الوثائق مؤرخة وموقعة من طالب الصلح، وإذا تعذر تقديم بعضها أو استيفاء بياناتها وجب أن يتضمن الطلب أسباب ذلك.$cc1465$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
