ما يفيد إيداع مبلغ ألف جنيه خزينة المحكمة على ذمة مصروفات نشر ما يصدر من أحكام.
وإذا كان الطلب خاصا بشركة وجب أن يرفق به فضلا عن الوثائق المذكورة في الفقرة السابقة صورة من عقد الشركة ونظامها مصدقا عليها من مكتب السجل التجاري والوثائق المثبتة لصفة مقدم الطلب وصورة من قرار الشركاء أو الجمعية العامة بطلب الصلح وبيان بأسماء الشركاء المتضامنين وعناوينهم وجنسياتهم.
ويجب أن تكون تلك الوثائق مؤرخة وموقعة من طالب الصلح، وإذا تعذر تقديم بعضها أو استيفاء بياناتها وجب أن يتضمن الطلب أسباب ذلك.$cc1465$, '1999-10-01', 'active' FROM ins_art_law17_1999_731;

WITH ins_art_law17_1999_732 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 732, $cc1466$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل التاسع: الصلح الواقي من الإفلاس$cc1466$, $cc1467$1- للمحكمة التي تنظر في طلب الصلح أن تأمر باتخاذ التدابير اللازمة للمحافظة على أموال المدين إلى حين الفصل في الطلب.
2- ويجوز للمحكمة أن تتخذ من الإجراءات ما يمكنها من الإحاطة بحالة المدين المالية واسباب اضطرابها.
3- وتنظر المحكمة في طلب الصلح في غير علانية وعلى وجه الاستعجال، وتفصل في الطلب بحكم انتهائي.$cc1467$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1467$1- للمحكمة التي تنظر في طلب الصلح أن تأمر باتخاذ التدابير اللازمة للمحافظة على أموال المدين إلى حين الفصل في الطلب.
2- ويجوز للمحكمة أن تتخذ من الإجراءات ما يمكنها من الإحاطة بحالة المدين المالية واسباب اضطرابها.
3- وتنظر المحكمة في طلب الصلح في غير علانية وعلى وجه الاستعجال، وتفصل في الطلب بحكم انتهائي.$cc1467$, '1999-10-01', 'active' FROM ins_art_law17_1999_732;

WITH ins_art_law17_1999_733 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 733, $cc1468$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل التاسع: الصلح الواقي من الإفلاس$cc1468$, $cc1469$يجب أن تقضى المحكمة برفض طلب الصلح الواقي في الأحوال الآتية:-
إذا لم يقدم طالب الصلح الوثائق والبيانات المنصوص عليها في المادة 731 من هذا القانون أو قدمها ناقصة دون مسوغ.
إذا سبق الحكم على التاجر بالإدانة في إحدى جرائم الإفلاس بالتدليس أو في جريمة التزوير أو السرقة أو النصب أو خيانة الأمانة أو إصدار شيك بدون مقابل وفاء أو اختلاس الأموال العامة ما لم يكن قد رد إليه اعتباره.
(ج) إذا اعتزل التجارة أو لجأ إلى الفرار.$cc1469$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
