2- ويجب أن يتضمن الحكم ما يأتي:
(أ) ندب أحد قضاة المحكمة للإشراف على إجراءات الصلح.
(ب) تعيين أمين أو اكثر لمباشرة إجراءات الصلح ومتابعتها.
