SELECT id, 1, $cc1477$تسرى على القرارات التي يصدرها القاضي المشرف على الصلح الأحكام المنصوص عليها في المادتين 579، 580 من هذا القانون.
[ملاحظة توثيقية: مصححة بالاستدراك المنشور بالجريدة الرسمية- العدد 38 (مكرر) في 1999/9/27.]$cc1477$, '1999-10-01', 'active' FROM ins_art_law17_1999_737;

WITH ins_art_law17_1999_738 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 738, $cc1478$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل التاسع: الصلح الواقي من الإفلاس$cc1478$, $cc1479$1- يخطر قلم الكتاب أمين الصلح بالحكم الصادر بتعيينه فور صدوره.
2- ويقوم أمين الصلح خلال خمسة أيام من تاريخ الإخطار بقيد الحكم بافتتاح إجراءات الصلح في السجل التجاري ونشر ملخصه مصحوبا بدعوة الدائنين إلى الاجتماع في صحيفة يومية يعينها القاضي المشرف.
3- وعلى أمين الصلح أن يرسل في الميعاد المذكور في الفقرة السابقة الدعوة إلى الاجتماع مرفقا بها مقترحات الصلح إلى الدائنين المعلومة عناوينهم.$cc1479$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1479$1- يخطر قلم الكتاب أمين الصلح بالحكم الصادر بتعيينه فور صدوره.
2- ويقوم أمين الصلح خلال خمسة أيام من تاريخ الإخطار بقيد الحكم بافتتاح إجراءات الصلح في السجل التجاري ونشر ملخصه مصحوبا بدعوة الدائنين إلى الاجتماع في صحيفة يومية يعينها القاضي المشرف.
3- وعلى أمين الصلح أن يرسل في الميعاد المذكور في الفقرة السابقة الدعوة إلى الاجتماع مرفقا بها مقترحات الصلح إلى الدائنين المعلومة عناوينهم.$cc1479$, '1999-10-01', 'active' FROM ins_art_law17_1999_738;

WITH ins_art_law17_1999_739 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 739, $cc1480$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل التاسع: الصلح الواقي من الإفلاس$cc1480$, $cc1481$1- يقوم القاضي المشرف فور صدور الحكم بافتتاح إجراءات الصلح بقفل دفاتر المدين ووضع توقيعه عليها.
2- ويباشر أمين الصلح خلال أربع وعشرين ساعة من وقت إخطاره بصدور الحكم إجراءات الجرد بحضور المدين وكاتب المحكمة.$cc1481$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1481$1- يقوم القاضي المشرف فور صدور الحكم بافتتاح إجراءات الصلح بقفل دفاتر المدين ووضع توقيعه عليها.
2- ويباشر أمين الصلح خلال أربع وعشرين ساعة من وقت إخطاره بصدور الحكم إجراءات الجرد بحضور المدين وكاتب المحكمة.$cc1481$, '1999-10-01', 'active' FROM ins_art_law17_1999_739;

WITH ins_art_law17_1999_740 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 740, $cc1482$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل التاسع: الصلح الواقي من الإفلاس$cc1482$, $cc1483$1- يبقى المدين بعد صدور الحكم بافتتاح إجراءات الصلح قائما على إدارة أمواله بإشراف أمين الصلح، وله أن يقوم بجميع التصرفات العادية التي تقتضيها أعماله التجارية، ومع ذلك لا يجوز الاحتجاج على الدائنين بالتبرعات التي يجريها المدين بعد صدور الحكم المذكور.
2- ولا يجوز للمدين بعد صدور الحكم بافتتاح إجراءات الصلح أن يعقد صلحا أو رهنا من أي نوع أو أن يجرى تصرفا ناقلا للملكية لا تستلزمه أعماله التجارية العادية إلا بعد الحصول على إذن من القاضي المشرف، وكل تصرف يتم على خلاف ذلك لا يحتج به على الدائنين.$cc1483$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1483$1- يبقى المدين بعد صدور الحكم بافتتاح إجراءات الصلح قائما على إدارة أمواله بإشراف أمين الصلح، وله أن يقوم بجميع التصرفات العادية التي تقتضيها أعماله التجارية، ومع ذلك لا يجوز الاحتجاج على الدائنين بالتبرعات التي يجريها المدين بعد صدور الحكم المذكور.
2- ولا يجوز للمدين بعد صدور الحكم بافتتاح إجراءات الصلح أن يعقد صلحا أو رهنا من أي نوع أو أن يجرى تصرفا ناقلا للملكية لا تستلزمه أعماله التجارية العادية إلا بعد الحصول على إذن من القاضي المشرف، وكل تصرف يتم على خلاف ذلك لا يحتج به على الدائنين.$cc1483$, '1999-10-01', 'active' FROM ins_art_law17_1999_740;

WITH ins_art_law17_1999_741 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 741, $cc1484$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل التاسع: الصلح الواقي من الإفلاس$cc1484$, $cc1485$1- توقف جميع الدعاوى وإجراءات التنفيذ الموجهة إلى المدين بمجرد الحكم بافتتاح إجراءات الصلح، أما الدعاوى المرفوعة من المدين وإجراءات التنفيذ التي باشرها فتبقى سارية مع إدخال أمين الصلح فيها.
2- ولا يجوز بعد صدور الحكم بافتتاح إجراءات الصلح التمسك قبل الدائنين بقيد الرهون وحقوق الامتياز والاختصاص المقررة على أموال المدين.$cc1485$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1485$1- توقف جميع الدعاوى وإجراءات التنفيذ الموجهة إلى المدين بمجرد الحكم بافتتاح إجراءات الصلح، أما الدعاوى المرفوعة من المدين وإجراءات التنفيذ التي باشرها فتبقى سارية مع إدخال أمين الصلح فيها.
2- ولا يجوز بعد صدور الحكم بافتتاح إجراءات الصلح التمسك قبل الدائنين بقيد الرهون وحقوق الامتياز والاختصاص المقررة على أموال المدين.$cc1485$, '1999-10-01', 'active' FROM ins_art_law17_1999_741;

WITH ins_art_law17_1999_742 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 742, $cc1486$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل التاسع: الصلح الواقي من الإفلاس$cc1486$, $cc1487$لا يترتب على صدور الحكم بافتتاح إجراءات الصلح حلول آجال الديون التي على المدين أو وقف سريان عوائدها.$cc1487$
