WITH ins_art_law17_1999_743 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 743, $cc1488$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل التاسع: الصلح الواقي من الإفلاس$cc1488$, $cc1489$إذا أخفى المدين بعد تقديم طلب الصلح جزءا من أمواله أو أتلفه أو أجرى بسوء نية تصرفات ضارة بالدائنين أو تصرفات مخالفة لاحكام المادة 740 من هذا القانون تقضى المحكمة من تلقاء ذاتها بإلغاء إجراءات الصلح.$cc1489$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1489$إذا أخفى المدين بعد تقديم طلب الصلح جزءا من أمواله أو أتلفه أو أجرى بسوء نية تصرفات ضارة بالدائنين أو تصرفات مخالفة لاحكام المادة 740 من هذا القانون تقضى المحكمة من تلقاء ذاتها بإلغاء إجراءات الصلح.$cc1489$, '1999-10-01', 'active' FROM ins_art_law17_1999_743;

WITH ins_art_law17_1999_744 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 744, $cc1490$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل التاسع: الصلح الواقي من الإفلاس$cc1490$, $cc1491$1- على جميع الدائنين ولو كانت ديونهم غير حالة أو مضمونة بتأمينات خاصة أو ثابتة بأحكام نهائية أن يسلموا أمين الصلح خلال عشرة أيام من تاريخ نشر ملخص الحكم بافتتاح إجراءات الصلح في الصحف مستندات ديونهم مصحوبة ببيان هذه الديون وتأميناتها إن وجدت ومقدارها مقومة بالعملة الوطنية على أساس سعر الصرف المعلن لدى البنك المركزي بيعا أو إقفالا أو تحويلات أو بنكنوت إذا لم يوجد سعر تحويلات يوم صدور الحكم، ويجوز إرسال البيان والمستندات إلى أمين الصلح بكتاب مسجل مصحوبا بعلم الوصول.
2- ويكون الميعاد المذكور في الفقرة السابقة ثلاثين يوما بالنسبة الى الدائنين المقيمين خارج مصر.
3- ولا يضاف إلى الميعاد المذكور في الفقرتين السابقتين ميعاد للمسافة.$cc1491$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1491$1- على جميع الدائنين ولو كانت ديونهم غير حالة أو مضمونة بتأمينات خاصة أو ثابتة بأحكام نهائية أن يسلموا أمين الصلح خلال عشرة أيام من تاريخ نشر ملخص الحكم بافتتاح إجراءات الصلح في الصحف مستندات ديونهم مصحوبة ببيان هذه الديون وتأميناتها إن وجدت ومقدارها مقومة بالعملة الوطنية على أساس سعر الصرف المعلن لدى البنك المركزي بيعا أو إقفالا أو تحويلات أو بنكنوت إذا لم يوجد سعر تحويلات يوم صدور الحكم، ويجوز إرسال البيان والمستندات إلى أمين الصلح بكتاب مسجل مصحوبا بعلم الوصول.
2- ويكون الميعاد المذكور في الفقرة السابقة ثلاثين يوما بالنسبة الى الدائنين المقيمين خارج مصر.
3- ولا يضاف إلى الميعاد المذكور في الفقرتين السابقتين ميعاد للمسافة.$cc1491$, '1999-10-01', 'active' FROM ins_art_law17_1999_744;

WITH ins_art_law17_1999_745 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 745, $cc1492$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل التاسع: الصلح الواقي من الإفلاس$cc1492$, $cc1493$1- يضع أمين الصلح بعد انتهاء الميعاد المنصوص عليه في المادة 746 من هذا القانون قائمة بأسماء الدائنين الذين طلبوا الاشتراك في إجراءات الصلح وبيانا بمقدار كل دين على حدة والمستندات والتأمينات التي تؤيده ان وجدت وما يراه بشأن قبوله أو رفضه.
2- ولأمين الصلح أن يطلب من الدائن تقديم إيضاحات عن الدين أو تكملة مستندات أو تعديل مقداره أو صفاته.$cc1493$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1493$1- يضع أمين الصلح بعد انتهاء الميعاد المنصوص عليه في المادة 746 من هذا القانون قائمة بأسماء الدائنين الذين طلبوا الاشتراك في إجراءات الصلح وبيانا بمقدار كل دين على حدة والمستندات والتأمينات التي تؤيده ان وجدت وما يراه بشأن قبوله أو رفضه.
2- ولأمين الصلح أن يطلب من الدائن تقديم إيضاحات عن الدين أو تكملة مستندات أو تعديل مقداره أو صفاته.$cc1493$, '1999-10-01', 'active' FROM ins_art_law17_1999_745;

WITH ins_art_law17_1999_746 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 746, $cc1494$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل التاسع: الصلح الواقي من الإفلاس$cc1494$, $cc1495$1- على أمين الصلح إيداع قائمة الديون قلم كتاب المحكمة خلال أربعين يوما على الأكثر من تاريخ صدور حكم افتتاح إجراءات الصلح. ويجوز عند الاقتضاء إطالة هذا الميعاد بقرار من القاضي المشرف.
2- ويقوم أمين الصلح في اليوم التالي للإيداع بنشر بيان بحصول الإيداع في صحيفة يومية يعينها القاضي المشرف، ويرسل أمين الصلح إلى المدين والى كل دائن نسخة من قائمة الديون وبيان المبالغ التي يرى قبولها من كل دين.
3- ولكل ذي مصلحة الاطلاع على القائمة المودعة قلم كتاب المحكمة.$cc1495$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1495$1- على أمين الصلح إيداع قائمة الديون قلم كتاب المحكمة خلال أربعين يوما على الأكثر من تاريخ صدور حكم افتتاح إجراءات الصلح. ويجوز عند الاقتضاء إطالة هذا الميعاد بقرار من القاضي المشرف.
2- ويقوم أمين الصلح في اليوم التالي للإيداع بنشر بيان بحصول الإيداع في صحيفة يومية يعينها القاضي المشرف، ويرسل أمين الصلح إلى المدين والى كل دائن نسخة من قائمة الديون وبيان المبالغ التي يرى قبولها من كل دين.
3- ولكل ذي مصلحة الاطلاع على القائمة المودعة قلم كتاب المحكمة.$cc1495$, '1999-10-01', 'active' FROM ins_art_law17_1999_746;

WITH ins_art_law17_1999_747 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 747, $cc1496$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل التاسع: الصلح الواقي من الإفلاس$cc1496$, $cc1497$للمدين ولكل دائن ورد اسمه بقائمة الديون أن ينازع في الديون المدرجة بها خلال عشرة أيام من تاريخ النشر في الصحف عن حصول الإيداع، وتقدم المنازعة إلى قلم الكتاب ويجوز إرسالها بكتاب مسجل أو ببرقية أو بتلكس أو فاكس، ولا يضاف إلى هذا الميعاد ميعاد للمسافة.$cc1497$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1497$للمدين ولكل دائن ورد اسمه بقائمة الديون أن ينازع في الديون المدرجة بها خلال عشرة أيام من تاريخ النشر في الصحف عن حصول الإيداع، وتقدم المنازعة إلى قلم الكتاب ويجوز إرسالها بكتاب مسجل أو ببرقية أو بتلكس أو فاكس، ولا يضاف إلى هذا الميعاد ميعاد للمسافة.$cc1497$, '1999-10-01', 'active' FROM ins_art_law17_1999_747;

WITH ins_art_law17_1999_748 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 748, $cc1498$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل التاسع: الصلح الواقي من الإفلاس$cc1498$, $cc1499$1- يضع القاضي المشرف بعد انقضاء الميعاد المنصوص عليه في المادة السابقة قائمة نهائية بالديون غير المتنازع عليها ويؤشر على البيان الخاص بالدين بما يفيد قبوله ومقدار المقبول منه.
2- ويجوز للقاضي المشرف اعتبار الدين متنازعا عليه ولم يقدم بشأنه أية منازعة.
3- ويفصل القاضي المشرف في الديون المتنازع عليها خلال ثلاثين يوما من تاريخ انقضاء ميعاد المنازعة.
4- ويخطر قلم كتاب المحكمة ذوي الشأن بميعاد الجلسة قبل انعقادها بثلاثة أيام على الأقل، كما يبلغهم القرار الصادر في المنازعة فور صدوره.$cc1499$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1499$1- يضع القاضي المشرف بعد انقضاء الميعاد المنصوص عليه في المادة السابقة قائمة نهائية بالديون غير المتنازع عليها ويؤشر على البيان الخاص بالدين بما يفيد قبوله ومقدار المقبول منه.
2- ويجوز للقاضي المشرف اعتبار الدين متنازعا عليه ولم يقدم بشأنه أية منازعة.
3- ويفصل القاضي المشرف في الديون المتنازع عليها خلال ثلاثين يوما من تاريخ انقضاء ميعاد المنازعة.
4- ويخطر قلم كتاب المحكمة ذوي الشأن بميعاد الجلسة قبل انعقادها بثلاثة أيام على الأقل، كما يبلغهم القرار الصادر في المنازعة فور صدوره.$cc1499$, '1999-10-01', 'active' FROM ins_art_law17_1999_748;

WITH ins_art_law17_1999_749 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 749, $cc1500$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل التاسع: الصلح الواقي من الإفلاس$cc1500$, $cc1501$1- يجوز الطعن أمام المحكمة في القرار الصادر من القاضي المشرف بقبول الدين أو رفضه، ولا يترتب على الطعن وقف إجراءات الصلح إلا إذا أمرت المحكمة بذلك.
2- ويجوز للمحكمة قبل الفصل في الطعن أن تأمر بقبول الدين مؤقتا بمبلغ مؤقتا تقدره ولا يجوز قبول الدين مؤقتا إذا أقيمت بشأنه دعوى جنائية.
3- وإذا كانت المنازعة على الدين متعلقة بتأميناته وجب قبوله مؤقتا بوصفه دينا عاديا.$cc1501$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1501$1- يجوز الطعن أمام المحكمة في القرار الصادر من القاضي المشرف بقبول الدين أو رفضه، ولا يترتب على الطعن وقف إجراءات الصلح إلا إذا أمرت المحكمة بذلك.
2- ويجوز للمحكمة قبل الفصل في الطعن أن تأمر بقبول الدين مؤقتا بمبلغ مؤقتا تقدره ولا يجوز قبول الدين مؤقتا إذا أقيمت بشأنه دعوى جنائية.
3- وإذا كانت المنازعة على الدين متعلقة بتأميناته وجب قبوله مؤقتا بوصفه دينا عاديا.$cc1501$, '1999-10-01', 'active' FROM ins_art_law17_1999_749;

WITH ins_art_law17_1999_750 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 750, $cc1502$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل التاسع: الصلح الواقي من الإفلاس$cc1502$, $cc1503$لا يجوز أن يشترك في إجراءات الصلح الواقي الدائنون الذين لم يقدموا مستندات ديونهم في الميعاد المنصوص عليه في المادة 744 من هذا القانون ولا الدائنون الذين لم تقبل ديونهم نهائيا او مؤقتا.$cc1503$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
