INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1517$1- يحرر محضر بما تم في جلسة الصلح يوقعه القاضي المشرف وأمين الصلح والمدين والدائنون الحاضرون.
2- يجوز لكل دائن له حق الاشتراك في مداولات الصلح أن يبلغ القاضي المشرف كتابة بما لديه من اعتراض على الصلح وأسبابه وذلك خلال عشرة أيام من تاريخ التوقيع على محضر الصلح.
3- وعلى القاضي المشرف خلال سبعة أيام من انقضاء الميعاد المنصوص عليه في الفقرة السابقة أن يرسل محضر الصلح إلى المحكمة التي اصدر الأمر بافتتاح إجراءات الصلح للتصديق عليه، وذلك مع تقرير من القاضي عن حالة المفلس المالية واسباب اضطراب أعماله وشروط الصلح وبيان بالاعتراضات التي قدمت على الصلح واسبابها.$cc1517$, '1999-10-01', 'active' FROM ins_art_law17_1999_757;

WITH ins_art_law17_1999_758 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 758, $cc1518$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل التاسع: الصلح الواقي من الإفلاس$cc1518$, $cc1519$1- يقوم قلم كتاب المحكمة بتبليغ المدين والدائنين الذين قدموا اعتراضات على الصلح بميعاد - الجلسة التي حددت لنظر هذه الاعتراضات وطلب التصديق على الصلح، ويجوز لكل ذي مصلحة حضور هذه الجلسة.
2- تفصل المحكمة في الاعتراضات وفي طلب التصديق على الصلح بحكم واحد يكون نهائيا سواء أكان بقبول التصديق على الصلح أم برفض التصديق عليه.
3- يجوز للمحكمة أن ترفض التصديق على الصلح ولو لم يقدم بشأنه أي اعتراض إذا وجدت أسباب تتصل بالمصلحة العامة أو بمصلحة الدائنين تبرر ذلك.
4- إذا رفضت المحكمة الاعتراض على الصلح جاز لها الحكم على المعترض بغرامة لا تقل عن ألف جنيه ولا تزيد على خمسة آلاف جنيه إذا تبين انه تعمد تأخير الصلح.$cc1519$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1519$1- يقوم قلم كتاب المحكمة بتبليغ المدين والدائنين الذين قدموا اعتراضات على الصلح بميعاد - الجلسة التي حددت لنظر هذه الاعتراضات وطلب التصديق على الصلح، ويجوز لكل ذي مصلحة حضور هذه الجلسة.
2- تفصل المحكمة في الاعتراضات وفي طلب التصديق على الصلح بحكم واحد يكون نهائيا سواء أكان بقبول التصديق على الصلح أم برفض التصديق عليه.
3- يجوز للمحكمة أن ترفض التصديق على الصلح ولو لم يقدم بشأنه أي اعتراض إذا وجدت أسباب تتصل بالمصلحة العامة أو بمصلحة الدائنين تبرر ذلك.
4- إذا رفضت المحكمة الاعتراض على الصلح جاز لها الحكم على المعترض بغرامة لا تقل عن ألف جنيه ولا تزيد على خمسة آلاف جنيه إذا تبين انه تعمد تأخير الصلح.$cc1519$, '1999-10-01', 'active' FROM ins_art_law17_1999_758;

WITH ins_art_law17_1999_759 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 759, $cc1520$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل التاسع: الصلح الواقي من الإفلاس$cc1520$, $cc1521$1- يجوز أن يتضمن الصلح الواقي منح المدين آجالا لوفاء الديون. كما يجوز أن يتضمن إبراء المدين من جزء من الدين.
2- يجوز أن يعقد الصلح بشرط الوفاء إذا أيسر المدين خلال مدة تعين في شروط الصلح على ألا تجاوز خمس سنوات من تاريخ التصديق على الصلح، ولا يعتبر المدين قد أيسر إلا إذا زادت موجوداته على الديون المترتبة عليه بما يعادل عشرة في المائة على الأقل.
3- وللدائنين أن يشترطوا تقديم ضمان عيني أو شخصي لتنفيذ شروط الصلح.$cc1521$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1521$1- يجوز أن يتضمن الصلح الواقي منح المدين آجالا لوفاء الديون. كما يجوز أن يتضمن إبراء المدين من جزء من الدين.
2- يجوز أن يعقد الصلح بشرط الوفاء إذا أيسر المدين خلال مدة تعين في شروط الصلح على ألا تجاوز خمس سنوات من تاريخ التصديق على الصلح، ولا يعتبر المدين قد أيسر إلا إذا زادت موجوداته على الديون المترتبة عليه بما يعادل عشرة في المائة على الأقل.
3- وللدائنين أن يشترطوا تقديم ضمان عيني أو شخصي لتنفيذ شروط الصلح.$cc1521$, '1999-10-01', 'active' FROM ins_art_law17_1999_759;

WITH ins_art_law17_1999_760 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 760, $cc1522$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل التاسع: الصلح الواقي من الإفلاس$cc1522$, $cc1523$1- يشهر الحكم الصادر بالتصديق على الصلح الواقي وفقا للأحكام المقررة لشهر حكم الإفلاس.
2- ويجب أن يشتمل الملخص الذي ينشر في الصحف على اسم المدين وموطنه ورقم قيده في السجل التجاري والمحكمة التي صدقت على الصلح وتاريخ حكم التصديق.$cc1523$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1523$1- يشهر الحكم الصادر بالتصديق على الصلح الواقي وفقا للأحكام المقررة لشهر حكم الإفلاس.
2- ويجب أن يشتمل الملخص الذي ينشر في الصحف على اسم المدين وموطنه ورقم قيده في السجل التجاري والمحكمة التي صدقت على الصلح وتاريخ حكم التصديق.$cc1523$, '1999-10-01', 'active' FROM ins_art_law17_1999_760;

WITH ins_art_law17_1999_761 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 761, $cc1524$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل التاسع: الصلح الواقي من الإفلاس$cc1524$, $cc1525$1- يسرى الصلح الواقي من الإفلاس بمجرد صدور الحكم بالتصديق عليه على جميع الدائنين الذين تعتبر ديونهم عادية وفقا لاحكام الإفلاس ولو لم يشتركوا في إجراءاته أو لم يوافقوا على شروطه.
2- لا يفيد من الصلح الواقي المدينون المتضامنون مع المدين أو كفلاؤه في الدين ومع ذلك إذا وقع الصلح مع شركة أفاد من شروطه الشركاء المسئولون في جميع أموالهم عن ديون الشركة إلا إذا نص في عقد الصلح على غير ذلك.
3- لا يسرى الصلح على دين النفقة ولا على الديون التي نشأت بعد صدور الحكم بافتتاح إجراءات الصلح.$cc1525$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1525$1- يسرى الصلح الواقي من الإفلاس بمجرد صدور الحكم بالتصديق عليه على جميع الدائنين الذين تعتبر ديونهم عادية وفقا لاحكام الإفلاس ولو لم يشتركوا في إجراءاته أو لم يوافقوا على شروطه.
2- لا يفيد من الصلح الواقي المدينون المتضامنون مع المدين أو كفلاؤه في الدين ومع ذلك إذا وقع الصلح مع شركة أفاد من شروطه الشركاء المسئولون في جميع أموالهم عن ديون الشركة إلا إذا نص في عقد الصلح على غير ذلك.
3- لا يسرى الصلح على دين النفقة ولا على الديون التي نشأت بعد صدور الحكم بافتتاح إجراءات الصلح.$cc1525$, '1999-10-01', 'active' FROM ins_art_law17_1999_761;

WITH ins_art_law17_1999_762 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 762, $cc1526$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل التاسع: الصلح الواقي من الإفلاس$cc1526$, $cc1527$1- يجوز للمحكمة التي صدقت على الصلح أن تمنح المدين بناء على طلبه آجالا للوفاء بالديون التي لايسرى عليها الصلح بشرط الا تجاوز الآجال التي تمنحها المحكمة الأجل المقرر في الصلح.
2- ولا يترتب على التصديق على الصلح حرمان المدين من الآجال التي تكون أبعد مدى من الأجل المقرر في الصلح.$cc1527$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1527$1- يجوز للمحكمة التي صدقت على الصلح أن تمنح المدين بناء على طلبه آجالا للوفاء بالديون التي لايسرى عليها الصلح بشرط الا تجاوز الآجال التي تمنحها المحكمة الأجل المقرر في الصلح.
2- ولا يترتب على التصديق على الصلح حرمان المدين من الآجال التي تكون أبعد مدى من الأجل المقرر في الصلح.$cc1527$, '1999-10-01', 'active' FROM ins_art_law17_1999_762;

WITH ins_art_law17_1999_763 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 763, $cc1528$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل التاسع: الصلح الواقي من الإفلاس$cc1528$, $cc1529$1- تأمر المحكمة في حكم التصديق على الصلح بناء على تقرير من القاضي المشرف باستبقاء أمين الصلح أو بتعيين رقيب من بين الدائنين أو من غيرهم لمراقبة تنفيذ شروط الصلح وابلاغ المحكمة بما يقع من مخالفات لهذه الشروط.
2- يطلب الرقيب من المحكمة التي صدقت على الصلح خلال عشرة أيام من الانتهاء من تنفيذ شروط الصلح، الحكم بقفل الإجراءات، ويشهر هذا الطلب بالكيفية المنصوص عليها في المادة 738 من هذا القانون.
3- ويصدر الحكم بقفل الإجراءات خلال ثلاثين يوما من تاريخ النشر في الصحف، ويفيد ملخصه في السجل التجاري.$cc1529$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1529$1- تأمر المحكمة في حكم التصديق على الصلح بناء على تقرير من القاضي المشرف باستبقاء أمين الصلح أو بتعيين رقيب من بين الدائنين أو من غيرهم لمراقبة تنفيذ شروط الصلح وابلاغ المحكمة بما يقع من مخالفات لهذه الشروط.
2- يطلب الرقيب من المحكمة التي صدقت على الصلح خلال عشرة أيام من الانتهاء من تنفيذ شروط الصلح، الحكم بقفل الإجراءات، ويشهر هذا الطلب بالكيفية المنصوص عليها في المادة 738 من هذا القانون.
3- ويصدر الحكم بقفل الإجراءات خلال ثلاثين يوما من تاريخ النشر في الصحف، ويفيد ملخصه في السجل التجاري.$cc1529$, '1999-10-01', 'active' FROM ins_art_law17_1999_763;

WITH ins_art_law17_1999_764 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 764, $cc1530$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل التاسع: الصلح الواقي من الإفلاس$cc1530$, $cc1531$1- يبطل الصلح الواقي من الإفلاس إذا ظهر بعد التصديق عليه تدليس من جانب المدين ويعتبر تدليسا على وجه الخصوص إخفاء الأموال واصطناع الديون وتعمد المبالغة في مقدارها.
2- يجب أن يطلب إبطال الصلح خلال ستة اشهر من اليوم الذي يظهر فيه التدليس وإلا كان الطلب غير مقبول، وفي جميع الأحوال لا يكون الطلب مقبولا إذا قدم بعد انقضاء سنتين من تاريخ صدور الحكم بالتصديق على الصلح.
3- لا يلزم الدائنون برد ما قبضوه من ديونهم قبل الحكم بإبطال الصلح.
4- يترتب على إبطال الصلح براءة ذمة الكفيل الذي يضمن تنفيذ شروطه.$cc1531$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1531$1- يبطل الصلح الواقي من الإفلاس إذا ظهر بعد التصديق عليه تدليس من جانب المدين ويعتبر تدليسا على وجه الخصوص إخفاء الأموال واصطناع الديون وتعمد المبالغة في مقدارها.
2- يجب أن يطلب إبطال الصلح خلال ستة اشهر من اليوم الذي يظهر فيه التدليس وإلا كان الطلب غير مقبول، وفي جميع الأحوال لا يكون الطلب مقبولا إذا قدم بعد انقضاء سنتين من تاريخ صدور الحكم بالتصديق على الصلح.
3- لا يلزم الدائنون برد ما قبضوه من ديونهم قبل الحكم بإبطال الصلح.
4- يترتب على إبطال الصلح براءة ذمة الكفيل الذي يضمن تنفيذ شروطه.$cc1531$, '1999-10-01', 'active' FROM ins_art_law17_1999_764;

WITH ins_art_law17_1999_765 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 765, $cc1532$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل التاسع: الصلح الواقي من الإفلاس$cc1532$, $cc1533$1- للمحكمة بناء على طلب كل دائن تسرى عليه شروط الصلح أن تقضى بفسخ الصلح في الأحوال الآتية:-
(أ) إذا لم ينفذ المدين شروط الصلح كما اتفق عليها.
(ب) إذا تصرف المدين بعد التصديق على الصلح تصرفا ناقلا لملكية متجره دون مسوغ مقبول.
(ج) إذا توفى المدين وتبين انه لا ينتظر تنفيذ الصلح أو إتمام تنفيذه.
2- ولا يلزم الدائنون برد ما قبضوه من ديونهم قبل الحكم بفسخ الصلح.
3- ولا يترتب على فسخ الصلح براءة ذمة الكفيل الذي يضمن تنفيذ شروطه، ويجب تكليف الكفيل بحضور الجلسة التي ينظر فيها طلب فسخ الصلح.$cc1533$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1533$1- للمحكمة بناء على طلب كل دائن تسرى عليه شروط الصلح أن تقضى بفسخ الصلح في الأحوال الآتية:-
(أ) إذا لم ينفذ المدين شروط الصلح كما اتفق عليها.
(ب) إذا تصرف المدين بعد التصديق على الصلح تصرفا ناقلا لملكية متجره دون مسوغ مقبول.
(ج) إذا توفى المدين وتبين انه لا ينتظر تنفيذ الصلح أو إتمام تنفيذه.
2- ولا يلزم الدائنون برد ما قبضوه من ديونهم قبل الحكم بفسخ الصلح.
3- ولا يترتب على فسخ الصلح براءة ذمة الكفيل الذي يضمن تنفيذ شروطه، ويجب تكليف الكفيل بحضور الجلسة التي ينظر فيها طلب فسخ الصلح.$cc1533$, '1999-10-01', 'active' FROM ins_art_law17_1999_765;

WITH ins_art_law17_1999_766 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 766, $cc1534$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل التاسع: الصلح الواقي من الإفلاس$cc1534$, $cc1535$1- يقدر القاضي المشرف على الصلح اجر كل من أمين الصلح والرقيب إذا كان من غير الدائنين، ويودع قرار القاضي في هذا الشأن قلم كتاب المحكمة في اليوم التالي لصدوره.
2- ويجوز لكل ذي مصلحة الاعتراض على القرار أمام المحكمة خلال خمسة عشر يوما من تاريخ الإيداع، ويكون الحكم الصادر في الاعتراض نهائيا.$cc1535$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1535$1- يقدر القاضي المشرف على الصلح اجر كل من أمين الصلح والرقيب إذا كان من غير الدائنين، ويودع قرار القاضي في هذا الشأن قلم كتاب المحكمة في اليوم التالي لصدوره.
2- ويجوز لكل ذي مصلحة الاعتراض على القرار أمام المحكمة خلال خمسة عشر يوما من تاريخ الإيداع، ويكون الحكم الصادر في الاعتراض نهائيا.$cc1535$, '1999-10-01', 'active' FROM ins_art_law17_1999_766;

WITH ins_art_law17_1999_767 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 767, $cc1536$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل التاسع: الصلح الواقي من الإفلاس$cc1536$, $cc1537$يجوز للمحكمة من تلقاء ذاتها أو بناء على تقرير من القاضي المشرف في الصلح أن تأمر في الحكم بقفل إجراءات الصلح بصرف مكافأة إجمالية للرقيب إذا كان من الدائنين وتبين انه بذل في عمله جهدا غير عادي وكانت حالة المدين المالية تسمح بذلك.$cc1537$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
