INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1537$يجوز للمحكمة من تلقاء ذاتها أو بناء على تقرير من القاضي المشرف في الصلح أن تأمر في الحكم بقفل إجراءات الصلح بصرف مكافأة إجمالية للرقيب إذا كان من الدائنين وتبين انه بذل في عمله جهدا غير عادي وكانت حالة المدين المالية تسمح بذلك.$cc1537$, '1999-10-01', 'active' FROM ins_art_law17_1999_767;

WITH ins_art_law17_1999_768 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 768, $cc1538$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل العاشر: جرائم الإفلاس والصلح الواقي منه$cc1538$, $cc1539$تسرى في شأن جرائم التفالس الأحكام المنصوص عليها في قانون العقوبات.$cc1539$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1539$تسرى في شأن جرائم التفالس الأحكام المنصوص عليها في قانون العقوبات.$cc1539$, '1999-10-01', 'active' FROM ins_art_law17_1999_768;

WITH ins_art_law17_1999_769 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 769, $cc1540$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل العاشر: جرائم الإفلاس والصلح الواقي منه$cc1540$, $cc1541$تسرى في شأن جرائم الصلح الواقي من الإفلاس الأحكام الآتية:-
1- يعاقب المدين بالحبس مدة لا تقل عن ستة أشهر إذا:
(أ) أخفى بسوء نية كل أمواله أو بعضها أو غالى في تقديرها بقصد الحصول على الصلح.
(ب) ترك بسوء نية دائنا وهميا أو ممنوعا من الاشتراك في دينه يشترك في مداولات الصلح والتصويت عليها أو مكنه من ذلك.
(ج) أغفل بسوء نية ذكر دائن في قائمة الدائنين.
2- يعاقب الدائن بالعقوبة المنصوص عليها بالفقرة السابقة إذا اشترك بسوء نية في مداولات الصلح والتصويت عليه وهو ممنوع من هذا الاشتراك، أو كان دينه مغالى فيه، أو قرر له المدين أو أي شخص آخر مزايا خاصة مقابل تصويته مع الصلح.
3- يعاقب بالحبس مدة لا تقل عن ستة اشهر أمين الصلح الذي قدم أو اقر بسوء نية بيانات غير صحيحة عن حالة المدين.$cc1541$
  FROM laws WHERE law_no = 17 AND law_year = 1999 AND country_code = 'EG'
  ON CONFLICT (law_id, article_no) DO NOTHING
  RETURNING id
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, $cc1541$تسرى في شأن جرائم الصلح الواقي من الإفلاس الأحكام الآتية:-
1- يعاقب المدين بالحبس مدة لا تقل عن ستة أشهر إذا:
(أ) أخفى بسوء نية كل أمواله أو بعضها أو غالى في تقديرها بقصد الحصول على الصلح.
(ب) ترك بسوء نية دائنا وهميا أو ممنوعا من الاشتراك في دينه يشترك في مداولات الصلح والتصويت عليها أو مكنه من ذلك.
(ج) أغفل بسوء نية ذكر دائن في قائمة الدائنين.
2- يعاقب الدائن بالعقوبة المنصوص عليها بالفقرة السابقة إذا اشترك بسوء نية في مداولات الصلح والتصويت عليه وهو ممنوع من هذا الاشتراك، أو كان دينه مغالى فيه، أو قرر له المدين أو أي شخص آخر مزايا خاصة مقابل تصويته مع الصلح.
3- يعاقب بالحبس مدة لا تقل عن ستة اشهر أمين الصلح الذي قدم أو اقر بسوء نية بيانات غير صحيحة عن حالة المدين.$cc1541$, '1999-10-01', 'active' FROM ins_art_law17_1999_769;

WITH ins_art_law17_1999_770 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, body)
  SELECT id, 770, $cc1542$الباب الخامس: الإفلاس والصلح الواقي منه — الفصل العاشر: جرائم الإفلاس والصلح الواقي منه$cc1542$, $cc1543$لا يترتب على إقامة الدعوى الجنائية بالإفلاس بالتدليس او بالتقصير أي تعديل في الأحكام الخاصة بإجراءات التفليسة إلا إذا نص القانون على غير ذلك.$cc1543$
